-- Generated by tasks/content-cutover/scripts/build-seeds.ts from content/ at cc079bee7.
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Acorn was an application packaging and deployment framework for Kubernetes that let developers define an entire app — containers, volumes, secrets, and ingress — in a single file written in Acornfile, a CUE-derived configuration language. "},{"type":"text","text":"acorn run","marks":[{"type":"code"}]},{"type":"text","text":" would then push that bundle to a cluster as an OCI image and reconcile it into the underlying Kubernetes primitives."}]},{"type":"paragraph","content":[{"type":"text","text":"The project was built by the team behind Rancher and k3s (Darren Shepherd, Ibrahim Jarif, and others at Acorn Labs) as an attempt to hide Helm charts and raw YAML behind a simpler developer-facing abstraction. It shipped a CLI, a per-cluster controller, and a managed SaaS (Acorn Cloud) for sharing apps across clusters."}]},{"type":"paragraph","content":[{"type":"text","text":"Acorn Labs pivoted away from the runtime in 2024 to focus on GPTScript and AI tooling, and the repository is no longer maintained. If you need the same shape of abstraction today, look at Score, KubeVela, Radius, or just Helm with a thin wrapper — all of which are actively developed. With the repository archived and no security updates planned, migration is the sensible path."}]}]}' WHERE `id` = 'acorn';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Aeraki Mesh (\"Aeraki\" is Greek for \"breeze\") is a management plane that extends Istio to handle non-HTTP Layer 7 protocols. Out of the box Istio and Envoy give rich traffic management for HTTP and gRPC, but protocols like Dubbo, Thrift, Redis, Kafka, and MetaProtocol need extra work — Aeraki provides that missing piece without forcing users to modify Istio or Envoy themselves."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally, Aeraki runs alongside istiod as a separate controller. It watches Istio''s service registry and pushes protocol-specific configuration to Envoy sidecars via EnvoyFilter resources. It ships MetaProtocol, a generic Layer 7 framework that lets operators add support for custom RPC protocols by writing a codec plugin instead of a full Envoy network filter in C++."}]},{"type":"paragraph","content":[{"type":"text","text":"In practice Aeraki is most useful in environments with heavy Dubbo or Thrift traffic — typically larger Chinese tech stacks migrating from traditional microservice frameworks into Istio. For plain HTTP/gRPC workloads it adds no value over stock Istio. The project is a CNCF sandbox entry and is primarily maintained by Tetrate."}]}]}' WHERE `id` = 'aerakimesh';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"agentgateway is an AI-native proxy, written in Rust, for the traffic patterns that agentic systems create: agent-to-LLM, agent-to-tool, and agent-to-agent communication. It speaks the protocols of that world natively — Model Context Protocol (MCP) and Agent2Agent (A2A) — and layers security, observability, and governance on top, so platform teams can see and control what their agents are actually saying to models and tools."}]},{"type":"paragraph","content":[{"type":"text","text":"Created by Solo.io and donated to the Linux Foundation, it slots into the existing cloud native stack rather than beside it: kgateway can act as its control plane, and at KubeCon + CloudNativeCon Europe 2026 the Istio project announced experimental agentgateway support alongside its Gateway API Inference Extension work. Capabilities include MCP multiplexing (federating many MCP servers behind one endpoint), tool-level RBAC, prompt guardrails, and OpenTelemetry-based tracing of agent conversations."}]},{"type":"paragraph","content":[{"type":"text","text":"It occupies the emerging \"agent gateway\" niche alongside LiteLLM, Portkey, and the LLM-routing features appearing in traditional API gateways; its bet is that agent traffic deserves a purpose-built, vendor-neutral data plane rather than bolt-ons to HTTP gateways."}]}]}' WHERE `id` = 'agentgateway';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"agentregistry is a cloud native registry for the building blocks of agentic AI systems: MCP servers, agents, and skills. It gives organizations a curated, single source of truth for which agents and tools are approved for use, and handles discovery and deployment of those artifacts across local development environments and Kubernetes clusters."}]},{"type":"paragraph","content":[{"type":"text","text":"The project was created by Solo.io — its third agentic-infrastructure donation after kagent and agentgateway — and donated to the Linux Foundation, with a CNCF Sandbox application submitted in March 2026. It integrates with the projects you''d expect: Kubernetes for deployment, and Prometheus and OpenTelemetry for observability, with agentgateway as the natural enforcement point for what the registry curates."}]},{"type":"paragraph","content":[{"type":"text","text":"The problem it addresses is real and growing: as teams accumulate dozens of MCP servers and agents of varying provenance, \"which of these are vetted, versioned, and safe to run?\" needs an answer that isn''t a wiki page. Whether the ecosystem standardizes on agentregistry or on registry features inside existing artifact stores (Artifact Hub, OCI registries) is the open question."}]}]}' WHERE `id` = 'agentregistry';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Akri is a Kubernetes resource interface for exposing leaf devices — IP cameras, USB peripherals, OPC UA servers, Bluetooth sensors — as native cluster resources. It was originally built by Microsoft to solve a concrete edge/IoT problem: Kubernetes knows how to schedule pods onto nodes, but it has no native way to discover a thermal camera on the same LAN and hand it to a workload."}]},{"type":"paragraph","content":[{"type":"text","text":"The project is written in Rust and works through two main components. Discovery Handlers run on each node and implement protocol-specific discovery (ONVIF, udev, OPC UA, and custom gRPC-based handlers). When a device is found, the Akri Controller creates an Instance CRD and exposes the device through the Kubernetes device plugin framework, so pods can request it with a standard resource limit. If the device appears on multiple nodes, Akri can schedule a broker pod per node to proxy access."}]},{"type":"paragraph","content":[{"type":"text","text":"Akri sits in a niche next to projects like KubeEdge and k3s on the edge side, and is distinct from CSI or device plugins because it focuses on dynamic, network-attached leaf devices rather than local hardware. It has been a CNCF sandbox project since 2021, though development activity has slowed significantly in the last year."}]}]}' WHERE `id` = 'akri';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Antrea is a Kubernetes CNI plugin that uses Open vSwitch (OVS) as its dataplane to implement pod networking, NetworkPolicy, and service load balancing. It was created by VMware and is the CNI that underpins vSphere with Tanzu and several other VMware Kubernetes offerings."}]},{"type":"paragraph","content":[{"type":"text","text":"Instead of relying on iptables or eBPF like Calico and Cilium do, Antrea programs OVS flow rules through a per-node agent written in Go. This gives it strong visibility tooling — "},{"type":"text","text":"antctl traceflow","marks":[{"type":"code"}]},{"type":"text","text":" can inject a packet and show every OVS table hit it takes through the cluster — and makes it a natural fit for environments already running NSX or other OVS-based infrastructure. It supports overlay (Geneve, VXLAN, GRE) and no-encap modes, Windows nodes, multi-cluster networking via ClusterSet, and Kubernetes NetworkPolicy plus its own ClusterNetworkPolicy CRD with tiers and FQDN rules."}]},{"type":"paragraph","content":[{"type":"text","text":"Antrea competes directly with Calico, Cilium, and Flannel. Its main draws are OVS-based debuggability, first-class Windows support, and tight integration with the VMware ecosystem; its main trade-off is that it lacks the kernel-level eBPF story that Cilium has made the default for new clusters. It has been a CNCF sandbox project since 2021."}]}]}' WHERE `id` = 'antrea';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"apko is a tool from Chainguard that builds OCI container images declaratively from a YAML file and a set of APK packages. There is no Dockerfile, no "},{"type":"text","text":"RUN","marks":[{"type":"code"}]},{"type":"text","text":" steps, and no container runtime involved in the build — apko resolves the package list, fetches the APKs, and writes a tarball that is already a valid OCI image."}]},{"type":"paragraph","content":[{"type":"text","text":"Because the build is purely a package install with no arbitrary shell execution, apko produces bit-for-bit reproducible images: the same config and package versions give the exact same image hash on any machine. Every build also generates an SBOM in SPDX format and sets the image creation timestamp to the epoch (or a user-specified value) so layer digests are stable. It is the tool Chainguard uses to produce their Wolfi-based distroless images, and it is typically paired with "},{"type":"text","text":"melange","marks":[{"type":"code"}]},{"type":"text","text":", which builds the APKs themselves from source."}]},{"type":"paragraph","content":[{"type":"text","text":"In the image build landscape apko sits alongside "},{"type":"text","text":"ko","marks":[{"type":"code"}]},{"type":"text","text":" (for Go binaries), BuildKit (general Dockerfile builds), and Buildpacks. Its niche is supply-chain focused base images: minimal, reproducible, SBOM-attested, and free of the build tools and package managers that inflate attack surface in traditional Alpine or Debian images. If you are not using Wolfi or Alpine APK packages, apko is not the right tool."}]}]}' WHERE `id` = 'apko';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Aqua is a declarative CLI version manager. You list the tools you need — "},{"type":"text","text":"terraform","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"helm","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"gh","marks":[{"type":"code"}]},{"type":"text","text":", hundreds more — with exact versions in an "},{"type":"text","text":"aqua.yaml","marks":[{"type":"code"}]},{"type":"text","text":" file, and "},{"type":"text","text":"aqua install","marks":[{"type":"code"}]},{"type":"text","text":" downloads them into a per-user cache and creates shim binaries on your "},{"type":"text","text":"$PATH","marks":[{"type":"code"}]},{"type":"text","text":". Run any tool and aqua transparently resolves it to the correct pinned version for the current directory."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood, aqua is a single Go binary that pulls from a community-maintained registry of package definitions (over 1,500 tools). Each registry entry describes where to download the binary for each OS/arch and, crucially, an SHA-256 checksum or Cosign signature. That makes aqua a practical supply-chain tool as well: every install can be checksum-verified, and you can enforce policies that refuse to install unsigned or unknown packages. It also generates lockfiles so CI and developer machines stay in sync."}]},{"type":"paragraph","content":[{"type":"text","text":"In the broader ecosystem, aqua overlaps with "},{"type":"text","text":"asdf","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"mise","marks":[{"type":"code"}]},{"type":"text","text":", and Nix. Compared to asdf/mise it is narrower (binaries only, no language toolchains) but significantly faster and has better checksum handling out of the box. Compared to Nix it is drastically simpler at the cost of flexibility. It is a good fit for platform teams who want every engineer to run the same "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"terraform","marks":[{"type":"code"}]},{"type":"text","text":" without writing bootstrap scripts."}]}]}' WHERE `id` = 'aquaproj';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Argo is a family of four Kubernetes-native projects that share a common controller pattern but solve different problems. Argo CD is a GitOps continuous delivery controller that reconciles a Git repository of manifests against a cluster. Argo Workflows is a DAG/step-based workflow engine where each node is a Kubernetes Pod. Argo Events provides an event bus and sensors for triggering workflows or other actions from webhooks, Kafka, SQS, calendar events, and so on. Argo Rollouts extends Deployments with canary and blue-green strategies driven by Prometheus or other metrics."}]},{"type":"paragraph","content":[{"type":"text","text":"All four are implemented as Kubernetes controllers in Go, using CRDs as their public API. Argo CD in particular has become the de-facto GitOps engine in the CNCF ecosystem: it renders manifests from Helm, Kustomize, Jsonnet, or raw YAML, computes a diff against live cluster state, and applies changes with pluggable sync waves and health checks. The web UI and "},{"type":"text","text":"argocd","marks":[{"type":"code"}]},{"type":"text","text":" CLI make drift between Git and cluster state immediately obvious."}]},{"type":"paragraph","content":[{"type":"text","text":"Argo graduated from the CNCF in December 2022 and is maintained by Intuit, Red Hat, Akuity, Codefresh, and others. Its main competitor in GitOps is Flux (also CNCF graduated); for workflows it overlaps with Tekton and Kubeflow Pipelines, though Argo Workflows is actually the engine Kubeflow Pipelines runs on top of."}]}]}' WHERE `id` = 'argo';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Armada is a multi-cluster batch job scheduler built for high-throughput, bursty workloads — the kind of problem that breaks the default Kubernetes scheduler. It was built at G-Research, a quantitative finance firm, to run millions of backtest and risk jobs per day across tens of thousands of nodes spread over multiple Kubernetes clusters."}]},{"type":"paragraph","content":[{"type":"text","text":"The architecture separates a central Armada server (backed by Postgres and Pulsar for the event log) from per-cluster executor components. Jobs are submitted to Armada queues with fair-share priority; the server decides which cluster a job should run on, then the executor actually creates the Pod. Because queueing and scheduling happen outside any single Kubernetes scheduler, Armada can sustain job submission rates in the hundreds of thousands per hour, far beyond what "},{"type":"text","text":"kube-scheduler","marks":[{"type":"code"}]},{"type":"text","text":" was designed for, and it handles cluster failover naturally."}]},{"type":"paragraph","content":[{"type":"text","text":"Armada competes with Volcano, Kueue, and YuniKorn in the Kubernetes batch space, and more broadly with HTCondor and Slurm in traditional HPC. It is the right choice specifically when you have many small jobs, many clusters, and a need for fair-share queueing; for single-cluster ML training Kueue is usually simpler. It has been a CNCF sandbox project since 2022."}]}]}' WHERE `id` = 'armada';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Artifact Hub is a web-based discovery index for cloud-native packages — Helm charts, OLM operators, Falco rules, OPA policies, Tekton tasks, Krew kubectl plugins, Tinkerbell actions, KEDA scalers, Keptn integrations, Kyverno policies, and more. It solves the \"where do I find a chart for X\" problem that existed after the original "},{"type":"text","text":"helm/charts","marks":[{"type":"code"}]},{"type":"text","text":" monorepo was deprecated in 2020 and chart publishing became federated."}]},{"type":"paragraph","content":[{"type":"text","text":"It''s a Go backend with a React frontend, backed by PostgreSQL. Repositories self-register ("},{"type":"text","text":"helm repo add","marks":[{"type":"code"}]},{"type":"text","text":" style) and Artifact Hub periodically crawls them to ingest metadata, README files, values schemas, signatures, and security scan results from Trivy. Packages are ranked by signals like maintainer verification, Cosign signatures, OpenSSF Scorecard results, and recency. You can search across every indexed artifact type in one place and, for charts specifically, get inline values documentation and install commands."}]},{"type":"paragraph","content":[{"type":"text","text":"Artifact Hub is maintained by the CNCF itself (it moved from a Helm subproject to a top-level CNCF project in 2020, now incubating) and the public instance at artifacthub.io is the closest thing the ecosystem has to a central package registry. You can also self-host it if you need to index private repositories alongside public ones."}]}]}' WHERE `id` = 'artifacthub';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Athenz is a service-to-service authentication and fine-grained authorization system built at Yahoo (now part of Verizon Media / Yahoo again) and open sourced in 2016. It issues short-lived X.509 certificates and JWT-like access tokens that workloads use to prove their identity to each other, and it evaluates RBAC policies to decide what those identities are allowed to do."}]},{"type":"paragraph","content":[{"type":"text","text":"The core architecture is two services: ZMS (the authorization management system) holds the source-of-truth for domains, roles, and policies in a central database; ZTS (the token service) runs regionally and mints service certificates and access tokens against that policy, doing the hot-path work without hitting ZMS on every request. Workloads authenticate to ZTS with a bootstrapped identity — typically a node attestation provided by AWS, GCP, or a Kubernetes service account — and receive an SVID-style cert they can then present to peers or to an Envoy sidecar."}]},{"type":"paragraph","content":[{"type":"text","text":"In the broader identity landscape Athenz overlaps significantly with SPIFFE/SPIRE, HashiCorp Vault''s PKI engine, and cert-manager. Its distinguishing feature is that it ties identity issuance directly to a centralized RBAC policy model, which is why it''s still used heavily inside large operators like Yahoo, LinkedIn, and Verizon Media. Outside of those environments most new projects reach for SPIFFE first."}]}]}' WHERE `id` = 'athenz';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Atlantis is a self-hosted Terraform pull request automation server. You point it at your GitHub, GitLab, Bitbucket, or Azure DevOps repo, and when someone opens a PR touching Terraform code Atlantis runs "},{"type":"text","text":"terraform plan","marks":[{"type":"code"}]},{"type":"text","text":" and posts the output as a PR comment. Reviewers approve the plan by commenting "},{"type":"text","text":"atlantis apply","marks":[{"type":"code"}]},{"type":"text","text":", at which point Atlantis runs the apply and reports back. The Terraform state is locked on the PR while it''s open so two PRs can''t race each other."}]},{"type":"paragraph","content":[{"type":"text","text":"It''s a single Go binary that you run somewhere with network access to your VCS webhook endpoint and credentials for your cloud provider. Workflows are configurable per-repo via an "},{"type":"text","text":"atlantis.yaml","marks":[{"type":"code"}]},{"type":"text","text":" — you can define projects, pin Terraform versions (via the tfenv-like "},{"type":"text","text":"terraform_version","marks":[{"type":"code"}]},{"type":"text","text":" field), run custom pre/post hooks, and scope applies to specific directories. It supports Terragrunt, OpenTofu, and policy checks via Conftest."}]},{"type":"paragraph","content":[{"type":"text","text":"Atlantis was originally built at HootSuite in 2017, open sourced in 2018, and became a CNCF sandbox project in 2024. It competes with Terraform Cloud/HCP, Spacelift, env0, and Scalr — the main appeal being that it''s free, self-hosted, and you keep your state and credentials entirely inside your own infrastructure. For teams that just want PR-driven Terraform without a SaaS dependency, it''s the obvious choice."}]}]}' WHERE `id` = 'atlantis';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"AWS Lambda is Amazon''s flagship serverless compute service and the function-as-a-service offering that effectively defined the category when it launched in 2014. You upload a function, declare its memory and timeout, and Lambda runs it on demand in a managed execution environment, scaling from zero to thousands of concurrent invocations without you provisioning servers, patching operating systems, or sizing fleets. Billing is per-millisecond of execution against the memory you request, so idle code costs nothing."}]},{"type":"paragraph","content":[{"type":"text","text":"The execution model is event-driven. Functions are invoked by events from across the AWS ecosystem (S3 object writes, DynamoDB streams, SQS and Kinesis messages, EventBridge rules, IoT topics, Cognito triggers, and many others) or synchronously through API Gateway, Application Load Balancer, or a Lambda Function URL. Managed runtimes are provided for Node.js, Python, Java, .NET, and Ruby, with the "},{"type":"text","text":"provided.al2023","marks":[{"type":"code"}]},{"type":"text","text":" custom runtime covering Go, Rust, C++, and anything else that can produce a Linux binary. Both x86_64 and ARM64 (Graviton) architectures are supported, and functions can be packaged either as zip archives or as OCI container images up to 10 GB pulled from Amazon ECR, which is the usual route when dependencies are large, such as machine learning models or scientific libraries."}]},{"type":"paragraph","content":[{"type":"text","text":"Cold starts are the headline operational concern: the first invocation into a fresh environment pays for container setup and runtime initialisation, typically tens to hundreds of milliseconds for Node.js or Python and longer for the JVM or .NET, though SnapStart materially reduces that for Java, .NET, and Python by restoring a pre-initialised snapshot. Provisioned Concurrency keeps warm environments on standby for latency-sensitive paths at additional cost. Teams reach for Lambda when they want event glue between AWS services, lightweight HTTP APIs fronted by API Gateway or a Function URL, scheduled jobs via EventBridge, or background processing of queues and streams, particularly where traffic is spiky and scale-to-zero economics matter more than the steady-state efficiency of a long-running container."}]}]}' WHERE `id` = 'aws-lambda';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Backstage is an open-source framework for building internal developer portals, originally created at Spotify in 2016 and donated to the CNCF in 2020. At its core it is a TypeScript/React application with a Node.js backend, plus a plugin system that lets you bolt on integrations with the rest of your stack: Kubernetes, GitHub, Jenkins, ArgoCD, PagerDuty, Grafana, Jira, and several hundred others."}]},{"type":"paragraph","content":[{"type":"text","text":"The centerpiece is the Software Catalog — a YAML-driven ("},{"type":"text","text":"catalog-info.yaml","marks":[{"type":"code"}]},{"type":"text","text":" in each repo) registry of components, APIs, systems, resources, and the teams that own them, stored in Postgres and visualized as a graph. On top of that sit two other pillars: Software Templates (a scaffolder that generates new repos/services from golden-path templates using Cookiecutter-style actions) and TechDocs (a docs-as-code system that renders Markdown from each repo into a searchable site using MkDocs). Plugins live inside the monorepo you scaffold from "},{"type":"text","text":"@backstage/create-app","marks":[{"type":"code"}]},{"type":"text","text":" — Backstage is explicitly not a SaaS; you fork it, add plugins, and run your own instance."}]},{"type":"paragraph","content":[{"type":"text","text":"Backstage is effectively the de-facto platform for IDPs in the cloud-native world, and Spotify, Red Hat (Janus/RHDH), Roadie, and others sell managed or opinionated distributions on top of it. The main criticism is fair: it''s a React monorepo you have to own and upgrade, and the learning curve for writing plugins is steep. Alternatives like Port, Cortex, and OpsLevel trade that ownership for a SaaS model."}]}]}' WHERE `id` = 'backstage';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bank-Vaults is a set of tools and a Kubernetes operator that make HashiCorp Vault easier to run on Kubernetes. Operating Vault correctly — auto-unsealing, storing the root keys safely, configuring auth methods and policies in a reproducible way, and getting secrets to applications — is surprisingly fiddly, and Bank-Vaults packages a set of opinions that handle most of it for you."}]},{"type":"paragraph","content":[{"type":"text","text":"The project is built around three main pieces. The Vault Operator deploys and manages Vault clusters from a CRD, including auto-initialization and auto-unseal using KMS keys from AWS, GCP, Azure, or plain Kubernetes Secrets. A mutating webhook injects secrets directly into Pods as environment variables or files by rewriting them at admission time — so application code can use "},{"type":"text","text":"vault:secret/data/mysecret#key","marks":[{"type":"code"}]},{"type":"text","text":" references in its env vars and get the real value at runtime, without needing a Vault-aware SDK or a sidecar. A Go library wraps the Vault API and adds higher-level helpers that the other components share."}]},{"type":"paragraph","content":[{"type":"text","text":"Bank-Vaults was originally built by Banzai Cloud and is now maintained as the "},{"type":"text","text":"bank-vaults","marks":[{"type":"code"}]},{"type":"text","text":" GitHub org; it joined the CNCF sandbox in 2024. It overlaps with Vault''s own official Helm chart and the Vault Secrets Operator from HashiCorp, and with External Secrets Operator for the secret-injection story. Its niche is teams that want a batteries-included, CRD-driven way to run Vault on Kubernetes without writing their own operator."}]}]}' WHERE `id` = 'bank-vaults';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"BFE (Beyond Front End) is a Layer 7 reverse proxy and load balancer written in Go, originally developed at Baidu where it handles the bulk of the company''s front-door traffic — reportedly over a trillion requests per day. It was open sourced in 2019 and donated to the CNCF as a sandbox project in 2020."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally BFE sits in the same category as Nginx, HAProxy, and Envoy: terminate TLS, parse HTTP/HTTPS/HTTP/2/HTTP/3 requests, run them through a rules engine, and forward to a backend cluster. Its distinguishing features are a condition-expression-based routing language ("},{"type":"text","text":"req_host_in(\"example.com\") && req_path_prefix_in(\"/api\")","marks":[{"type":"code"}]},{"type":"text","text":") instead of Nginx-style location blocks, and a modular pluggable filter chain that lets you add request/response processing in Go without forking the proxy. It supports multi-tenancy with per-tenant config, health checks, connection pooling, dynamic config reload, and active/passive backend probing."}]},{"type":"paragraph","content":[{"type":"text","text":"In practice BFE is an interesting alternative if you want an Nginx-class edge proxy written in Go that you can extend in Go, but outside of Baidu and a few other large Chinese deployments adoption is limited. For most teams, Envoy (plus a control plane like Istio or Contour) or Nginx remain the default choices."}]}]}' WHERE `id` = 'bfe';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"bootc (\"bootable containers\") lets you ship and update an entire Linux operating system as an OCI container image. You build a "},{"type":"text","text":"FROM quay.io/fedora/fedora-bootc:41","marks":[{"type":"code"}]},{"type":"text","text":" image, add your own packages and config with normal Dockerfile instructions, push it to a registry, and "},{"type":"text","text":"bootc switch","marks":[{"type":"code"}]},{"type":"text","text":" on the target host pulls and boots it as the root filesystem. Upgrades become "},{"type":"text","text":"bootc upgrade","marks":[{"type":"code"}]},{"type":"text","text":", and rollbacks are just the previous image."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood bootc is built on top of OSTree (the same content-addressed filesystem technology behind Fedora Silverblue and Red Hat CoreOS) but presents a container-native interface instead of the older "},{"type":"text","text":"rpm-ostree","marks":[{"type":"code"}]},{"type":"text","text":" workflow. The host runs a transactional, image-based filesystem where the OS is immutable between reboots; "},{"type":"text","text":"/etc","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"/var","marks":[{"type":"code"}]},{"type":"text","text":" are writable but the rest of the tree is swapped atomically on update. Because the artifact is a standard OCI image, you build, sign, scan, and distribute it with the same tooling as your application containers — Cosign, Trivy, any registry."}]},{"type":"paragraph","content":[{"type":"text","text":"bootc is maintained in the "},{"type":"text","text":"bootc-dev","marks":[{"type":"code"}]},{"type":"text","text":" GitHub org, primarily driven by Red Hat, and became a CNCF sandbox project in 2025. It''s the foundation for Fedora/CentOS/RHEL bootc image modes and a direct conceptual cousin of Flatcar, Talos, and Chainguard''s container-optimized OSes."}]}]}' WHERE `id` = 'bootc';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"bpfman (formerly bpfd) is a system daemon for loading, unloading, and managing eBPF programs on Linux hosts, with a focus on Kubernetes. The problem it solves is that eBPF programs usually want to be loaded directly by the application that uses them, which means every eBPF-using workload needs "},{"type":"text","text":"CAP_BPF","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"CAP_SYS_ADMIN","marks":[{"type":"code"}]},{"type":"text","text":", and multiple programs attaching to the same hook (like XDP on a NIC) can fight for ownership. bpfman centralizes that loading behind a single privileged daemon and exposes a gRPC API to unprivileged clients."}]},{"type":"paragraph","content":[{"type":"text","text":"The daemon is written in Rust on top of Aya (a pure-Rust eBPF library). It can load programs from OCI images — you package your compiled "},{"type":"text","text":".o","marks":[{"type":"code"}]},{"type":"text","text":" file as an OCI artifact, push it to a registry, and bpfman pulls, verifies, and attaches it. On Kubernetes, bpfman runs as a DaemonSet and ships CRDs like "},{"type":"text","text":"XdpProgram","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"TcProgram","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"TracepointProgram","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"UprobeProgram","marks":[{"type":"code"}]},{"type":"text","text":"; a controller reconciles those into gRPC calls to the local daemon on each node. Multiple XDP programs can be multiplexed safely onto the same interface using bpfman''s dispatcher."}]},{"type":"paragraph","content":[{"type":"text","text":"bpfman is a CNCF sandbox project, originally from Red Hat, and is aimed squarely at the \"eBPF on Kubernetes\" problem space that Cilium and Tetragon also operate in — but it''s a layer below them, providing the loader/manager infrastructure rather than a specific networking or observability solution. It''s the closest thing to a standard eBPF program manager for cluster operators."}]}]}' WHERE `id` = 'bpfman';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"BuildKit is the build backend that replaced Docker''s legacy image builder. When you run "},{"type":"text","text":"docker build","marks":[{"type":"code"}]},{"type":"text","text":" on any recent version of Docker, you''re using BuildKit under the hood. It lives in the Moby project and is also the engine behind "},{"type":"text","text":"buildx","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"nerdctl build","marks":[{"type":"code"}]},{"type":"text","text":", earthly, depot.dev, and most of the third-party container build tools in the ecosystem."}]},{"type":"paragraph","content":[{"type":"text","text":"The key idea is LLB (Low-Level Build), an intermediate representation that describes a build as a DAG of filesystem operations. Frontends parse high-level input — Dockerfiles or custom formats — into LLB, and the BuildKit daemon executes that DAG with aggressive parallelism and fine-grained content-addressed caching. Independent stages run concurrently, cache keys are computed per operation from input digests rather than per-line, and cache can be exported to and imported from an OCI registry so CI runners share work. It also supports secret mounts ("},{"type":"text","text":"--mount=type=secret","marks":[{"type":"code"}]},{"type":"text","text":"), SSH forwarding ("},{"type":"text","text":"--mount=type=ssh","marks":[{"type":"code"}]},{"type":"text","text":"), rootless builds, and cross-platform builds via QEMU emulation or remote builders."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally it''s "},{"type":"text","text":"buildkitd","marks":[{"type":"code"}]},{"type":"text","text":" (the daemon, written in Go) plus "},{"type":"text","text":"buildctl","marks":[{"type":"code"}]},{"type":"text","text":" (a thin client), though most users only ever interact with it through "},{"type":"text","text":"docker buildx","marks":[{"type":"code"}]},{"type":"text","text":". Because the Dockerfile frontend is itself pulled from an image ("},{"type":"text","text":"# syntax=docker/dockerfile:1.7","marks":[{"type":"code"}]},{"type":"text","text":"), new Dockerfile features ship independently of the BuildKit release cycle. If you care about build performance, BuildKit is not optional — it''s the baseline."}]}]}' WHERE `id` = 'buildkit';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cloud Native Buildpacks (CNB) turn source code into OCI images without a Dockerfile. You point "},{"type":"text","text":"pack build myapp","marks":[{"type":"code"}]},{"type":"text","text":" at a directory; the buildpack detects the language (Go, Node, Python, Java, Ruby, .NET, PHP, …), installs the right toolchain, compiles the app, and produces a runnable image using a known-good base. The contract is: give me source, I''ll give you an image."}]},{"type":"paragraph","content":[{"type":"text","text":"A CNB build runs through an ordered set of buildpacks against a \"stack\" (a pair of build and run base images). Each buildpack has a "},{"type":"text","text":"detect","marks":[{"type":"code"}]},{"type":"text","text":" phase that decides whether it applies and a "},{"type":"text","text":"build","marks":[{"type":"code"}]},{"type":"text","text":" phase that contributes layers. The lifecycle caches layers by content hash and, crucially, supports rebasing: if only the OS base image changes for a security fix, "},{"type":"text","text":"pack rebase","marks":[{"type":"code"}]},{"type":"text","text":" swaps the bottom layers without rebuilding the app layers, which is something Dockerfile-based images can''t do cheaply. Builds can happen locally via pack, inside Kubernetes via kpack (from the Tanzu team, now the VMware OSS org), or as part of CI."}]},{"type":"paragraph","content":[{"type":"text","text":"Buildpacks originated at Heroku and were redesigned as Cloud Native Buildpacks by Heroku and Pivotal in 2018. They''re a CNCF incubating project and are the image-build mechanism behind Heroku, Cloud Foundry, Google Cloud Run source deploys, and Tanzu Application Platform. For teams that don''t want every repo to own a Dockerfile — especially in a golden-path platform — they''re the cleanest alternative to BuildKit."}]}]}' WHERE `id` = 'buildpacks';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cadence is a durable execution engine built at Uber for writing long-running, fault-tolerant workflows as plain application code. You write a workflow function in Go or Java that calls \"activities\" (your actual side-effecting work — HTTP calls, database writes, etc.), and Cadence records every activity result to persistent storage. If the worker process crashes halfway through, the workflow is replayed from the event history on a new worker and deterministically resumes exactly where it left off. Sleeps can last months, retries are automatic, and failures of any piece are recoverable."}]},{"type":"paragraph","content":[{"type":"text","text":"The server is Go, stores event history in Cassandra, MySQL, or PostgreSQL, and uses a sharded architecture with four service roles (frontend, matching, history, worker). Workers are separate processes running your code, pulling tasks from task lists over gRPC. The workflow determinism requirement means you can''t call "},{"type":"text","text":"time.Now()","marks":[{"type":"code"}]},{"type":"text","text":" or make direct network calls from workflow code — you go through Cadence primitives so the replay is consistent."}]},{"type":"paragraph","content":[{"type":"text","text":"If this sounds like Temporal, that''s because Temporal is a fork of Cadence created in 2019 by the original Cadence team (Maxim Fateev, Samar Abbas) after they left Uber. Temporal has since become the more actively developed and commercially backed of the two, while Cadence continues as an Uber-maintained open source project and joined the CNCF sandbox in 2025. For new projects, most engineers reach for Temporal first; Cadence is mainly relevant if you''re already on it or inside Uber''s ecosystem."}]}]}' WHERE `id` = 'cadence';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Capsule is a Kubernetes operator that implements soft multi-tenancy on a single cluster. Instead of giving each tenant their own cluster or virtual control plane, Capsule introduces a "},{"type":"text","text":"Tenant","marks":[{"type":"code"}]},{"type":"text","text":" CRD that owns a group of namespaces, and a set of policies that constrain what workloads inside those namespaces can do — how many namespaces a tenant can create, which nodes they can schedule on, what storage classes they can use, what ingress hostnames they can claim, and so on."}]},{"type":"paragraph","content":[{"type":"text","text":"It works as a validating/mutating admission webhook plus a controller. When a tenant-owner user creates a namespace, Capsule automatically stamps it with the tenant label, applies the tenant''s ResourceQuotas, LimitRanges, NetworkPolicies, and RBAC, and blocks any resource that would violate tenant boundaries. A tenant owner gets enough RBAC to self-serve namespaces without ever touching cluster-scoped resources directly — which is the core problem: stock Kubernetes RBAC has no notion of \"owner of a group of namespaces\"."}]},{"type":"paragraph","content":[{"type":"text","text":"Capsule is built by Clastix and has been a CNCF sandbox project since 2022. It sits in the same space as vcluster (virtual control planes), HNC (Hierarchical Namespace Controller from sig-multitenancy), and Kiosk. The Capsule approach is lighter-weight than vcluster — one real control plane, policy-enforced tenant boundaries — which is a good fit for internal platforms where hard isolation isn''t required but self-service is."}]}]}' WHERE `id` = 'capsule';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Carina is a Kubernetes CSI driver for local disks. It discovers the local block devices on each node, groups them into LVM volume groups, and then carves PersistentVolumes out of those VGs on demand as logical volumes. The goal is to give stateful workloads like MySQL, PostgreSQL, MongoDB, and Cassandra the raw performance of local NVMe/SSD storage without asking operators to hand-manage PVs."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally Carina ships a CSI controller and a per-node agent. The node agent watches local disks, formats them into one of several named device classes (for example "},{"type":"text","text":"ssd","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"hdd","marks":[{"type":"code"}]},{"type":"text","text":"), and reports capacity back to the control plane. When a PVC requests a Carina storage class, the scheduler extender co-locates the pod with a node that has enough free capacity in the right device class, and the agent creates the LV and bind-mounts it into the pod. It also supports raw block volumes, volume expansion, bcache-based tiered storage, and disk failure detection."}]},{"type":"paragraph","content":[{"type":"text","text":"Carina was originally built at Bocloud, open sourced in 2021, and entered the CNCF sandbox in 2022. In the local-storage space it competes with TopoLVM (which is a close conceptual cousin, also LVM-based), OpenEBS LocalPV, and the upstream Kubernetes Local Persistent Volume feature. Activity has been relatively quiet recently; TopoLVM is the more popular choice for new deployments."}]}]}' WHERE `id` = 'carina';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cartography crawls your cloud and SaaS inventory and loads it into a Neo4j graph database so you can query the relationships with Cypher. It was open sourced by Lyft''s security team in 2019 to answer questions that are painful in flat tabular asset inventories — things like \"which IAM principals can assume a role that has access to this S3 bucket\" or \"which GitHub users have write access to a repo whose CI deploys to this Kubernetes namespace\"."}]},{"type":"paragraph","content":[{"type":"text","text":"Cartography is written in Python and works by running \"intel modules\" on a schedule. Each module calls a provider''s API (AWS, GCP, Azure, Okta, GitHub, Kubernetes, CrowdStrike, Duo, Snowflake, Tailscale, and dozens more) and MERGEs the results into Neo4j as nodes and relationships. Once the graph is populated, you ask questions with Cypher: "},{"type":"text","text":"MATCH (u:GitHubUser)-[:MEMBER_OF]->(t:GitHubTeam)-[:ADMIN]->(r:GitHubRepository) RETURN u, r","marks":[{"type":"code"}]},{"type":"text","text":". Cartography ships an analysis job runner that can execute canned Cypher queries on a schedule and emit findings."}]},{"type":"paragraph","content":[{"type":"text","text":"The project moved from Lyft to the CNCF as a sandbox project in 2024. It''s one of the foundational tools in the modern attack-surface-management and \"cloud security graph\" space — commercial tools like Wiz, Orca, and Steampipe solve similar problems, but Cartography is the open-source option and is frequently used as a building block by security teams who want to write their own detections."}]}]}' WHERE `id` = 'cartography';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Carvel is a suite of single-purpose Unix-style CLI tools for configuring, packaging, and deploying applications to Kubernetes. It came out of VMware Tanzu (originally as "},{"type":"text","text":"k14s","marks":[{"type":"code"}]},{"type":"text","text":") and is a deliberate alternative to the \"one big tool\" approach of Helm: each Carvel tool does one job, reads and writes plain files, and composes with the others through pipes."}]},{"type":"paragraph","content":[{"type":"text","text":"The core tools are "},{"type":"text","text":"ytt","marks":[{"type":"code"}]},{"type":"text","text":", a YAML templating language based on Starlark that operates on parsed YAML documents instead of raw text (so you can''t generate invalid YAML by accident); "},{"type":"text","text":"kapp","marks":[{"type":"code"}]},{"type":"text","text":", a deployer that computes a diff between a set of manifests and live cluster state, groups resources into a labeled \"app\", orders changes by type, and waits on readiness — effectively a safer "},{"type":"text","text":"kubectl apply","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"kbld","marks":[{"type":"code"}]},{"type":"text","text":", which resolves image references to immutable digests and rewrites manifests accordingly; "},{"type":"text","text":"imgpkg","marks":[{"type":"code"}]},{"type":"text","text":", which bundles a directory of configuration plus all the images it references into a single OCI artifact; and "},{"type":"text","text":"vendir","marks":[{"type":"code"}]},{"type":"text","text":", which declaratively syncs external sources (Git repos, Helm charts, HTTP tarballs) into a "},{"type":"text","text":"vendor/","marks":[{"type":"code"}]},{"type":"text","text":" directory. "},{"type":"text","text":"kapp-controller","marks":[{"type":"code"}]},{"type":"text","text":" runs the same machinery inside a cluster as a GitOps-style operator with "},{"type":"text","text":"App","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"PackageInstall","marks":[{"type":"code"}]},{"type":"text","text":" CRDs."}]},{"type":"paragraph","content":[{"type":"text","text":"Carvel joined the CNCF sandbox in 2022. In practice it sits alongside Helm and Kustomize as a third option for Kubernetes configuration: you reach for it when you''ve been burned by Helm''s text-based templating or want a stricter, more auditable pipeline from source YAML to live cluster. It''s the packaging system underneath Tanzu Kubernetes Grid and Tanzu Community Edition."}]}]}' WHERE `id` = 'carvel';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"cdk8s (Cloud Development Kit for Kubernetes) lets you define Kubernetes resources in TypeScript, Python, Java, or Go instead of YAML, and then synthesizes the result to plain manifests you can apply with "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":" or any GitOps tool. It was created at AWS by the same team behind the AWS CDK, open sourced in 2020, and donated to the CNCF sandbox shortly after."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood cdk8s uses the Constructs Programming Model (the same "},{"type":"text","text":"constructs","marks":[{"type":"code"}]},{"type":"text","text":" library that powers AWS CDK and Terraform CDK). You import type-safe classes generated from the Kubernetes OpenAPI spec — "},{"type":"text","text":"Deployment","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Service","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Ingress","marks":[{"type":"code"}]},{"type":"text","text":" — instantiate them as a tree of constructs, and call "},{"type":"text","text":"app.synth()","marks":[{"type":"code"}]},{"type":"text","text":" to produce YAML in "},{"type":"text","text":"dist/","marks":[{"type":"code"}]},{"type":"text","text":". Because it''s real code, you get a real type checker, real tests, real loops and conditionals, and real IDE autocomplete against the Kubernetes API. The "},{"type":"text","text":"cdk8s+","marks":[{"type":"code"}]},{"type":"text","text":" library provides higher-level abstractions (e.g. "},{"type":"text","text":"WebService","marks":[{"type":"code"}]},{"type":"text","text":") that compose multiple primitives."}]},{"type":"paragraph","content":[{"type":"text","text":"cdk8s occupies the same slot as Pulumi (Kubernetes provider), Helm, Kustomize, and jsonnet-based tools like Tanka. Its distinguishing trait is that it is pure code-to-YAML — nothing runs in the cluster, there''s no state, no lock-in. That makes it a pragmatic choice if you already write TypeScript or Python and want strong typing over Kubernetes manifests without adopting a full IaC tool. It''s also the easiest way to build reusable, shareable abstractions over Kubernetes resources for an internal platform team."}]}]}' WHERE `id` = 'cdk8s';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"cert-manager is a Kubernetes controller that issues and renews X.509 certificates automatically. You create a "},{"type":"text","text":"Certificate","marks":[{"type":"code"}]},{"type":"text","text":" resource describing the hostnames you want, point it at an "},{"type":"text","text":"Issuer","marks":[{"type":"code"}]},{"type":"text","text":" (Let''s Encrypt, Vault, Venafi, an internal CA, or a self-signed CA), and cert-manager handles CSR generation, ACME challenges, renewal before expiry, and storage of the resulting key/cert pair in a Kubernetes Secret. An ingress annotation is usually enough to TLS-enable an entire application."}]},{"type":"paragraph","content":[{"type":"text","text":"The architecture is a set of CRDs — "},{"type":"text","text":"Issuer","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"ClusterIssuer","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Certificate","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"CertificateRequest","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Order","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Challenge","marks":[{"type":"code"}]},{"type":"text","text":" — reconciled by a controller written in Go. ACME support includes both HTTP-01 (via an ingress shim that creates solver pods) and DNS-01 across most major DNS providers (Route53, Cloud DNS, Cloudflare, Azure DNS, RFC2136, and many more). Beyond ACME, it plugs into Vault PKI, Google CA Service, AWS Private CA, Venafi TPP/Cloud, and "},{"type":"text","text":"step-ca","marks":[{"type":"code"}]},{"type":"text","text":". The "},{"type":"text","text":"trust-manager","marks":[{"type":"code"}]},{"type":"text","text":" sub-project distributes CA bundles cluster-wide."}]},{"type":"paragraph","content":[{"type":"text","text":"cert-manager started at Jetstack in 2017, became a CNCF sandbox project in 2020, and graduated in September 2024. It is the de-facto standard for TLS on Kubernetes — if your cluster runs an ingress controller or a service mesh with mTLS, there is an overwhelming chance cert-manager is issuing its certificates. Alternatives like SPIRE exist but target a different problem (workload identity) rather than PKI for HTTPS."}]}]}' WHERE `id` = 'cert-manager';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ChaosBlade is a chaos engineering toolkit originally built at Alibaba from the lessons of their internal MonkeyKing fault-injection system. It''s distributed as a single "},{"type":"text","text":"blade","marks":[{"type":"code"}]},{"type":"text","text":" CLI that can inject a wide catalog of faults into Linux hosts, JVM applications, Docker and containerd containers, Kubernetes clusters, and cloud resources — CPU load, memory pressure, disk fill, network latency and loss, process kill, file corruption, JVM method exceptions and delays, and database query faults among them."}]},{"type":"paragraph","content":[{"type":"text","text":"The core is Go, with language-specific agents where needed. For Linux OS-level faults it wraps utilities like "},{"type":"text","text":"tc","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"stress-ng","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"iptables","marks":[{"type":"code"}]},{"type":"text","text":" behind a unified grammar. For JVM faults, a Java agent uses bytecode instrumentation to inject exceptions or delays into specific methods without restarting the application. For Kubernetes, a "},{"type":"text","text":"chaosblade-operator","marks":[{"type":"code"}]},{"type":"text","text":" exposes "},{"type":"text","text":"ChaosBlade","marks":[{"type":"code"}]},{"type":"text","text":" CRDs so you can describe experiments declaratively and target pods via label selectors."}]},{"type":"paragraph","content":[{"type":"text","text":"ChaosBlade joined the CNCF sandbox in 2021. In the chaos engineering space it sits next to Chaos Mesh (also CNCF, more Kubernetes-native and with a richer UI), LitmusChaos, and the commercial Gremlin. ChaosBlade''s strongest points are the breadth of OS-level fault types and the JVM bytecode injection, which matches Alibaba''s Java-heavy stack. Outside of JVM-dominated environments, most new adopters pick Chaos Mesh or Litmus instead."}]}]}' WHERE `id` = 'chaosblade';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Chaos Mesh is a Kubernetes-native chaos engineering platform originally built at PingCAP to stress-test TiDB. You describe experiments as CRDs — "},{"type":"text","text":"NetworkChaos","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"PodChaos","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"IOChaos","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"StressChaos","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"TimeChaos","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"DNSChaos","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"HTTPChaos","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"KernelChaos","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"JVMChaos","marks":[{"type":"code"}]},{"type":"text","text":" — pick targets with label selectors, and the controller applies the fault to matching pods for a specified duration or on a cron schedule. There''s also a web dashboard (Chaos Dashboard) and a YAML-based "},{"type":"text","text":"Workflow","marks":[{"type":"code"}]},{"type":"text","text":" CRD for building multi-step experiments."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood the implementation is interesting. Network chaos uses "},{"type":"text","text":"tc","marks":[{"type":"code"}]},{"type":"text","text":" and iptables via a privileged chaos-daemon DaemonSet on each node. I/O chaos uses a FUSE sidecar that mirrors the container''s filesystem and injects latency or errors on selected paths. Time chaos uses eBPF and "},{"type":"text","text":"LD_PRELOAD","marks":[{"type":"code"}]},{"type":"text","text":" to shift the monotonic clock for a specific process without affecting the rest of the host. JVM chaos uses bytecode instrumentation via Byteman. DNS chaos intercepts DNS queries by replacing the pod''s DNS config with a custom resolver. None of this requires changes to the target application."}]},{"type":"paragraph","content":[{"type":"text","text":"Chaos Mesh was donated to the CNCF in 2020 and became an incubating project in 2022. In the chaos engineering landscape it and LitmusChaos are the two leading Kubernetes-native options; ChaosBlade is a close cousin with broader OS-level reach, and Gremlin is the commercial alternative. If you''re on Kubernetes and want declarative, CRD-driven chaos experiments, Chaos Mesh is the most full-featured open source choice."}]}]}' WHERE `id` = 'chaosmesh';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cilium is a CNI plugin for Kubernetes that uses eBPF to implement networking, load balancing, observability, and security directly in the Linux kernel. Instead of iptables chains and kube-proxy, Cilium attaches eBPF programs at tc, XDP, and socket hooks to route packets between pods, enforce NetworkPolicy, and load-balance Services. On kernels with sufficient support it can replace kube-proxy entirely."}]},{"type":"paragraph","content":[{"type":"text","text":"The implementation centers on a per-node agent ("},{"type":"text","text":"cilium-agent","marks":[{"type":"code"}]},{"type":"text","text":", written in Go) that compiles and loads eBPF programs, and a set of CRDs: "},{"type":"text","text":"CiliumNetworkPolicy","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"CiliumClusterwideNetworkPolicy","marks":[{"type":"code"}]},{"type":"text","text":" add Layer 7 (HTTP, Kafka, gRPC, DNS) policy on top of standard NetworkPolicy; "},{"type":"text","text":"CiliumEndpoint","marks":[{"type":"code"}]},{"type":"text","text":" tracks per-pod identity; "},{"type":"text","text":"CiliumBGPPeeringPolicy","marks":[{"type":"code"}]},{"type":"text","text":" speaks BGP directly from the node for integration with physical networks. Hubble is the observability layer — it taps the same eBPF datapath to produce flow logs, service maps, and metrics with near-zero overhead. Cluster Mesh connects multiple Kubernetes clusters into a single service namespace, and the Cilium Service Mesh provides sidecarless mTLS and L7 traffic management using the Envoy proxy embedded in the agent."}]},{"type":"paragraph","content":[{"type":"text","text":"Cilium graduated from the CNCF in October 2023 and is the CNI underneath GKE Dataplane V2, EKS, AKS Azure CNI Powered by Cilium, and most new self-managed clusters. It competes with Calico, Flannel, and Antrea; in practice it has become the default choice for anyone building a new Kubernetes cluster today because of the combined networking, observability, and security story that eBPF enables. The commercial sponsor is Isovalent, acquired by Cisco in 2024."}]}]}' WHERE `id` = 'cilium';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Civo is a UK-based cloud provider that positions itself squarely at developers, with a product surface and pricing model built around predictability and low operational overhead rather than the breadth of a hyperscaler. The company runs its own data centres and exposes infrastructure through a web console, a REST API, and a first-party CLI, with a deliberate focus on keeping the path from sign-up to running workload as short as possible."}]},{"type":"paragraph","content":[{"type":"text","text":"The flagship product is managed Kubernetes built on K3s, the lightweight distribution originally created at Rancher. Because K3s has a much smaller control-plane footprint than upstream Kubernetes, Civo is able to provision new clusters in around 90 seconds, and it offers the control plane at no charge so customers pay only for the underlying worker nodes, volumes, and any optional add-ons. Pricing across the platform is published as flat monthly or hourly rates with no egress or ingress fees, which makes cost modelling straightforward and removes the data-transfer surprises common with the larger clouds."}]},{"type":"paragraph","content":[{"type":"text","text":"Around Kubernetes, Civo offers a familiar set of supporting services: compute instances, block and object storage (with an S3-compatible API), managed databases, load balancers, and DNS. For AI and ML workloads it provides GPU compute on NVIDIA A100 hardware, along with newer Blackwell-class options, and it also markets a private-cloud product, CivoStack, for organisations that want the same operational model on their own infrastructure."}]}]}' WHERE `id` = 'civo';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cloud Run is Google Cloud''s managed serverless container platform, originally built on the Knative Serving API. It accepts any container image that listens for HTTP requests on a configurable port, so the runtime, language, and dependency story is entirely up to the image. Workloads scale automatically from zero to many instances based on inbound concurrency, and with request-based billing you are only charged for CPU and memory while a container is actively handling a request, metered at 100ms granularity."}]},{"type":"paragraph","content":[{"type":"text","text":"The product exposes two distinct workload shapes. A Service is a long-lived, request-driven deployment that can scale to zero and sits behind an HTTPS URL with revision-based traffic splitting inherited from Knative. A Job runs a container to completion for batch or scheduled work, is always instance-billed for the full execution time, and does not scale to zero in the same way. Underneath, workloads run in one of two execution environments: the first-generation gVisor sandbox, which gives faster cold starts and a smaller attack surface but reimplements syscalls in user space, and the second-generation gVisor-on-microVM environment, which provides a full Linux kernel, better CPU and network performance, and broader compatibility at the cost of slower starts."}]},{"type":"paragraph","content":[{"type":"text","text":"Cloud Run sits deliberately between Lambda-style FaaS and a full Kubernetes cluster. You bring a container instead of a function, but you do not run, patch, or scale the underlying nodes, and you do not write Deployments or Services. Because the surface area is the Knative Serving API, manifests remain largely portable: the same descriptor can target managed Cloud Run, Cloud Run on GKE, or a self-hosted Knative installation on any conformant cluster, which keeps an escape hatch open even though the day-to-day experience is fully managed by Google."}]}]}' WHERE `id` = 'cloud-run';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cloud Custodian (\"c7n\") is a policy-as-code engine for enforcing compliance, cost, and security rules against cloud resources. You write YAML policies that select resources with JMESPath-like filters — \"EBS volumes that are unencrypted\", \"S3 buckets without versioning\", \"EC2 instances older than 30 days with the "},{"type":"text","text":"env=dev","marks":[{"type":"code"}]},{"type":"text","text":" tag\" — and specify actions to take: tag, notify, stop, terminate, snapshot, delete. Custodian then scans the account and applies the policy."}]},{"type":"paragraph","content":[{"type":"text","text":"It was originally built at Capital One in 2016 and is written in Python. The architecture is straightforward: a rules engine that maps policy YAML to provider APIs. It started as AWS-only and now also has solid support for Azure, GCP, Kubernetes, Tencent Cloud, and OCI, with varying coverage. Policies can run in \"pull\" mode from a CI/CD job or an EC2 instance, but the more interesting mode is \"push\" — Custodian compiles the policy into a Lambda function triggered by CloudTrail events or EventBridge, so noncompliant resources are caught and remediated seconds after creation. Output goes to S3, CloudWatch, or a SIEM."}]},{"type":"paragraph","content":[{"type":"text","text":"Cloud Custodian joined the CNCF sandbox in 2020 and moved to incubating in 2022. It overlaps with Prowler, Steampipe, and AWS Config rules on the detection side and with AWS Lambda automation patterns on the remediation side. Its niche is very clear: if you want to write declarative YAML rules that both detect and fix cloud misconfigurations without building a custom Lambda pipeline per rule, this is the mature, battle-tested option."}]}]}' WHERE `id` = 'cloudcustodian';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CloudEvents is a specification — not a piece of software — that defines a common envelope for describing event data. Every event has a small set of required attributes ("},{"type":"text","text":"id","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"source","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"specversion","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"type","marks":[{"type":"code"}]},{"type":"text","text":") and optional ones ("},{"type":"text","text":"subject","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"time","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"datacontenttype","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"dataschema","marks":[{"type":"code"}]},{"type":"text","text":"), plus an opaque "},{"type":"text","text":"data","marks":[{"type":"code"}]},{"type":"text","text":" payload. That''s it. The whole spec fits in a short document; the value is that any producer and any consumer can agree on how to identify, route, and deduplicate an event without negotiating a bespoke schema."}]},{"type":"paragraph","content":[{"type":"text","text":"The spec defines bindings for how events are carried over different protocols: HTTP (binary mode puts attributes in headers, structured mode puts the whole envelope in the body), Kafka (headers + key), AMQP, MQTT, NATS, and WebSockets. It also defines a JSON format for serialization and extensions like "},{"type":"text","text":"partitionkey","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"traceparent","marks":[{"type":"code"}]},{"type":"text","text":" (W3C Trace Context), and "},{"type":"text","text":"sequence","marks":[{"type":"code"}]},{"type":"text","text":". Reference SDKs exist for Go, Java, JavaScript, Python, C#, Rust, Ruby, and PHP."}]},{"type":"paragraph","content":[{"type":"text","text":"CloudEvents is the event format used by Knative Eventing, Argo Events, AWS EventBridge (for partner events), Azure Event Grid, Google Eventarc, and essentially every CNCF project that emits events. It graduated from the CNCF in January 2024. Adopting it costs almost nothing — you set a few headers on an HTTP POST — and it pays off the first time you need to route events through a broker or build a consumer that isn''t tightly coupled to one producer''s schema. If you''re designing a service that emits events, there''s no good reason not to use it."}]}]}' WHERE `id` = 'cloudevents';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CloudNativePG is a Kubernetes operator for running PostgreSQL in production. You create a "},{"type":"text","text":"Cluster","marks":[{"type":"code"}]},{"type":"text","text":" resource describing the Postgres version, instance count, storage, and backup configuration, and the operator provisions a primary and replicas, handles streaming replication, performs fast failover on primary loss, runs continuous physical base backups and WAL archiving to S3-compatible object storage, and can do point-in-time recovery to a new cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"What makes it architecturally interesting is that it doesn''t use a separate high-availability agent like Patroni or Stolon. The operator itself (running in its own namespace) is the control loop, and every Postgres pod runs an instance manager that acts as both PID 1 and the replication client. Primary selection is driven by Kubernetes API state rather than a separate DCS — etcd is already the DCS. It uses standard Postgres streaming replication, supports synchronous and quorum-based replication, and integrates with Barman for WAL archiving. Connection pooling via PgBouncer, pg_rewind-based reattachment after failover, and rolling minor-version upgrades are all first class."}]},{"type":"paragraph","content":[{"type":"text","text":"CloudNativePG was created by EDB and donated to the CNCF as a sandbox project in 2025. In the Postgres-on-Kubernetes space it competes with Zalando''s postgres-operator, Crunchy Data''s PGO, StackGres, and Kubegres. CloudNativePG has become the most actively developed and is rapidly becoming the default community choice, especially for teams that don''t want to pay for a commercial distribution."}]}]}' WHERE `id` = 'cloudnativepg';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cluster API (CAPI) is a Kubernetes SIG project that uses Kubernetes CRDs and controllers to manage the lifecycle of Kubernetes clusters themselves. You run a \"management cluster\" with CAPI installed, then create "},{"type":"text","text":"Cluster","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Machine","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"MachineDeployment","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"KubeadmControlPlane","marks":[{"type":"code"}]},{"type":"text","text":" resources to describe the workload clusters you want. Controllers reconcile those resources into real infrastructure and kubeadm-bootstrapped nodes."}]},{"type":"paragraph","content":[{"type":"text","text":"The power of CAPI is that the infrastructure side is pluggable. A provider implements "},{"type":"text","text":"InfrastructureProvider","marks":[{"type":"code"}]},{"type":"text","text":" contracts to create machines and networks on a specific platform, and there are mature providers for AWS (CAPA), Azure (CAPZ), GCP (CAPG), vSphere (CAPV), OpenStack, Equinix Metal, MAAS, Nutanix, Proxmox, Hetzner, and many more. Bootstrap providers (usually kubeadm) turn raw machines into Kubernetes nodes; control plane providers manage the etcd/API server lifecycle and handle rolling upgrades of the control plane by replacing nodes one at a time. Upgrades are declarative — bump the "},{"type":"text","text":"version","marks":[{"type":"code"}]},{"type":"text","text":" field, CAPI rolls the control plane and then the worker MachineDeployments."}]},{"type":"paragraph","content":[{"type":"text","text":"CAPI is the machinery behind Tanzu Kubernetes Grid, Rancher (RKE2 via CAPI), OpenShift Hosted Control Planes, Kubermatic, and many internal \"cluster-as-a-service\" platforms. If you need to manage more than a handful of Kubernetes clusters across heterogeneous infrastructure, it''s the standard answer — the alternative is writing Terraform per provider and gluing it together with bash, which is exactly the problem CAPI exists to solve."}]}]}' WHERE `id` = 'cluster-api';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Clusternet is a multi-cluster management and application distribution platform for Kubernetes. It lets you manage a fleet of \"child\" clusters from a single \"parent\" cluster — including child clusters sitting behind NAT or firewalls where the parent can''t reach them directly — and schedule applications across them with a pluggable scheduler and declarative subscription model."}]},{"type":"paragraph","content":[{"type":"text","text":"The unusual architectural choice is the reverse tunnel. Each child cluster runs a "},{"type":"text","text":"clusternet-agent","marks":[{"type":"code"}]},{"type":"text","text":" that registers itself with the parent and establishes an outbound websocket tunnel. The parent then exposes each child''s API server at a path on the parent''s aggregated API server, so "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":" against the parent (with a context switch via the "},{"type":"text","text":"kubectl cluster-info","marks":[{"type":"code"}]},{"type":"text","text":" shim) can reach any child without any inbound connectivity on the child side. On top of that, a "},{"type":"text","text":"Subscription","marks":[{"type":"code"}]},{"type":"text","text":" CRD describes \"deploy these manifests / Helm charts / kustomizations to these clusters selected by labels\", and a scheduler handles spreading, placement constraints, and dynamic rebalancing."}]},{"type":"paragraph","content":[{"type":"text","text":"Clusternet has been a CNCF sandbox project since 2023. Its peers are Karmada (also a CNCF project, fleet scheduling focused), Open Cluster Management, KubeFed (effectively deprecated), and Rancher''s Fleet. Clusternet''s specific strength is the reverse-tunnel model, which is genuinely useful for edge deployments where child clusters run inside customer networks; for pure cloud fleets, Karmada has seen broader adoption."}]}]}' WHERE `id` = 'clusternet';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Clusterpedia is a multi-cluster search engine for Kubernetes resources. It aggregates resources from many clusters into a single, queryable store so you can run complex searches, list, and watch across fleets without hitting each cluster''s API server directly."}]},{"type":"paragraph","content":[{"type":"text","text":"It works by running a set of controllers (ClusterSynchro Manager) that connect to registered "},{"type":"text","text":"PediaCluster","marks":[{"type":"code"}]},{"type":"text","text":" resources, pull their resources, and persist them into a storage layer backed by a relational database (MySQL or PostgreSQL) or other pluggable backends. A custom API server then exposes a Kubernetes-compatible API under the "},{"type":"text","text":"clusterpedia.io","marks":[{"type":"code"}]},{"type":"text","text":" group, letting you use "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":" with extra search parameters like label selectors, field selectors, fuzzy name matching, pagination, and SQL-style ordering that the upstream API server does not support."}]},{"type":"paragraph","content":[{"type":"text","text":"In practice, Clusterpedia fills a gap that tools like Karmada and Open Cluster Management leave open: they federate workloads, but searching resources across clusters still requires fanning out queries. Clusterpedia is purpose-built for the read path — inventory, audit, and debugging across tens or hundreds of clusters — and supports both \"real-time\" (proxy to live cluster) and \"cached\" query modes depending on whether you want consistency or speed."}]}]}' WHERE `id` = 'clusterpedia';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Distribution is the reference implementation of the OCI Distribution Specification — the HTTP API used to pull and push container images. It is the codebase that originally shipped as Docker Registry v2, donated to the CNCF in 2018, and today powers the official "},{"type":"text","text":"registry:3","marks":[{"type":"code"}]},{"type":"text","text":" image."}]},{"type":"paragraph","content":[{"type":"text","text":"Written in Go, Distribution implements the "},{"type":"text","text":"/v2/","marks":[{"type":"code"}]},{"type":"text","text":" REST API for manifests, blobs, tags, and uploads, with pluggable storage drivers for filesystem, S3, GCS, Azure Blob, and Swift. Content is addressed by SHA-256 digest, making image layers deduplicated and immutable. It supports OCI image and artifact manifests, image indexes for multi-arch images, and — as of recent releases — the referrers API used by Sigstore and in-toto attestations."}]},{"type":"paragraph","content":[{"type":"text","text":"Distribution is deliberately minimal: no auth backend, no UI, no vulnerability scanning. Those concerns are layered on by downstream projects like Harbor (which embeds Distribution), Zot, or managed registry services. If you need a plain, standards-compliant registry to run in a pipeline or airgap, this is the one."}]}]}' WHERE `id` = 'cncf-distribution';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Container Network Interface (CNI) is a specification and set of libraries for configuring network interfaces in Linux containers. Originally built by CoreOS for rkt, it is now the networking plugin API used by Kubernetes, OpenShift, Cloud Foundry, Mesos, containerd, CRI-O, Podman, and Kata Containers."}]},{"type":"paragraph","content":[{"type":"text","text":"The contract is deliberately tiny. A runtime calls a CNI plugin binary with a JSON config on stdin and a command ("},{"type":"text","text":"ADD","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"DEL","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"CHECK","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"GC","marks":[{"type":"code"}]},{"type":"text","text":") plus environment variables identifying the container''s network namespace. The plugin sets up (or tears down) the interface — creating veth pairs, bridges, routes, IPAM allocations — and returns a JSON result describing IPs and DNS. Plugins can be chained: a typical Kubernetes node runs an IPAM plugin ("},{"type":"text","text":"host-local","marks":[{"type":"code"}]},{"type":"text","text":") followed by a main plugin ("},{"type":"text","text":"bridge","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ptp","marks":[{"type":"code"}]},{"type":"text","text":") and a "},{"type":"text","text":"portmap","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"bandwidth","marks":[{"type":"code"}]},{"type":"text","text":" plugin."}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"containernetworking/cni","marks":[{"type":"code"}]},{"type":"text","text":" repo ships the spec and libcni; "},{"type":"text","text":"containernetworking/plugins","marks":[{"type":"code"}]},{"type":"text","text":" ships the reference plugins ("},{"type":"text","text":"bridge","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"macvlan","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ipvlan","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"host-local","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"loopback","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"portmap","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"bandwidth","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"firewall","marks":[{"type":"code"}]},{"type":"text","text":"). In production, most Kubernetes clusters run a higher-level CNI implementation instead: Cilium, Calico, Flannel, Weave, or the AWS/Azure/GCP cloud-provider plugins. CNI itself is the thin interface that lets all of them plug into the same runtime."}]}]}' WHERE `id` = 'cni';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Comtrya is a dotfiles and workstation configuration manager written in Rust. It is aimed squarely at the problem of setting up a new laptop — installing packages, symlinking dotfiles, cloning repos, configuring macOS defaults — without the weight of Ansible, Chef, or Puppet."}]},{"type":"paragraph","content":[{"type":"text","text":"Configuration is declared as YAML \"manifests\" containing a list of actions: "},{"type":"text","text":"package.install","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"file.link","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"file.copy","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"directory.create","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"command.run","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"git.clone","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"user.group","marks":[{"type":"code"}]},{"type":"text","text":", and more. Manifests declare dependencies on other manifests so Comtrya resolves them into a DAG and runs them in order. Package actions abstract over the underlying manager (Homebrew, apt, dnf, pacman, winget), so the same manifest can target macOS, Linux, and Windows with per-OS overrides via Tera templating."}]},{"type":"paragraph","content":[{"type":"text","text":"Comtrya sits in the same niche as chezmoi, Nix Home Manager, and yadm, but trades Nix-level reproducibility for a lighter, more imperative model that feels closer to Ansible playbooks. It is a hobby-scale project — originally created by David Flanagan (Rawkode) — and best suited to individual workstation bootstrapping rather than fleet management."}]}]}' WHERE `id` = 'comtrya';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Confidential Containers (CoCo) is a project that runs unmodified Kubernetes Pods inside hardware Trusted Execution Environments (TEEs) such as Intel TDX, AMD SEV-SNP, IBM Secure Execution, and ARM CCA. The goal is to protect workloads and their data from the host operating system, hypervisor, and cluster administrator — the cloud provider can run your Pod without being able to read its memory."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally, CoCo builds on Kata Containers: each Pod runs inside a lightweight VM, and CoCo extends Kata so that VM is launched inside a TEE. An in-guest "},{"type":"text","text":"agent","marks":[{"type":"code"}]},{"type":"text","text":" pulls container images directly into the encrypted VM (rather than trusting the host to unpack them), decrypts them using keys released only after remote attestation, and starts them under a container runtime. The trust root is the Key Broker Service (KBS) and Attestation Service: they verify TEE evidence from the guest and only then release image decryption keys, signed-image verification policies, and secrets."}]},{"type":"paragraph","content":[{"type":"text","text":"On the Kubernetes side, CoCo plugs in as a "},{"type":"text","text":"RuntimeClass","marks":[{"type":"code"}]},{"type":"text","text":" (e.g. "},{"type":"text","text":"kata-qemu-tdx","marks":[{"type":"code"}]},{"type":"text","text":"), so existing workloads opt in per-Pod without application changes. It is still a young area with significant performance and tooling trade-offs, but it is the main upstream effort to make confidential computing usable through standard Kubernetes APIs."}]}]}' WHERE `id` = 'confidential-containers';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Connect is an RPC framework from Buf that uses Protobuf schemas but runs over plain HTTP/1.1, HTTP/2, and HTTP/3 — without the gRPC wire protocol''s hard dependency on HTTP/2 trailers. A Connect server speaks three protocols simultaneously on the same endpoint: Connect''s own protocol (which works through any HTTP proxy, browser "},{"type":"text","text":"fetch","marks":[{"type":"code"}]},{"type":"text","text":", and curl), gRPC, and gRPC-Web. Clients can pick whichever they need."}]},{"type":"paragraph","content":[{"type":"text","text":"The practical win is that you get one "},{"type":"text","text":".proto","marks":[{"type":"code"}]},{"type":"text","text":" file, one generated service interface, and a single handler that any client can call: a Go backend, a TypeScript web app using "},{"type":"text","text":"@connectrpc/connect-web","marks":[{"type":"code"}]},{"type":"text","text":", a Swift iOS app, or a regular gRPC client. Unary calls look like JSON or Protobuf POSTs with predictable status codes, so they''re debuggable with "},{"type":"text","text":"curl","marks":[{"type":"code"}]},{"type":"text","text":" and cacheable by CDNs. Streaming uses enveloped messages over a single HTTP body. There are official implementations for Go ("},{"type":"text","text":"connect-go","marks":[{"type":"code"}]},{"type":"text","text":"), TypeScript/JavaScript ("},{"type":"text","text":"connect-es","marks":[{"type":"code"}]},{"type":"text","text":"), Swift, Kotlin, and Python."}]},{"type":"paragraph","content":[{"type":"text","text":"Connect exists because gRPC-Web required a translating proxy (Envoy) in front of gRPC services to be callable from browsers, and because the gRPC protocol itself is awkward to debug. It''s a pragmatic alternative to gRPC for teams that are all-in on Protobuf but want browser reachability and simpler ops."}]}]}' WHERE `id` = 'connect-rpc';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"containerd is the daemon that actually runs containers on most Kubernetes nodes today. It pulls OCI images, unpacks them into snapshots, sets up mounts and namespaces, hands execution off to an OCI runtime like "},{"type":"text","text":"runc","marks":[{"type":"code"}]},{"type":"text","text":", and supervises the resulting processes. Originally extracted from Docker in 2017 and donated to the CNCF, it became a graduated project in 2019 and is now the default runtime in GKE, EKS, AKS, and almost every managed Kubernetes distribution since Kubernetes deprecated the "},{"type":"text","text":"dockershim","marks":[{"type":"code"}]},{"type":"text","text":" in 1.24."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally, containerd is a gRPC daemon exposing services for images, containers, snapshots, tasks, events, and content. The "},{"type":"text","text":"cri","marks":[{"type":"code"}]},{"type":"text","text":" plugin implements the Kubernetes Container Runtime Interface, so the kubelet talks directly to containerd without an intermediate Docker shim. Images are stored content-addressed in the "},{"type":"text","text":"content","marks":[{"type":"code"}]},{"type":"text","text":" store, then materialized into snapshots by pluggable snapshotters: "},{"type":"text","text":"overlayfs","marks":[{"type":"code"}]},{"type":"text","text":" by default, with "},{"type":"text","text":"stargz","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"native","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"btrfs","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"zfs","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"devmapper","marks":[{"type":"code"}]},{"type":"text","text":" available for lazy pulls or different storage backends. Containers are launched via a per-container "},{"type":"text","text":"containerd-shim-runc-v2","marks":[{"type":"code"}]},{"type":"text","text":" process that calls "},{"type":"text","text":"runc","marks":[{"type":"code"}]},{"type":"text","text":" and keeps the container alive if containerd itself restarts."}]},{"type":"paragraph","content":[{"type":"text","text":"You rarely interact with containerd directly — the typical entry points are "},{"type":"text","text":"crictl","marks":[{"type":"code"}]},{"type":"text","text":" (CRI-level debugging), "},{"type":"text","text":"ctr","marks":[{"type":"code"}]},{"type":"text","text":" (low-level built-in CLI), or "},{"type":"text","text":"nerdctl","marks":[{"type":"code"}]},{"type":"text","text":" (a Docker-compatible CLI with BuildKit, Compose, and rootless support). Alongside CRI-O, it is one of the two mainstream CRI runtimes; Docker Engine itself embeds containerd underneath."}]}]}' WHERE `id` = 'containerd';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ContainerSSH is an SSH server that launches a fresh container for every incoming SSH session. Instead of granting users accounts on a shared host, each "},{"type":"text","text":"ssh user@host","marks":[{"type":"code"}]},{"type":"text","text":" drops the user into an ephemeral container — configured per-user via a webhook — and destroys it on disconnect."}]},{"type":"paragraph","content":[{"type":"text","text":"On each connection, ContainerSSH calls out to an HTTP authentication server (you implement it) to authenticate the user, then calls a configuration server to decide which image to run, what environment variables to set, and which backend to use. Supported backends are Docker and Kubernetes; in the Kubernetes case each session becomes a Pod. Audit logs can be written in a tamper-evident format and include full session recordings compatible with "},{"type":"text","text":"asciinema","marks":[{"type":"code"}]},{"type":"text","text":" for replay."}]},{"type":"paragraph","content":[{"type":"text","text":"The use cases are niche but real: honeypots, CTF and training platforms, per-customer shell access for SaaS products, and jump hosts where you want zero-trust, zero-persistence sessions. It''s written in Go and was accepted into the CNCF sandbox in 2022. Development has slowed considerably in recent years, so check current maintenance status before relying on it for production."}]}]}' WHERE `id` = 'containerssh';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Contour is a Kubernetes Ingress controller that uses Envoy as its data plane. The Contour control plane watches Kubernetes Ingress, Gateway API, and its own "},{"type":"text","text":"HTTPProxy","marks":[{"type":"code"}]},{"type":"text","text":" CRD, translates those resources into Envoy xDS configuration, and streams it to Envoy Pods over gRPC. Envoy handles the actual L7 traffic."}]},{"type":"paragraph","content":[{"type":"text","text":"Contour was created by Heptio (now VMware/Broadcom) to expose the power of Envoy without making users hand-write Envoy YAML. Its "},{"type":"text","text":"HTTPProxy","marks":[{"type":"code"}]},{"type":"text","text":" CRD fills gaps the original Ingress resource left open — weighted traffic splitting, header and path rewrites, external auth, rate limiting, TLS delegation across namespaces, and inclusion/delegation so platform teams can carve namespaces into subroutes without giving tenants access to the root host. Contour was also one of the first controllers to implement the Kubernetes Gateway API and is a reference implementation."}]},{"type":"paragraph","content":[{"type":"text","text":"In the ecosystem, Contour competes with ingress-nginx, Traefik, HAProxy Ingress, Emissary-ingress (another Envoy-based controller from Ambassador Labs), and Istio/Gloo when used purely as ingress. If you''re already running Envoy or want first-class Gateway API support without pulling in a full service mesh, Contour is the lightweight option."}]}]}' WHERE `id` = 'contour';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Copa (Copacetic) patches known OS-package vulnerabilities in container images without rebuilding them from source. You feed it an image and a vulnerability scan report from Trivy (or a Grype report, or nothing at all for \"update everything\"), and it produces a new image with the affected "},{"type":"text","text":"apt","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"apk","marks":[{"type":"code"}]},{"type":"text","text":", or "},{"type":"text","text":"dnf","marks":[{"type":"code"}]},{"type":"text","text":" packages upgraded in place."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood, Copa uses BuildKit directly: it mounts the target image as a BuildKit rootfs, runs the distro''s package manager inside it against the appropriate upstream repositories, and emits a new image layer containing only the updated package files. Because it never touches the original Dockerfile or rebuilds from scratch, it can patch vendor images, base images you don''t own, and long-lived production images much faster than a full rebuild — typically seconds instead of minutes — and it preserves the original layer structure so downstream signatures and SBOMs remain meaningful."}]},{"type":"paragraph","content":[{"type":"text","text":"Copa was started by Microsoft, entered the CNCF sandbox in 2023, and is typically wired into CI pipelines after a scan step ("},{"type":"text","text":"trivy image --format json","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"copa patch","marks":[{"type":"code"}]},{"type":"text","text":") or run as a controller in environments like Azure Container Registry. It sits in the same space as tools like Chainguard''s image refresh approach, but works on any distro image you already have."}]}]}' WHERE `id` = 'copa';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CoreDNS is a DNS server written in Go that has been the default cluster DNS for Kubernetes since 1.13, replacing kube-dns. Inside a Kubernetes cluster it resolves "},{"type":"text","text":"my-svc.my-namespace.svc.cluster.local","marks":[{"type":"code"}]},{"type":"text","text":" to Service ClusterIPs, handles Pod A records, and forwards everything else upstream."}]},{"type":"paragraph","content":[{"type":"text","text":"Its defining feature is the plugin chain. CoreDNS is built on the same Caddy core as the Caddy web server, and every feature — zone files, caching, Kubernetes service discovery, Prometheus metrics, rewrites, DNS-over-TLS — is a plugin compiled into the binary and composed via a "},{"type":"text","text":"Corefile","marks":[{"type":"code"}]},{"type":"text","text":". A query walks through the chain until a plugin answers it. The order in the Corefile matters, and swapping plugins in or out is a recompile ("},{"type":"text","text":"go build","marks":[{"type":"code"}]},{"type":"text","text":" with a plugin list) rather than a dynamic load, which keeps the runtime small and predictable."}]},{"type":"paragraph","content":[{"type":"text","text":"Beyond Kubernetes, CoreDNS is used as an authoritative and recursive DNS server in its own right, with backends for etcd, Consul, file-based zones, and external plugins for Redis, route53, and more. It''s a CNCF graduated project and, in practical terms, the de-facto DNS server of the cloud-native world — if you''re running Kubernetes, you''re running CoreDNS."}]}]}' WHERE `id` = 'coredns';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cortex is a horizontally scalable, multi-tenant long-term storage backend for Prometheus. Prometheus servers remote-write their samples into Cortex, which stores them in object storage (S3, GCS, Azure Blob) and exposes a fully PromQL-compatible query API. Tenants are identified by the "},{"type":"text","text":"X-Scope-OrgID","marks":[{"type":"code"}]},{"type":"text","text":" header, so a single Cortex cluster can serve metrics for dozens or hundreds of isolated teams or customers."}]},{"type":"paragraph","content":[{"type":"text","text":"Cortex is decomposed into a handful of microservices that you can scale independently: distributors hash and replicate incoming samples to ingesters; ingesters buffer recent data in memory and periodically flush TSDB blocks to object storage; the store-gateway serves historical blocks; queriers fan out PromQL reads across ingesters and store-gateways; the query-frontend splits long queries, caches results, and queues them; the compactor merges and deduplicates blocks in the background. It uses a hash ring (backed by Consul, etcd, or memberlist) for service discovery and sharding."}]},{"type":"paragraph","content":[{"type":"text","text":"Historically, Cortex and Thanos were the two main answers to the \"global Prometheus\" problem. In 2022, Grafana Labs forked Cortex to create Grafana Mimir, and much of the active development shifted there. Cortex itself is still maintained in CNCF incubation, but Mimir, Thanos, and VictoriaMetrics are now the more commonly deployed options for new long-term Prometheus storage."}]}]}' WHERE `id` = 'cortex';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cozystack is a free, open-source PaaS built on Kubernetes and designed to turn bare-metal servers into a private cloud. You install it directly onto a handful of physical machines and end up with a platform that can provision managed Kubernetes clusters, VMs, and databases for internal tenants."}]},{"type":"paragraph","content":[{"type":"text","text":"The architecture glues together a lot of existing cloud-native projects rather than reinventing them. Talos Linux runs on the bare metal; the management cluster uses Cluster API plus KubeVirt to spin up tenant Kubernetes clusters as sets of VMs. Storage is handled by LINSTOR/DRBD for block and Rook/Ceph for object; networking uses Cilium and Kube-OVN; managed services (PostgreSQL via CloudNativePG, MySQL, Kafka, Redis, RabbitMQ, MongoDB, ClickHouse, Seaweed, NATS) are delivered by their respective operators and exposed as tenant-consumable resources."}]},{"type":"paragraph","content":[{"type":"text","text":"Cozystack is built by Ænix and entered the CNCF sandbox in 2025. It sits in the same space as Rancher/Harvester, Sylva, and OpenShift on bare metal — the niche of \"give me a usable private cloud on commodity hardware without paying VMware\" — but with a stronger emphasis on multi-tenant managed services rather than just VM hosting."}]}]}' WHERE `id` = 'cozystack';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C++ is a statically typed, compiled, multi-paradigm systems programming language standardized by ISO (the current revision is C++23, with C++26 in progress). Designed by Bjarne Stroustrup in 1979 as \"C with Classes\", it gives you C-level control over memory and hardware while layering on classes, templates, exceptions, RAII, and — since C++11 — move semantics, lambdas, and a serious concurrency model with "},{"type":"text","text":"std::thread","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::atomic","marks":[{"type":"code"}]},{"type":"text","text":", and the memory model."}]},{"type":"paragraph","content":[{"type":"text","text":"In the cloud-native world, C++ is the language underneath a surprising amount of the data plane. Envoy, the proxy that powers Istio, Contour, Gloo, and AWS App Mesh, is written in C++. So are ClickHouse, ScyllaDB, MongoDB''s core server, RocksDB, Ceph, MySQL, Apache Kafka''s librdkafka, and most high-performance trading and market-data systems. When a project needs sub-millisecond tail latency or wants to squeeze an extra 3x out of the same hardware compared to a Go or Java implementation, C++ is still the default choice."}]},{"type":"paragraph","content":[{"type":"text","text":"Modern C++ has dragged a lot of the old footguns into smart pointers ("},{"type":"text","text":"std::unique_ptr","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::shared_ptr","marks":[{"type":"code"}]},{"type":"text","text":"), "},{"type":"text","text":"std::optional","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::variant","marks":[{"type":"code"}]},{"type":"text","text":", ranges, and coroutines. The standard library is deliberately minimal by cloud-native standards — there is no HTTP client, no JSON parser, no TLS — so most projects pull in Boost, Abseil, Folly, gRPC''s C++ bindings, and Protobuf. Rust is taking some of C++''s ground for new infrastructure, but for the foreseeable future the core of the cloud-native data plane remains C++."}]}]}' WHERE `id` = 'cpp';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CRI-O is a container runtime built exclusively to implement the Kubernetes Container Runtime Interface (CRI). It is the default runtime on OpenShift and is used by Kubernetes distributions that want a minimal, Kubernetes-only runtime rather than the more general-purpose containerd."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally, CRI-O is a small Go daemon that receives CRI gRPC calls from the kubelet and delegates the work to existing libraries: "},{"type":"text","text":"containers/image","marks":[{"type":"code"}]},{"type":"text","text":" for pulling OCI images, "},{"type":"text","text":"containers/storage","marks":[{"type":"code"}]},{"type":"text","text":" for overlay snapshots, CNI for networking, and an OCI runtime (usually "},{"type":"text","text":"runc","marks":[{"type":"code"}]},{"type":"text","text":", but also "},{"type":"text","text":"crun","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"youki","marks":[{"type":"code"}]},{"type":"text","text":", or "},{"type":"text","text":"kata-runtime","marks":[{"type":"code"}]},{"type":"text","text":") for launching containers. There is no daemon owning the containers themselves — CRI-O uses a small "},{"type":"text","text":"conmon","marks":[{"type":"code"}]},{"type":"text","text":" process per container to supervise the runtime and handle logs and exit status, so if CRI-O restarts, containers keep running."}]},{"type":"paragraph","content":[{"type":"text","text":"Because the scope is bounded by the CRI spec, CRI-O tracks Kubernetes releases one-to-one: CRI-O 1.30 targets Kubernetes 1.30. That tight coupling, along with SELinux, seccomp, and user-namespace defaults that line up with Red Hat''s security posture, is why Red Hat picked it for OpenShift. For most other Kubernetes users, containerd is the more common choice; the two are broadly interchangeable from the kubelet''s point of view. CRI-O graduated in the CNCF in 2023."}]}]}' WHERE `id` = 'crio';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Crossplane turns a Kubernetes cluster into a control plane for arbitrary external resources — AWS RDS databases, GCP buckets, Cloudflare zones, GitHub repos, Snowflake warehouses, and anything else with an API. You write Kubernetes manifests, Crossplane reconciles them against the target cloud, and the rest of your Kubernetes tooling (RBAC, GitOps with ArgoCD or Flux, audit logs, admission policies) applies to infrastructure for free."}]},{"type":"paragraph","content":[{"type":"text","text":"The runtime is a set of controllers. Providers ("},{"type":"text","text":"provider-upjet-aws","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"provider-gcp","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"provider-azure","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"provider-terraform","marks":[{"type":"code"}]},{"type":"text","text":", hundreds of community providers) install CRDs for each managed service and reconcile them against the vendor API. On top of that, Crossplane''s Composition engine lets platform teams define a high-level "},{"type":"text","text":"CompositeResourceDefinition","marks":[{"type":"code"}]},{"type":"text","text":" (XRD) — for example, "},{"type":"text","text":"XPostgresDatabase","marks":[{"type":"code"}]},{"type":"text","text":" — and a "},{"type":"text","text":"Composition","marks":[{"type":"code"}]},{"type":"text","text":" that fans it out into the underlying provider resources (a VPC, subnet, RDS instance, parameter group, DNS record, and Secret). Application teams then consume the simple "},{"type":"text","text":"Claim","marks":[{"type":"code"}]},{"type":"text","text":" and never see the cloud-specific details. Modern Crossplane uses composition functions (WASM or gRPC) so you can write composition logic in KCL, Python, Go, or CUE instead of raw YAML patches."}]},{"type":"paragraph","content":[{"type":"text","text":"Crossplane is the main Kubernetes-native alternative to Terraform/OpenTofu and Pulumi. The trade-off is continuous reconciliation and a Kubernetes-shaped UX versus Terraform''s plan/apply model and mature ecosystem. It graduated in the CNCF in 2025 and is the backbone of several commercial platform products, notably Upbound."}]}]}' WHERE `id` = 'crossplane';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CubeFS (originally ChubaoFS) is a distributed file system written in Go that exposes POSIX, HDFS, and S3-compatible APIs over the same backend. It was open-sourced by JD.com, where it runs large-scale AI training, container image storage, and database workloads, and was accepted into the CNCF in 2019, graduating in December 2024."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally, CubeFS splits metadata and data across independent services. The Master handles cluster topology. Metanodes store file system metadata in memory, replicated via Raft, and shard a single filesystem (\"volume\") into metadata partitions. Datanodes store the actual file content in data partitions, using either multi-replica for small files or Reed-Solomon erasure coding for large cold data to cut storage overhead. Clients mount volumes via a FUSE client, an HDFS-compatible client, or the S3 gateway. Each volume can be tuned independently for consistency, replication factor, and erasure-coding policy."}]},{"type":"paragraph","content":[{"type":"text","text":"CubeFS competes with JuiceFS, Alluxio, Ceph (CephFS), and Lustre. Its pitch compared to Ceph is simpler operations and Go-based tooling; compared to JuiceFS, that it stores data in its own datanodes rather than delegating to object storage, which gives it lower latency for small-file AI training workloads."}]}]}' WHERE `id` = 'cubefs';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CUE (Configure, Unify, Execute) is a data constraint language from Marcel van Lohuizen, who previously worked on Borg''s configuration language (BCL/GCL) at Google. It''s a superset of JSON where types and values live in the same lattice: "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" is a constraint satisfied by all integers, "},{"type":"text","text":">0","marks":[{"type":"code"}]},{"type":"text","text":" is a narrower constraint, "},{"type":"text","text":"42","marks":[{"type":"code"}]},{"type":"text","text":" is the narrowest. Unification — CUE''s core operation — combines any two values into the most specific value that satisfies both, or fails with a clear conflict. This means schemas, defaults, and concrete data compose associatively and commutatively, and order of imports doesn''t matter."}]},{"type":"paragraph","content":[{"type":"text","text":"In practice, CUE is used for Kubernetes manifests (it round-trips to YAML and JSON, and can import OpenAPI, Protobuf, and JSON Schema), generating configuration across multiple systems from a single source of truth, validating data in CI, and as the base language for higher-level tools — Dagger''s pipelines originally used CUE, Istio uses it internally for CRD validation, and Timoni is a Helm-alternative built entirely on CUE modules. It has a package manager ("},{"type":"text","text":"cue mod","marks":[{"type":"code"}]},{"type":"text","text":"), a central registry, and modules with SemVer."}]},{"type":"paragraph","content":[{"type":"text","text":"Compared to Jsonnet, Dhall, or Helm templates, CUE''s win is that there is no separate templating language layered on top of your data: constraints, defaults, and values are all the same thing, and conflicts are statically detectable. The cost is a steep learning curve — unification, disjunctions, and the type lattice are unfamiliar to most engineers arriving from YAML and Go templates."}]}]}' WHERE `id` = 'cue';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CueBlox was an experimental headless CMS built on top of CUE. The idea was to use CUE schemas to define content types, validate Markdown/YAML content against them, and expose the result as a typed content API — effectively a Hugo/Netlify CMS alternative where the schema language was CUE instead of bespoke YAML."}]},{"type":"paragraph","content":[{"type":"text","text":"The project was created by David Flanagan (Rawkode) and is no longer actively developed. The interesting ideas from it — CUE as the schema layer for structured content and configuration — have been picked up more broadly by the CUE ecosystem itself and by tools like Timoni for Kubernetes packaging."}]},{"type":"paragraph","content":[{"type":"text","text":"If you''re looking at CueBlox today, you almost certainly want something else: Astro''s content collections, Keystatic, Sanity, or a plain Git-backed setup with CUE used directly for validation."}]}]}' WHERE `id` = 'cueblox';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dagger is a portable CI/CD engine that lets you write pipelines as code in a real programming language — Go, Python, TypeScript, PHP, Java, or any language for which an SDK exists — and executes them as containerized DAGs on top of BuildKit. The same pipeline runs locally on your laptop and in any CI system (GitHub Actions, GitLab, Jenkins, CircleCI) because the CI system''s only job is to call "},{"type":"text","text":"dagger call","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood, Dagger is a GraphQL API served by the Dagger Engine. When you call a function from an SDK, it compiles to GraphQL queries that describe container operations — pull image, run command, mount directory, set env — and BuildKit executes them with aggressive caching based on content-addressed layers. Reruns that hit the cache are effectively free, even across branches and machines, if you point Dagger at a shared cache like Dagger Cloud or a remote BuildKit instance. Pipelines are packaged as \"Modules\" with typed functions that can be published and composed: your release pipeline can import someone else''s test module the same way you''d import a library."}]},{"type":"paragraph","content":[{"type":"text","text":"Dagger was founded by the creators of Docker (Solomon Hykes and team) and is the main contender in the \"programmable CI\" space alongside Pulumi''s approach for infrastructure and tools like Earthly. The pitch is simple: stop writing thousands of lines of YAML that only run in one CI vendor, and start writing pipelines in a language with types, tests, and IDE support."}]}]}' WHERE `id` = 'dagger';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dalec is a BuildKit frontend for producing OS packages (RPM, DEB, Windows MSIs, Azure Linux images) and signed container images from a single declarative YAML spec. It was originally built by Microsoft to harden the Azure Linux (formerly CBL-Mariner) supply chain, and entered the CNCF sandbox in October 2025."}]},{"type":"paragraph","content":[{"type":"text","text":"You write a "},{"type":"text","text":"spec.yaml","marks":[{"type":"code"}]},{"type":"text","text":" that describes sources (Git repos, HTTP downloads, inline scripts), build dependencies, build steps, and the target artifacts. Because Dalec is a BuildKit frontend, "},{"type":"text","text":"docker build","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"buildx","marks":[{"type":"code"}]},{"type":"text","text":" picks it up via the "},{"type":"text","text":"#syntax=","marks":[{"type":"code"}]},{"type":"text","text":" directive the same way the standard Dockerfile frontend works — no separate tool to install. BuildKit then resolves the DAG, runs builds in sandboxed, content-addressed containers, signs artifacts, and emits either OS packages, base images containing those packages, or SBOMs and provenance attestations in the in-toto format."}]},{"type":"paragraph","content":[{"type":"text","text":"The interesting property is reproducibility and supply-chain clarity: the same spec file produces both the "},{"type":"text","text":".rpm","marks":[{"type":"code"}]},{"type":"text","text":" and the container image that bundles it, with matching SLSA attestations, so you don''t end up with a \"build the package\" pipeline and a separate, divergent \"build the image\" pipeline. It''s aimed at distro maintainers and platform teams shipping first-party base images, not at application developers."}]}]}' WHERE `id` = 'dalec';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dapr (Distributed Application Runtime) is a sidecar that exposes common distributed-systems primitives — service-to-service invocation, pub/sub, state stores, secrets, bindings, workflows, and virtual actors — as a local HTTP/gRPC API your application calls over "},{"type":"text","text":"localhost","marks":[{"type":"code"}]},{"type":"text","text":". Your code never imports a Kafka client or an S3 SDK; it POSTs to "},{"type":"text","text":"http://localhost:3500/v1.0/publish/mybroker/mytopic","marks":[{"type":"code"}]},{"type":"text","text":" and Dapr routes the message to whatever broker the operator has configured."}]},{"type":"paragraph","content":[{"type":"text","text":"The key idea is a separation between application code (which uses stable Dapr APIs) and \"components\" (pluggable implementations of those APIs). A state store component can be Redis in dev, CosmosDB in production, and PostgreSQL in a regulated environment, without touching code. Pub/sub can swap between Kafka, RabbitMQ, Azure Service Bus, NATS, or Pulsar the same way. Dapr ships with over 100 components. The actor building block implements Orleans-style virtual actors with automatic placement and turn-based concurrency; the workflow engine is built on top of actors and provides durable, code-first workflows."}]},{"type":"paragraph","content":[{"type":"text","text":"On Kubernetes, Dapr runs as a sidecar injected by a mutating webhook, plus control-plane services for placement (actors), operator, sentry (mTLS between sidecars via an automatic CA), and scheduler. It can also run as a process on VMs or locally. Dapr was created by Microsoft, graduated in the CNCF in 2024, and is backed commercially by Diagrid. It competes conceptually with service meshes (Istio, Linkerd) and application frameworks (Spring Cloud, Micronaut), but operates at a higher level of abstraction: it cares about application semantics, not just network traffic."}]}]}' WHERE `id` = 'dapr';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Daytona is an open-source infrastructure layer for running AI-generated code inside isolated sandboxes. You create a sandbox through its CLI, API, or SDKs, run code inside it, inspect the filesystem and processes, and tear it down when the task is done. The current product is aimed at LLM agents and automation systems rather than interactive developer workspaces."}]},{"type":"paragraph","content":[{"type":"text","text":"The original project ("},{"type":"text","text":"daytonaio/daytona","marks":[{"type":"code"}]},{"type":"text","text":" v0.x) positioned itself as a self-hosted alternative to GitHub Codespaces and Gitpod, built around the open "},{"type":"text","text":"devcontainer.json","marks":[{"type":"code"}]},{"type":"text","text":" standard. In 2024 Daytona pivoted toward AI sandboxes, and the current SDKs are available for Python, TypeScript, Ruby, and Go. The underlying engine still provisions isolated container-based environments, but the product focus is now secure programmatic code execution."}]},{"type":"paragraph","content":[{"type":"text","text":"In the CDE space it sits alongside Gitpod, Coder, DevPod (which has a similar devcontainer-based model), and GitHub Codespaces. For AI agent sandboxing it overlaps with E2B and Modal."}]}]}' WHERE `id` = 'daytona';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"devenv is a Nix-based tool for defining per-project development environments. Instead of writing raw Nix expressions, you describe your environment in a "},{"type":"text","text":"devenv.nix","marks":[{"type":"code"}]},{"type":"text","text":" file using a high-level options schema — "},{"type":"text","text":"languages.rust.enable = true;","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"services.postgres.enable = true;","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"packages = [ pkgs.ffmpeg ];","marks":[{"type":"code"}]},{"type":"text","text":" — and devenv compiles that to a Nix flake behind the scenes."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood it builds on Nix flakes, Cachix for binary caches (the project is built by the Cachix team), and process-compose for supervising background services. When you "},{"type":"text","text":"cd","marks":[{"type":"code"}]},{"type":"text","text":" into a project with direnv integration, devenv activates the shell with the exact pinned package versions, sets environment variables, and can start supporting processes (Postgres, Redis, MailHog, Caddy, a hundred others) declared in the same file. It supports pre-commit hooks via "},{"type":"text","text":"pre-commit-hooks.nix","marks":[{"type":"code"}]},{"type":"text","text":", containers built directly from the shell via "},{"type":"text","text":"devenv container","marks":[{"type":"code"}]},{"type":"text","text":", and a test runner that asserts the shell is working."}]},{"type":"paragraph","content":[{"type":"text","text":"In the \"reproducible dev environment\" space, devenv competes with plain Nix shells, flox, Mise, asdf, and the devcontainer/DevPod approach. The trade-off is that you get Nix''s reproducibility and huge package set ("},{"type":"text","text":"nixpkgs","marks":[{"type":"code"}]},{"type":"text","text":") without writing Nix from scratch — at the cost of needing Nix installed and tolerating its cold-cache build times. Works on Linux and macOS; Windows is WSL-only."}]}]}' WHERE `id` = 'devenv';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Devfile is an open specification — and a set of libraries and registries implementing it — for describing a containerized development environment in portable YAML. A "},{"type":"text","text":"devfile.yaml","marks":[{"type":"code"}]},{"type":"text","text":" declares components (container images, Kubernetes resources, volumes), commands (build, run, test, debug), and events (preStart, postStart) in a tool-neutral format. A Devfile-aware tool reads the file and spins up the corresponding workspace."}]},{"type":"paragraph","content":[{"type":"text","text":"It originated at Red Hat as the configuration format for Eclipse Che and OpenShift Dev Spaces, and has since been adopted by odo (the OpenShift developer CLI), IntelliJ''s Red Hat extensions, and the public Devfile Registry that ships ready-to-use stacks for Node, Java, Python, Go, Quarkus, Spring Boot, and others. The project joined the CNCF sandbox in 2022."}]},{"type":"paragraph","content":[{"type":"text","text":"Devfile overlaps conceptually with the Microsoft-driven "},{"type":"text","text":"devcontainer.json","marks":[{"type":"code"}]},{"type":"text","text":" standard used by VS Code Dev Containers, GitHub Codespaces, and DevPod. The practical difference is focus: "},{"type":"text","text":"devcontainer.json","marks":[{"type":"code"}]},{"type":"text","text":" describes a single container with VS Code features; Devfile describes a multi-component, Kubernetes-native workspace including build and run commands, which fits Che/OpenShift''s in-cluster development model. In practice, "},{"type":"text","text":"devcontainer.json","marks":[{"type":"code"}]},{"type":"text","text":" has won broader mindshare in the wider ecosystem, while Devfile remains the native format inside the Red Hat developer tooling world."}]}]}' WHERE `id` = 'devfile';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DevPod is a client-only tool that provisions development environments from "},{"type":"text","text":"devcontainer.json","marks":[{"type":"code"}]},{"type":"text","text":" files on any backend — local Docker, Kubernetes, SSH, AWS, GCP, Azure, DigitalOcean — and connects your local IDE (VS Code, JetBrains, or a plain SSH terminal) to them. Unlike Codespaces or Gitpod, there is no server-side control plane to run; DevPod is a binary on your laptop that talks directly to the backend via pluggable providers."}]},{"type":"paragraph","content":[{"type":"text","text":"Internally, DevPod implements the same "},{"type":"text","text":"devcontainer.json","marks":[{"type":"code"}]},{"type":"text","text":" spec that VS Code Dev Containers and GitHub Codespaces use, so an existing repo with a devcontainer just works. The provider model is the interesting piece: a provider is a small executable (written by the community or vendored in) that knows how to "},{"type":"text","text":"Init","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Create","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Start","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Stop","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Delete","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"Command","marks":[{"type":"code"}]},{"type":"text","text":" on its target. That means adding a new backend is essentially shipping a binary — there are providers for Hetzner, Civo, Scaleway, Proxmox, and plain SSH alongside the hyperscaler ones."}]},{"type":"paragraph","content":[{"type":"text","text":"DevPod is built by Loft Labs (also responsible for vcluster and DevSpace) and is MPL-2.0 licensed. In the CDE space it competes with Gitpod, Coder, Codespaces, and Daytona; the distinguishing features are the absence of a central server, direct devcontainer compatibility, and the ability to use your own cloud account to avoid per-seat SaaS billing."}]}]}' WHERE `id` = 'devpod';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DevSpace is a CLI for developing applications directly inside a Kubernetes cluster, built around a tight inner loop: build image, deploy, sync files into the running container, port-forward, stream logs, attach a debugger. The goal is to eliminate the "},{"type":"text","text":"docker build → push → kubectl apply → wait","marks":[{"type":"code"}]},{"type":"text","text":" cycle by syncing source files straight into the Pod and letting your existing entrypoint (or a hot-reloader like "},{"type":"text","text":"nodemon","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"air","marks":[{"type":"code"}]},{"type":"text","text":", or "},{"type":"text","text":"tsx watch","marks":[{"type":"code"}]},{"type":"text","text":") pick up the change."}]},{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"devspace.yaml","marks":[{"type":"code"}]},{"type":"text","text":" describes images to build (with BuildKit, Kaniko, or plain Docker), deployments (Helm, Kustomize, or raw manifests), and a "},{"type":"text","text":"dev","marks":[{"type":"code"}]},{"type":"text","text":" section that defines file sync rules, port forwards, terminals, and which containers to swap into \"dev mode\". "},{"type":"text","text":"devspace dev","marks":[{"type":"code"}]},{"type":"text","text":" applies all of that in one command. DevSpace also supports profiles for different environments, hooks for pre/post actions, and an interactive command picker."}]},{"type":"paragraph","content":[{"type":"text","text":"DevSpace is built by Loft Labs (the same team behind vcluster and DevPod) and is a CNCF sandbox project. It overlaps with Skaffold, Tilt, Telepresence, Garden, and Okteto in the \"inner-loop Kubernetes development\" space. Compared to Skaffold, DevSpace leans more into file sync and terminal-based dev workflows; compared to Telepresence, it runs your code inside the cluster rather than tunneling traffic back to your laptop."}]}]}' WHERE `id` = 'devspace';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DevStand is a developer-experience tool aimed at Kubernetes-based application development, focused on visually authoring and validating Kubernetes manifests and Dockerfiles from within an IDE. It sits in the same general space as Lens, Monokle, and Headlamp, emphasizing a GUI-first workflow over editing raw YAML."}]},{"type":"paragraph","content":[{"type":"text","text":"Information about the project is limited and the upstream is not heavily maintained. If you are evaluating tooling in this area, the more actively developed alternatives are Monokle (for manifest editing and validation), Lens or Headlamp (for cluster navigation), and Tilt or DevSpace (for in-cluster inner-loop development)."}]}]}' WHERE `id` = 'devstand';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dex is an OpenID Connect (OIDC) and OAuth 2.0 identity provider that acts as a federation layer in front of other identity stores. It doesn''t store passwords itself; instead it delegates authentication to upstream \"connectors\" — LDAP, SAML, GitHub, Google, Microsoft, GitLab, Bitbucket, OpenShift, OIDC-compliant providers, and more — and re-exposes them as a single OIDC endpoint your applications can trust."}]},{"type":"paragraph","content":[{"type":"text","text":"The original use case, and still the dominant one, is issuing OIDC tokens for "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":" and the Kubernetes API server. Kubernetes only speaks OIDC for user authentication, so putting Dex in front of, say, GitHub or LDAP gives you "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":" login flows with group claims that map cleanly to RBAC. Argo CD, Harbor, Gitea, Grafana, and many other cloud-native apps use Dex the same way. It''s written in Go, stores its state in etcd, Postgres, MySQL, SQLite, or Kubernetes CRDs, and ships as a single binary or container."}]},{"type":"paragraph","content":[{"type":"text","text":"Dex was originally created by CoreOS (which also open-sourced etcd and rkt), later maintained by Red Hat, and is now a CNCF sandbox project with an independent community. Alternatives in the same space include Keycloak (heavier, Java-based, with a full user database and admin UI), Ory Hydra and Kratos (more modular), Authelia, and Zitadel. Dex''s niche is being small, stateless-ish, and purely a federation layer — not a full IAM product."}]}]}' WHERE `id` = 'dex';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dgraph is a distributed, ACID-compliant graph database written in Go. It stores data as a native graph — subject-predicate-object triples sharded by predicate — and is queryable via GraphQL and its own GraphQL-inspired language, DQL (previously GraphQL+-), which adds traversal primitives, aggregations, and recursive queries that plain GraphQL lacks."}]},{"type":"paragraph","content":[{"type":"text","text":"A Dgraph cluster has two components: "},{"type":"text","text":"dgraph zero","marks":[{"type":"code"}]},{"type":"text","text":", which handles cluster membership, shard assignment, and timestamp oracle duties; and "},{"type":"text","text":"dgraph alpha","marks":[{"type":"code"}]},{"type":"text","text":", which serves the actual data. Predicates are the unit of sharding, so all triples with the same predicate land on the same group of Alpha nodes, which are replicated via Raft. Storage is backed by Badger, a fast embedded LSM-tree key-value store also written by the Dgraph team. The result is horizontal scale for large graphs with strong consistency guarantees — a rare combination in graph databases, most of which (Neo4j community, JanusGraph) trade one for the other."}]},{"type":"paragraph","content":[{"type":"text","text":"Dgraph is open source but has had a turbulent commercial history: the original company (Dgraph Labs) ran into funding issues, the project spent a period under Hypermode, and Istari Digital acquired Dgraph from Hypermode in 2025. The main competitors are Neo4j, TigerGraph, JanusGraph, ArangoDB (multi-model), and Amazon Neptune. Dgraph''s pitch remains \"horizontally scalable graph DB with GraphQL as a first-class query language\" — useful if you''re building social graphs, knowledge graphs, or recommendation systems that don''t fit a relational model."}]}]}' WHERE `id` = 'dgraph';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Docker is the tool that made Linux containers usable. The original 2013 release wrapped "},{"type":"text","text":"cgroups","marks":[{"type":"code"}]},{"type":"text","text":", namespaces, and "},{"type":"text","text":"aufs","marks":[{"type":"code"}]},{"type":"text","text":" behind a friendly CLI, a layered image format, and a public registry (Docker Hub), and more or less defined how a generation of engineers thinks about packaging and shipping software. The "},{"type":"text","text":"Dockerfile","marks":[{"type":"code"}]},{"type":"text","text":" format and the image spec it introduced are now OCI standards used by every container tool in the ecosystem."}]},{"type":"paragraph","content":[{"type":"text","text":"Today, \"Docker\" refers to several related things. Docker Engine ("},{"type":"text","text":"dockerd","marks":[{"type":"code"}]},{"type":"text","text":") is the daemon that builds images and runs containers; since 2017 it has used containerd internally to run containers and BuildKit to build them. Docker Desktop is the commercial product for macOS and Windows that runs a Linux VM with the engine inside it, plus Kubernetes, volume mounts, and a GUI. Docker Hub is the registry. Docker Compose is the multi-container orchestration tool. "},{"type":"text","text":"docker buildx","marks":[{"type":"code"}]},{"type":"text","text":" is the modern BuildKit-based build frontend, with multi-arch and remote builders."}]},{"type":"paragraph","content":[{"type":"text","text":"With Kubernetes dropping the "},{"type":"text","text":"dockershim","marks":[{"type":"code"}]},{"type":"text","text":" in 1.24, Docker is no longer the runtime on most production Kubernetes nodes — containerd and CRI-O have taken that role. But Docker remains dominant for local development, CI image builds, and single-host deployments, and the "},{"type":"text","text":"Dockerfile","marks":[{"type":"code"}]},{"type":"text","text":" is still the default way most teams describe how to build an image. Alternatives for the daemon (Podman, nerdctl), builder (BuildKit directly, Buildah, ko), and desktop UX (Rancher Desktop, Podman Desktop, OrbStack, Colima) all exist and are worth considering depending on your needs."}]}]}' WHERE `id` = 'docker';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Docker Build Cloud is a hosted BuildKit service from Docker Inc. You register a cloud builder with "},{"type":"text","text":"docker buildx create --driver cloud <org>/<name>","marks":[{"type":"code"}]},{"type":"text","text":", and subsequent "},{"type":"text","text":"docker build","marks":[{"type":"code"}]},{"type":"text","text":" commands ship their build context to Docker''s remote builders instead of executing locally. The image layers come back, or get pushed directly to a registry from the cloud side."}]},{"type":"paragraph","content":[{"type":"text","text":"Two things make it useful in practice. First, native multi-architecture builds: the service runs native ARM64 and AMD64 builders, so "},{"type":"text","text":"docker build --platform linux/amd64,linux/arm64","marks":[{"type":"code"}]},{"type":"text","text":" doesn''t fall back to QEMU emulation (which can be 10x slower for compile-heavy languages). Second, shared cache: the BuildKit cache lives on the remote builder and is shared across your team and CI jobs, so the layer your coworker built this morning is a cache hit when you build locally this afternoon. That eliminates the usual \"CI cache is cold because each runner starts fresh\" problem."}]},{"type":"paragraph","content":[{"type":"text","text":"Docker Build Cloud is a commercial add-on to Docker paid plans. Alternatives are running your own remote BuildKit instance (the open-source piece does all of this, you just manage the machines), Depot.dev (a popular third-party remote build service that predates Docker''s offering), Namespace, Blacksmith, or the native multi-arch runners some CI vendors now provide. Under the hood it''s all the same BuildKit; the question is who runs the servers and cache."}]}]}' WHERE `id` = 'docker-build-cloud';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Docker Compose is a tool for defining and running multi-container applications on a single Docker host from a declarative YAML file. A "},{"type":"text","text":"compose.yaml","marks":[{"type":"code"}]},{"type":"text","text":" lists "},{"type":"text","text":"services","marks":[{"type":"code"}]},{"type":"text","text":" (containers to run), "},{"type":"text","text":"networks","marks":[{"type":"code"}]},{"type":"text","text":" (user-defined bridge networks that connect them), and "},{"type":"text","text":"volumes","marks":[{"type":"code"}]},{"type":"text","text":" (named Docker volumes for persistent state); "},{"type":"text","text":"docker compose up","marks":[{"type":"code"}]},{"type":"text","text":" brings the whole stack online in dependency order, and "},{"type":"text","text":"docker compose down","marks":[{"type":"code"}]},{"type":"text","text":" tears it back down."}]},{"type":"paragraph","content":[{"type":"text","text":"Compose started life in 2014 as Fig, was acquired by Docker and rewritten in Go as Compose v2 (now a "},{"type":"text","text":"docker compose","marks":[{"type":"code"}]},{"type":"text","text":" subcommand instead of the separate Python "},{"type":"text","text":"docker-compose","marks":[{"type":"code"}]},{"type":"text","text":" binary), and its file format has been standardized as the open Compose Specification. Other tools implement it: Podman''s "},{"type":"text","text":"podman compose","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"nerdctl","marks":[{"type":"code"}]},{"type":"text","text":", and Kubernetes-focused converters like "},{"type":"text","text":"kompose","marks":[{"type":"code"}]},{"type":"text","text":" all understand some subset of the spec."}]},{"type":"paragraph","content":[{"type":"text","text":"Its sweet spot is local development of multi-service apps (web + database + cache + worker), CI integration tests, and quick demos — any situation where Kubernetes is overkill but you still need more than one container wired together. For production deployments beyond a single host, most teams graduate to Kubernetes, Nomad, or a managed container service; recent Compose versions do also have limited \"deploy to cloud\" backends, but the mainstream path is still Compose for dev and Kubernetes for prod, often with the same image definitions used in both."}]}]}' WHERE `id` = 'docker-compose';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dragonfly is a peer-to-peer file and container image distribution system originally built at Alibaba to move large binaries across thousands of hosts without melting the origin registry. Instead of every node pulling from a central OCI registry, Dragonfly peers share layers and blobs directly, and a manager coordinates which peer has what."}]},{"type":"paragraph","content":[{"type":"text","text":"The architecture has three main components written in Go: the "},{"type":"text","text":"manager","marks":[{"type":"code"}]},{"type":"text","text":" (cluster-wide control plane and UI), "},{"type":"text","text":"scheduler","marks":[{"type":"code"}]},{"type":"text","text":" (matches peers to pieces of content and drives the P2P topology), and "},{"type":"text","text":"dfdaemon","marks":[{"type":"code"}]},{"type":"text","text":" (runs on each host, either as a proxy intercepting registry pulls or as a sidecar). A companion project, Nydus, pairs with Dragonfly to provide on-demand, chunk-level lazy image loading — containers start before the full image has been pulled, which is a big deal for multi-GB AI/ML images."}]},{"type":"paragraph","content":[{"type":"text","text":"It''s used in production by Alibaba, Ant Group, Meituan, Tencent, Baidu and others for image distribution at the scale of hundreds of thousands of nodes. The typical alternative is just hammering Harbor with more replicas; Dragonfly trades that for a more complex topology in exchange for dramatically lower origin load and faster cold-start times. CNCF graduated the project in October 2025."}]}]}' WHERE `id` = 'dragonfly';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Drasi is a data change processing platform from Microsoft that watches data sources for changes, evaluates continuous queries over those change streams, and fires reactions when a query''s result set changes. The idea is to replace the usual homegrown mess of polling jobs, CDC pipelines, Kafka topics, and stream processors when all you actually wanted was \"tell me when this condition becomes true.\""}]},{"type":"paragraph","content":[{"type":"text","text":"The runtime has three moving parts. Sources subscribe to change feeds from systems like PostgreSQL, Cosmos DB, Dapr state stores, or Kubernetes resources and normalise them into a change stream. Continuous Queries are declared in Cypher — the same query language as Neo4j — and are evaluated incrementally against a graph built from the incoming changes, so the engine only re-computes the affected subgraph on each update. Reactions (webhooks, SignalR, storage queues, Dapr, Gremlin, Debezium) fire when the query result set adds, removes, or updates rows."}]},{"type":"paragraph","content":[{"type":"text","text":"Drasi can run embedded as a Rust library ("},{"type":"text","text":"drasi-lib","marks":[{"type":"code"}]},{"type":"text","text":"), as a standalone server, or on Kubernetes. It joined the CNCF Sandbox in January 2025. The interesting thing is Cypher over live heterogeneous sources: you can write one query that joins a row from Postgres with a Kubernetes pod and a message queue entry, and have it re-evaluated continuously without standing up Flink."}]}]}' WHERE `id` = 'drasi';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Easegress is a Go-based traffic orchestration system from MegaEase that functions as an API gateway, reverse proxy, and service mesh data plane. It speaks HTTP/1.1, HTTP/2, HTTP/3 (QUIC), and MQTT, and can sit in front of services to handle routing, load balancing, rate limiting, circuit breaking, and canary/traffic-splitting."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally, Easegress runs as a cluster of nodes that use an embedded Raft implementation for leader election and configuration replication — there is no external etcd dependency, which makes it one of the simpler gateways to operate standalone. Traffic flows through user-defined Pipelines composed of Filters (proxy, validator, request builder, wasm, etc.), so you build behavior by composing small filters rather than writing Envoy-style xDS config. It supports WebAssembly filters for custom logic and has an OpenTelemetry integration for tracing."}]},{"type":"paragraph","content":[{"type":"text","text":"It competes most directly with Envoy, Kong, and Traefik. The pitch versus Envoy is operational simplicity (one Go binary, built-in clustering), and more recently it has picked up AI gateway features — proxying and observing calls to OpenAI, Anthropic, and similar providers. Easegress entered the CNCF Sandbox in December 2023."}]}]}' WHERE `id` = 'easegress';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"eBPF (extended Berkeley Packet Filter) is an in-kernel virtual machine in Linux that lets you load small, verified programs and attach them to hooks throughout the kernel — syscalls, kprobes, uprobes, tracepoints, network interfaces (XDP, tc), cgroups, LSM hooks, and more. Programs are typically written in a restricted subset of C, compiled to eBPF bytecode with Clang/LLVM, loaded via the "},{"type":"text","text":"bpf()","marks":[{"type":"code"}]},{"type":"text","text":" syscall, checked by the in-kernel verifier, then JIT-compiled to native code."}]},{"type":"paragraph","content":[{"type":"text","text":"The verifier is what makes eBPF interesting: it statically proves that a program terminates, doesn''t touch memory it shouldn''t, and won''t panic the kernel. That guarantee is why the kernel community is willing to run user-supplied code in kernel context. Programs communicate with userspace through "},{"type":"text","text":"maps","marks":[{"type":"code"}]},{"type":"text","text":" — hash tables, arrays, ring buffers, perf buffers — which are the shared memory between the eBPF program and whatever tool is reading its output."}]},{"type":"paragraph","content":[{"type":"text","text":"eBPF is the substrate under a huge amount of modern infrastructure. Cilium uses it for Kubernetes networking, load balancing, and replacing kube-proxy. Falco and Tetragon use it for runtime security observability. Pixie, Parca, and bpftrace use it for zero-instrumentation tracing and profiling. Katran (Facebook) and Cloudflare use XDP-based eBPF for DDoS mitigation and L4 load balancing at line rate. The standard toolchains are libbpf + BTF/CO-RE for portable programs, and bcc or bpftrace for ad-hoc tracing. Windows has its own eBPF-for-Windows port, but Linux is where everything real happens."}]}]}' WHERE `id` = 'ebpf';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Emissary-Ingress is a Kubernetes-native API gateway built on top of Envoy. Originally released as Ambassador by Datawire (now Ambassador Labs), it was renamed and donated to the CNCF in 2021. Its job is to translate Kubernetes CRDs — "},{"type":"text","text":"Mapping","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Host","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"TLSContext","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"AuthService","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"RateLimitService","marks":[{"type":"code"}]},{"type":"text","text":" — into Envoy xDS configuration and push it to an embedded Envoy process that actually handles the traffic."}]},{"type":"paragraph","content":[{"type":"text","text":"The control plane is written in Python and Go. It watches the Kubernetes API for Emissary CRDs (and, optionally, Gateway API resources), compiles them into a full Envoy bootstrap + xDS snapshot, and hot-reloads Envoy. Because the data plane is stock Envoy, you get the usual Envoy features: HTTP/1.1, HTTP/2, gRPC, WebSockets, mTLS, retries, timeouts, rate limiting, external auth via ext_authz. Canary and traffic-splitting are done by weighting Mappings that point at the same prefix."}]},{"type":"paragraph","content":[{"type":"text","text":"Emissary competes with Contour, Gloo, Istio ingress, and increasingly the Kubernetes Gateway API implementations directly. Its historical selling point was the developer-friendly CRD model — app teams own their own Mappings — versus Istio''s cluster-wide ops-heavy approach. Ambassador Labs has been shifting focus to their commercial Edge Stack and Telepresence, so Emissary''s upstream cadence is slower than it once was, but it''s still in wide production use and remains a CNCF incubating project."}]}]}' WHERE `id` = 'emissary-ingress';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"env0 is a commercial SaaS (with a self-hosted option) for running Infrastructure-as-Code pipelines — Terraform, OpenTofu, Terragrunt, Pulumi, CloudFormation, and Ansible — against cloud accounts, with policy, cost, and RBAC wrapped around them. It sits in roughly the same slot as Terraform Cloud/HCP Terraform, Spacelift, and Scalr."}]},{"type":"paragraph","content":[{"type":"text","text":"The core primitive is an \"environment\": a Git-backed IaC workspace tied to a deployment target, a set of variables, and a run history. env0 clones the repo, runs "},{"type":"text","text":"terraform plan","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"apply","marks":[{"type":"code"}]},{"type":"text","text":" (or the equivalent for other tools) inside an ephemeral agent, captures state and plan output, and gates applies behind approvals, OPA policies, drift detection, and cost estimates from Infracost. Self-hosted agents let the actual IaC runs happen inside a customer VPC so cloud credentials never leave the network."}]},{"type":"paragraph","content":[{"type":"text","text":"Distinguishing features versus Terraform Cloud include first-class OpenTofu support, multi-IaC-tool support in one product, PR-based ephemeral environments with automatic TTL destruction, and native Kubernetes manifest/Helm/Argo workflows in addition to Terraform. For teams doing platform engineering, the \"self-service environment\" model — developers hit a form, env0 spins up a full stack from a template — is the part people actually buy it for."}]}]}' WHERE `id` = 'env0';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Envoy is a high-performance L4/L7 proxy written in C++, originally built at Lyft and now the data plane under most of cloud-native networking. It speaks HTTP/1.1, HTTP/2, HTTP/3, gRPC, TCP, UDP, and has first-class support for mTLS, retries, timeouts, outlier detection, circuit breaking, rate limiting, and rich observability out of every request."}]},{"type":"paragraph","content":[{"type":"text","text":"The defining idea is xDS: Envoy''s configuration (listeners, clusters, routes, endpoints, secrets) is streamed in from a control plane over gRPC, so the proxy can be reconfigured dynamically without dropping connections. That split is why Envoy became the substrate for Istio, Consul Connect, Gloo, Emissary-Ingress, Contour, Kuma, AWS App Mesh, and Cloudflare''s internal gateway. The filter chain architecture — HTTP filters, network filters, and listener filters — lets you compose behavior, and WebAssembly filters (proxy-wasm) plus Lua give you custom extension points without recompiling."}]},{"type":"paragraph","content":[{"type":"text","text":"Envoy Mobile embeds the same core in iOS/Android apps, and Envoy Gateway is a newer project that wraps Envoy behind the Kubernetes Gateway API to give it a Kubernetes-native UX without pulling in all of Istio. It''s the first CNCF graduated proxy and remains the default answer for \"we need a service proxy we can actually observe.\" The main cost is configuration complexity — raw Envoy config is famously verbose, which is precisely why everyone runs it behind a control plane."}]}]}' WHERE `id` = 'envoy';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Equinix Metal is a bare-metal-as-a-service offering that provisions dedicated physical hosts through an API, without a hypervisor sitting between the workload and the hardware. It began life as Packet, an API-first bare-metal startup that Equinix acquired in 2020 and rebranded the same year to slot the product into its global footprint of interconnection facilities."}]},{"type":"paragraph","content":[{"type":"text","text":"Unlike a typical public cloud, every machine is single-tenant and unshared, which removes the noisy-neighbour and virtualisation overhead that makes bare-metal attractive for latency-sensitive or throughput-bound workloads. Networking is the other differentiator: hosts ship with BGP-ready uplinks, support for bringing your own IP space, and direct access to the Equinix Fabric, so a deployment can peer with carriers, clouds, and exchanges from points of presence in dozens of metros worldwide. Common use cases include high-performance and HPC-style workloads, Kubernetes control planes and storage clusters that want predictable hardware, edge and CDN footprints, anycast services, and networking labs that need real BGP rather than an overlay simulation."}]},{"type":"paragraph","content":[{"type":"text","text":"In November 2024 Equinix announced that the public, self-serve Metal product would be wound down by 30 June 2026, with no new feature work and existing customers moved to month-to-month terms as their contracts expire. The Equinix Metal brand and the underlying interconnected bare-metal infrastructure remain part of the company''s portfolio, but the consumer-grade compute offering is on a clear sunset path, so any new project should weigh that timeline against alternatives."}]}]}' WHERE `id` = 'equinix-metal';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Eraser is a Kubernetes component that removes vulnerable and unused container images from worker nodes. On a typical cluster, kubelet''s garbage collection only evicts images under disk pressure, so known-CVE images can linger on nodes long after no pod uses them — Eraser''s job is to actively go find and delete them."}]},{"type":"paragraph","content":[{"type":"text","text":"It runs as a controller plus a per-node DaemonSet-spawned job pattern. An "},{"type":"text","text":"ImageList","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"ImageJob","marks":[{"type":"code"}]},{"type":"text","text":" CR tells Eraser which images to remove; the controller schedules short-lived pods on each node that talk directly to the container runtime (containerd, CRI-O) via CRI and delete the specified images. It can also run in a scanning mode where it uses Trivy to find vulnerable images on each node and then remove them automatically on a schedule."}]},{"type":"paragraph","content":[{"type":"text","text":"Eraser is maintained primarily by Microsoft and lives in the CNCF Sandbox (accepted 2023). It''s narrow in scope — it doesn''t scan running containers, patch images, or manage admission — but it fills a real gap that Kyverno, Gatekeeper, and image-scanning tools don''t: actually deleting the bad bits off the nodes once you know they''re there."}]}]}' WHERE `id` = 'eraser';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"etcd is a distributed key-value store that provides strongly consistent reads and writes across a cluster. It is the default backing store for Kubernetes, where it holds the entire cluster state — every Pod, Service, ConfigMap, and Secret — behind the API server."}]},{"type":"paragraph","content":[{"type":"text","text":"Internally, etcd uses the Raft consensus algorithm to replicate data across an odd-numbered cluster (typically 3 or 5 members) and tolerate the loss of a minority of nodes. Data is stored in a multi-version concurrency control (MVCC) B+ tree backed by bbolt, which lets clients watch keys for changes and receive ordered notifications — the mechanism Kubernetes controllers rely on to react to state. Clients talk gRPC, and every write is an fsync-to-disk per committed Raft entry."}]},{"type":"paragraph","content":[{"type":"text","text":"Beyond Kubernetes, etcd is also used by Cilium, M3, OpenStack, CoreDNS, and Rook. Operating it well is mostly about disk I/O: etcd is extremely sensitive to fsync latency, and a slow disk will produce the \"apply took too long\" messages that eventually turn into leader elections and API server timeouts. The usual production advice is dedicated SSDs, isolation from noisy neighbours, and backups via "},{"type":"text","text":"etcdctl snapshot save","marks":[{"type":"code"}]},{"type":"text","text":". It graduated from the CNCF in 2020."}]}]}' WHERE `id` = 'etcd';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"External Secrets Operator (ESO) is a Kubernetes controller that syncs secrets from external secret managers — AWS Secrets Manager, HashiCorp Vault, Google Secret Manager, Azure Key Vault, 1Password, Doppler, Akeyless, and many others — into native Kubernetes "},{"type":"text","text":"Secret","marks":[{"type":"code"}]},{"type":"text","text":" objects. It solves the very practical problem of \"my source of truth for credentials is Vault, but my workloads only know how to read Kubernetes Secrets.\""}]},{"type":"paragraph","content":[{"type":"text","text":"The model has three CRDs. A "},{"type":"text","text":"SecretStore","marks":[{"type":"code"}]},{"type":"text","text":" (or cluster-scoped "},{"type":"text","text":"ClusterSecretStore","marks":[{"type":"code"}]},{"type":"text","text":") describes a backend and how to authenticate to it — IRSA, workload identity, Vault Kubernetes auth, static tokens, etc. An "},{"type":"text","text":"ExternalSecret","marks":[{"type":"code"}]},{"type":"text","text":" says \"fetch these keys from that store and create a Kubernetes Secret called X.\" A "},{"type":"text","text":"PushSecret","marks":[{"type":"code"}]},{"type":"text","text":" does the inverse, pushing Kubernetes-defined values out to a backend. The controller reconciles on an interval (default 1h) and on changes, so rotation in the backend eventually propagates into the cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"ESO is effectively the successor to the older Secrets Store CSI Driver + provider plugin approach for most use cases, because it produces real Kubernetes Secrets that any pod can consume via "},{"type":"text","text":"envFrom","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"valueFrom","marks":[{"type":"code"}]},{"type":"text","text":" without a CSI mount. It''s a CNCF Sandbox project and is widely deployed — the combination of ESO + Vault or ESO + AWS Secrets Manager is the standard pattern for secret management on Kubernetes now."}]}]}' WHERE `id` = 'external-secrets-operator';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Falco is a runtime security tool that watches system calls on Linux hosts and fires alerts when they match suspicious patterns — a shell spawning inside a container, an unexpected write to "},{"type":"text","text":"/etc","marks":[{"type":"code"}]},{"type":"text","text":", a process opening a raw socket, a sensitive file being read. It was created by Sysdig and was the first runtime security project to graduate from the CNCF."}]},{"type":"paragraph","content":[{"type":"text","text":"Falco gets its event stream from one of two drivers: a classic kernel module, or (more commonly now) an eBPF probe — either a legacy eBPF probe or the modern CO-RE probe that works across kernel versions without recompilation. Events flow into a userspace engine that evaluates them against rules written in a YAML DSL with macros and lists, so you can express things like \"a process named "},{"type":"text","text":"bash","marks":[{"type":"code"}]},{"type":"text","text":" exec''d inside a container whose image is not in this allow-list.\" Matched events get emitted as structured output to stdout, files, gRPC, or through Falcosidekick to Slack/webhooks/SIEMs."}]},{"type":"paragraph","content":[{"type":"text","text":"It runs as a DaemonSet on Kubernetes and ships with a large default ruleset covering MITRE ATT&CK techniques and CIS benchmarks. Related projects include Falcosidekick (event fan-out), Falco Talon (automated response), and the broader plugin framework that lets Falco ingest non-syscall sources like Kubernetes audit logs, AWS CloudTrail, GitHub audit, and Okta. The main alternative in the same space is Tetragon, which is also eBPF-based but integrates more tightly with Cilium and can enforce policy in-kernel rather than only alert."}]}]}' WHERE `id` = 'falco';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Firecracker is a minimal KVM-based virtual machine monitor written in Rust by AWS, originally built to run Lambda and Fargate. It launches microVMs — lightweight VMs with a stripped-down device model — in under 125ms and uses only a few megabytes of memory per VM, so you can densely pack thousands of them on one host and still get hardware-level isolation between tenants."}]},{"type":"paragraph","content":[{"type":"text","text":"The trick is aggressive minimalism. Firecracker''s VMM implements only the devices you actually need to run a serverless workload: virtio-net, virtio-block, virtio-vsock, a serial console, and a minimal PS/2 keyboard. There''s no BIOS, no PCI, no USB, no graphics — boot goes straight into a Linux kernel via the 64-bit Linux boot protocol. Each microVM is a single process controlled over a REST API on a Unix socket, which makes it easy to wrap in orchestrators. The codebase is small enough to audit, and it runs under seccomp-bpf on the host for defense in depth."}]},{"type":"paragraph","content":[{"type":"text","text":"Outside AWS, Firecracker is the runtime under Fly.io''s machines, Kata Containers'' firecracker backend, Koyeb, and a growing set of CI-sandboxing systems (Depot, Namespace, etc.). It competes conceptually with gVisor (userspace syscall interception, weaker isolation, no KVM required) and Cloud Hypervisor (a more feature-complete Rust VMM that Firecracker actually shares code lineage with). If you need \"run untrusted code fast with real VM isolation,\" Firecracker is the reference answer."}]}]}' WHERE `id` = 'firecracker';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Flatcar Container Linux is a minimal, immutable, automatically-updating Linux distribution purpose-built for running containers. It''s the direct continuation of CoreOS Container Linux — when Red Hat bought CoreOS and eventually sunset the original, Kinvolk forked it as Flatcar, and it was later acquired by Microsoft and donated to the CNCF (Incubating, 2024)."}]},{"type":"paragraph","content":[{"type":"text","text":"The OS image is read-only. "},{"type":"text","text":"/usr","marks":[{"type":"code"}]},{"type":"text","text":" is mounted from a signed, verity-protected partition and there are two of them in an A/B layout, so updates are atomic: the new image is written to the passive slot, activated on reboot, and can be rolled back if boot fails. There is no package manager in the traditional sense — if you want extra software on the host, you run it in a container. First-boot configuration is done declaratively through Ignition (JSON, usually generated from Butane YAML), which sets up users, networks, disks, and systemd units before the system ever reaches multi-user mode. Updates come from Nebraska (the open-source update server) in public or private channels (alpha/beta/stable/LTS)."}]},{"type":"paragraph","content":[{"type":"text","text":"Flatcar is the base OS under a lot of production Kubernetes: Kinvolk''s own Lokomotive, Giant Swarm''s clusters, Azure''s AKS node images in some configurations, and many bare-metal Cluster API deployments. Its closest peers are Talos Linux (even more opinionated, API-driven, no SSH), Fedora CoreOS (the upstream successor to Red Hat''s CoreOS), and Bottlerocket (AWS''s Rust-based equivalent)."}]}]}' WHERE `id` = 'flatcar';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fleet is Rancher/SUSE''s GitOps engine for managing Kubernetes at scale — specifically, at the \"thousands of clusters\" scale that edge and retail deployments produce. It''s the continuous delivery backbone of Rancher 2.5+ and ships as the default app-delivery mechanism for RKE2, K3s, and Rancher-managed clusters."}]},{"type":"paragraph","content":[{"type":"text","text":"Fleet has a two-level architecture. A central \"upstream\" Kubernetes cluster runs the Fleet controller and holds "},{"type":"text","text":"GitRepo","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Bundle","marks":[{"type":"code"}]},{"type":"text","text":" resources; downstream clusters run a lightweight agent that registers with the upstream and pulls its assigned bundles. A "},{"type":"text","text":"GitRepo","marks":[{"type":"code"}]},{"type":"text","text":" points at a Git repo containing raw manifests, Helm charts, or Kustomize overlays; Fleet renders them into "},{"type":"text","text":"Bundles","marks":[{"type":"code"}]},{"type":"text","text":", then uses "},{"type":"text","text":"ClusterGroup","marks":[{"type":"code"}]},{"type":"text","text":" label selectors to decide which downstream clusters get which bundle, with per-target customizations. Because the targeting is label-based, rolling a config change across 10,000 edge stores is the same operation as rolling it across one."}]},{"type":"paragraph","content":[{"type":"text","text":"Compared to Argo CD and Flux, Fleet''s distinguishing trait is that scale-out model: one control plane managing many heterogeneous clusters, with the agent-pull design tolerating flaky edge networks. The tradeoff is a smaller ecosystem and a UX that''s tightly coupled to Rancher. If you already run Rancher, Fleet is what you use; if you don''t, Argo CD or Flux are usually the first picks."}]}]}' WHERE `id` = 'fleet';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Flipt is a self-hosted, open-source feature flag service written in Go. Unlike LaunchDarkly or Statsig, it''s a single binary you run yourself, with no SaaS dependency, which makes it popular with teams that don''t want customer or evaluation data leaving their infrastructure."}]},{"type":"paragraph","content":[{"type":"text","text":"The server exposes REST and gRPC APIs for flag evaluation and management, backed by SQLite, Postgres, MySQL, or CockroachDB. Flags can be boolean or multivariate, and rule-based targeting is driven by arbitrary context attributes that the client passes on every evaluation. Flipt v2 introduced a \"declarative / GitOps\" mode where flag state lives in a Git repo as YAML and the server watches it, so flag changes go through pull requests and audit comes for free. There are also native client SDKs that pull flag state and evaluate fully client-side for low-latency use."}]},{"type":"paragraph","content":[{"type":"text","text":"Flipt is OpenFeature-compatible and ships an OpenFeature provider, so you can swap it behind standard SDKs without rewriting application code. Its natural competitors are Unleash (also self-hosted, Node.js), OpenFeature''s own reference providers, and the hosted SaaS flag vendors. If you want \"feature flags without a vendor\" and are comfortable running a Go binary and a database, Flipt is the straightforward pick."}]}]}' WHERE `id` = 'flipt';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fluent Bit is a log, metric, and trace processor and forwarder written in C, designed to be small enough to run as a sidecar or DaemonSet on every node without noticeable overhead — typically ~650KB binary, single-digit-MB RSS. It''s the default logging agent on most managed Kubernetes distributions and the de facto successor to its older sibling Fluentd for the collection layer."}]},{"type":"paragraph","content":[{"type":"text","text":"The pipeline model is Inputs → Parsers → Filters → Buffer → Routers → Outputs. Inputs read from sources like "},{"type":"text","text":"tail","marks":[{"type":"code"}]},{"type":"text","text":" (container logs on disk), systemd, kmsg, Prometheus scraping, OpenTelemetry, Kafka, forward protocol. Filters enrich or mutate events — the Kubernetes filter, for example, resolves pod metadata by calling the kube API and caches it. Buffers can be memory or disk-backed for durability across restarts. Outputs ship to Elasticsearch, Loki, Splunk, S3, Kafka, OpenSearch, Datadog, OpenTelemetry collectors, and dozens more. A scripting layer via Lua and a newer WASM filter interface let you write custom processing without forking the binary."}]},{"type":"paragraph","content":[{"type":"text","text":"Fluent Bit is a CNCF graduated project alongside Fluentd, and the two are usually deployed together: Fluent Bit on every node for collection, Fluentd (or a Fluent Bit aggregator tier) for heavier parsing and routing. Increasingly, Fluent Bit alone handles both roles, especially since it picked up OpenTelemetry-native support and can now do metrics and traces too."}]}]}' WHERE `id` = 'fluent-bit';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fluentd is an open-source data collector written in Ruby (with a C core for performance-critical paths) that unifies log collection, processing, and forwarding through a plugin-based pipeline. It was created at Treasure Data, donated to the CNCF in 2016, and graduated in 2019."}]},{"type":"paragraph","content":[{"type":"text","text":"Configuration is a set of directives — "},{"type":"text","text":"<source>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"<filter>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"<match>","marks":[{"type":"code"}]},{"type":"text","text":" — that define where events come from, how they''re transformed, and where they go. Events are tagged, and tags drive routing through match directives. The plugin ecosystem is huge: over a thousand input/output/filter plugins covering everything from tailing files and syslog to shipping into Elasticsearch, S3, Kafka, BigQuery, Splunk, and whatever obscure SIEM you have. Buffering is built in — memory or file-backed — with configurable retry, chunking, and backpressure semantics, which is what you actually want when your downstream sink gets slow at 3am."}]},{"type":"paragraph","content":[{"type":"text","text":"In modern Kubernetes deployments, Fluentd is usually paired with or replaced by Fluent Bit: Fluent Bit runs on every node as the lightweight collector, and Fluentd (if still used) runs as a heavier aggregator tier that does complex parsing and routing before shipping to storage. The Ruby runtime is the main cost — Fluent Bit is an order of magnitude lighter per instance — but Fluentd''s plugin coverage and mature buffering still make it the right tool when you need those specific outputs or complex filter logic."}]}]}' WHERE `id` = 'fluentd';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fluid is a Kubernetes-native orchestrator for data-intensive workloads — AI training, big data, analytics — whose bottleneck is fetching remote data from object stores like S3, OSS, or HDFS. Instead of jobs pulling straight from remote storage every time, Fluid introduces the concept of a "},{"type":"text","text":"Dataset","marks":[{"type":"code"}]},{"type":"text","text":" CRD backed by a distributed cache engine that runs alongside the compute workloads."}]},{"type":"paragraph","content":[{"type":"text","text":"The architecture decouples \"what data you want\" ("},{"type":"text","text":"Dataset","marks":[{"type":"code"}]},{"type":"text","text":") from \"how it''s cached\" ("},{"type":"text","text":"Runtime","marks":[{"type":"code"}]},{"type":"text","text":"). Fluid plugs into multiple cache engines — Alluxio, JuiceFS, JindoFS, GooseFS, Vineyard — and provisions them as Kubernetes resources. When a pod mounts a Dataset, Fluid''s scheduler extender prefers nodes where the relevant cache blocks already live, so training jobs read from a co-located cache over loopback or the local network instead of pulling terabytes across WAN links on every epoch. Warmup, preload, and eviction are all controlled through CRDs."}]},{"type":"paragraph","content":[{"type":"text","text":"Fluid came out of Alibaba and Nanjing University and is a CNCF Incubating project. It''s most compelling when you''re doing repeated, read-heavy access to the same large dataset — ML training on a shared corpus is the canonical example — and your object store egress costs or latency have become the thing limiting GPU utilization."}]}]}' WHERE `id` = 'fluid';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Flux is a GitOps toolkit for Kubernetes: a set of controllers that watch Git repositories (or OCI artifacts, or S3 buckets) and reconcile cluster state to match. It was built at Weaveworks, rewritten as \"Flux v2\" on top of the Kubernetes controller-runtime and Fluxcd''s own GitOps Toolkit, and graduated from the CNCF in 2022."}]},{"type":"paragraph","content":[{"type":"text","text":"Unlike Argo CD, Flux is not one monolithic controller but a composition of purpose-built ones, each owning a CRD. "},{"type":"text","text":"source-controller","marks":[{"type":"code"}]},{"type":"text","text":" fetches from Git/Helm/OCI/S3 and exposes artifacts internally. "},{"type":"text","text":"kustomize-controller","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"helm-controller","marks":[{"type":"code"}]},{"type":"text","text":" apply those artifacts to the cluster. "},{"type":"text","text":"notification-controller","marks":[{"type":"code"}]},{"type":"text","text":" handles inbound webhooks and outbound alerts to Slack/Teams/GitHub. "},{"type":"text","text":"image-reflector-controller","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"image-automation-controller","marks":[{"type":"code"}]},{"type":"text","text":" scan container registries for new tags and write commits back to Git to trigger updates — the \"image update automation\" loop that makes Flux feel continuous even without a CI system in the middle. Everything is driven by Kubernetes CRDs, so multi-tenancy, RBAC, and policy work the way you already expect."}]},{"type":"paragraph","content":[{"type":"text","text":"Flux has no UI of its own by default, which is the classic point of comparison with Argo CD: Argo has a great dashboard and a pull-centric app model, Flux has a controller-set-of-primitives model that composes more cleanly with other Kubernetes tooling. Both are production-grade; the choice usually comes down to whether you want a UI-first experience (Argo) or a pure-CRD GitOps plumbing layer (Flux). Flux is the engine under Weave GitOps, Azure Arc GitOps, and EKS Anywhere''s app delivery."}]}]}' WHERE `id` = 'fluxcd';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gimlet was an open-source application deployment platform for Kubernetes, aimed at small teams who wanted a Heroku-style UX on top of their own clusters without adopting all of Argo CD or a full internal developer platform. Its core was OneChart, a generic Helm chart that could model most 12-factor-ish apps through values files, plus a web UI that turned those values into GitOps commits and watched Flux reconcile them."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood, Gimlet used Flux for the actual reconciliation loop: the UI and API server produced manifests, committed them to a Git repo, and let Flux apply them. Environments were modeled as directories in the infra repo, and promotion between staging and production was a cherry-pick/PR workflow triggered from the dashboard. It also integrated with GitHub for build status and automatic deploys on new images."}]},{"type":"paragraph","content":[{"type":"text","text":"The project was archived by its maintainers in 2024/2025 — per the website, \"it was not sustainable to run it\" — so it''s no longer an active option. It''s useful mostly as a reference for the \"Flux + OneChart + a nice UI\" pattern, which you can still assemble yourself. Teams looking for the same shape of product today typically land on Argo CD with generators, Kargo, or a Backstage-based internal portal instead."}]}]}' WHERE `id` = 'gimlet';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gitea is a self-hosted Git service written in Go — a single binary (plus a database) that gives you repository hosting, pull requests, issues, a wiki, releases, package registries, and a web UI. It started as a fork of Gogs in 2016 and has since become the dominant lightweight self-hosted alternative to GitHub, GitLab, and Bitbucket."}]},{"type":"paragraph","content":[{"type":"text","text":"The appeal is resource footprint and operational simplicity. Gitea runs comfortably on a Raspberry Pi, boots in seconds, and stores data in SQLite, MySQL, Postgres, or TiDB with repositories on a local or NFS filesystem (or S3-compatible object storage via newer storage drivers). It speaks SSH and HTTPS for Git, supports LFS, and has a built-in package registry that speaks the protocols for npm, Maven, NuGet, PyPI, Docker/OCI, Helm, Composer, Conan, Cargo, and others. Gitea Actions, introduced in 1.19, implements a GitHub Actions–compatible runner protocol so you can run existing "},{"type":"text","text":".github/workflows","marks":[{"type":"code"}]},{"type":"text","text":" YAML against Gitea."}]},{"type":"paragraph","content":[{"type":"text","text":"In 2022, a commercial entity (Gitea Ltd) was formed around the project, which caused a governance split and a community fork called Forgejo — hosted by Codeberg. Both are still active; Gitea continues on its roadmap including a federation effort (ForgeFed) and an enterprise edition, while Forgejo focuses on staying copyleft and community-governed. If you want self-hosted Git without GitLab''s weight, one of the two is almost always the answer."}]}]}' WHERE `id` = 'gitea';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GitLab is an end-to-end DevOps platform: Git hosting, merge requests, CI/CD, container registry, package registry, issue tracking, wiki, SAST/DAST/dependency scanning, infrastructure-as-code state, a Kubernetes agent, and an observability stack, all in one application. It''s available as SaaS (gitlab.com) or self-hosted (Community Edition under MIT, Enterprise Edition under a source-available license with paid tiers)."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally, GitLab is a large Ruby on Rails monolith ("},{"type":"text","text":"gitlab-rails","marks":[{"type":"code"}]},{"type":"text","text":") plus a handful of Go services: "},{"type":"text","text":"gitaly","marks":[{"type":"code"}]},{"type":"text","text":" (the Git RPC layer that owns the actual repositories), "},{"type":"text","text":"gitlab-shell","marks":[{"type":"code"}]},{"type":"text","text":" (SSH), "},{"type":"text","text":"gitlab-workhorse","marks":[{"type":"code"}]},{"type":"text","text":" (HTTP request smart-proxying and large file handling), "},{"type":"text","text":"sidekiq","marks":[{"type":"code"}]},{"type":"text","text":" (background jobs), and the CI runner agents. Storage is Postgres plus Redis plus object storage; Gitaly Cluster provides replication and leader election for Git itself via Praefect. The CI system is defined in "},{"type":"text","text":".gitlab-ci.yml","marks":[{"type":"code"}]},{"type":"text","text":", runs on GitLab Runner, and supports Docker, Kubernetes, shell, and custom executors."}]},{"type":"paragraph","content":[{"type":"text","text":"Compared to a GitHub + third-party stack, GitLab''s pitch is \"one tool, one auth model, one UI for everything DevOps\" — which is genuinely useful for regulated environments that need self-hosting and audit, and painful when you want to swap a component for a best-of-breed alternative. The product has aggressively absorbed adjacent categories (security scanning, value stream analytics, and more recently AI via GitLab Duo), which is either a feature or a source of bloat depending on whom you ask."}]}]}' WHERE `id` = 'gitlab';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GitLab Duo is GitLab''s AI feature set bolted onto the DevOps platform — code completion, chat, merge request summaries, vulnerability explanations, root-cause analysis for failing CI jobs, and test generation. It''s the direct analogue of GitHub Copilot + Copilot Chat, scoped to GitLab''s project, issue, MR, pipeline, and security-finding context."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood, Duo is a set of features that call out to an \"AI Gateway\" service that GitLab operates, which in turn proxies to underlying foundation models (historically Anthropic Claude for chat and Google Vertex AI models for code completion, with the set evolving). The gateway is what lets self-managed GitLab instances use Duo without shipping raw code straight to a third-party inference provider — requests go from the GitLab instance to GitLab''s gateway and back. Completion is wired into the Web IDE and several editor extensions (VS Code, JetBrains, Neovim) via the GitLab Language Server."}]},{"type":"paragraph","content":[{"type":"text","text":"Duo is sold as an add-on on top of Premium/Ultimate tiers, split into Duo Pro (code suggestions + chat) and Duo Enterprise (plus the deeper MR/pipeline/vulnerability features and self-hosted model options). The differentiator versus Copilot is context: because GitLab already owns the MR, pipeline, and SAST data, Duo can answer questions like \"why did this pipeline fail\" or \"explain this vulnerability in the context of this MR\" without a separate integration layer. The flip side is that it''s only useful if you''re already on GitLab."}]}]}' WHERE `id` = 'gitlab-duo';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gitpod is a cloud development environment platform — you push a "},{"type":"text","text":".gitpod.yml","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"devcontainer.json","marks":[{"type":"code"}]},{"type":"text","text":") to a repo, click a button, and get a full ephemeral Linux workspace in the browser or your local VS Code/JetBrains, preconfigured with the tools, services, and ports your project needs. It was one of the earliest serious products in the CDE category."}]},{"type":"paragraph","content":[{"type":"text","text":"The original Gitpod Classic was an open-source, Kubernetes-based multi-tenant platform: each workspace was a pod with a containerized VS Code Server, backed by a workspace content sync service and a websocket-based IDE bridge. In 2024 Gitpod introduced Gitpod Flex, a rearchitected product that runs workspaces on dedicated VMs (including inside the customer''s own AWS account) rather than shared Kubernetes nodes, to address the isolation and compliance complaints from larger customers. Workspaces can be prebuilt — Gitpod runs your init commands ahead of time on every commit, so opening one is effectively instant."}]},{"type":"paragraph","content":[{"type":"text","text":"It sits in the same category as GitHub Codespaces, Coder, JetBrains Space/Remote Dev, and DevPod. The historical selling point versus Codespaces was being cloud-and-host agnostic; the current selling point versus Coder is the prebuild system and the managed experience. Gitpod Classic is open source (AGPL); Flex is the commercial SaaS/self-hosted product."}]},{"type":"paragraph","content":[{"type":"text","text":"In September 2025 the company rebranded as Ona, repositioning from cloud development environments to \"mission control\" for software engineering agents: the same sandboxed, prebuild-backed workspaces, but driven by autonomous coding agents with humans reviewing. Gitpod Classic was sunset as part of the transition. On June 11, 2026, OpenAI announced it was acquiring Ona so Codex agents can run long, multi-hour tasks inside a customer''s own cloud — making the Gitpod brand a historical artifact, though the workspace technology lives on inside Codex."}]}]}' WHERE `id` = 'gitpod';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GraalVM is a high-performance JDK distribution that extends the Java platform with an advanced just-in-time compiler, ahead-of-time compilation via Native Image, and a polyglot runtime capable of executing JavaScript, Python, Ruby, R, and LLVM-based languages alongside Java. Originating from Oracle Labs and stewarded by Oracle, the project is developed in the open on GitHub and the Community Edition is released under GPL-2.0 with the Classpath Exception, so applications built on top of it are not encumbered by the GPL."}]},{"type":"paragraph","content":[{"type":"text","text":"The headline feature is Native Image, which performs closed-world static analysis of a Java application and compiles it ahead of time into a self-contained native binary. The result is a single executable that boots in milliseconds, consumes a fraction of the memory of a traditional JVM process, and ships in a much smaller container image because the JIT, class loader, and unreachable code are all stripped away. The Graal compiler itself also plugs into HotSpot as a top-tier JIT, delivering peak-performance gains for long-running workloads that stay on the JVM."}]},{"type":"paragraph","content":[{"type":"text","text":"These properties matter for cloud-native deployments where cold-start latency, per-pod memory footprint, and image size translate directly into cost and user-facing performance. Frameworks like Quarkus, Micronaut, and Spring Boot (with Spring Native and the AOT engine introduced in Spring Boot 3) lean heavily on GraalVM to compete with Go and Node.js on serverless platforms, Kubernetes, and edge runtimes, while the polyglot Truffle framework lets teams embed other languages into the same process when the use case calls for it."}]}]}' WHERE `id` = 'graalvm';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grafana is an open-source observability dashboard and visualization layer. You point it at data sources — Prometheus, Loki, Tempo, Mimir, Elasticsearch, InfluxDB, Postgres, MySQL, CloudWatch, BigQuery, Datadog, and dozens more — and build dashboards, alerts, and ad-hoc Explore queries on top of them. It''s written in Go (backend) and TypeScript/React (frontend), and it''s the G in the LGTM stack that Grafana Labs sells."}]},{"type":"paragraph","content":[{"type":"text","text":"The data source plugin model is the core idea: Grafana doesn''t store metrics itself, it federates queries to whatever backend owns the data, translating between the panel''s query editor and the backend''s native query language (PromQL, LogQL, TraceQL, SQL, Flux, etc.). Dashboards are JSON definitions — version-controllable, importable, and increasingly provisioned as code via "},{"type":"text","text":"grafana.com","marks":[{"type":"code"}]},{"type":"text","text":" dashboards, Terraform, or the Grafana Operator for Kubernetes. Unified Alerting (since v8) replaced the old per-dashboard alerting with a Prometheus-compatible rule engine that evaluates against any data source and routes through Alertmanager-compatible notifiers."}]},{"type":"paragraph","content":[{"type":"text","text":"Grafana Labs also maintains the backends Grafana is typically paired with: Prometheus-compatible Mimir for metrics, Loki for logs, Tempo for traces, Pyroscope for continuous profiling, and Beyla/Alloy for collection. The core Grafana product is AGPLv3 since 2021 (relicensed from Apache 2.0); Grafana Enterprise and Grafana Cloud are the commercial layers. It''s the default \"look at my metrics\" UI for basically all of cloud-native."}]}]}' WHERE `id` = 'grafana';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grafbase is a GraphQL federation platform centered on a Rust-based gateway that composes multiple subgraphs — GraphQL, REST via OpenAPI, gRPC, or MCP — into a single federated API. It implements Apollo Federation v2 composition, so existing subgraphs built against the Apollo spec work without changes, but the runtime is a Rust rewrite rather than a fork of Apollo Router."}]},{"type":"paragraph","content":[{"type":"text","text":"The core open-source component is the Grafbase Gateway (known previously as "},{"type":"text","text":"grafbase-gateway","marks":[{"type":"code"}]},{"type":"text","text":"), deployable as a single Rust binary, a Docker container, or on the edge via Grafbase Cloud''s Cloudflare-backed runtime. It supports hot schema reloading, entity caching, rate limiting, JWT/JWKS auth, operation allow-lists (trusted documents), OpenTelemetry tracing/metrics, and WASI-based custom hooks for request/response mutation. The commercial platform adds a schema registry, composition checks in CI, analytics, and managed deployment."}]},{"type":"paragraph","content":[{"type":"text","text":"Grafbase competes directly with Apollo GraphOS / Router, Hive Gateway (which also drives this very site), Cosmo (WunderGraph), and Mesh. The \"GraphQL gateway written in Rust, Federation v2-compatible, runnable on the edge\" angle is the shared pitch across that cohort; differentiation is mostly about extensibility model (WASM vs. TypeScript plugins vs. Rhai scripts), the registry/tooling, and which non-GraphQL protocols the gateway can pull into a subgraph without writing glue code."}]}]}' WHERE `id` = 'grafbase';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"gRPC is a high-performance RPC framework originally built at Google and open-sourced in 2015. Service interfaces are defined in Protocol Buffers "},{"type":"text","text":".proto","marks":[{"type":"code"}]},{"type":"text","text":" files, the "},{"type":"text","text":"protoc","marks":[{"type":"code"}]},{"type":"text","text":" compiler (with language plugins) generates client stubs and server skeletons, and the runtime handles serialization, transport, flow control, deadlines, metadata, and retries. It''s a CNCF incubating project."}]},{"type":"paragraph","content":[{"type":"text","text":"The transport is HTTP/2, which is the detail that makes the rest of gRPC work: multiplexed streams on a single TCP connection, bidirectional streaming, header compression via HPACK, and first-class support for trailers (how gRPC delivers final status codes after a streamed response). That gives you four call patterns for free — unary, server streaming, client streaming, and bidi streaming — without any framework-level bolt-ons. Payloads are protobuf binary by default; there are also JSON transcoding layers (grpc-gateway, Envoy''s grpc-json transcoder) for REST compatibility."}]},{"type":"paragraph","content":[{"type":"text","text":"Ecosystem-wise, gRPC is the default inter-service protocol in modern cloud-native systems: Kubernetes API clients use it via client-go + protobuf, etcd speaks it natively, Envoy''s xDS control plane is gRPC streaming, and basically every service mesh assumes it. The usual tradeoff versus REST/JSON is tooling and debuggability (you need gRPC-aware tools like "},{"type":"text","text":"grpcurl","marks":[{"type":"code"}]},{"type":"text","text":", Postman, or Wireshark dissectors) in exchange for tighter schemas, smaller wire size, and streaming. gRPC-Web exists for browser clients, but it requires a proxy (Envoy or grpc-web''s own) because browsers can''t speak raw HTTP/2 trailers. Connect (buf.build) is a newer, compatible alternative runtime that smooths over several of gRPC''s rough edges."}]}]}' WHERE `id` = 'grpc';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grype is a container image and filesystem vulnerability scanner from Anchore, written in Go. You point it at an image ("},{"type":"text","text":"grype alpine:3.19","marks":[{"type":"code"}]},{"type":"text","text":"), a directory, a tarball, or an SBOM, and it emits a list of known CVEs affecting the packages it finds, with severity, fix version, and upstream data source."}]},{"type":"paragraph","content":[{"type":"text","text":"Internally Grype works in two steps. First it builds (or ingests) a Syft SBOM — Syft is Anchore''s sibling project that catalogs installed packages from OS distros (apk, dpkg, rpm), language ecosystems (npm, pip, gem, cargo, go modules, maven, composer), and binary artifacts. Then it matches that package list against its own vulnerability database, which Anchore builds nightly by aggregating NVD, GitHub Security Advisories, and per-distro security trackers (Alpine SecDB, Debian Security Tracker, RHSA, Amazon Linux ALAS, Ubuntu USN, Wolfi, Chainguard, etc.). That split is why Grype tends to be accurate for distro packages: it uses the distro''s own advisory data instead of falling back to NVD version matching, which is notoriously noisy."}]},{"type":"paragraph","content":[{"type":"text","text":"It overlaps heavily with Trivy (Aquasec), which is the dominant scanner in the same niche, and with Clair, Docker Scout, and Snyk Container. Grype''s distinguishing trait is the clean split with Syft — you can generate an SBOM once, archive it, and re-scan it later as new CVEs are published without re-pulling the image. It''s the scanner under a lot of admission-time policy setups via Kyverno + Cosign + Grype."}]}]}' WHERE `id` = 'grype';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Guidepad is a commercial \"platform-as-data\" product that models entities, services, APIs, permissions, infrastructure, and workflows as declarative configuration, then turns that configuration into running software at runtime. The pitch is low-code/no-code primitives for building internal platforms that cover DevOps, MLOps, data engineering, and workflow automation under one roof."}]},{"type":"paragraph","content":[{"type":"text","text":"Instead of assembling a bespoke internal developer platform from Backstage, Terraform, a workflow engine, and custom glue, Guidepad exposes a set of modular abstractions — entity schemas, service definitions, API operations, permission boundaries, and a bundled workflow engine — that get interpreted by the platform runtime. Users describe what they want (schemas, pipelines, permissions) and Guidepad generates the corresponding UIs, APIs, and orchestration. The workflow engine is reused as the substrate for ML/AI pipelines, DevOps automation, and ETL, so the same primitives model a data pipeline and a deployment pipeline."}]},{"type":"paragraph","content":[{"type":"text","text":"It''s a closed-source, commercial product rather than an open project, and it''s less widely known than the open-source IDP building blocks it competes with (Backstage, Port, Cortex, Humanitec). The audience is enterprises that want a single vendor-owned platform layer instead of integrating half a dozen tools themselves."}]}]}' WHERE `id` = 'guidepad';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hadron is a minimal Linux distribution built from scratch for cloud and edge systems. It uses upstream components, including musl libc, systemd, and vanilla Linux kernels, while avoiding a traditional package manager in the base operating system."}]},{"type":"paragraph","content":[{"type":"text","text":"In the Kairos ecosystem, Hadron provides a lean base for immutable, image-based systems. Kairos handles the lifecycle model around installation, A/B upgrades, rollback, and Kubernetes distribution integration, while Hadron supplies the small, upstream-aligned Linux foundation underneath."}]}]}' WHERE `id` = 'hadron';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"HAMi (Heterogeneous AI Computing Virtualization Middleware, formerly \"k8s-vGPU-scheduler\") is a Kubernetes middleware that lets multiple pods share a single physical accelerator with hard resource limits. The headline use case is splitting one NVIDIA GPU across several workloads by core percentage and memory bytes, without needing MIG-capable hardware or a paid vGPU license."}]},{"type":"paragraph","content":[{"type":"text","text":"HAMi has three moving parts: a mutating webhook that rewrites pod specs to request virtual devices, a scheduler extender that picks nodes with enough free slice to satisfy a request, and per-device plugins that do the actual in-container virtualization. For NVIDIA GPUs it hooks the CUDA driver to enforce memory and SM utilization limits in-container, so a pod that asks for 3GiB of an 8GiB card simply cannot allocate more — the isolation is real rather than just scheduling-time accounting. Beyond NVIDIA, it supports Cambricon MLUs, Hygon DCUs, Moore Threads, Iluvatar CoreX, Ascend NPUs, and several other Chinese AI accelerators, which is rare for Kubernetes GPU tooling."}]},{"type":"paragraph","content":[{"type":"text","text":"HAMi is a CNCF Sandbox project and workloads don''t need changes to adopt it — they still request "},{"type":"text","text":"nvidia.com/gpu","marks":[{"type":"code"}]},{"type":"text","text":"-style resources, but through the HAMi extended resource names. It competes with NVIDIA''s own device plugin + MIG / Time-Slicing, Volcano''s vGPU support, and Run:AI''s scheduler. The attraction is getting meaningful multi-tenancy on commodity GPUs without MIG-capable silicon."}]}]}' WHERE `id` = 'hami';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Harbor is an open-source OCI registry — container images, Helm charts, CNABs, and other OCI artifacts — with a focus on security, multi-tenancy, and replication. It was created at VMware, donated to the CNCF in 2018, and graduated in 2020. It''s effectively the default self-hosted registry choice when Docker Registry / Distribution alone isn''t enough."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally, Harbor wraps the upstream CNCF Distribution registry with a set of Go services: "},{"type":"text","text":"core","marks":[{"type":"code"}]},{"type":"text","text":" (API, auth, RBAC, project model), "},{"type":"text","text":"jobservice","marks":[{"type":"code"}]},{"type":"text","text":" (async tasks like replication, GC, and retention), "},{"type":"text","text":"portal","marks":[{"type":"code"}]},{"type":"text","text":" (Angular UI), a Postgres metadata database, Redis, and optional integrations with Trivy for vulnerability scanning and Notary/Cosign for signing. Storage is pluggable — local filesystem, S3, GCS, Azure Blob, Swift. Projects are the tenancy boundary: RBAC, quotas, content trust policies, vulnerability severity gates, and retention rules all attach at the project level."}]},{"type":"paragraph","content":[{"type":"text","text":"The features that actually make people pick Harbor over plain Distribution are image signing and scan-gated pulls (block any pull of an image with critical CVEs), tag immutability and retention rules, project quotas, proxy-cache projects (Harbor as a pull-through cache for Docker Hub, GCR, ECR), and active-active replication between Harbor instances — essential for multi-region or air-gapped deployments. Most large on-prem Kubernetes shops end up running Harbor, and it''s often paired with Dragonfly/Nydus for in-cluster image distribution at scale."}]}]}' WHERE `id` = 'harbor';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Headlamp is an open-source Kubernetes dashboard, originally built by Kinvolk (now Microsoft), donated to the CNCF Sandbox in 2022, and since adopted by Kubernetes SIG UI as an official Kubernetes subproject. It''s a web UI — or a desktop app via Electron — for browsing and managing clusters: workloads, storage, networking, RBAC, custom resources, logs, exec, and port-forward."}]},{"type":"paragraph","content":[{"type":"text","text":"The interesting bit versus the older Kubernetes Dashboard is that Headlamp is built as an extensible React/TypeScript frontend with a first-class plugin API. You can ship a plugin that adds new pages, sidebar entries, resource detail tabs, action buttons, or entire custom-resource viewers, and load it into any Headlamp deployment without forking the project. That''s what makes vendors (like Flux, Kubeflow, Kanister, Kubescape, KubeVirt) ship Headlamp plugins as the UI layer for their controllers. Authentication is whatever the kubeconfig or OIDC provider says — Headlamp itself doesn''t store credentials — and it can run in-cluster, as a standalone app, or as a local desktop tool pointing at multiple kubeconfig contexts at once."}]},{"type":"paragraph","content":[{"type":"text","text":"It competes with K9s (terminal UI), Lens (closed-source after a relicense), OpenLens, and the legacy Kubernetes Dashboard. Its niche is being \"the extensible, vendor-neutral web UI for Kubernetes\" — the piece the community wanted after Lens went proprietary."}]}]}' WHERE `id` = 'headlamp';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Helm is the package manager for Kubernetes. A Helm chart is a directory of Go-templated YAML manifests plus a "},{"type":"text","text":"values.yaml","marks":[{"type":"code"}]},{"type":"text","text":" file; "},{"type":"text","text":"helm install","marks":[{"type":"code"}]},{"type":"text","text":" renders the templates against the supplied values and submits the resulting objects to the Kubernetes API as a named \"release.\" It''s a CNCF graduated project and was one of the first Kubernetes ecosystem tools to exist."}]},{"type":"paragraph","content":[{"type":"text","text":"Helm 3 (2019) removed the in-cluster "},{"type":"text","text":"tiller","marks":[{"type":"code"}]},{"type":"text","text":" server that Helm 2 shipped with; the modern CLI talks directly to the Kubernetes API and stores release metadata as Secrets (or ConfigMaps) in the target namespace. That makes the security model the same as any other kubectl user. Charts can declare dependencies on other charts, run lifecycle hooks (pre-install, post-upgrade, etc.), and ship tests. Values can be supplied via "},{"type":"text","text":"--set","marks":[{"type":"code"}]},{"type":"text","text":", values files, or increasingly through higher-level tools that treat Helm as a rendering library: Argo CD, Flux, Terraform''s helm provider, and Helmfile all consume charts without running "},{"type":"text","text":"helm install","marks":[{"type":"code"}]},{"type":"text","text":" themselves."}]},{"type":"paragraph","content":[{"type":"text","text":"The Go-templating-over-YAML approach is Helm''s most-criticized design choice — whitespace-sensitive templates producing YAML is famously painful — and it''s driven the existence of alternatives like Kustomize (patch-based, no templates), Jsonnet/Tanka, and cdk8s. Despite that, Helm remains the lingua franca for distributing Kubernetes applications: almost every vendor ships a Helm chart, and "},{"type":"text","text":"artifacthub.io","marks":[{"type":"code"}]},{"type":"text","text":" is where you go to find them. OCI-based chart storage (pushing charts to any OCI registry like Harbor or ECR) is now the recommended distribution method, replacing the older chart museum/repo index pattern."}]}]}' WHERE `id` = 'helm';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Helm Dashboard was a web UI for inspecting and managing Helm releases in a Kubernetes cluster, originally built by Komodor. It listed installed releases, showed manifest diffs between revisions, let you browse the actual Kubernetes resources a chart produced, and exposed rollback and upgrade buttons on top of the Helm SDK."}]},{"type":"paragraph","content":[{"type":"text","text":"The project is abandoned. The repository has not received meaningful updates since Komodor stopped investing in it, and it is not maintained by the Helm project itself — despite the name, it was never an official Helm subproject. It still works against older Helm releases but does not track current Helm 3.x changes."}]},{"type":"paragraph","content":[{"type":"text","text":"If you want a GUI for Helm today, look at k9s (TUI with Helm plugin), Headlamp, or the Helm integration in whatever cluster dashboard you already run. For GitOps-driven release management, Argo CD and Flux have replaced the \"click to upgrade\" workflow Helm Dashboard was targeting."}]}]}' WHERE `id` = 'helm-dashboard';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Heroku is the managed PaaS that popularized "},{"type":"text","text":"git push heroku main","marks":[{"type":"code"}]},{"type":"text","text":" as a deployment workflow. You point it at a repository, it detects the language via a buildpack, compiles a slug, and runs it inside a lightweight Linux container called a dyno. Everything — processes, scaling, logging, add-ons — is described through the "},{"type":"text","text":"Procfile","marks":[{"type":"code"}]},{"type":"text","text":" and a handful of CLI commands."}]},{"type":"paragraph","content":[{"type":"text","text":"The dyno model is the core abstraction: stateless, ephemeral containers that are restarted at least daily and assigned to a process type ("},{"type":"text","text":"web","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"worker","marks":[{"type":"code"}]},{"type":"text","text":", etc.). Scaling is horizontal ("},{"type":"text","text":"heroku ps:scale web=5","marks":[{"type":"code"}]},{"type":"text","text":") and vertical across predefined dyno sizes. Persistent state lives in managed add-ons — Heroku Postgres, Heroku Redis, Kafka — attached via config vars. Releases are immutable and rollbacks are a single command."}]},{"type":"paragraph","content":[{"type":"text","text":"Heroku was acquired by Salesforce in 2010 and the buildpack spec it invented became the basis for Cloud Native Buildpacks, now used by Paketo, kpack, and "},{"type":"text","text":"pack","marks":[{"type":"code"}]},{"type":"text","text":". It ended its free tier in late 2022, which pushed many hobby users toward Fly.io, Render, and Railway, but it remains a reference point for what a good developer experience on top of a container platform looks like. If you have ever deployed to Kubernetes and thought \"this should be one command,\" you are thinking of Heroku."}]}]}' WHERE `id` = 'heroku';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hexa is a policy orchestration project that translates a single, vendor-neutral authorization policy into the native policy formats of different target systems. The core idea is IDQL (Identity Query Language), a JSON-based policy format that describes \"who can do what to which resource,\" which Hexa then converts into Google Cloud IAM, AWS Cedar/Verified Permissions, Azure RBAC, Open Policy Agent rego, and similar dialects."}]},{"type":"paragraph","content":[{"type":"text","text":"The project ships a Go-based policy orchestrator and a set of \"provider\" plugins that read and write policy in each target system. The workflow is: author IDQL centrally, apply via the orchestrator, and let Hexa reconcile each platform''s native policy store. This matters for organizations that have identical access rules scattered across four clouds and an API gateway, all expressed differently."}]},{"type":"paragraph","content":[{"type":"text","text":"Hexa is a CNCF sandbox project, donated by Strata Identity, and is still early — the set of supported providers and the IDQL spec itself are evolving. If you are already all-in on OPA or Cedar, Hexa is not a replacement; it is an upstream abstraction that targets those engines alongside cloud-native IAM."}]}]}' WHERE `id` = 'hexa';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"HolmesGPT is an LLM-powered troubleshooting agent for Kubernetes and related infrastructure, built by Robusta. Given an alert or a question like \"why is this pod crashlooping,\" it iteratively calls tools — "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":", Prometheus queries, log fetches, Grafana, Loki, OpenSearch, Datadog, Confluence runbooks — and feeds the output back into an LLM until it produces a root-cause explanation."}]},{"type":"paragraph","content":[{"type":"text","text":"The tool-calling design is the important part: HolmesGPT is not a chatbot wrapped around a static prompt. It uses the ReAct pattern with a pluggable set of \"toolsets\" defined in YAML, so you can extend it to query your own systems. It runs as a CLI, a Kubernetes deployment, or as part of Robusta''s alert pipeline, and supports OpenAI, Anthropic, Azure OpenAI, AWS Bedrock, and local models via LiteLLM."}]},{"type":"paragraph","content":[{"type":"text","text":"In practice it is most useful as a first-responder glued onto Alertmanager: instead of paging a human for every noisy alert, HolmesGPT produces a structured investigation report with the commands it ran and what they returned. Whether that report is actually correct is still entirely a function of the underlying model and the quality of the toolsets you give it."}]}]}' WHERE `id` = 'holmesgpt';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Home Assistant is a Python home automation server that runs on your own hardware and talks directly to smart devices over their native protocols instead of routing everything through a vendor cloud. It is usually deployed as Home Assistant OS on a Raspberry Pi, NUC, or VM, and exposes a web UI, REST API, and WebSocket API."}]},{"type":"paragraph","content":[{"type":"text","text":"The core is an event bus with a state machine: every device is an entity with a state, and \"integrations\" (over 2,000 of them) push state updates onto the bus. Automations are triggered by state changes, time, or events, and are authored either in YAML or in the visual editor — both compile down to the same representation. For local device access it ships with add-ons for Zigbee (ZHA, Zigbee2MQTT), Z-Wave JS, Matter, Thread/OpenThread Border Router, and MQTT via Mosquitto. The \"Supervisor\" architecture runs these add-ons as Docker containers alongside core."}]},{"type":"paragraph","content":[{"type":"text","text":"It is the reference project for local-first smart home: automations keep running if your internet drops, device state does not leave the LAN unless you opt into Home Assistant Cloud (Nabu Casa) for remote access and Alexa/Google Assistant bridging. The ESPHome project, which generates firmware for ESP32/ESP8266 sensors that speak Home Assistant''s native API, is maintained by the same organization."}]}]}' WHERE `id` = 'home-assistant';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hubble is the network, service, and security observability layer for Cilium. It taps directly into Cilium''s eBPF dataplane to produce flow logs, service dependency maps, and security events for Kubernetes clusters without requiring sidecars, packet capture, or any application-level instrumentation. Because the visibility is generated by the same eBPF programs that already process every packet, the overhead is minimal and the data covers L3/L4 connections, L7 protocols like HTTP, gRPC, Kafka, and DNS, and policy verdicts (allowed, denied, dropped) in a single stream."}]},{"type":"paragraph","content":[{"type":"text","text":"The system is distributed. Each node runs a Hubble server inside the Cilium agent that exposes a gRPC API for the flows observed on that node. Hubble Relay aggregates those per-node streams into a single cluster-wide API endpoint, and Hubble UI consumes the relay to draw service dependency graphs and connectivity maps in the browser. The "},{"type":"text","text":"hubble","marks":[{"type":"code"}]},{"type":"text","text":" CLI talks to either the local socket or the relay and is the day-to-day tool for filtering and tailing flows, much like "},{"type":"text","text":"tcpdump","marks":[{"type":"code"}]},{"type":"text","text":" for a Kubernetes cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"Typical use cases are diagnosing DNS resolution failures, debugging why a NetworkPolicy is dropping traffic, mapping which services actually talk to each other before tightening policy, and feeding flow metrics into Prometheus and Grafana. Hubble is bundled with Cilium rather than maintained as a separate project, so it does not carry its own CNCF status; it inherits Cilium''s graduated standing and ships in the same release cadence."}]}]}' WHERE `id` = 'hubble';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hurl is a command line tool that runs and tests HTTP requests defined in a simple plain text format. Built in Rust and distributed as a single static binary, it lets you describe a request, or a chain of requests, in a file that reads almost like the raw HTTP exchange itself: a method and URL, optional headers and body, then the expected response. The same file is both the request specification and the test, which makes Hurl files trivial to commit alongside the service they exercise and easy to diff when behaviour changes."}]},{"type":"paragraph","content":[{"type":"text","text":"The file format leans on familiar HTTP grammar and adds two key sections for testing. Captures pull values out of a response (a header, a JSON path, an XPath expression, a cookie) and bind them to variables that subsequent requests can reference, which is how authentication tokens, CSRF challenges, and resource IDs get threaded through a flow. Asserts run predicates against the response: status codes, headers, JSON or XML bodies, response duration, TLS certificate details, even raw bytes. Because assertions live next to the request they validate, a Hurl file doubles as executable documentation of how an API is supposed to behave."}]},{"type":"paragraph","content":[{"type":"text","text":"Hurl is most at home in integration and smoke tests run from CI. It outputs JUnit, TAP, and HTML reports out of the box, integrates cleanly with GitHub Actions, GitLab CI, and similar runners, and is fast enough to use as a post-deploy health check against production endpoints. Teams reach for it when bash and curl have become unmaintainable but a full test framework feels like overkill, and when REST, GraphQL, or SOAP contracts need to be pinned down in something a reviewer can actually read."}]}]}' WHERE `id` = 'hurl';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"HwameiStor is a local storage system for Kubernetes that turns the disks on your worker nodes (HDD, SSD, NVMe) into a pool of persistent volumes exposed via CSI. It is developed by DaoCloud and aimed at workloads that want the performance of direct-attached storage without giving up dynamic provisioning or volume lifecycle management."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally it runs as a set of controllers and per-node agents that discover local block devices, group them into storage pools by media type, and carve out LVM-backed logical volumes on demand. A scheduler extender ensures pods are scheduled onto the node that actually has the data, and it supports volume replication across nodes for HA, snapshots, expansion, and migration when a node is drained. Volumes are exposed through the standard CSI driver."}]},{"type":"paragraph","content":[{"type":"text","text":"It occupies the same niche as OpenEBS LocalPV / Mayastor, Longhorn, and TopoLVM: use local NVMe for databases and AI/ML workloads where the Ceph-style network-replicated approach is too slow. Compared to Longhorn it leans more toward raw LVM performance and less toward distributed block replication. CNCF sandbox."}]}]}' WHERE `id` = 'hwameistor';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hyperlight is a Rust library from Microsoft for running small, untrusted functions inside bare-bones hardware-virtualized micro-VMs, with startup times measured in a millisecond or two. It was open-sourced in late 2024 and donated to the CNCF sandbox in 2025. The goal is to give function-as-a-service platforms isolation stronger than a container or a language runtime sandbox without the cold-start cost of a full VM like Firecracker."}]},{"type":"paragraph","content":[{"type":"text","text":"Hyperlight micro-VMs have no kernel, no OS, no virtual devices, and no BIOS. The host loads guest code directly into memory and enters the hypervisor (KVM on Linux, Windows Hypervisor Platform on Windows) with a minimal CPU state. Guests typically run WebAssembly compiled to native via "},{"type":"text","text":"wasmtime","marks":[{"type":"code"}]},{"type":"text","text":", but any code that conforms to the very restricted guest ABI works. Communication between host and guest happens through a shared memory region and a small set of hypercalls instead of virtio."}]},{"type":"paragraph","content":[{"type":"text","text":"The use case Microsoft is building around it is multi-tenant serverless: run each customer request in its own fresh micro-VM to get hardware isolation without paying for a VM boot. If Firecracker is \"strip a VM to the bone,\" Hyperlight is \"skip the OS entirely and run a single function.\""}]}]}' WHERE `id` = 'hyperlight';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"in-toto is a framework for cryptographically verifying that every step of a software supply chain was performed by the expected party and produced the expected artifacts. It originated from NYU''s Secure Systems Lab alongside TUF, and is now a CNCF graduated project."}]},{"type":"paragraph","content":[{"type":"text","text":"The model is built on two primitives: a "},{"type":"text","text":"layout","marks":[{"type":"bold"}]},{"type":"text","text":", signed by the project owner, which declares the steps of the supply chain (clone, test, build, package), who is authorized to perform each one, and how the artifacts flow between them; and "},{"type":"text","text":"link metadata","marks":[{"type":"bold"}]},{"type":"text","text":", signed by whoever actually performs a step, which records the materials that went in and the products that came out. A verifier replays the layout against the collected link files and fails the build if anything is missing, unauthorized, or tampered with. This maps cleanly onto SLSA provenance — in-toto attestations are the on-wire format SLSA uses."}]},{"type":"paragraph","content":[{"type":"text","text":"It is wired into Sigstore (cosign produces in-toto attestations), Tekton Chains (which emits link metadata for every TaskRun), Jenkins, GitLab, and SPIRE for identity. If you have ever signed a container image with cosign, you have already used in-toto''s attestation format whether you noticed or not."}]}]}' WHERE `id` = 'in-toto';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Inclavare Containers is a confidential-computing container runtime that launches each container inside a hardware enclave — originally Intel SGX, with later work for TDX and AMD SEV. It was started at Alibaba and accepted into the CNCF sandbox in 2021. The name is Latin for \"to enclave.\""}]},{"type":"paragraph","content":[{"type":"text","text":"The runtime is OCI-compatible: it implements the "},{"type":"text","text":"runc","marks":[{"type":"code"}]},{"type":"text","text":" interface as "},{"type":"text","text":"rune","marks":[{"type":"code"}]},{"type":"text","text":", so Kubernetes and containerd can schedule enclave workloads without changes higher up the stack. When "},{"type":"text","text":"rune","marks":[{"type":"code"}]},{"type":"text","text":" starts a container, instead of invoking the host kernel directly, it loads the workload inside an enclave through a libOS layer — Occlum (Rust, MIT-developed) or Graphene/Gramine — which provides a POSIX surface to the application while keeping memory encrypted and inaccessible to the host OS, hypervisor, or other tenants. It also ships an attestation service so remote parties can verify that a running container is genuinely inside a legitimate enclave before releasing secrets to it."}]},{"type":"paragraph","content":[{"type":"text","text":"Activity on the main repo has slowed; much of the confidential-containers work has shifted to the broader CNCF Confidential Containers project, which Inclavare contributors helped seed."}]}]}' WHERE `id` = 'inclavare';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Infisical is an open-source secrets management platform built as a modern alternative to HashiCorp Vault for teams that want something closer to \"Doppler, but self-hostable.\" The server is a Node.js/TypeScript application backed by Postgres, and it exposes secrets through a web UI, CLI, REST API, Kubernetes operator, and SDKs for most major languages."}]},{"type":"paragraph","content":[{"type":"text","text":"The data model is organized around projects, environments (dev/staging/prod), and folder paths, with per-path RBAC, approval workflows, secret versioning, PR-style change requests, and audit logs. It supports dynamic secrets for Postgres, MySQL, AWS IAM, and similar backends — short-lived credentials generated on demand — as well as secret rotation, PKI issuance, and SSH certificate signing. The Kubernetes operator syncs secrets into native "},{"type":"text","text":"Secret","marks":[{"type":"code"}]},{"type":"text","text":" objects or injects them directly via a mutating webhook, and there is an External Secrets Operator provider for teams already using ESO."}]},{"type":"paragraph","content":[{"type":"text","text":"Infisical is dual-licensed: the core is MIT, and enterprise features (SAML/SCIM, HSM integration, higher-tier compliance) sit behind a commercial license. Compared to Vault it has a much gentler learning curve but less breadth; compared to cloud KMS-backed solutions like AWS Secrets Manager it gives you one store that spans clouds and developer laptops."}]}]}' WHERE `id` = 'infisical';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"InfluxDB is a time-series database purpose-built for metrics, events, and other timestamped data. Data is written using the InfluxDB line protocol — a simple text format of "},{"type":"text","text":"measurement,tag=value field=value timestamp","marks":[{"type":"code"}]},{"type":"text","text":" — typically via Telegraf, the project''s companion collection agent that ships with hundreds of input plugins."}]},{"type":"paragraph","content":[{"type":"text","text":"InfluxDB 1.x used a custom TSM storage engine and the InfluxQL query language. 2.x added Flux, a functional data-scripting language, plus a tasks/alerting UI. InfluxDB 3 is a complete rewrite in Rust on top of Apache Arrow, DataFusion, and Parquet: data is held in-memory in Arrow format, persisted as Parquet files to object storage, and queried with SQL via DataFusion (with InfluxQL still supported). The Core edition is open source under MIT/Apache-2.0 dual license; clustering, replication, and long-term historical query live in the commercial Enterprise and Cloud editions."}]},{"type":"paragraph","content":[{"type":"text","text":"In the observability stack it is typically paired with Grafana for dashboards and Telegraf or an OpenTelemetry collector for ingestion. Compared to Prometheus it is a true pushed-ingest database with much higher cardinality tolerance in 3.x, and compared to TimescaleDB it is not a Postgres extension — you get a dedicated engine but give up the rest of the Postgres ecosystem."}]}]}' WHERE `id` = 'influxdb';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Inlets is a reverse tunnel built by Alex Ellis (of OpenFaaS) that punches out from a private network to a public exit-server and relays inbound traffic back. You run the server on a cheap cloud VM with a public IP, run the client next to the thing you want to expose (laptop, Raspberry Pi, on-prem Kubernetes), and the client holds an outbound websocket to the server over which all traffic is multiplexed."}]},{"type":"paragraph","content":[{"type":"text","text":"Originally the project had an open-source core (inlets OSS) and a Pro edition; as of 2022 the open-source edition was deprecated and Inlets Pro / \"inlets\" is now a commercial product. It supports both HTTP (L7, with host-based routing, multiple upstream services per tunnel, TLS termination) and raw TCP (L4, for SSH, Postgres, RDP, etc.), runs natively on Kubernetes with a LoadBalancer controller that provisions real public IPs for clusters behind NAT, and can be automated via "},{"type":"text","text":"inletsctl","marks":[{"type":"code"}]},{"type":"text","text":" to spin up exit-servers on DigitalOcean, Linode, Hetzner, Scaleway, and others."}]},{"type":"paragraph","content":[{"type":"text","text":"It occupies the same space as ngrok, Cloudflare Tunnel, and Tailscale Funnel, but the sales pitch is that you own the exit node, your data never traverses a third-party SaaS, and you pay per VM instead of per tunnel."}]}]}' WHERE `id` = 'inlets';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Inspektor Gadget is a collection of eBPF-based debugging and observation \"gadgets\" for Kubernetes, originally built at Kinvolk and now maintained by Microsoft. It gives you the BCC/bpftrace family of tools (execsnoop, opensnoop, tcptracer, biolatency, oomkill, etc.) but automatically enriched with Kubernetes metadata — pod, container, namespace, and node — so you can say \"show me every file opened in pods matching label "},{"type":"text","text":"app=api","marks":[{"type":"code"}]},{"type":"text","text":"\" instead of \"show me every file opened by PID 4712 on node "},{"type":"text","text":"ip-10-0-3-41","marks":[{"type":"code"}]},{"type":"text","text":".\""}]},{"type":"paragraph","content":[{"type":"text","text":"It runs as a DaemonSet. The "},{"type":"text","text":"ig","marks":[{"type":"code"}]},{"type":"text","text":" binary loads eBPF programs into the kernel on each node and correlates the resulting events with the container runtime via the cgroup/mntns identifier. Gadgets come in several flavors: tracers that stream events, snapshotters that capture state at a point in time, profilers that collect stacks, and top-style gadgets. Inspektor Gadget supports optional WebAssembly modules and OCI image-based gadgets; image-based gadgets reached GA in v0.31.0, so gadgets can now be pulled and distributed like container images."}]},{"type":"paragraph","content":[{"type":"text","text":"It is the closest thing Kubernetes has to a first-class equivalent of "},{"type":"text","text":"strace","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"bpftrace","marks":[{"type":"code"}]},{"type":"text","text":" for clusters. For deeper runtime security use cases overlap with Falco and Tetragon, but Inspektor Gadget is deliberately aimed at ad-hoc investigation rather than rule-based alerting."}]}]}' WHERE `id` = 'inspektor-gadget';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Intar is a QEMU-based DevOps lab environment. It runs HCL-defined scenarios in local virtual machines, evaluates probes, and presents progress through a terminal UI."}]},{"type":"paragraph","content":[{"type":"text","text":"The project is built around reproducible infrastructure training and debugging exercises, where a scenario describes the VM image, probes, and target state that the user needs to repair."}]}]}' WHERE `id` = 'intar';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Interlink is a Kubernetes virtual kubelet provider that lets a pod land on a node that is not actually a Kubernetes node at all — most commonly an HPC batch system like Slurm, HTCondor, or a remote cloud batch API. It was built out of the INFN and interTwin EU research projects to let physics workloads written as container images run on existing supercomputing allocations without forcing those sites to install Kubernetes."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally it has two halves. A virtual-kubelet provider runs in the \"user\" cluster and registers a fake node. When a pod is scheduled to it, the provider hands the pod spec to an "},{"type":"text","text":"interLink API server","marks":[{"type":"bold"}]},{"type":"text","text":", which in turn forwards it to a "},{"type":"text","text":"sidecar plugin","marks":[{"type":"bold"}]},{"type":"text","text":" for the target system. Plugins exist for Slurm (sbatch scripts that pull a Singularity/Apptainer image), Docker, remote Kubernetes, and cloud batch. The sidecar reports status back, and from the user cluster''s point of view it is just a long-running pod."}]},{"type":"paragraph","content":[{"type":"text","text":"The headline use case is bursting Kubernetes workloads onto HPC resources at CERN and similar sites, but it is also useful for any scenario where you want Kubernetes as the control plane while the actual execution happens somewhere that cannot run kubelet. CNCF sandbox, Apache-2.0."}]}]}' WHERE `id` = 'interlink';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Iroh is a peer-to-peer networking stack for connecting devices directly across local networks, the public internet, and relay paths when direct connectivity is not available."}]},{"type":"paragraph","content":[{"type":"text","text":"The project provides end-to-end encrypted QUIC connections, endpoint addressing, discovery, relays, and higher-level protocols for blobs, gossip, and realtime documents. It is aimed at applications that need direct device-to-device communication without treating IP addresses as the primary application identity."}]}]}' WHERE `id` = 'iroh';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Istio is a service mesh for Kubernetes built around Envoy. It intercepts traffic to and from workloads, terminates and originates mTLS, routes based on HTTP/gRPC semantics, and emits uniform telemetry — all without requiring application code changes. It was originally a joint project of Google, IBM, and Lyft; it moved to the CNCF in 2022 and graduated in 2023."}]},{"type":"paragraph","content":[{"type":"text","text":"The data plane is Envoy. Historically it was deployed as a sidecar injected into every pod, and the control plane ("},{"type":"text","text":"istiod","marks":[{"type":"code"}]},{"type":"text","text":") pushed configuration — listeners, clusters, routes, secrets — over xDS to each proxy. "},{"type":"text","text":"istiod","marks":[{"type":"code"}]},{"type":"text","text":" also acts as the CA, issuing SPIFFE-style X.509 identities that back mTLS between workloads. Newer versions support "},{"type":"text","text":"ambient mode","marks":[{"type":"bold"}]},{"type":"text","text":", which replaces sidecars with a per-node L4 proxy ("},{"type":"text","text":"ztunnel","marks":[{"type":"code"}]},{"type":"text","text":", written in Rust) and optional per-namespace L7 waypoint proxies, so you only pay the full Envoy cost where you actually need L7 features. Configuration is expressed through "},{"type":"text","text":"VirtualService","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"DestinationRule","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"AuthorizationPolicy","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"Gateway","marks":[{"type":"code"}]},{"type":"text","text":" CRDs, with growing support for the upstream Gateway API."}]},{"type":"paragraph","content":[{"type":"text","text":"Istio is the heavyweight of the mesh space. Linkerd (Rust micro-proxy, simpler model) and Cilium Service Mesh (eBPF, no sidecars) are the main alternatives. The tradeoff is well understood: Istio gives you the most features and the most knobs, and in exchange you inherit Envoy''s operational surface area."}]}]}' WHERE `id` = 'istio';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Jaeger is a distributed tracing backend originally built at Uber and modeled on Google''s Dapper paper. It ingests spans from instrumented applications, indexes and stores them, and exposes a query API and UI for digging through individual traces and computing service dependency graphs. It graduated from the CNCF in 2019."}]},{"type":"paragraph","content":[{"type":"text","text":"The classic Jaeger pipeline was: application → Jaeger client library → "},{"type":"text","text":"jaeger-agent","marks":[{"type":"code"}]},{"type":"text","text":" (local UDP receiver) → "},{"type":"text","text":"jaeger-collector","marks":[{"type":"code"}]},{"type":"text","text":" → storage (Cassandra or Elasticsearch) → "},{"type":"text","text":"jaeger-query","marks":[{"type":"code"}]},{"type":"text","text":" + UI. Jaeger v2, released in 2024, replaces the hand-rolled collector with an OpenTelemetry Collector build: the receivers, processors, and exporters are OTel components, and Jaeger is effectively a distribution of the OTel Collector plus the Jaeger UI and query service. The native instrumentation libraries are deprecated in favor of OpenTelemetry SDKs, and both Jaeger and OTLP span formats are accepted."}]},{"type":"paragraph","content":[{"type":"text","text":"Storage backends include Cassandra, Elasticsearch/OpenSearch, and Badger (single-node); there is also ClickHouse support via the OTel Collector. For sampling at volume, the recommended pattern is tail-based sampling in the collector tier. Jaeger''s main competition is Tempo (Grafana''s trace backend, which uses object storage and delegates search to Loki/metrics-generated links) and commercial APM tools."}]}]}' WHERE `id` = 'jaeger';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Java is a class-based, statically typed, object-oriented programming language created by James Gosling at Sun Microsystems in 1995 and now stewarded through the Java Community Process. The language compiles to bytecode that runs on the Java Virtual Machine (JVM), which provides garbage collection, just-in-time compilation, and a portable execution model across operating systems and architectures. OpenJDK is the canonical reference implementation, released under GPL-2.0 with the Classpath Exception so that applications linked against the runtime are not encumbered by the GPL."}]},{"type":"paragraph","content":[{"type":"text","text":"The JVM has evolved into a polyglot platform hosting languages like Kotlin, Scala, Groovy, and Clojure, and the broader Java ecosystem is one of the largest in software, spanning Maven Central, application servers, build tools, and decades of enterprise libraries. For cloud-native workloads, GraalVM enables ahead-of-time compilation into self-contained native images with fast startup and reduced memory footprint, which has reshaped how Java is packaged for containers and Kubernetes. Frameworks such as Quarkus, Micronaut, and Spring Boot lean into this model, offering reactive runtimes, build-time dependency injection, and first-class GraalVM native-image support to compete with Go and Node.js on cold-start and density."}]},{"type":"paragraph","content":[{"type":"text","text":"Java is a sprawling ecosystem that no single profile can fully capture; this entry exists so that cloud-native videos referencing Java, the JVM, or OpenJDK have a canonical hub to link back to."}]}]}' WHERE `id` = 'java';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"jsPolicy is a Kubernetes admission-control engine from Loft Labs that lets you write validating, mutating, and controller policies in JavaScript or TypeScript instead of Rego. Policies are delivered as "},{"type":"text","text":"JsPolicy","marks":[{"type":"code"}]},{"type":"text","text":" CRDs; the controller compiles the code (TypeScript is transpiled), bundles it, and executes it in a sandboxed V8 runtime embedded in the jsPolicy webhook server."}]},{"type":"paragraph","content":[{"type":"text","text":"There are three policy types. "},{"type":"text","text":"Validating","marks":[{"type":"bold"}]},{"type":"text","text":" policies reject API requests that don''t match the rules. "},{"type":"text","text":"Mutating","marks":[{"type":"bold"}]},{"type":"text","text":" policies can patch objects before they are persisted. "},{"type":"text","text":"Controller","marks":[{"type":"bold"}]},{"type":"text","text":" policies watch existing resources and react on changes, which lets you use the same mental model for admission and for background reconciliation. Because the runtime is V8, policies can import a curated subset of helpers and even use parts of the npm ecosystem, and they are cached as compiled bundles so hot-path evaluation is fast."}]},{"type":"paragraph","content":[{"type":"text","text":"It sits in the same category as Kyverno (YAML-native) and OPA/Gatekeeper (Rego). The pitch is simply: your platform team already knows JavaScript, and expressing policy as imperative code with normal control flow and unit tests is easier than Rego for most people. The latest tagged upstream release is v0.2.2 (2023-02-21), so evaluate its maintenance status before committing to it for production policy."}]}]}' WHERE `id` = 'jspolicy';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Jujutsu, commonly called "},{"type":"text","text":"jj","marks":[{"type":"code"}]},{"type":"text","text":", is a Git-compatible version control system with a different workflow model from Git. It treats the working copy as a change, keeps an operation log for undo and recovery, and can work with existing Git repositories and remotes."}]},{"type":"paragraph","content":[{"type":"text","text":"The project focuses on making history editing, rebasing, conflict handling, and day-to-day changes easier to reason about without cutting users off from Git hosting and collaboration workflows."}]}]}' WHERE `id` = 'jujutsu';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"k0s is a conformant Kubernetes distribution from Mirantis that ships as a single static Go binary containing the API server, controller manager, scheduler, kubelet, kube-proxy, and an embedded etcd. You download one file, run "},{"type":"text","text":"k0s install controller","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"k0s install worker","marks":[{"type":"code"}]},{"type":"text","text":", and you have a cluster — no package manager, no Docker, no host-side systemd fleet of components."}]},{"type":"paragraph","content":[{"type":"text","text":"The distinguishing design choices versus k3s: k0s uses vanilla upstream Kubernetes with zero patches, uses etcd by default for multi-node clusters, and falls back to SQLite via kine for single-node installs while also supporting MySQL and PostgreSQL. It also supports a \"controller-only\" mode where control-plane nodes refuse to run workloads and ships "},{"type":"text","text":"k0sctl","marks":[{"type":"code"}]},{"type":"text","text":", a separate tool that takes a YAML inventory of SSH hosts and performs zero-downtime install, upgrade, and rollback across the cluster, which is closer to a real lifecycle manager than what k3s offers out of the box. CNIs (Kube-router default, Calico supported), CSI, and runtime are all pluggable."}]},{"type":"paragraph","content":[{"type":"text","text":"It is aimed at the same space as k3s, MicroK8s, and Talos: edge, bare metal, air-gapped, and IoT. Rough rule of thumb: choose k3s if you want the smallest possible footprint and don''t mind the upstream modifications; choose k0s if you want unmodified Kubernetes in a single binary with fleet-style lifecycle tooling."}]}]}' WHERE `id` = 'k0s';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"k3s is a lightweight, CNCF-certified Kubernetes distribution originally built by Rancher Labs (now SUSE). It ships as a single ~60MB binary that bundles the API server, scheduler, controller manager, kubelet, kube-proxy, containerd, runc, and CNI plugins — installable with a one-line "},{"type":"text","text":"curl | sh","marks":[{"type":"code"}]},{"type":"text","text":" script that also sets up a systemd unit."}]},{"type":"paragraph","content":[{"type":"text","text":"The interesting design choice is "},{"type":"text","text":"Kine","marks":[{"type":"bold"}]},{"type":"text","text":", a shim that lets k3s speak the etcd API to a SQL backend. By default it uses SQLite, which removes etcd''s disk-IO sensitivity and lets single-node clusters run comfortably on a Raspberry Pi. For HA you can switch to embedded etcd, external PostgreSQL, MySQL, or real etcd. k3s also strips out legacy in-tree cloud providers and alpha features to shrink the binary, and bundles Traefik as the default ingress controller, ServiceLB (klipper-lb) as a LoadBalancer implementation, local-path-provisioner for PVs, and CoreDNS — all of which can be disabled with "},{"type":"text","text":"--disable","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Compared to k0s, k3s is more opinionated and slightly more patched: the single binary does a bit more \"magic\" out of the box, and SQLite-as-datastore is a workflow nobody else in the distribution space offers. It is the default Kubernetes in Rancher, K3OS/K3s cluster launcher tools, and is the foundation of RKE2 (which swaps SQLite for etcd and adds FIPS/hardened defaults)."}]}]}' WHERE `id` = 'k3s';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"k8gb is a global server load balancer for Kubernetes that uses DNS — not BGP, not an overlay — to steer traffic between multiple clusters in different regions. It is designed to be cheap, multi-cluster native, and have zero dependence on a commercial GSLB appliance like F5 BIG-IP GTM or a cloud-vendor product like Route 53 traffic policies."}]},{"type":"paragraph","content":[{"type":"text","text":"The architecture is deliberately small. Each cluster runs a k8gb controller alongside CoreDNS. You annotate an Ingress with a "},{"type":"text","text":"k8gb.io/strategy","marks":[{"type":"code"}]},{"type":"text","text":" (round-robin, failover, geoip, weighted) and the controller generates DNS records in an edge DNS zone — Infoblox, Route 53, NS1, ns1, CoreDNS itself — that resolve to the correct cluster''s load balancer IPs. Health checks are driven by each cluster''s own Kubernetes liveness data: if an Ingress goes unhealthy in one cluster, the local controller removes its IP from the shared DNS zone, and traffic shifts to the surviving cluster without any central brain. Because state lives in DNS, there is no cross-cluster control plane to keep in sync."}]},{"type":"paragraph","content":[{"type":"text","text":"It fits naturally with Cilium or Submariner for L4/L7 cluster connectivity, and slots into the \"active-active across regions\" gap that many teams have been filling with spreadsheets and manual Route 53 weights. CNCF sandbox, Apache-2.0."}]}]}' WHERE `id` = 'k8gb';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"K8sGPT scans a Kubernetes cluster for broken resources and explains what is wrong in plain English. Under the hood it is a Go CLI (and a companion operator) that runs a set of hard-coded \"analyzers\" — one per resource type — which look for well-known failure modes: pods in "},{"type":"text","text":"ImagePullBackOff","marks":[{"type":"code"}]},{"type":"text","text":", services with no matching endpoints, ingresses pointing at nothing, RBAC roles with dangling subjects, and so on. The analyzer output is already useful on its own ("},{"type":"text","text":"k8sgpt analyze","marks":[{"type":"code"}]},{"type":"text","text":" prints a structured list), and then optionally an LLM is called to translate each finding into a remediation suggestion."}]},{"type":"paragraph","content":[{"type":"text","text":"The LLM layer is pluggable: OpenAI, Azure OpenAI, AWS Bedrock, Cohere, Google Vertex AI, Ollama for local models, and several others. Sensitive fields can be anonymized before they leave the cluster. The operator variant ("},{"type":"text","text":"k8sgpt-operator","marks":[{"type":"code"}]},{"type":"text","text":") runs the same analyzers continuously and emits "},{"type":"text","text":"Result","marks":[{"type":"code"}]},{"type":"text","text":" CRs that can be surfaced in Grafana or Backstage, so the tool becomes an always-on triage layer instead of an interactive CLI."}]},{"type":"paragraph","content":[{"type":"text","text":"It was started by Alex Jones and donated to the CNCF sandbox in late 2023. It is one of the cleaner examples of LLM-assisted ops because most of the value comes from the deterministic analyzers; the model is just doing natural-language rewriting on top."}]}]}' WHERE `id` = 'k8sgpt';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"K8up is a Kubernetes operator, built by VSHN, that backs up PersistentVolumeClaims and application-level dumps using "},{"type":"text","text":"restic","marks":[{"type":"bold"}]},{"type":"text","text":". You apply a "},{"type":"text","text":"Backup","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Schedule","marks":[{"type":"code"}]},{"type":"text","text":" CRD in a namespace, and the operator spawns a Job that mounts the PVCs in read-only mode, runs restic against an S3, Azure Blob, GCS, Swift, or B2 repository, and records the result as a "},{"type":"text","text":"Snapshot","marks":[{"type":"code"}]},{"type":"text","text":" CR."}]},{"type":"paragraph","content":[{"type":"text","text":"The useful details: because it is restic under the hood, you get deduplication, encryption at rest, and incremental backups for free, and you can restore using plain "},{"type":"text","text":"restic","marks":[{"type":"code"}]},{"type":"text","text":" from outside the cluster if the operator is unavailable. K8up also supports pre-backup hooks — it can exec into pods to run "},{"type":"text","text":"pg_dump","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"mysqldump","marks":[{"type":"code"}]},{"type":"text","text":", or custom commands and stream the output into the same restic repository, so databases get consistent logical backups alongside volume snapshots. Retention ("},{"type":"text","text":"keepDaily","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"keepWeekly","marks":[{"type":"code"}]},{"type":"text","text":", etc.) and prune jobs are expressed in the same CRD, so lifecycle policy is GitOps-friendly."}]},{"type":"paragraph","content":[{"type":"text","text":"It sits alongside Velero and Kanister in the Kubernetes backup space. Velero focuses on whole-cluster disaster recovery and is heavier; K8up is simpler and per-namespace, which tends to suit multi-tenant clusters where each team wants to own its own backup policy."}]}]}' WHERE `id` = 'k8up';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Apache Kafka is a distributed event streaming platform for durable, high-throughput publish/subscribe workloads. It originated at LinkedIn, became an Apache Software Foundation project, and is widely used as the backbone for event-driven architectures, log aggregation, change-data capture, stream processing, and data integration pipelines."}]},{"type":"paragraph","content":[{"type":"text","text":"Kafka stores records in partitioned, ordered logs called topics. Producers append events, consumers track their own offsets, and brokers replicate partitions across a cluster for availability. Modern Kafka clusters can run without ZooKeeper through KRaft mode, where metadata is managed by Kafka''s own quorum controllers. The broader ecosystem includes Kafka Connect for source and sink integration, Kafka Streams for application-level stream processing, Schema Registry implementations, and Kubernetes operators such as Strimzi."}]},{"type":"paragraph","content":[{"type":"text","text":"In cloud-native environments, Kafka is usually chosen when teams need replayable event history, strong ordering within partitions, back-pressure tolerance, and large-scale fan-out. It is heavier to operate than lightweight messaging systems such as NATS, but it remains a common foundation for data platforms and service-to-service event streams."}]}]}' WHERE `id` = 'kafka';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"kagent is a framework for running LLM agents as first-class Kubernetes workloads. It was started by Solo.io and donated to the CNCF sandbox in 2025. The project defines CRDs — "},{"type":"text","text":"Agent","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Tool","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ModelConfig","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Team","marks":[{"type":"code"}]},{"type":"text","text":" — so that agents, the tools they can call, and the models behind them are declared in YAML and reconciled by a controller, exactly like the rest of your cluster state."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally the control plane is built on Microsoft''s AutoGen Python agent framework; each declared agent runs as a pod that exposes a chat/MCP-style interface and is wired up to tools that can be inline Python, MCP servers, or wrappers around existing cluster-native CLIs ("},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":", Istio "},{"type":"text","text":"istioctl","marks":[{"type":"code"}]},{"type":"text","text":", Prometheus queries, Argo CD). A bundled web UI lets you converse with agents and inspect the tool calls, traces, and token usage. Because tools are decoupled from agents, you can give the same SRE-investigator agent access to different tool sets per team or per environment."}]},{"type":"paragraph","content":[{"type":"text","text":"The initial target use cases are Kubernetes troubleshooting, Istio/Envoy debugging, and general \"agentic SRE\" workflows, with kagent positioned as the Kubernetes-native place to run those agents rather than a SaaS dashboard. It overlaps conceptually with HolmesGPT but focuses on multi-agent coordination and a declarative, CRD-based runtime."}]}]}' WHERE `id` = 'kagent';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kairos turns any Linux distribution into an immutable, A/B-upgradeable, container-packaged OS for edge and Kubernetes nodes. The operating system is shipped and updated as an OCI image: you "},{"type":"text","text":"docker pull","marks":[{"type":"code"}]},{"type":"text","text":" a new version, and the node atomically switches to it on reboot, with the previous image kept as a fallback partition. There is no package manager on the running system."}]},{"type":"paragraph","content":[{"type":"text","text":"The build process is a \"factory\" that takes a base image (openSUSE, Ubuntu, Alpine, Rocky, Debian, etc.) and layers Kairos''s immutable-root tooling, a cloud-init-compatible provisioning agent, and optionally a Kubernetes distribution (k3s, k0s, or RKE2) on top. You declare the node configuration in a YAML cloud-config — users, network, kube config, any extensions — either at install time via a USB image or via a P2P mesh that lets nodes discover each other and bootstrap a cluster automatically (the project calls this \"zero-touch\" mode, built on libp2p)."}]},{"type":"paragraph","content":[{"type":"text","text":"It is aimed squarely at fleets of edge nodes where you want containers-everywhere semantics extended to the OS itself: image-based immutability, signed boot, and rollback on failure. It sits alongside Talos Linux, Flatcar, Bottlerocket, and Fedora CoreOS, with Kairos''s differentiator being that you can turn "},{"type":"text","text":"any","marks":[{"type":"italic"}]},{"type":"text","text":" existing distro into an immutable Kairos derivative rather than being locked into a single base. Kairos joined the CNCF sandbox in 2024."}]}]}' WHERE `id` = 'kairos';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KAITO (Kubernetes AI Toolchain Operator) is a Kubernetes operator from Microsoft that makes serving open-weight LLMs on a cluster a one-CRD operation. You write a "},{"type":"text","text":"Workspace","marks":[{"type":"code"}]},{"type":"text","text":" resource that names a model — "},{"type":"text","text":"falcon-7b","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"llama-2-13b-chat","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"phi-3","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"mistral-7b","marks":[{"type":"code"}]},{"type":"text","text":", etc. — and KAITO takes care of provisioning GPU nodes, pulling a pre-built inference image, and exposing the model behind an OpenAI-compatible HTTP endpoint."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood it has two controllers. The "},{"type":"text","text":"workspace controller","marks":[{"type":"bold"}]},{"type":"text","text":" reconciles model workloads: it picks the right inference runtime (vLLM or Hugging Face TGI), mounts the model weights (either pre-baked into images hosted in MCR, or downloaded at runtime), and wires up a Service. The "},{"type":"text","text":"node provisioner","marks":[{"type":"bold"}]},{"type":"text","text":" integrates with Karpenter to request the exact GPU SKU the chosen model needs (A100, H100, specific VRAM class) from the underlying cloud, so you are not pre-sizing a node pool. KAITO also supports fine-tuning jobs using LoRA/QLoRA with the same Workspace abstraction, and RAG pipelines via a companion "},{"type":"text","text":"RAGEngine","marks":[{"type":"code"}]},{"type":"text","text":" CRD."}]},{"type":"paragraph","content":[{"type":"text","text":"It was donated to the CNCF sandbox in 2024 and is the opinionated \"just serve this model\" counterpart to lower-level stacks like KServe + vLLM. If you are on AKS the Karpenter integration is native; on other clouds you bring your own node provisioning."}]}]}' WHERE `id` = 'kaito';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kamaji runs Kubernetes control planes as pods inside another Kubernetes cluster. Instead of giving every tenant a set of dedicated control-plane VMs, the management cluster runs a Deployment per tenant containing "},{"type":"text","text":"kube-apiserver","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"kube-controller-manager","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"kube-scheduler","marks":[{"type":"code"}]},{"type":"text","text":"; the tenant''s etcd is either a shared multi-tenant etcd with per-tenant namespaces or, more commonly, a pooled backing store via "},{"type":"text","text":"Kine","marks":[{"type":"bold"}]},{"type":"text","text":" against PostgreSQL, MySQL, or NATS. Worker nodes connect to the tenant API server through a Service (and optional Ingress/LoadBalancer) exposed from the management cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"This approach is called \"Hosted Control Planes\" and Kamaji is one of the main open-source implementations of it (alongside HyperShift from Red Hat, which targets OpenShift). The operational win is cost: a dozen tenant control planes can live on a handful of nodes because each one is just a few pods rather than three HA VMs and an etcd cluster. Version upgrades, certificate rotation, and failover are handled by the management cluster''s normal reconcilers."}]},{"type":"paragraph","content":[{"type":"text","text":"Kamaji is built by Clastix and integrates with Cluster API ("},{"type":"text","text":"KamajiControlPlane","marks":[{"type":"code"}]},{"type":"text","text":"), so it plugs into the existing CAPI provider ecosystem for workload node provisioning across bare metal, vSphere, AWS, and similar. Worth a look if you are running a multi-tenant Kubernetes PaaS and each tenant currently has its own 3-node etcd bill."}]}]}' WHERE `id` = 'kamaji';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kaniko is a daemonless container image builder from Google that executes a Dockerfile entirely in userspace inside a container. It was created to solve one specific problem: building OCI images in a Kubernetes pod without Docker-in-Docker, "},{"type":"text","text":"--privileged","marks":[{"type":"code"}]},{"type":"text","text":", or a mounted Docker socket."}]},{"type":"paragraph","content":[{"type":"text","text":"The executor image ("},{"type":"text","text":"gcr.io/kaniko-project/executor","marks":[{"type":"code"}]},{"type":"text","text":") takes a build context (local tarball, Git URL, S3, GCS) and a Dockerfile, pulls the base image, then walks each instruction one at a time. For each "},{"type":"text","text":"RUN","marks":[{"type":"code"}]},{"type":"text","text":" it executes the command in the container''s root filesystem and then snapshots the filesystem changes by diffing against the previous state to produce a new layer. The resulting image is pushed directly to a registry. Because nothing calls "},{"type":"text","text":"runc","marks":[{"type":"code"}]},{"type":"text","text":" or a daemon, Kaniko only needs its own container and does not require root on the host — though it does require elevated capabilities inside its own user namespace to chroot and manipulate the filesystem."}]},{"type":"paragraph","content":[{"type":"text","text":"It is the default builder inside Tekton, Jenkins X, Argo Workflows, and GitLab''s Kubernetes executor for anyone allergic to DinD. The main trade-offs versus BuildKit (the modern default behind "},{"type":"text","text":"docker build","marks":[{"type":"code"}]},{"type":"text","text":"): Kaniko is single-threaded per stage, layer caching is less sophisticated, and it is slower on large builds. Google archived the repository on June 3, 2025, and the remaining maintainers retired, ending upstream development. Community forks exist — Chainguard maintains one, and the osscontainertools fork keeps dependencies patched — but for new pipelines BuildKit, Buildah, or podman build are the recommended replacements; GitLab has removed its Kaniko documentation and now recommends Buildah."}]}]}' WHERE `id` = 'kaniko';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kanister is an extensible application-aware data protection framework for Kubernetes, built by Kasten (now Veeam Kasten). Unlike PV-level snapshot tools, it starts from the assumption that the right way to back up a stateful application is to run its own commands — "},{"type":"text","text":"mongodump","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"pg_basebackup","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"redis-cli BGSAVE","marks":[{"type":"code"}]},{"type":"text","text":", Cassandra "},{"type":"text","text":"nodetool snapshot","marks":[{"type":"code"}]},{"type":"text","text":" — and stream the output to object storage."}]},{"type":"paragraph","content":[{"type":"text","text":"The core abstraction is a "},{"type":"text","text":"Blueprint","marks":[{"type":"bold"}]},{"type":"text","text":": a CRD containing a set of named actions ("},{"type":"text","text":"backup","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"restore","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"delete","marks":[{"type":"code"}]},{"type":"text","text":") where each action is a list of phases. Each phase is a function — "},{"type":"text","text":"KubeExec","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"KubeTask","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"PrepareData","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"BackupData","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"CreateVolumeSnapshot","marks":[{"type":"code"}]},{"type":"text","text":", and others — that Kanister''s controller executes in the target namespace. An "},{"type":"text","text":"ActionSet","marks":[{"type":"code"}]},{"type":"text","text":" CRD is what you create to actually run a Blueprint against a specific application instance; the controller picks it up and records status. Because Blueprints are declarative YAML, the community maintains a library of them for the common stateful workloads (Postgres, MongoDB, MySQL, Cassandra, Elasticsearch, etc.)."}]},{"type":"paragraph","content":[{"type":"text","text":"It is routinely paired with Velero — Kanister provides the application-consistent dump, Velero handles namespace-level object backup and restore orchestration. CNCF sandbox, Apache-2.0."}]}]}' WHERE `id` = 'kanister';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kapitan is a generic templating and inventory tool originally built inside Deutsche Bank for managing configuration across many environments and targets. Its central idea is a single hierarchical "},{"type":"text","text":"inventory","marks":[{"type":"bold"}]},{"type":"text","text":", powered by "},{"type":"text","text":"reclass","marks":[{"type":"bold"}]},{"type":"text","text":", where every deployable thing (\"target\") inherits parameters from a tree of classes, and those parameters are then fed into templates to produce concrete output files."}]},{"type":"paragraph","content":[{"type":"text","text":"The templating side is deliberately pluggable: you can render Jinja2, Jsonnet, Kadet (Kapitan''s own Python DSL that builds dict trees and serializes to YAML), Helm charts, or CUE, all driven by the same inventory values. The output is written into "},{"type":"text","text":"compiled/<target>/","marks":[{"type":"code"}]},{"type":"text","text":", which you then commit or hand off to "},{"type":"text","text":"kubectl apply","marks":[{"type":"code"}]},{"type":"text","text":", Terraform, or whatever else consumes it. For secrets, Kapitan ships "},{"type":"text","text":"kapitan refs","marks":[{"type":"code"}]},{"type":"text","text":", which supports GPG, AWS KMS, Google KMS, Azure Key Vault, Vault, and age, with the secret references embedded in the inventory and resolved at compile time."}]},{"type":"paragraph","content":[{"type":"text","text":"It is the tool you reach for when Helm''s values.yaml is not structured enough and you have, say, 200 clusters that all need slightly different versions of 30 components. It sits in the same space as Jsonnet+tanka, cdk8s, and Crossplane compositions, but with a much stronger inventory model. Maintained by a small community; expect a learning curve because the Reclass-plus-everything model is unlike most other config tools."}]}]}' WHERE `id` = 'kapitan';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Karmada is a multi-cluster Kubernetes orchestrator, the spiritual successor to the abandoned Kubernetes Federation v2 project. You run a Karmada control plane (its own API server, etcd, and controllers) that joins any number of member clusters, and you then submit normal Kubernetes manifests to it. Karmada decides which member clusters each object belongs on and distributes it there."}]},{"type":"paragraph","content":[{"type":"text","text":"Placement decisions are driven by two CRDs: "},{"type":"text","text":"PropagationPolicy","marks":[{"type":"code"}]},{"type":"text","text":" declares which resources go to which clusters (filtered by label, region, provider, or static name), and "},{"type":"text","text":"OverridePolicy","marks":[{"type":"code"}]},{"type":"text","text":" lets you mutate fields per cluster — image tags, replica counts, resource requests — so you can propagate the same Deployment to three clusters with different settings. The scheduler supports weighted, duplicated, and aggregated (split-replicas) spread modes, and can rebalance when clusters come or go. A \"pull mode\" agent lets member clusters behind firewalls reach out to the Karmada control plane instead of the other way around."}]},{"type":"paragraph","content":[{"type":"text","text":"It is Huawei''s answer to running workloads across multi-cloud and hybrid fleets with one logical control plane, and is widely used in Chinese cloud providers. Alternatives include Red Hat''s Open Cluster Management (OCM), Liqo, and Cluster API + Argo CD ApplicationSets. CNCF incubating since 2023."}]}]}' WHERE `id` = 'karmada';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KCL (Kusion Configuration Language) is a statically typed, constraint-based configuration language built for generating Kubernetes manifests, Terraform input, and other structured configuration. It originated at Ant Group, powers their internal Kusion platform, and was donated to the CNCF sandbox in 2023."}]},{"type":"paragraph","content":[{"type":"text","text":"Syntactically KCL looks like a blend of Python and TypeScript: you declare schemas with typed fields, default values, and inline validation rules, then instantiate them and the compiler checks everything at compile time. "},{"type":"text","text":"check","marks":[{"type":"code"}]},{"type":"text","text":" blocks let you attach assertions directly to a schema (\"replicas must be odd in production,\" \"memory limit ≥ request\"), so policy lives next to the data. The toolchain is written in Rust, compiles fast, and ships a package registry ("},{"type":"text","text":"kcl.mod","marks":[{"type":"code"}]},{"type":"text","text":"), an LSP, formatter, import tools for Helm/CRDs/OpenAPI, and bindings to Go, Python, and Java for embedding. It also integrates with Argo CD, Flux, Helm (as a post-renderer), Crossplane, and Kustomize."}]},{"type":"paragraph","content":[{"type":"text","text":"It lives in the same territory as Jsonnet, CUE, Pkl, and Nickel. The rough positioning: Jsonnet gave you templating, CUE gave you types and constraints with a new mental model, and KCL aims for CUE-level validation with a more familiar imperative syntax and a better error-message experience for people coming from Python."}]}]}' WHERE `id` = 'kcl';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"kcp is the Kubernetes API machinery without Kubernetes. It is a fork of "},{"type":"text","text":"kube-apiserver","marks":[{"type":"code"}]},{"type":"text","text":" and the surrounding controller libraries, stripped of pods, nodes, and the rest of the container-oriented APIs, and extended with a native multi-tenancy concept called "},{"type":"text","text":"workspaces","marks":[{"type":"bold"}]},{"type":"text","text":". The result is a control plane that serves CRDs and the full watch/list/reconcile machinery you know from Kubernetes, but as a general-purpose declarative API platform rather than a container orchestrator."}]},{"type":"paragraph","content":[{"type":"text","text":"Workspaces are the headline feature: a kcp server can serve effectively unlimited logical clusters, each with its own API surface, RBAC, and resource graph, all sharing one etcd. "},{"type":"text","text":"APIExports","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"APIBindings","marks":[{"type":"bold"}]},{"type":"text","text":" let one workspace publish a set of CRDs and another workspace consume them, with a controller-facing \"virtual workspace\" endpoint that presents bound APIs across many tenants at once. This makes it possible to build a SaaS where every tenant thinks they have their own Kubernetes-style API for your product, without you running a cluster per tenant."}]},{"type":"paragraph","content":[{"type":"text","text":"Originally a Red Hat research project, kcp is now a CNCF sandbox project. It is not a Kubernetes distribution and you cannot run pods on it; think of it as \"the API layer of Kubernetes as a platform-building toolkit,\" in the space of Crossplane, Upbound Spaces, and the internal developer platform ecosystem."}]}]}' WHERE `id` = 'kcp';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KEDA (Kubernetes Event-Driven Autoscaling) scales Deployments, StatefulSets, and Jobs based on external event sources — queue depth, stream lag, database row counts, Prometheus queries, HTTP rate — instead of just CPU and memory. Crucially, it can scale a workload all the way down to zero replicas when there is nothing to do, and back up again when work arrives."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally KEDA is small. The "},{"type":"text","text":"operator","marks":[{"type":"bold"}]},{"type":"text","text":" watches "},{"type":"text","text":"ScaledObject","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"ScaledJob","marks":[{"type":"code"}]},{"type":"text","text":" CRDs, and for each one it reconciles a standard Kubernetes HPA behind the scenes. The scale-to-zero behavior is handled by the operator itself, because HPA alone cannot cross the 0⇔1 boundary. The "},{"type":"text","text":"metrics adapter","marks":[{"type":"bold"}]},{"type":"text","text":" implements the Kubernetes external metrics API, so the HPA can fetch \"messages in queue\" from KEDA rather than from an in-cluster metrics server. The actual event sources are exposed as \"scalers\" — over 60 of them, including Kafka, RabbitMQ, AWS SQS, Azure Service Bus, Redis streams, Prometheus, MongoDB, and NATS — each a Go package in the KEDA repo."}]},{"type":"paragraph","content":[{"type":"text","text":"KEDA was started by Microsoft and Red Hat, donated to the CNCF, and graduated in 2023. It is the standard answer for \"my worker should run zero pods when the Kafka topic is empty,\" and the underlying building block for serverless stacks like Azure Container Apps and the HTTP add-on for scale-from-zero on web workloads."}]}]}' WHERE `id` = 'keda';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kepler (Kubernetes Efficient Power Level Exporter) is a Prometheus exporter that estimates the energy consumption of Kubernetes pods, containers, and nodes. It attributes power draw back to individual workloads so you can reason about watts-per-request, not just CPU-per-request."}]},{"type":"paragraph","content":[{"type":"text","text":"Kepler reads hardware counters via eBPF programs attached to scheduler tracepoints, combining them with RAPL (Running Average Power Limit) on Intel/AMD CPUs, NVML for NVIDIA GPUs, and ACPI where available. On hardware that does not expose direct power counters — most public cloud VMs — it falls back to a pre-trained machine learning model that maps CPU cycles, instructions, cache misses, and memory references to estimated joules. Metrics are exported with standard Kubernetes labels (namespace, pod, container) so they join the rest of your Prometheus data without extra plumbing."}]},{"type":"paragraph","content":[{"type":"text","text":"It is typically paired with Grafana dashboards and the OpenTelemetry collector, and is the data source behind most CNCF TAG Environmental Sustainability work on carbon-aware scheduling and reporting. If you want a defensible number for the carbon footprint of a specific Deployment rather than a cluster-wide average from your cloud bill, Kepler is the project doing that job today."}]}]}' WHERE `id` = 'kepler';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keptn is a Kubernetes-native tool for evaluating deployments against Service Level Objectives and running pre- and post-deployment checks. In its current incarnation (Keptn Lifecycle Toolkit) it runs as an operator that watches Deployments, StatefulSets, and DaemonSets and attaches KeptnTask and KeptnEvaluation resources to their rollout lifecycle."}]},{"type":"paragraph","content":[{"type":"text","text":"The core idea is the KeptnMetric and KeptnEvaluationDefinition CRDs: you declare SLOs as queries against Prometheus, Datadog, Dynatrace, or any provider implementing the metrics provider interface, and Keptn blocks or fails a rollout if the query result is outside the expected range. It emits OpenTelemetry traces spanning from \"application version deployed\" through every pre/post task so you can see deployment lifecycle data in the same backend as your runtime traces."}]},{"type":"paragraph","content":[{"type":"text","text":"The original v1 Keptn was a heavier event-driven delivery platform built around its own Shipyard/Cloud Events control plane; that version was superseded by the lightweight lifecycle toolkit. Keptn was archived by the CNCF in September 2025, so new adopters should expect to be on their own for maintenance — the functional overlap is with Argo Rollouts analysis templates and Flagger for the same SLO-gated rollout use case."}]}]}' WHERE `id` = 'keptn';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keycloak is an open-source identity and access management server. It implements OpenID Connect, OAuth 2.0, and SAML 2.0, and handles user federation, single sign-on, social login, and fine-grained authorization against a pluggable user store."}]},{"type":"paragraph","content":[{"type":"text","text":"A Keycloak deployment is organized into realms, each with its own users, clients (applications), roles, groups, and identity providers. Users can live in Keycloak''s own database (backed by a JDBC store — Postgres in practice) or be federated from LDAP, Active Directory, or a custom SPI. Brokering to upstream IdPs (Google, GitHub, another Keycloak, any OIDC/SAML server) is a first-class feature, which is why it is so frequently used as the SSO layer in front of a mixed stack of in-house and off-the-shelf apps. The server is written in Java on Quarkus (Keycloak 17+ replaced the older WildFly distribution)."}]},{"type":"paragraph","content":[{"type":"text","text":"It competes with Okta, Auth0, and Azure AD on the commercial side, and with Authentik, Ory Hydra/Kratos, and Zitadel on the open-source side. Keycloak is the heaviest of those but also the most feature-complete for enterprise protocol support — if you need SAML, WS-Federation, LDAP federation, and OIDC in one box, it is usually the default answer."}]}]}' WHERE `id` = 'keycloak';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keylime is a remote boot attestation and runtime integrity monitoring system built on TPM 2.0. It lets you cryptographically verify that a remote machine booted the kernel, initramfs, and boot arguments you expected, and continuously monitor the IMA (Integrity Measurement Architecture) event log for unexpected file executions."}]},{"type":"paragraph","content":[{"type":"text","text":"The architecture has three parts: an agent running on each node that talks to the local TPM, a verifier that performs periodic quote attestation against known-good PCR values, and a registrar that tracks which agents exist and their enrollment keys (AIK/EK). When a node fails a quote — a PCR value diverges from policy, or IMA records a hash that is not on the allowlist — the verifier fires a revocation action, which can kick the node out of a cluster, rotate its credentials, or trigger any custom webhook."}]},{"type":"paragraph","content":[{"type":"text","text":"Keylime originated at MIT Lincoln Laboratory and is now used heavily in telco, government, and edge deployments where you need confidential/measured-boot guarantees. It is the hardware-root-of-trust counterpart to tools like in-toto or Sigstore (which attest to software supply chains) — Keylime attests to the machine the software is actually running on."}]}]}' WHERE `id` = 'keylime';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"kgateway is an Envoy-based ingress controller and API gateway that implements the Kubernetes Gateway API. It is the open-source project formerly known as Gloo Edge, donated to the CNCF by Solo.io in 2024 and renamed when it entered the sandbox."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally it is a control plane that watches Gateway, HTTPRoute, and kgateway-specific CRDs, then translates them into Envoy xDS configuration served to a fleet of Envoy proxies. The data plane is just vanilla Envoy, so you get the full set of Envoy filters — HTTP/1.1, HTTP/2, HTTP/3, gRPC, WebSockets, TCP, TLS termination, external authz, rate limiting via the Envoy ratelimit service, and WASM filter extensions. It supports transformation filters for request/response rewriting without writing a plugin, and has specific features for LLM/agent traffic (token-based rate limiting, prompt guarding) via the agentgateway integration."}]},{"type":"paragraph","content":[{"type":"text","text":"In the Gateway API landscape it sits alongside Istio, Envoy Gateway, Contour, and Traefik. The differentiator versus bare Envoy Gateway is the larger set of policy CRDs (auth, rate limit, transformations) inherited from Gloo, and a longer production history under the old name."}]}]}' WHERE `id` = 'kgateway';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KitOps packages AI/ML projects as OCI artifacts so model weights, datasets, code, and configuration can be versioned, signed, and distributed through any existing container registry. The packaging format is called a ModelKit, defined by a Kitfile manifest that lists each asset and its role."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood a ModelKit is a regular OCI artifact: each asset (model, dataset, notebook, code directory, config) becomes its own layer with a SHA-256 digest. Because it is plain OCI, you can push it to Docker Hub, ECR, GCR, GHCR, Harbor, Artifactory, or any other registry without new infrastructure, and sign it with Cosign the same way you sign container images. The "},{"type":"text","text":"kit","marks":[{"type":"code"}]},{"type":"text","text":" CLI lets you pull selectively — grab only the weights on a GPU inference node, only the dataset on a training job — without downloading the entire bundle."}]},{"type":"paragraph","content":[{"type":"text","text":"The problem KitOps solves is that ML teams were previously scattering models across Hugging Face, S3 buckets, DVC, and Git LFS, with no unified provenance story. It is the closest thing to \"containers for models\" and overlaps with Hugging Face Hub, MLflow''s model registry, and ORAS-based workflows, but stays closer to the existing DevOps toolchain by reusing OCI end-to-end."}]}]}' WHERE `id` = 'kitops';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kluctl is a declarative deployment tool for Kubernetes built around the concept of a deployment project — a directory tree of Kustomize bases, Helm charts, and Jinja2-templated manifests that describes an entire environment. Unlike most GitOps tools, it is designed to be run interactively from a terminal as well as from a controller."}]},{"type":"paragraph","content":[{"type":"text","text":"A Kluctl project defines targets (clusters/environments) and renders the same base deployment differently per target through variable sources pulled from Git, files, or env vars. The "},{"type":"text","text":"kluctl diff","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"kluctl deploy","marks":[{"type":"code"}]},{"type":"text","text":" commands show you exactly which resources will change before you apply them, with a tree-structured diff that distinguishes between new, changed, orphaned, and hook resources. Pruning is explicit: Kluctl tracks previously applied resources via labels and asks before deleting orphans. A flux-style controller is available for GitOps mode, but many users stick with the CLI workflow because the diff-first UX is the point."}]},{"type":"paragraph","content":[{"type":"text","text":"It overlaps with Flux, Argo CD, Helmfile, and raw Kustomize. Kluctl''s niche is teams who want Helm+Kustomize composition plus templating plus a proper local diff/apply loop without committing to a full GitOps controller."}]}]}' WHERE `id` = 'kluctl';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kmesh is a sidecarless service mesh data plane that runs traffic management logic in the Linux kernel via eBPF. Instead of steering pod traffic through a per-pod Envoy proxy, Kmesh attaches eBPF programs at the socket/cgroup level on each node and handles L4 routing, load balancing, and authorization there."}]},{"type":"paragraph","content":[{"type":"text","text":"It speaks the xDS protocol, so it can consume configuration from an Istio control plane (istiod) and replace the Envoy sidecar for most L4 use cases. For L7 features that are harder to implement in eBPF, Kmesh has a \"dual-engine\" mode that offloads HTTP-aware processing to a per-node waypoint proxy — conceptually similar to Istio ambient mesh''s ztunnel + waypoint split. The headline numbers the project reports are roughly 60% lower forwarding latency and 70% lower data-plane overhead versus sidecar Envoy, which is the usual motivation for moving mesh logic into the kernel."}]},{"type":"paragraph","content":[{"type":"text","text":"It is developed largely by Huawei and competes with Istio ambient, Cilium Service Mesh, and Linkerd. If you are evaluating ambient-style meshes specifically for the CPU/memory savings at high pod density, Kmesh is one of two serious eBPF-native options."}]}]}' WHERE `id` = 'kmesh';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Knative is a set of Kubernetes CRDs and controllers that add serverless primitives on top of any conformant cluster. It has two independent components: Serving, which handles request-driven workloads with scale-to-zero and revisions, and Eventing, which provides pub/sub plumbing around CloudEvents."}]},{"type":"paragraph","content":[{"type":"text","text":"Serving introduces the Service, Configuration, Revision, and Route resources. A Knative Service creates an immutable Revision for each config change; the Route then splits traffic between revisions by percentage, which is how you get canary and blue/green deployments for free. The activator and autoscaler (KPA) scale pods based on concurrent in-flight requests rather than CPU, and scale to zero by parking traffic at the activator until the first request arrives. Eventing provides Brokers, Triggers, Channels, and Subscriptions so you can wire up event sources (Kafka, GitHub, Kubernetes API, S3, etc.) to any HTTP endpoint with filtering by CloudEvent attributes."}]},{"type":"paragraph","content":[{"type":"text","text":"It is the engine behind Google Cloud Run, IBM Code Engine, and Red Hat OpenShift Serverless. If you want FaaS-style scale-to-zero and URL-addressable revisions on your own Kubernetes cluster — without buying into OpenFaaS, Fission, or a cloud provider — Knative is the de-facto choice. It graduated from the CNCF in September 2025."}]}]}' WHERE `id` = 'knative';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ko is a CLI that builds and publishes container images for Go applications without a Dockerfile and without a Docker daemon. You point it at a Go import path and it produces an OCI image and pushes it to a registry in one command."}]},{"type":"paragraph","content":[{"type":"text","text":"Because Go binaries are statically linked, ko skips the whole multi-stage Dockerfile dance: it cross-compiles the binary directly with the Go toolchain, then assembles an OCI image in-process using go-containerregistry. The resulting image is based on distroless ("},{"type":"text","text":"gcr.io/distroless/static","marks":[{"type":"code"}]},{"type":"text","text":" by default), so you get a tiny, non-root image with no shell or package manager. Because the image has a deterministic, reproducible layer layout, re-publishing the same source produces the same digest, which plays nicely with Sigstore/Cosign signing. ko also has a "},{"type":"text","text":"ko resolve","marks":[{"type":"code"}]},{"type":"text","text":" mode that rewrites "},{"type":"text","text":"image: ko://./cmd/foo","marks":[{"type":"code"}]},{"type":"text","text":" references in your YAML manifests with the pushed digest, which is the workflow Knative, Tekton, and Kubernetes SIGs use to ship their own components."}]},{"type":"paragraph","content":[{"type":"text","text":"For Go projects specifically it replaces Docker+Dockerfile entirely. For multi-language shops the rough equivalents are Buildpacks, Jib (Java), and Bazel rules_oci."}]}]}' WHERE `id` = 'ko';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Komodor is a commercial SaaS platform for Kubernetes troubleshooting and fleet operations. You install an agent in each cluster and it streams Kubernetes events, resource diffs, Helm releases, Argo CD sync history, and optional log/metric snapshots into a central backend that builds a timeline of every change."}]},{"type":"paragraph","content":[{"type":"text","text":"The product is organized around that timeline: when a pod starts crashlooping, you can see which Deployment revision, ConfigMap, Secret, or upstream chart change correlates in time with the failure, without stitching together kubectl output yourself. It layers RBAC, drift detection across a fleet of clusters, a node actions/remediation layer, and an AI assistant (Klaudia) that proposes probable root cause. Komodor is agnostic about where clusters run — EKS, GKE, AKS, on-prem — and connects to Prometheus/Datadog/Sentry/PagerDuty for cross-correlation."}]},{"type":"paragraph","content":[{"type":"text","text":"Overlapping tools include Robusta, Cast AI, Datadog''s Kubernetes product, and open-source k8sgpt. Komodor''s focus is specifically the change-centric view of why a workload broke between yesterday and today, which is a different angle than general-purpose Kubernetes observability."}]}]}' WHERE `id` = 'komodor';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Konveyor is a toolchain for assessing and migrating existing applications to Kubernetes and cloud-native runtimes. Its flagship component is the Migration Toolkit for Applications (MTA/Tackle), which performs static analysis of Java and other source codebases against rule sets to flag code that will not run well on OpenShift/Kubernetes."}]},{"type":"paragraph","content":[{"type":"text","text":"The analyzer is driven by YAML rule sets that match source patterns, library versions, or XML descriptors — for example, flagging EJB remote interfaces, JNDI lookups of a proprietary app server, or filesystem paths that assume local storage. Findings are tagged with effort estimates and categorized by migration target (containerization, Quarkus, Spring Boot, EAP on OpenShift) so a platform team can triage a portfolio of hundreds of apps. Beyond assessment, Konveyor includes Move2Kube for generating Kubernetes manifests from Cloud Foundry/Docker Compose input, and Crane for live migration of namespaces between clusters."}]},{"type":"paragraph","content":[{"type":"text","text":"It originated at Red Hat as the OSS side of Migration Toolkit for Applications and is most useful in enterprise Java shops moving legacy workloads off WebSphere/WebLogic/JBoss EAP onto OpenShift or vanilla Kubernetes."}]}]}' WHERE `id` = 'konveyor';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Koordinator is a Kubernetes scheduling system for colocating latency-sensitive online services with batch and AI workloads on the same nodes. It was open-sourced by Alibaba out of their internal experience running mixed workloads at very high cluster utilization."}]},{"type":"paragraph","content":[{"type":"text","text":"The core idea is QoS-aware overcommit. Koordinator labels pods with priority classes (product, mid, batch, free) and uses its koordlet node agent to continuously measure real CPU/memory headroom — not requests — and publish a \"reclaimed\" resource back to the scheduler. Batch pods then bin-pack into reclaimed capacity and get throttled or evicted under CPU/memory pressure before they can hurt the online tier. Isolation is enforced through cgroup tuning, CPU suppression, and memory QoS features in the kernel. It ships a scheduler built as a set of kube-scheduler plugins plus descheduler components that rebalance hot nodes."}]},{"type":"paragraph","content":[{"type":"text","text":"It is the closest open-source analog to Google''s Borg-style colocation, and overlaps with Volcano (batch scheduling) and Crane (cost/efficiency). Its niche is specifically wringing 60-70% cluster utilization out of hardware that would otherwise sit at 20% because the online services refuse to share nodes."}]}]}' WHERE `id` = 'koordinator';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"kpt is a package-oriented tool for managing Kubernetes configuration as data. A kpt package is a directory of plain YAML manifests plus a "},{"type":"text","text":"Kptfile","marks":[{"type":"code"}]},{"type":"text","text":" that records its upstream Git source, so "},{"type":"text","text":"kpt pkg get","marks":[{"type":"code"}]},{"type":"text","text":" clones the package and "},{"type":"text","text":"kpt pkg update","marks":[{"type":"code"}]},{"type":"text","text":" performs a 3-way merge when the upstream changes — the fork-with-updates workflow that bare Kustomize does not provide."}]},{"type":"paragraph","content":[{"type":"text","text":"Its distinguishing feature is KRM functions: containerized mutators and validators that implement the Kubernetes Resource Model (KRM) function spec. You run them via "},{"type":"text","text":"kpt fn render","marks":[{"type":"code"}]},{"type":"text","text":" as an in-package pipeline defined in the Kptfile, or ad-hoc via "},{"type":"text","text":"kpt fn eval","marks":[{"type":"code"}]},{"type":"text","text":". Functions can be written in Go using the kpt-functions-sdk, or any language packaged in a container, and are used for things like setting namespaces, injecting labels, substituting image tags, and policy validation (Gatekeeper constraints, conftest). Configurations stay declarative — functions read and rewrite the YAML — which is the \"configuration as data\" approach Google has pushed as an alternative to string templating."}]},{"type":"paragraph","content":[{"type":"text","text":"Google''s Config Sync and Nephio build on kpt. Its direct competitors are Kustomize, Helm, and Jsonnet. kpt never reached wide adoption outside Google-adjacent projects; the CNCF listing is sandbox and the matrix status here marks it graveyard, which is accurate — activity has slowed considerably."}]}]}' WHERE `id` = 'kpt';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Krkn (pronounced \"kraken\") is a chaos engineering tool for Kubernetes and OpenShift. It was originally built by Red Hat''s performance and scale team to find resilience bugs in OpenShift itself, and is the chaos framework they use in their own release pipeline."}]},{"type":"paragraph","content":[{"type":"text","text":"It ships a library of chaos scenarios driven by YAML — pod disruption, node shutdown, network chaos via tc/iptables, CPU/memory/IO hogs, time skew, application outages, etcd/API-server outages, zone failures, and PVC/ceph disruption. Each scenario runs for a configured duration while Krkn snapshots Prometheus metrics and measures cluster/application health against user-defined Cerberus signals. If the cluster or a monitored app breaches its SLOs during the run, the scenario fails, which makes the tool useful inside CI rather than just for manual game days. Krkn-hub packages the scenarios as container images so you can run them from a pipeline with only environment variables."}]},{"type":"paragraph","content":[{"type":"text","text":"In the chaos tooling landscape it sits alongside Chaos Mesh, LitmusChaos, and Gremlin. Its niche is Kubernetes control-plane and infrastructure-level fault injection with tight Prometheus/SLO integration, rather than application-level HTTP/gRPC fault injection."}]}]}' WHERE `id` = 'krkn';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KRR (Kubernetes Resource Recommender) is a command-line tool from Robusta that reads historical CPU and memory usage from Prometheus and recommends new "},{"type":"text","text":"requests","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"limits","marks":[{"type":"code"}]},{"type":"text","text":" for every workload in a cluster. It is agentless: nothing is installed in the cluster, the CLI just queries Prometheus and the Kubernetes API directly."}]},{"type":"paragraph","content":[{"type":"text","text":"By default it uses the \"simple\" strategy — CPU request set to the 95th percentile of observed usage, memory request set to the maximum observed usage plus a 15% buffer, and CPU limits unset to avoid throttling latency-sensitive workloads. The strategy is pluggable, so you can ship your own scoring function if you disagree with those heuristics. Output includes a terminal table, JSON, CSV, or HTML, showing current vs recommended values and the cost savings if you applied them. KRR does not write back to the cluster by default; you are meant to review the diff and roll it into your GitOps repo."}]},{"type":"paragraph","content":[{"type":"text","text":"It is an alternative to the built-in Vertical Pod Autoscaler (VPA) recommender, which requires installing the VPA controller and is awkward to run in report-only mode. If you already run Prometheus or a compatible store (Thanos, Mimir, Victoria Metrics, Coralogix, Grafana Cloud), KRR is the quickest way to get a ranked list of over- and under-provisioned workloads."}]}]}' WHERE `id` = 'krr';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KServe is a Kubernetes-native model inference platform. It provides an "},{"type":"text","text":"InferenceService","marks":[{"type":"code"}]},{"type":"text","text":" CRD that takes a model artifact (from S3, GCS, PVC, or an OCI registry) and a framework name, and stands up a serving deployment with autoscaling, canary rollouts, and a standard prediction HTTP/gRPC interface."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood it sits on top of Knative Serving for request-driven autoscaling (including scale-to-zero) and Istio or Gateway API for traffic routing. A model pod runs a framework-specific runtime — TensorFlow Serving, TorchServe, Triton, SKLearn, XGBoost, HuggingFace — wrapped in the KServe predictor contract, and can optionally chain to transformer and explainer pods for pre/post-processing and feature attribution. KServe implements the Open Inference Protocol (v2), so clients speak the same REST/gRPC API regardless of the backing runtime. ModelMesh, merged into the project, adds multi-model serving where hundreds of small models share a pool of runtime pods, which is how you serve a long tail of models cost-effectively."}]},{"type":"paragraph","content":[{"type":"text","text":"It started life as KFServing inside Kubeflow and was spun out as its own project. Comparable tools include Seldon Core, BentoML, NVIDIA Triton standalone, and Ray Serve — KServe''s differentiator is the tight Kubernetes/Knative integration and the standardized inference protocol."}]}]}' WHERE `id` = 'kserve';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kuadrant is a set of Kubernetes Gateway API policy extensions that add rate limiting, authentication, authorization, and multi-cluster DNS/TLS to any Gateway API implementation. It does not ship its own gateway; instead it attaches policies to existing Istio or Envoy Gateway installations."}]},{"type":"paragraph","content":[{"type":"text","text":"The core CRDs are AuthPolicy, RateLimitPolicy, DNSPolicy, and TLSPolicy, all of which attach to a Gateway or HTTPRoute via the Gateway API policy attachment pattern. Auth and rate limit policies are enforced by two sub-components — Authorino (an ext_authz service backed by OPA/CEL-like expressions, supporting OIDC, API keys, mTLS, OPA Rego) and Limitador (a Redis-backed ext_ratelimit service implementing the Envoy ratelimit protocol). Because these are standard Envoy extension points, the same policies work across any Envoy-based Gateway API implementation. DNSPolicy and TLSPolicy, paired with a multi-cluster gateway setup, handle GSLB-style failover and cert-manager integration across clusters."}]},{"type":"paragraph","content":[{"type":"text","text":"Kuadrant is developed by Red Hat and shares heritage with 3scale. Compared to a bespoke API management product (Kong, Apigee, 3scale on-premises), Kuadrant is specifically the Kubernetes-native, CRD-driven version layered on open Gateway API rather than a separate proxy and control plane."}]}]}' WHERE `id` = 'kuadrant';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kuasar is a container runtime that implements the containerd \"sandboxer\" API to support multiple sandbox technologies side-by-side on a single node. It is written in Rust and was donated to the CNCF by Huawei."}]},{"type":"paragraph","content":[{"type":"text","text":"The problem it solves is shim sprawl. In stock containerd, each pod spawns its own containerd-shim process per sandbox, which at high density (hundreds of pods on a node) becomes meaningful memory and CPU overhead. Kuasar replaces the per-pod shim with a single long-running sandboxer process per sandbox type, using containerd''s sandbox API (introduced in 1.7). It ships sandboxers for MicroVM-based runtimes (Cloud Hypervisor, QEMU, StratoVirt — the Kata Containers use case), WasmEdge for WebAssembly workloads, quark for lightweight Linux sandboxes, and a runc sandboxer for classic Linux containers. All of them are managed through one unified interface so you can mix VM, Wasm, and runc pods on the same node."}]},{"type":"paragraph","content":[{"type":"text","text":"The reported win versus per-shim runtimes is ~99% reduction in shim memory overhead and ~2x faster pod startup. It competes with Kata''s shim-v2 and the traditional runc+containerd stack when the goal is high-density multi-tenant nodes or mixing sandbox types."}]}]}' WHERE `id` = 'kuasar';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"kube-bench is a Go tool from Aqua Security that checks whether a Kubernetes cluster is deployed according to the CIS Kubernetes Benchmark. It runs on a node (or as a Job), inspects process flags, file permissions, and configuration files for the API server, controller manager, scheduler, kubelet, and etcd, and prints a pass/fail/warn per CIS control."}]},{"type":"paragraph","content":[{"type":"text","text":"Checks are declarative YAML, grouped by benchmark version (CIS 1.23, 1.24, 1.27, etc.) and by target (master, node, etcd, policies). Each check has a "},{"type":"text","text":"test","marks":[{"type":"code"}]},{"type":"text","text":" that can run a binary, parse a file, or grep a process argument — for example, \"ensure "},{"type":"text","text":"--anonymous-auth=false","marks":[{"type":"code"}]},{"type":"text","text":" on the API server\" or \"ensure "},{"type":"text","text":"/etc/kubernetes/admin.conf","marks":[{"type":"code"}]},{"type":"text","text":" has 600 permissions.\" Because the checks are data, you can override them for managed distributions; kube-bench ships variants for EKS, GKE, AKS, OpenShift, Rancher, and k3s that skip controls the cloud provider owns."}]},{"type":"paragraph","content":[{"type":"text","text":"It is effectively the standard tool for auditing cluster configuration against CIS and is commonly run as a Kubernetes CronJob with results shipped to a SIEM. It only checks static configuration — for runtime and workload-level checks you pair it with kube-hunter, Trivy, or Falco."}]}]}' WHERE `id` = 'kube-bench';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"kube-burner is a performance and scale testing tool for Kubernetes. It hammers an API server with configurable churn of objects — Namespaces, Deployments, Pods, Services, Secrets, ConfigMaps, custom CRDs — while recording timing, API server latency, and cluster metrics to measure how a cluster behaves at scale."}]},{"type":"paragraph","content":[{"type":"text","text":"A test is a YAML config file listing jobs; each job specifies an object template, how many to create (jobIterations), queries-per-second limits, and an optional churn phase where objects are deleted and recreated to simulate long-running turnover. kube-burner talks to the API server directly via client-go, measures per-object apply/ready latency, and optionally scrapes Prometheus at the end of the run to compute alerting and a set of built-in indicators (etcd fsync P99, API server request latency, kubelet pod startup latency) that get indexed into Elasticsearch/OpenSearch for later comparison. It has a plugin for OCP (kube-burner-ocp) that wraps the canonical Red Hat scale tests — node-density, cluster-density-v2, etc."}]},{"type":"paragraph","content":[{"type":"text","text":"Red Hat uses kube-burner in its own release pipeline to catch scale regressions in OpenShift. It is the go-to tool when you want to answer \"how many pods/nodes/secrets can this control plane handle before latency degrades\" with reproducible numbers rather than vibes."}]}]}' WHERE `id` = 'kube-burner';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"kube-hunter is a penetration-testing tool for Kubernetes, also from Aqua Security. Where kube-bench audits static configuration, kube-hunter actively probes a cluster from the network to find exploitable weaknesses — exposed kubelets, open etcd, unauthenticated API server endpoints, leaked service account tokens, insecure dashboard installs, and so on."}]},{"type":"paragraph","content":[{"type":"text","text":"It can run in three modes: remote (from outside the cluster, pointed at an IP or CIDR), internal (from inside a pod, simulating a compromised workload), and network (scanning a whole subnet for Kubernetes components). Each \"hunter\" module is a Python plugin that looks for one class of issue and reports a CVE or vulnerability ID with severity. An \"active hunting\" flag enables checks that go beyond detection and actually attempt exploitation — e.g., running a command through an exposed kubelet — which is why it is normally only pointed at test clusters."}]},{"type":"paragraph","content":[{"type":"text","text":"It is the tool you reach for when you want to answer \"what can an attacker see and do if they land on a pod in this cluster?\" rather than \"is this cluster configured correctly?\" Aqua now says kube-hunter is not under active development and recommends Trivy for new Kubernetes scanning work; the project still works, but new coverage has largely moved there and to commercial scanners."}]}]}' WHERE `id` = 'kube-hunter';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kube-OVN is a Kubernetes CNI plugin that uses OVN (Open Virtual Network) and Open vSwitch as its data plane. OVN originated in the OpenStack/Neutron world, and Kube-OVN wraps it to deliver Kubernetes pod networking with the kind of SDN features the traditional CNI plugins (Flannel, Calico) do not emphasise."}]},{"type":"paragraph","content":[{"type":"text","text":"Each Kubernetes Namespace maps to an OVN logical switch by default, so you get subnet-per-namespace, native IPAM, and subnet-level QoS/ACLs out of the box. Beyond that it ships static IPs for pods, multiple subnets and IP pools, VPCs with overlapping CIDRs, virtual routers, load balancers, ECMP, BGP/VXLAN underlay modes, DPDK/Hardware offload for high throughput, and a SR-IOV/Offload path for bare metal. Multus multi-NIC, dual-stack IPv4/IPv6, and egress gateways are all supported. Observability pulls through OVN flow tracing, "},{"type":"text","text":"kubectl ko","marks":[{"type":"code"}]},{"type":"text","text":" pktmon utilities, and Prometheus metrics on flow table depth, conntrack entries, and per-pod traffic."}]},{"type":"paragraph","content":[{"type":"text","text":"Kube-OVN is heavy compared to Flannel or Calico, but that is the point — it is aimed at telco/NFV, edge, and multi-tenant workloads that need VPC-like isolation, overlapping IP spaces, or per-workload QoS that Calico''s BGP-first model does not cover cleanly."}]}]}' WHERE `id` = 'kube-ovn';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"kube-rs is the Rust client for Kubernetes and the ecosystem around it. It is the Rust equivalent of client-go: an async API client, typed resource bindings, a watch/informer cache layer, and a controller-runtime-style reconciliation framework for writing operators in Rust."}]},{"type":"paragraph","content":[{"type":"text","text":"The crate set is split into "},{"type":"text","text":"kube","marks":[{"type":"code"}]},{"type":"text","text":" (the umbrella), "},{"type":"text","text":"kube-client","marks":[{"type":"code"}]},{"type":"text","text":" (HTTP/gRPC client over hyper and tower), "},{"type":"text","text":"kube-core","marks":[{"type":"code"}]},{"type":"text","text":" (types and API mechanics), "},{"type":"text","text":"kube-derive","marks":[{"type":"code"}]},{"type":"text","text":" (a procedural macro that generates CRD structs with OpenAPI schemas from Rust types), and "},{"type":"text","text":"kube-runtime","marks":[{"type":"code"}]},{"type":"text","text":" (watcher streams, reflectors, and a "},{"type":"text","text":"Controller","marks":[{"type":"code"}]},{"type":"text","text":" that maps to the Go controller-runtime pattern). CRDs are defined as ordinary Rust structs annotated with "},{"type":"text","text":"#[derive(CustomResource, JsonSchema)]","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"kube::CustomResourceExt::crd()","marks":[{"type":"code"}]},{"type":"text","text":" emits the YAML CRD definition at compile time. It targets stable Rust, builds on tokio, and interoperates with tower middleware for tracing, metrics, and retries."}]},{"type":"paragraph","content":[{"type":"text","text":"It is the foundation for most Rust-based Kubernetes controllers in production — Krustlet, Linkerd''s policy controller, Stackable, Materialize''s operators, and many of the controllers inside Fermyon. If you want to write an operator in Rust instead of Go, kube-rs is effectively the only serious choice."}]}]}' WHERE `id` = 'kube-rs';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"kube-vip provides a virtual IP and L4 load balancer for Kubernetes on bare metal, where there is no cloud LB sitting in front of the cluster. It handles two distinct jobs: HA for the control plane (a floating VIP in front of the kube-apiserver) and Service type LoadBalancer implementation for workload traffic."}]},{"type":"paragraph","content":[{"type":"text","text":"It runs as a static pod on control plane nodes or a DaemonSet on workers and supports two announcement modes. In ARP/Layer 2 mode, a leader elected via a Kubernetes lease emits gratuitous ARPs for the VIP; on failover the next leader takes over the address, same pattern as keepalived. In BGP mode it peers with your top-of-rack routers (or a route reflector) and announces VIPs as /32 routes, enabling ECMP across nodes and routable failover across L3 boundaries. For Service LoadBalancer it allocates IPs from a configured pool and optionally integrates with kube-vip-cloud-provider to implement the standard "},{"type":"text","text":"LoadBalancer","marks":[{"type":"code"}]},{"type":"text","text":" status handshake."}]},{"type":"paragraph","content":[{"type":"text","text":"It is the default LB in Kubernetes the Hard Way-style bare-metal installs and in distros like k3s, RKE2, Talos, and Cluster API''s CAPV/CAPBM. The main alternative is MetalLB — kube-vip''s advantage is the combined control-plane VIP + Service LB in one component, whereas MetalLB only handles Services."}]}]}' WHERE `id` = 'kube-vip';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubean is a Kubernetes cluster lifecycle operator built on top of Kubespray. It wraps Kubespray''s Ansible playbooks in a set of CRDs so you can drive cluster install, scale, upgrade, and teardown operations by writing YAML to a management cluster instead of running ansible-playbook from a laptop."}]},{"type":"paragraph","content":[{"type":"text","text":"The key CRDs are "},{"type":"text","text":"Cluster","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ClusterOperation","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Manifest","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"LocalService","marks":[{"type":"code"}]},{"type":"text","text":". A Cluster defines inventory and global vars; a ClusterOperation is a Job-like resource describing the action (create, upgrade, scale, reset) and kicks off a pod that runs the corresponding Kubespray playbook against the target hosts. The Manifest records the tested matrix of Kubernetes + addon versions and the container images required for air-gapped installs, and LocalService configures the offline package/image mirror that Kubean can serve. Because the operator model gives you status subresources and events, you can GitOps cluster lifecycles the same way you GitOps workloads."}]},{"type":"paragraph","content":[{"type":"text","text":"Kubean is developed by DaoCloud and is used as the cluster installer inside their Kairship and DCE platforms. Compared to Cluster API it is less abstract — it is specifically Kubespray-as-an-operator — which makes it a good fit for bare metal and air-gapped environments where Kubespray is already the trusted installer."}]}]}' WHERE `id` = 'kubean';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KubeArmor is a runtime security enforcement engine for Kubernetes, VMs, and bare metal. Unlike Falco, which detects and alerts on suspicious events, KubeArmor actively blocks them at the kernel level using Linux Security Modules — AppArmor, SELinux, or BPF-LSM depending on what the host supports."}]},{"type":"paragraph","content":[{"type":"text","text":"Policies are expressed as "},{"type":"text","text":"KubeArmorPolicy","marks":[{"type":"code"}]},{"type":"text","text":" CRDs that target pods by label and describe allowed/blocked process executions, file access paths, network access, and Linux capabilities. The KubeArmor daemon on each node translates those policies into concrete LSM rules (AppArmor profiles, SELinux context, or BPF-LSM programs) and attaches them to the matching container''s cgroup. Because enforcement happens in-kernel before the syscall returns, you get actual prevention rather than post-facto alerts: a pod that tries to exec "},{"type":"text","text":"/bin/sh","marks":[{"type":"code"}]},{"type":"text","text":" or write to "},{"type":"text","text":"/etc","marks":[{"type":"code"}]},{"type":"text","text":" outside of its policy is blocked with -EPERM. An eBPF-based observer emits telemetry of allowed and denied syscalls for SIEM ingestion."}]},{"type":"paragraph","content":[{"type":"text","text":"It was contributed to the CNCF by AccuKnox. Its natural comparisons are Falco (detection), Tetragon (observation + optional enforcement via eBPF), and plain AppArmor profiles — KubeArmor''s niche is giving you LSM-backed enforcement with a Kubernetes-native policy surface."}]}]}' WHERE `id` = 'kubearmor';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KubeClipper is a lightweight Kubernetes cluster lifecycle manager with a web UI. You install it with a single "},{"type":"text","text":"kcctl deploy","marks":[{"type":"code"}]},{"type":"text","text":" command and then drive cluster creation, scaling, upgrade, and backup across a fleet of remote hosts from a browser — no Ansible inventory, no separate management cluster required."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally it has two components: "},{"type":"text","text":"kc-server","marks":[{"type":"code"}]},{"type":"text","text":", a control plane that stores cluster state in an embedded etcd and exposes a REST API + UI, and "},{"type":"text","text":"kc-agent","marks":[{"type":"code"}]},{"type":"text","text":", a per-host agent that receives operations (install kubeadm, pull images, configure CRI, join cluster) from the server over a message queue. Because the agent is only ~10 MB and speaks a simple protocol, KubeClipper is well suited to bare metal, edge, and air-gapped sites where you cannot assume SSH + Python are available the way Kubespray does. It supports multiple Kubernetes distributions and CNI/CRI combinations, and includes a plugin system for registering addons."}]},{"type":"paragraph","content":[{"type":"text","text":"In the installer landscape it sits alongside Kubespray, Kubean, Kops, and Cluster API. Its niche is the \"I want a GUI to manage a handful of small clusters at the edge\" case that none of those cleanly address. It is developed by 99cloud."}]}]}' WHERE `id` = 'kubeclipper';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KubeEdge extends Kubernetes out to edge nodes that have intermittent connectivity, limited resources, and often sit behind NAT. Instead of running a full kubelet + kube-proxy + CNI stack on every edge device, KubeEdge splits the system into a cloud side (CloudCore) and an edge side (EdgeCore) and runs a tiny agent at the edge."}]},{"type":"paragraph","content":[{"type":"text","text":"CloudCore lives in your central Kubernetes cluster and extends the API server with EdgeController, DeviceController, and a sync service. EdgeCore is the edge agent: it contains Edged (a slimmed-down kubelet that runs pods via containerd/CRI-O), EdgeHub (a WebSocket client that tunnels back to CloudCore), DeviceTwin (a local SQLite store that caches device/state), and EventBus (an MQTT broker for talking to IoT devices on the LAN). Because the edge keeps a local state store, pods keep running and devices keep being controlled when the WAN link drops, and sync resumes automatically when connectivity returns. Device abstractions (Device, DeviceModel CRDs) let you model sensors/actuators declaratively and map them to Modbus, OPC-UA, Bluetooth, or MQTT protocol drivers."}]},{"type":"paragraph","content":[{"type":"text","text":"It graduated from the CNCF in September 2024. Its competition is K3s (which takes the opposite approach — run a full if slim Kubernetes at the edge), OpenYurt, and SuperEdge. KubeEdge''s differentiator is first-class IoT device modeling and the offline-tolerant sync design."}]}]}' WHERE `id` = 'kubeedge';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KubeFleet is a multi-cluster Kubernetes resource placement controller. You designate one cluster as the fleet hub and register other clusters as members; KubeFleet then propagates selected resources from the hub to member clusters according to declarative placement policies."}]},{"type":"paragraph","content":[{"type":"text","text":"The core CRDs are "},{"type":"text","text":"MemberCluster","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ClusterResourcePlacement","marks":[{"type":"code"}]},{"type":"text","text":" (CRP), and "},{"type":"text","text":"Work","marks":[{"type":"code"}]},{"type":"text","text":". A CRP selects a set of resources on the hub (by namespace, label, or GVK) and a set of target clusters (by label, property, or a scheduling strategy — PickAll, PickN, PickFixed). The fleet scheduler then produces Work objects that an agent on each member cluster reconciles into actual resources, with rollout strategies, drift detection, and staged updates. It supports cluster properties and cost-based scoring so you can prefer cheaper or less-loaded clusters, and taints/tolerations at the cluster level so you can cordon clusters for maintenance without changing every placement."}]},{"type":"paragraph","content":[{"type":"text","text":"KubeFleet is the open-source upstream behind Azure Kubernetes Fleet Manager; Microsoft donated it to the CNCF sandbox in early 2025. It overlaps with Karmada, Open Cluster Management, and Liqo — its differentiator is the close mapping to the Kubernetes API (placements feel like a multi-cluster scheduler for arbitrary resources) and production hardening from the Azure Fleet service."}]}]}' WHERE `id` = 'kubefleet';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubeflow is an umbrella project for running the end-to-end machine learning lifecycle on Kubernetes. It is not a single binary but a collection of independently installable components that share the same CRD-driven, Kubernetes-native model."}]},{"type":"paragraph","content":[{"type":"text","text":"The main components are Kubeflow Pipelines (a DAG engine for ML workflows backed by Argo Workflows, with Python SDK, artifact tracking, and a UI for experiments and runs), the Training Operator (TFJob, PyTorchJob, MPIJob, XGBoostJob, PaddleJob CRDs for distributed training with gang scheduling), Katib (a CRD-driven hyperparameter tuning and neural architecture search controller supporting Bayesian optimization, TPE, Hyperband, and random search), Notebooks (managed JupyterLab and VSCode instances per user, mounted on PVCs with GPU access), and the Kubeflow Central Dashboard with multi-tenant profiles built on Istio + Dex for per-namespace isolation. KServe used to be in-tree as KFServing and is now a separate CNCF incubating project you compose with."}]},{"type":"paragraph","content":[{"type":"text","text":"It originated at Google as a way to run TensorFlow Extended pipelines on Kubernetes and now underpins managed products like Vertex AI Pipelines, AWS SageMaker (Kubeflow on EKS), and IBM watsonx.ai. Its main alternatives are MLflow plus raw Kubernetes jobs for smaller setups, and SageMaker/Vertex for a fully managed path — Kubeflow is what you pick when you want to own the full stack on your own clusters."}]}]}' WHERE `id` = 'kubeflow';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kuberhealthy is a synthetic monitoring operator for Kubernetes. It runs user-defined \"check\" pods on a schedule and exposes their pass/fail results as Prometheus metrics and a JSON status endpoint, so you can alert on \"can this cluster actually do the thing\" rather than only on symptomatic CPU or memory signals."}]},{"type":"paragraph","content":[{"type":"text","text":"A check is just a container that runs, does something, and reports success or failure back to the Kuberhealthy operator via an injected URL and token. Out of the box it ships checks for deployment (can the cluster create a Deployment, roll it, and tear it down?), DNS resolution, image pull, PVC provisioning, kube-proxy connectivity, daemonset rollout, and network connectivity across nodes. Because checks are just containers, you can write your own in any language — the standard pattern is a small Go or Python binary that calls the Kubernetes API or your own application and reports success via the client library. A "},{"type":"text","text":"KuberhealthyCheck","marks":[{"type":"code"}]},{"type":"text","text":" CRD declares the image, schedule, and timeout; the operator runs the pod in a dedicated namespace and tracks its last state."}]},{"type":"paragraph","content":[{"type":"text","text":"It was open-sourced by Comcast and later moved to the kuberhealthy org. Its niche versus Prometheus blackbox_exporter is that checks run inside the cluster and exercise Kubernetes primitives, which is how you catch things like \"PersistentVolumes have been failing to bind for two hours\" before any workload notices."}]}]}' WHERE `id` = 'kuberhealthy';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubernetes is a container orchestrator with a declarative API. You describe the desired state of your workloads as objects — Pods, Deployments, StatefulSets, Services, Ingresses, ConfigMaps, Secrets, Jobs, CronJobs — and a set of controllers continuously reconciles the cluster toward that state. This controller pattern is the single idea the entire project is built around: every feature, from core workload types to third-party operators, is implemented as a reconciliation loop watching an object in the API."}]},{"type":"paragraph","content":[{"type":"text","text":"A cluster has a control plane and a set of nodes. The control plane runs the API server (the only component that talks to storage), etcd (the backing key-value store holding every object), the scheduler (which assigns Pods to nodes based on resource requests, affinities, taints, and topology constraints), and the controller manager (which runs the built-in reconciliation loops for ReplicaSets, endpoints, nodes, service accounts, and so on). Each node runs the kubelet, which takes Pod specs from the API server and drives a container runtime over CRI to actually start containers, and kube-proxy (or eBPF equivalents like Cilium) to implement ClusterIP Services via iptables/IPVS/eBPF. Networking, storage, and container runtime are all pluggable via CNI, CSI, and CRI, which is how the ecosystem ended up with dozens of interchangeable network and storage backends."}]},{"type":"paragraph","content":[{"type":"text","text":"Multi-tenancy is handled through namespaces, RBAC, ResourceQuotas, NetworkPolicies, and PodSecurity admission. Extension is handled through CustomResourceDefinitions plus controllers — \"the operator pattern\" — which is why Kubernetes has become the substrate for things as diverse as databases, CI systems, ML platforms, and service meshes."}]},{"type":"paragraph","content":[{"type":"text","text":"It came out of Google''s Borg lineage, was the first project to graduate from the CNCF, and is now the de facto API for running server-side workloads in essentially every cloud and most data centers. Its main competition at this point is itself: the interesting choices are between distributions (EKS, GKE, AKS, OpenShift, k3s, Talos, kubeadm) rather than between Kubernetes and something else."}]}]}' WHERE `id` = 'kubernetes';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubescape is a Kubernetes security scanner that checks manifests, Helm charts, and live clusters against hardening frameworks including the NSA/CISA Kubernetes Hardening Guide, MITRE ATT&CK, and the CIS Kubernetes Benchmark. It was created by ARMO and donated to the CNCF, where it is now an incubating project."}]},{"type":"paragraph","content":[{"type":"text","text":"The scanner runs as a CLI for CI pipelines and as an in-cluster operator that continuously evaluates resources. Controls are written in Rego and executed by the OPA engine, so rules are portable and auditable. Beyond static checks, Kubescape ships an eBPF-based node agent that records syscalls and network activity to build application profiles, then flags runtime deviations and generates tailored seccomp profiles and network policies from observed behaviour. It also pulls SBOMs and matches them against Grype''s vulnerability database to correlate CVEs with the workloads that actually load the affected files."}]},{"type":"paragraph","content":[{"type":"text","text":"Results surface through a CLI, a Prometheus exporter, VS Code and Lens integrations, and the hosted ARMO Platform. In the CNCF landscape Kubescape overlaps with kube-bench (CIS-only), Trivy (image-first), and Falco (runtime-only), combining posture scanning, vulnerability management, and runtime detection in a single agent."}]}]}' WHERE `id` = 'kubescape';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KubeSlice is a Kubernetes multi-cluster networking project, originally built by Avesha and donated to the CNCF as a sandbox project. It stitches namespaces across clusters into a logical \"slice\" with its own overlay network, flat IP space, and isolation boundary, letting pods in different clusters talk as if they sat in the same cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"A slice is defined by a SliceConfig custom resource managed by the KubeSlice Controller, which runs on a dedicated Kubernetes cluster and drives workers in every participating data-plane cluster. Each worker runs slice operators that program an overlay built on WireGuard tunnels between slice gateway pods, plus an Istio-based east-west service export and import mechanism for discovery. Namespace isolation, network policies, and per-slice QoS are enforced by the operators so that tenants sharing a cluster cannot see each other''s traffic."}]},{"type":"paragraph","content":[{"type":"text","text":"In the CNCF landscape KubeSlice overlaps with Submariner, Cilium Cluster Mesh, and Liqo, but differs by framing multi-cluster connectivity as tenanted slices rather than raw pod-to-pod routing, which fits multi-tenant platforms and 5G edge deployments where each tenant needs its own network view across clouds."}]}]}' WHERE `id` = 'kubeslice';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KubeStellar is a CNCF sandbox project for multi-cluster workload placement on Kubernetes. It lets you write a normal Kubernetes manifest once in a central control plane and have it delivered to any number of target clusters selected by label, without teaching your tooling about the remote clusters."}]},{"type":"paragraph","content":[{"type":"text","text":"The architecture is built on KubeFlex, which hosts lightweight Kubernetes control planes as tenants. A Workload Description Space (WDS) holds the user''s desired manifests, an Inventory and Transport Space (ITS) tracks registered workload execution clusters (WECs), and BindingPolicy custom resources match objects in the WDS to clusters in the ITS. A transport controller then syncs the matched objects out to the target clusters and reports status back. Because the WDS exposes a real kube-apiserver, any tool that speaks Kubernetes — kubectl, Helm, Argo CD, Flux — can drive multi-cluster deployments unchanged."}]},{"type":"paragraph","content":[{"type":"text","text":"KubeStellar grew out of IBM Research''s work on the earlier KCP project and overlaps with Open Cluster Management, Karmada, and Argo CD ApplicationSets, but leans harder on the \"plain Kubernetes API everywhere\" model and decouples inventory, workload description, and transport."}]}]}' WHERE `id` = 'kubestellar';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KubeVela is an application delivery platform built on the Open Application Model (OAM), originally developed at Alibaba and now a CNCF incubating project. It lets platform teams describe reusable Components, Traits, Policies, and Workflow steps in CUE, then exposes them to developers through a single Application custom resource that hides the underlying Kubernetes machinery."}]},{"type":"paragraph","content":[{"type":"text","text":"At runtime the KubeVela controller renders an Application into concrete resources — Deployments, Services, Helm releases, Terraform modules, or any CRD — by executing the workflow steps defined on the app. Rollouts, canary, multi-cluster delivery via Cluster Gateway, and approval gates are all expressed as workflow steps rather than bolted on. Because definitions are CUE-based, platform engineers can extend the catalog without forking the controller."}]},{"type":"paragraph","content":[{"type":"text","text":"KubeVela sits in the same space as Crossplane compositions, Argo CD + Kustomize stacks, and Humanitec, but its distinguishing idea is OAM''s separation of application definition from platform capabilities, so the same Application manifest can target different environments by swapping the backing Trait and Policy implementations."}]}]}' WHERE `id` = 'kubevela';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubevious is a Kubernetes dashboard and rule engine focused on configuration correlation and safety. Instead of showing resources as flat lists, it builds an application-centric tree that joins Deployments, Services, Ingresses, ConfigMaps, RBAC, and network policies so you can see everything that touches a workload in one place."}]},{"type":"paragraph","content":[{"type":"text","text":"The backend ingests cluster state into a graph, runs a rules engine against it, and ships built-in checks for common mistakes like dangling services, missing resource limits, or RBAC that grants cluster-admin by accident. Custom rules are written in a small JavaScript-like DSL and can flag or warn on any shape in the graph. A \"time machine\" feature snapshots cluster state so operators can diff configuration between two points in time for forensics. A Slack bot and a CLI round out the interface."}]},{"type":"paragraph","content":[{"type":"text","text":"Kubevious is a CNCF sandbox project and overlaps with Lens and Headlamp for visualisation, and with Polaris or Datree for policy checks, but its value is the correlated view — answering \"what will break if I change this ConfigMap\" rather than listing raw objects."}]}]}' WHERE `id` = 'kubevious';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KubeVirt is a Kubernetes add-on that runs virtual machines as first-class workloads alongside containers. A VirtualMachine custom resource maps to a pod whose main container wraps libvirt and QEMU/KVM, so the guest gets real hardware virtualisation while Kubernetes schedules, networks, and stores it like any other pod."}]},{"type":"paragraph","content":[{"type":"text","text":"The control plane consists of virt-operator, virt-api, and virt-controller running in the cluster, plus a virt-handler DaemonSet on every node that supervises local virt-launcher pods. Storage attaches via CDI (Containerized Data Importer), which imports disk images into PVCs, and live migration is implemented by streaming QEMU state between virt-launcher pods on different nodes. Networking uses the standard CNI stack, with Multus commonly layered in to attach extra NICs from bridges or SR-IOV for VMs that need bare-metal-grade connectivity."}]},{"type":"paragraph","content":[{"type":"text","text":"KubeVirt is a CNCF incubating project and the engine behind Red Hat OpenShift Virtualization and SUSE Harvester. It targets teams that want to retire standalone oVirt or vSphere clusters and run legacy VMs next to modern containerised workloads on a single Kubernetes control plane."}]}]}' WHERE `id` = 'kubevirt';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubewarden is a Kubernetes policy engine that executes admission policies as WebAssembly modules. Policies are compiled to Wasm from Rust, Go, Rego, or Swift and distributed as OCI artifacts, so the same supply-chain tooling used for container images — registries, signing, SBOMs — applies to policies."}]},{"type":"paragraph","content":[{"type":"text","text":"The project installs a ValidatingAdmissionWebhook and a MutatingAdmissionWebhook backed by PolicyServer pods, which load Wasm modules on demand and run them in a sandboxed wasmtime runtime. ClusterAdmissionPolicy and AdmissionPolicy custom resources bind a module to specific resources and operations, and an audit scanner re-evaluates policies against existing cluster state to catch drift. Because Wasm modules are stateless and deterministic, they start fast and can be cached and shared across clusters."}]},{"type":"paragraph","content":[{"type":"text","text":"Kubewarden is a CNCF sandbox project sponsored by SUSE. It sits in the same space as OPA Gatekeeper and Kyverno, but differs in letting policy authors use general-purpose languages compiled to Wasm instead of Rego or Kyverno''s YAML DSL, which appeals to teams that already have Rust or Go expertise."}]}]}' WHERE `id` = 'kubewarden';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KUDO, the Kubernetes Universal Declarative Operator, is a toolkit for building Kubernetes operators without writing Go code. An operator is packaged as a KUDO bundle containing templated manifests, parameter definitions, and a plan — an ordered set of phases and steps that describe install, upgrade, backup, and other lifecycle actions."}]},{"type":"paragraph","content":[{"type":"text","text":"The kudo-controller runs in-cluster and reconciles Instance custom resources against these plans, rendering manifests with the user''s parameters and executing steps sequentially or in parallel. Operators ship as versioned packages pulled from an operator repository, similar to Helm charts, but with first-class lifecycle plans instead of a single install template. A kubectl-kudo CLI drives installs, upgrades, and plan execution."}]},{"type":"paragraph","content":[{"type":"text","text":"KUDO was started by D2iQ and joined the CNCF sandbox in 2020. It competes conceptually with the Operator SDK''s Helm and Ansible modes and with Crossplane, and it remains a useful reference for how day-2 operations can be modelled declaratively without hand-written controllers."}]}]}' WHERE `id` = 'kudo';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kueue is Kubernetes-native job queueing and resource admission for batch, HPC, and AI/ML workloads. It decides when workloads may start based on quotas, priority, and available capacity, then leaves pod placement to the Kubernetes scheduler."}]},{"type":"paragraph","content":[{"type":"text","text":"The project supports shared ClusterQueues, namespace-scoped LocalQueues, ResourceFlavors, fair sharing, preemption, topology-aware scheduling, and multi-cluster dispatch. It integrates with Kubernetes Job, JobSet, KubeRay, Kubeflow Trainer, and other workload APIs."}]}]}' WHERE `id` = 'kueue';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kuma is a service mesh built on the Envoy proxy, originally created by Kong and donated to the CNCF. It supports both Kubernetes and VM-based workloads from a single control plane and was designed from the start for multi-zone deployments that span clusters and data centres."}]},{"type":"paragraph","content":[{"type":"text","text":"The control plane, kuma-cp, is written in Go and distributes xDS configuration to Envoy sidecars injected next to each workload. Policies — mTLS, traffic permissions, routing, retries, rate limits, circuit breakers — are expressed as Kubernetes CRDs or, on VMs, as YAML resources stored in kuma-cp''s built-in store backed by Postgres or the Kubernetes API. In multi-zone mode a global control plane federates with per-zone control planes that discover local workloads and synchronise state over a secure gRPC channel, giving cross-cluster service discovery without a flat network."}]},{"type":"paragraph","content":[{"type":"text","text":"Kuma competes with Istio, Linkerd, and Consul Connect. Its distinguishing points are first-class VM support, the universal/Kubernetes split, and a smaller surface area than Istio while still using Envoy, which makes it attractive for hybrid estates that have not fully migrated to Kubernetes."}]}]}' WHERE `id` = 'kuma';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kured (KUbernetes REboot Daemon) is a DaemonSet that reboots Kubernetes nodes safely when the underlying OS signals that a reboot is required. It was created by Weaveworks and is now a CNCF sandbox project."}]},{"type":"paragraph","content":[{"type":"text","text":"The daemon runs on every node and watches for a sentinel — by default the file /var/run/reboot-required that Debian and Ubuntu write after a kernel or glibc upgrade — or the result of a configurable sentinel command for other distributions. When a reboot is needed, kured takes a cluster-wide lock via an annotation on a DaemonSet object so only one node reboots at a time, cordons the node, drains its pods, and then triggers a systemd reboot. After the node comes back it uncordons itself and releases the lock. Reboots can be gated on a maintenance window, the absence of firing Prometheus alerts, or the absence of pods matching a selector, so rollouts pause automatically when the cluster is unhealthy."}]},{"type":"paragraph","content":[{"type":"text","text":"Kured is the standard answer for \"I enabled unattended-upgrades on my nodes, now what?\" and pairs naturally with tools like system-upgrade-controller, which handles the package updates themselves."}]}]}' WHERE `id` = 'kured';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KusionStack is an open-source toolchain for building internal developer platforms on Kubernetes, originally developed inside Ant Group and now a CNCF sandbox project. The core idea is to describe applications, infrastructure, and policies in KCL — a typed, constraint-based configuration language also maintained by the project — and compile that into concrete Kubernetes manifests and cloud resources."}]},{"type":"paragraph","content":[{"type":"text","text":"The stack is made of several components. Kusion is the CLI and engine that takes KCL modules, resolves them into a desired state graph, and applies it to target environments, similar in spirit to Terraform plan/apply but for mixed Kubernetes + cloud footprints. Karpor provides a multi-cluster search and insight layer over live resources. Kuperator (operating.kusionstack.io) ships workload CRDs such as CollaSet and PodDecoration that extend beyond the default Deployment/StatefulSet semantics, and CtrlMesh adds control-plane sharding for large operator fleets."}]},{"type":"paragraph","content":[{"type":"text","text":"KusionStack competes with Crossplane compositions, Backstage scaffolder + Terraform, and KubeVela, and is distinguished by betting on KCL as the single language for platform abstractions rather than HCL, CUE, or YAML overlays."}]}]}' WHERE `id` = 'kusionstack';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kustomize is a template-free configuration management tool for Kubernetes that customizes raw YAML manifests through declarative overlays. Rather than introducing a templating language or a parallel DSL, it operates directly on standard Kubernetes resources, leaving the original files untouched and producing the final manifests by composing layers at build time. The result is plain YAML that any Kubernetes-aware tool can validate, diff, and apply."}]},{"type":"paragraph","content":[{"type":"text","text":"The core model is built around bases and overlays. A base is a directory of resources together with a "},{"type":"text","text":"kustomization.yaml","marks":[{"type":"code"}]},{"type":"text","text":" that lists them; an overlay is another directory that references one or more bases and applies modifications on top. Modifications come in two main forms: generators that produce ConfigMaps and Secrets from files or literals, and transformers that mutate existing resources, including strategic-merge patches, JSON 6902 patches, name and namespace prefixes, common labels and annotations, image tag overrides, and replica counts. Because overlays compose, the same base can be reused across environments such as dev, staging, and production with only the differences captured per overlay."}]},{"type":"paragraph","content":[{"type":"text","text":"Kustomize ships inside "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":" and is invoked via "},{"type":"text","text":"kubectl apply -k","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"kubectl kustomize","marks":[{"type":"code"}]},{"type":"text","text":", which means teams can adopt it without installing additional tooling on clusters or in CI. It is commonly used to manage per-environment variants of an application, to wrap upstream manifests from vendors or Helm renders with local policy and naming conventions, and as the rendering layer underneath GitOps controllers like Argo CD and Flux, both of which support Kustomize directories natively."}]}]}' WHERE `id` = 'kustomize';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kwasm is a Kubernetes operator that installs containerd WebAssembly shims onto existing nodes so pods can run Wasm modules instead of Linux containers. It targets the common case where you want to try Wasm workloads on an existing cluster without rebuilding node images."}]},{"type":"paragraph","content":[{"type":"text","text":"The operator watches for a node label and, when it sees one, schedules a privileged installer pod that drops the chosen shim binary (runwasi-based shims for Spin, WasmEdge, Wasmtime, or Lunatic) into /opt on the host and patches containerd''s config.toml to register a new runtime handler. A RuntimeClass then points workloads at that handler, and any pod whose image is an OCI artifact containing a .wasm module is executed by the shim rather than runc. The node installer is driven by the kwasm-node-installer project so the same mechanism works on kind, k3s, AKS, EKS, and GKE nodes."}]},{"type":"paragraph","content":[{"type":"text","text":"Kwasm is explicitly flagged as a development and evaluation tool — for production Wasm on Kubernetes, projects like SpinKube and the runwasi shims shipped directly by distributions are the longer-term path."}]}]}' WHERE `id` = 'kwasm';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kyverno is a Kubernetes-native policy engine that expresses admission, mutation, and generation rules in YAML instead of a dedicated policy language. Policies are themselves Kubernetes resources (ClusterPolicy, Policy), so they are reviewed, versioned, and deployed with the same GitOps tooling as the rest of the cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"The kyverno controller registers validating and mutating admission webhooks and evaluates incoming API requests against matching rules. Rules can validate fields using pattern matching and CEL, mutate objects by patching them, generate downstream resources like default NetworkPolicies or ConfigMaps when a namespace is created, and verify container image signatures and attestations via Cosign. A background scanner re-evaluates existing resources so policy drift surfaces as PolicyReport custom resources consumed by dashboards and Prometheus. Kyverno also ships a CLI for testing policies against manifests in CI."}]},{"type":"paragraph","content":[{"type":"text","text":"Kyverno is a CNCF graduated project and directly competes with OPA Gatekeeper. Its main differentiator is avoiding Rego entirely — operators who already read Kubernetes YAML can write useful policies without learning a new language — and bundling image verification and resource generation in the same engine."}]}]}' WHERE `id` = 'kyverno';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Laravel is a server-side web framework for PHP, created by Taylor Otwell in 2011. It follows an MVC structure and ships an opinionated stack for routing, dependency injection, validation, queues, scheduling, and authentication out of the box."}]},{"type":"paragraph","content":[{"type":"text","text":"The core pieces engineers interact with daily are Eloquent, an active-record ORM that maps classes to database tables and expresses relationships as methods; Blade, a lightweight templating engine that compiles to plain PHP; and Artisan, a Symfony Console-based CLI that scaffolds code, runs migrations, and drives background workers. Laravel leans heavily on Symfony components (HTTP foundation, routing, console) underneath, and integrates with Redis and database-backed queues, Horizon for queue monitoring, Echo for WebSockets, and Sanctum or Passport for API tokens and OAuth2. Recent versions add first-class support for Laravel Octane, which runs the framework on Swoole, RoadRunner, or FrankenPHP for persistent-process performance."}]},{"type":"paragraph","content":[{"type":"text","text":"In the PHP ecosystem Laravel competes with Symfony and, at a smaller scale, CodeIgniter and Slim. It dominates the \"full-stack PHP for SaaS\" niche and underpins commercial offerings like Forge, Vapor (serverless on AWS Lambda), and the Livewire + Alpine.js frontend stack."}]}]}' WHERE `id` = 'laravel';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lens is a desktop IDE for Kubernetes, built as an Electron application that runs on macOS, Windows, and Linux. It reads your local kubeconfig, connects directly to clusters via the Kubernetes API, and presents workloads, nodes, events, and logs through a single navigation tree."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood Lens uses client-go-style API calls via its own TypeScript client, streams container logs and exec sessions over the API server''s websocket endpoints, and embeds a Monaco editor for live-editing manifests. It can attach a Prometheus instance discovered in-cluster to overlay CPU, memory, and network metrics on any workload view without requiring Grafana. An extension API lets third parties add catalog entries, custom views, and menu items; CNCF projects like OpenEBS, Calico, and Kubescape ship Lens extensions. Lens Desktop is distributed by Mirantis under a freemium model, and the fully open-source fork OpenLens exists for users who want a purely community-maintained build."}]},{"type":"paragraph","content":[{"type":"text","text":"Lens overlaps with Headlamp, k9s, and the official Kubernetes Dashboard. Its niche is offering a GUI-first experience that still gives power users kubectl-equivalent access through an embedded terminal and per-cluster context switching."}]}]}' WHERE `id` = 'lens';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lima (Linux Machines) launches Linux virtual machines on macOS and Linux with automatic file sharing, port forwarding, and containerd pre-installed. It exists to give macOS developers a lightweight way to run Linux workloads without Docker Desktop."}]},{"type":"paragraph","content":[{"type":"text","text":"On macOS Lima uses the native Virtualization.framework or QEMU as the hypervisor, boots a cloud-init-configured Ubuntu, Fedora, or Alpine image, and sets up a virtiofs or 9p mount so the host''s home directory appears inside the guest. Guest agents forward listening ports back to localhost on the host, so a service started inside the VM is reachable without extra configuration. The limactl CLI takes a YAML template describing CPU, memory, disk, mounts, and provisioning scripts, which makes per-project environments reproducible. nerdctl, the Docker-compatible CLI from the containerd project, is bundled so "},{"type":"text","text":"lima nerdctl run","marks":[{"type":"code"}]},{"type":"text","text":" works as a drop-in for "},{"type":"text","text":"docker run","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Lima is the engine underneath Colima, Rancher Desktop, and Finch, all of which wrap it with a simpler UX aimed at Docker replacement. It competes with Docker Desktop, Podman Machine, and OrbStack, and is maintained by Akihiro Suda, one of the containerd and BuildKit maintainers."}]}]}' WHERE `id` = 'lima';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Linkerd is a service mesh for Kubernetes and the project that coined the term. Rather than installing the Envoy proxy next to every pod as Istio does, Linkerd ships its own data-plane proxy, linkerd2-proxy, written in Rust on Tokio and scoped to the mesh''s exact feature set — HTTP/1, HTTP/2, gRPC, raw TCP, mTLS, and per-route metrics."}]},{"type":"paragraph","content":[{"type":"text","text":"The control plane is a handful of Go services — destination, identity, and proxy-injector — that hand out endpoints, issue short-lived TLS certificates per workload identity, and mutate pods at admission time to add the proxy sidecar. mTLS is on by default, and the identity component acts as an in-cluster CA rooted in a trust anchor you provide. Telemetry is exposed as Prometheus metrics directly by each proxy, and the "},{"type":"text","text":"linkerd viz","marks":[{"type":"code"}]},{"type":"text","text":" extension bundles Prometheus, Grafana, and a web dashboard. Multi-cluster support works by mirroring services between clusters and tunnelling traffic through gateway pods with mTLS end-to-end."}]},{"type":"paragraph","content":[{"type":"text","text":"Linkerd was the first CNCF service mesh and graduated in 2021. It competes with Istio, Consul Connect, and Kuma, and its pitch is operational simplicity and a much smaller resource footprint per proxy thanks to the purpose-built Rust data plane."}]}]}' WHERE `id` = 'linkerd';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Litestream is a streaming replication tool for SQLite, written in Go by Ben Johnson (the author of BoltDB). It runs as a sidecar process next to an application that uses SQLite and ships the database''s write-ahead log to object storage in near-real-time."}]},{"type":"paragraph","content":[{"type":"text","text":"Litestream opens the SQLite database in WAL mode, takes a shared lock, and tails the WAL file. New frames are batched into small segments and uploaded to S3, GCS, Azure Blob, SFTP, or a local filesystem, along with periodic full snapshots. Because it only reads the WAL, the application keeps writing without blocking, and there is no Litestream-aware client — existing SQLite code is unchanged. Recovery is done with "},{"type":"text","text":"litestream restore","marks":[{"type":"code"}]},{"type":"text","text":", which reconstructs the database from the latest snapshot plus replayed WAL segments, producing a point-in-time copy."}]},{"type":"paragraph","content":[{"type":"text","text":"Litestream turns SQLite into a viable primary store for single-node web apps that want cheap, continuous backups without running Postgres. It is often paired with Fly.io-style single-VM deployments and is the spiritual predecessor to LiteFS, Johnson''s follow-up project that adds distributed replicas on top of the same idea."}]}]}' WHERE `id` = 'litestream';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"LitmusChaos is a chaos engineering platform for Kubernetes. It provides a catalog of pre-built fault injections — pod delete, network latency, DNS chaos, disk fill, CPU hog, node drain, and cloud-provider-specific faults for AWS, Azure, and GCP — packaged as reusable experiments."}]},{"type":"paragraph","content":[{"type":"text","text":"Experiments are defined as ChaosExperiment and ChaosEngine custom resources and executed by the chaos-operator, which launches a runner pod that in turn invokes the actual fault logic (often via Ansible or Go-based executors). Workflows chain experiments together and are authored in Argo Workflows under the hood, so Litmus inherits Argo''s DAG semantics. The ChaosCenter web console provides multi-cluster scheduling, RBAC, and probes that assert application health before, during, and after an experiment — a run fails if the probes detect regressions. ChaosHub is a public catalog of community-contributed experiments packaged as charts."}]},{"type":"paragraph","content":[{"type":"text","text":"Litmus is a CNCF incubating project maintained by Harness, and it competes with Chaos Mesh, Gremlin, and AWS Fault Injection Simulator. Its distinguishing traits are the pluggable probe model and the use of Argo Workflows for orchestration."}]}]}' WHERE `id` = 'litmus';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"llm-d is a Kubernetes-native distributed inference serving stack for large language models, founded by Red Hat, Google Cloud, IBM Research, CoreWeave, and NVIDIA, with AMD, Cisco, Hugging Face, Intel, Lambda, and Mistral AI contributing. It was accepted as a CNCF Sandbox project at KubeCon + CloudNativeCon Europe 2026, with the stated goal of making distributed LLM inference a first-class cloud native workload."}]},{"type":"paragraph","content":[{"type":"text","text":"Rather than inventing a new model server, llm-d composes proven pieces: vLLM as the inference engine, the Gateway API Inference Extension as a model-aware request scheduler, and Kubernetes as the orchestration layer. On top of that it adds the techniques that matter at scale — disaggregated prefill and decode phases, KV-cache-aware routing that sends requests to replicas already holding relevant cache state, and support for heterogeneous accelerators including NVIDIA and AMD GPUs and Google TPUs. Deployment is via Helm charts with \"well-lit paths\" for common topologies."}]},{"type":"paragraph","content":[{"type":"text","text":"It competes with (and complements) KServe, Ray Serve, and NVIDIA''s serving stack; the differentiation is being vendor-neutral, Kubernetes-native, and tuned specifically for the traffic patterns of LLM inference rather than generic model serving."}]}]}' WHERE `id` = 'llm-d';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Logging Operator is a Kubernetes operator from Kube Logging (formerly Banzai Cloud) that manages Fluent Bit and Fluentd deployments declaratively. Instead of hand-writing Fluent Bit input plugins and Fluentd parser blocks, users describe logging pipelines as Kubernetes custom resources and the operator renders the configuration."}]},{"type":"paragraph","content":[{"type":"text","text":"Four CRDs do the work. Logging defines a tenant and points at a Fluent Bit DaemonSet and a Fluentd StatefulSet. Flow and ClusterFlow select which pods'' logs to route via label selectors and declare filter and parser chains. Output and ClusterOutput describe destinations — Loki, Elasticsearch, Kafka, S3, Splunk, Datadog, and more — complete with authentication from Kubernetes secrets. The operator generates the matching Fluent Bit and Fluentd configs, reloads the pods, and handles rolling upgrades."}]},{"type":"paragraph","content":[{"type":"text","text":"Logging Operator is a CNCF sandbox project and the log-collection layer behind Rancher''s fleet logging, Kubesphere, and several managed Kubernetes platforms. It competes with the OpenTelemetry Collector operator and with hand-rolled Helm charts for Fluent Bit, and is the right pick when teams want multi-tenant log routing expressed as Kubernetes objects rather than ConfigMaps."}]}]}' WHERE `id` = 'logging-operator';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Loki is a log aggregation system from Grafana Labs, designed to be \"Prometheus for logs.\" Instead of full-text indexing every log line, Loki indexes only a small set of labels — namespace, pod, container, job — and stores the raw log streams as compressed chunks in object storage. Queries then scan matching chunks directly, trading query speed for dramatically lower storage cost and operational overhead."}]},{"type":"paragraph","content":[{"type":"text","text":"The system can run as a single binary or as microservices — distributor, ingester, querier, query-frontend, compactor, and ruler — and all state lives in S3, GCS, Azure Blob, or a filesystem, with a small index kept in BoltDB-shipper, TSDB, or an external KV store. Logs are pushed in by Promtail (Loki''s own agent), Fluent Bit, Vector, the Grafana Alloy agent, or the OpenTelemetry Collector. Queries are written in LogQL, a pipeline language modelled on PromQL that supports label matchers, regex line filters, parsers for JSON and logfmt, and metric-style aggregations over log streams."}]},{"type":"paragraph","content":[{"type":"text","text":"Loki integrates tightly with Grafana dashboards and Alertmanager, and competes with Elasticsearch + Kibana, OpenSearch, and Splunk — winning on cost at the expense of arbitrary full-text search."}]}]}' WHERE `id` = 'loki';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Longhorn is a distributed block storage system for Kubernetes, created at Rancher Labs and now a CNCF incubating project. It turns the local disks attached to worker nodes into replicated persistent volumes that pods consume through a standard CSI driver."}]},{"type":"paragraph","content":[{"type":"text","text":"Each Longhorn volume has a dedicated microservice controller called the engine, implemented on top of a modified iSCSI target (longhorn-engine) that runs in a per-volume pod. The engine synchronously replicates writes to two or three replica pods, each of which stores the volume as a sparse file on a node''s local filesystem. Because every volume has its own engine process, a fault in one volume''s replicas cannot affect another. Snapshots are copy-on-write inside the engine; backups are incremental and uploaded to S3 or NFS; and volumes can be restored into another cluster from the same backup store, which is how disaster recovery and cross-cluster migration work."}]},{"type":"paragraph","content":[{"type":"text","text":"Longhorn ships a web UI for volume, snapshot, and backup management, plus a ShareManager for ReadWriteMany volumes backed by NFS. It competes with Rook-Ceph, OpenEBS, and Portworx, and its niche is being simple to install and operate on small-to-medium clusters that want replicated block storage without running a full Ceph cluster."}]}]}' WHERE `id` = 'longhorn';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"loxilb is an open-source load balancer for Kubernetes and edge workloads, built around an eBPF data plane and a Go control plane. It implements Kubernetes Service type LoadBalancer without depending on a cloud provider, which makes it a bare-metal and telco-friendly alternative to MetalLB."}]},{"type":"paragraph","content":[{"type":"text","text":"The data path is an eBPF/XDP program attached to network interfaces that performs connection tracking, DNAT, SNAT, stateful firewalling, and QoS entirely in-kernel, bypassing iptables and conntrack. A user-space Go daemon programs the eBPF maps and speaks BGP via an embedded goBGP stack, so loxilb can advertise service VIPs upstream the same way MetalLB does in BGP mode. Beyond L4, it supports SCTP multi-homing, GTP, and SRv6 — features that matter for 5G user-plane and edge deployments more than for typical web workloads. A companion kube-loxilb operator integrates with the Kubernetes Service API and optionally acts as an ingress controller."}]},{"type":"paragraph","content":[{"type":"text","text":"loxilb sits alongside MetalLB, Cilium''s LB-IPAM and BGP control plane, and PureLB, and differentiates on telco-grade protocol support and the eBPF-first data plane."}]}]}' WHERE `id` = 'loxilb';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lumigo is a commercial observability platform focused on distributed microservices, with strong roots in AWS Lambda and serverless tracing. It collects traces, logs, and metrics from cloud applications and correlates them to surface the actual root cause of an incident rather than a wall of spans."}]},{"type":"paragraph","content":[{"type":"text","text":"Instrumentation is primarily zero-code: on AWS Lambda, Lumigo injects its tracer via a Lambda layer and a runtime wrapper; on Kubernetes and ECS, an operator or sidecar auto-instruments Node.js, Python, Java, and Go using OpenTelemetry under the hood. Captured traces include the full payloads of HTTP, SQS, Kinesis, DynamoDB, and other AWS API calls, so debugging a failed request does not require redeploying with extra logging. The backend stitches traces across asynchronous boundaries — for example, following a message from an SQS producer through multiple Lambda consumers — and applies heuristics to flag the likely failing span."}]},{"type":"paragraph","content":[{"type":"text","text":"Lumigo competes with Datadog APM, Honeycomb, New Relic, and Dash0 (which recently acquired Lumigo). Its historical differentiator is serverless-first tracing with payload capture, which remains painful for general-purpose APM vendors to replicate."}]}]}' WHERE `id` = 'lumigo';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Meilisearch is an open-source search engine written in Rust, aimed at powering search-as-you-type experiences in web and mobile apps. It prioritises relevance tuning, sub-50ms response times on moderate datasets, and a REST API that an application developer can integrate in an afternoon."}]},{"type":"paragraph","content":[{"type":"text","text":"Internally Meilisearch stores documents in an LMDB-backed index and uses a custom inverted index plus a bucket-sort ranking pipeline with configurable ranking rules — words, typo, proximity, attribute, sort, exactness — that can be reordered per index. Typo tolerance is built in via a Levenshtein automaton, and the query pipeline supports filtering, faceting, geo search, synonyms, and stop-word lists. Recent releases add vector search with HNSW indexes and hybrid search that combines lexical BM25-style ranking with vector similarity, which brings LLM retrieval use cases into the same engine. Client SDKs exist for JavaScript, Python, Ruby, PHP, Go, Rust, Java, and .NET, and the project ships a hosted Meilisearch Cloud alongside the self-hostable binary."}]},{"type":"paragraph","content":[{"type":"text","text":"Meilisearch competes with Elasticsearch, OpenSearch, Typesense, and Algolia, and its niche is being a single small Rust binary that gives you Algolia-quality relevance defaults without running a JVM cluster."}]}]}' WHERE `id` = 'meilisearch';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Melange is a declarative build tool for Alpine apk packages, developed by Chainguard as part of the Wolfi undistro. It takes a YAML build definition and produces signed .apk artifacts, typically consumed by apko to assemble minimal, distroless-style container images."}]},{"type":"paragraph","content":[{"type":"text","text":"A melange.yaml file declares package metadata, build-time dependencies pulled from apk repositories, and a pipeline of steps drawn from a library of reusable actions — "},{"type":"text","text":"fetch","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"autoconf/configure","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"autoconf/make","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"go/build","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"patch","marks":[{"type":"code"}]},{"type":"text","text":", and so on. The build runs inside a freshly populated apk root, optionally under QEMU user-mode emulation so the same definition cross-builds for arm64, amd64, riscv64, and other architectures without changing the pipeline. Output apks are signed with a melange-managed key and can be published straight to an apk repository or consumed locally by apko."}]},{"type":"paragraph","content":[{"type":"text","text":"Together with apko, melange powers Chainguard Images and the Wolfi package set, and the same machinery is used by upstream projects that want reproducible, SBOM-annotated package builds. It competes with traditional distro build systems like Debian''s sbuild or RPM''s mock, and distinguishes itself by being container-native, YAML-first, and designed around supply-chain signing from day one."}]}]}' WHERE `id` = 'melange';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Meshery is a multi-cluster, multi-mesh management plane for cloud native infrastructure, maintained by Layer5. It models Kubernetes clusters and the stacks running on them as \"designs\" — declarative, visually-editable bundles of manifests, Helm charts, and operator CRDs — and deploys, compares, and lifecycles them across environments."}]},{"type":"paragraph","content":[{"type":"text","text":"The architecture is a Go server exposing REST and GraphQL APIs, a React front end, and a set of gRPC \"adapters\" that each wrap a specific ecosystem project — Istio, Linkerd, Consul, Cilium, Kuma, Nginx Service Mesh, and many non-mesh projects via its broader integrations catalog. Designs are authored in a Kubernetes-like model backed by the OAM-inspired MeshModel registry, rendered to concrete manifests at apply time, and can be pushed to any number of registered clusters from a single workspace. A mesheryctl CLI mirrors the web UI for CI use, and built-in load generators (fortio, wrk2, nighthawk) let users attach performance profiles to designs."}]},{"type":"paragraph","content":[{"type":"text","text":"Meshery is a CNCF project and sits alongside Argo CD, Flux, and Backstage in the platform-engineering toolbox, with its niche being visual, multi-project design plus opinionated support for comparing service-mesh implementations."}]}]}' WHERE `id` = 'meshery';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Metal3 (metal-cubed) is a Kubernetes-native bare-metal provisioning stack. It exposes physical servers as BareMetalHost custom resources so a Kubernetes control plane can inspect, power, partition, and install them the same way it reconciles Deployments."}]},{"type":"paragraph","content":[{"type":"text","text":"The core component is the baremetal-operator, which drives hosts via Ironic — the OpenStack bare-metal service — packaged as a container. Ironic handles the actual work: IPMI, Redfish, or iDRAC for power control; iPXE and virtual media for boot; inspection via ironic-python-agent; and image writing using qemu-img. On top of that, the Cluster API provider for Metal3 (CAPM3) turns BareMetalHosts into Cluster API Machines, so declaring a new worker becomes a matter of scaling a MachineDeployment, which provisions bare metal end-to-end without a separate automation layer."}]},{"type":"paragraph","content":[{"type":"text","text":"Metal3 is the upstream of Red Hat OpenShift''s bare-metal installer and is used by SUSE Rancher and several telco edge distributions. It competes with MAAS, Tinkerbell, and vendor-specific provisioners, and its niche is giving Cluster API a true bare-metal infrastructure provider so the same declarative workflow used for AWS or vSphere clusters works on physical hardware."}]}]}' WHERE `id` = 'metal3';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"MetalLB is a load-balancer implementation for Kubernetes clusters that do not run on a cloud provider, so Service type LoadBalancer actually gets an external IP on bare metal, on-prem vSphere, or home-lab clusters. It was the first widely-used answer to the \"pending external IP\" problem and is now a CNCF sandbox project."}]},{"type":"paragraph","content":[{"type":"text","text":"MetalLB has a controller that allocates IPs from configured IPAddressPools and a speaker DaemonSet that advertises those IPs to the surrounding network. It offers two operating modes. In L2 mode the speakers respond to ARP for IPv4 or NDP for IPv6 from one elected node per service, so failover is an ARP re-announce; this works on any flat L2 segment but funnels all traffic through a single node. In BGP mode every speaker peers with the upstream routers and advertises the service VIP with ECMP across all ready nodes, giving real multi-node load distribution and integrating cleanly with existing data-centre fabrics."}]},{"type":"paragraph","content":[{"type":"text","text":"MetalLB competes with PureLB, Cilium''s LB-IPAM, kube-vip, and loxilb. Its strength is being small, focused, and battle-tested — it does nothing except turn Services into routable IPs."}]}]}' WHERE `id` = 'metallb';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Microcks turns API and event specifications into live mock servers and contract tests. Given an OpenAPI, AsyncAPI, gRPC/protobuf, GraphQL SDL, Postman collection, or SoapUI project, it spins up an endpoint that replays example responses and, for async APIs, produces or consumes messages on the configured broker."}]},{"type":"paragraph","content":[{"type":"text","text":"The server is a Spring Boot application backed by MongoDB for artifact storage and Keycloak for auth. Uploaded artifacts are parsed into an internal model and exposed under stable mock URLs; example data can come from the spec itself, from Postman collection examples, or from separate \"secondary\" files so teams can keep mock data alongside the contract. For async APIs, Microcks integrates with Kafka, MQTT, AMQP, NATS, WebSockets, Google Pub/Sub, and Amazon SQS/SNS to publish and verify messages. A microcks-cli and GitHub Actions, Jenkins, and Tekton integrations run the same mocks as contract-conformance tests in CI against a real implementation."}]},{"type":"paragraph","content":[{"type":"text","text":"Microcks is a CNCF sandbox project and overlaps with Prism, WireMock, and Postman Mock Servers, with its distinguishing points being native AsyncAPI support and a single platform that handles both mocking and contract testing."}]}]}' WHERE `id` = 'microcks';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Micronaut is a full-stack JVM framework for building modular, easily testable microservices and serverless applications. Its defining technical choice is that dependency injection, aspect-oriented programming, and configuration are all resolved at compile time through Java annotation processors, rather than at runtime through reflection and dynamic proxies. The framework generates the wiring code ahead of the JVM ever starting, which keeps startup times in the tens of milliseconds, holds memory usage to a small fraction of a traditional Java stack, and produces applications whose footprint stays roughly constant as the codebase grows."}]},{"type":"paragraph","content":[{"type":"text","text":"That compile-time model is what makes Micronaut a natural fit for serverless functions, scale-to-zero Knative services, and densely packed Kubernetes deployments, where cold starts and per-pod RAM directly shape cost and latency. Because almost no reflection survives into the runtime, Micronaut applications also compile cleanly to GraalVM native images, producing standalone executables that start in single-digit milliseconds and frequently run in 20 to 40 MB of memory. The framework ships first-class Gradle and Maven tooling for both JVM-mode JARs and native binaries, alongside extensions covering HTTP routing, reactive streams, JPA and SQL, messaging, observability, and cloud SDKs for AWS, GCP, Azure, and Oracle Cloud."}]},{"type":"paragraph","content":[{"type":"text","text":"Micronaut originated at Object Computing, Inc., as a successor to the team''s earlier work on Grails, and is governed today by the Micronaut Foundation, a non-profit established in 2020 with a Technical Advisory Board that stewards the roadmap; the project has announced plans to move under the Commonhaus Foundation to broaden its open-source governance. Compared with Spring Boot, Micronaut trades a mature, reflection-heavy runtime for a leaner, AOT-friendly one; compared with Quarkus, it covers similar ground around fast startup and GraalVM but takes a different architectural path centred on annotation processors rather than build-time bytecode transformation, leaving teams to choose based on ecosystem fit and developer preference rather than any clear winner."}]}]}' WHERE `id` = 'micronaut';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"MinIO is an S3-compatible object store written in Go. A single binary speaks the full Amazon S3 REST API — including multipart upload, versioning, bucket policies, object lock (WORM), SSE-KMS encryption, and the Select API — so applications and tools built for S3 run against MinIO unchanged."}]},{"type":"paragraph","content":[{"type":"text","text":"MinIO scales out in \"server pools\" using erasure coding rather than replication. Objects are split into data and parity shards (the default 4+4 gives 50% usable capacity and tolerates half the drives failing) and written across drives with MinIO''s own BitRot protection via HighwayHash. A MinIO cluster has no metadata server; placement is derived from object names and the fixed pool topology, which keeps the control path simple and the data path fast. Site replication, bucket replication, and tiering to other S3 endpoints or cold cloud storage are built in, as are an IAM system, OIDC and LDAP integration, and a Prometheus metrics endpoint."}]},{"type":"paragraph","content":[{"type":"text","text":"MinIO runs on bare metal, in Docker, and on Kubernetes via the DirectPV CSI driver and its operator, and is used as the storage backend for Loki, Thanos, Mimir, and countless data-lake stacks. It competes with Ceph RGW, SeaweedFS, and Garage on the self-hosted side, and with AWS S3 and GCS in hybrid deployments."}]}]}' WHERE `id` = 'minio';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"mirrord is an open-source tool from MetalBear that connects a locally-running process to a remote Kubernetes pod so the local process sees the remote pod''s traffic, environment, and filesystem. The developer keeps their debugger, hot reload, and IDE on their laptop while the code behaves as if it were running in the cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"When mirrord starts a target process it injects a shared library via LD_PRELOAD (or the equivalent on macOS) that hooks network, filesystem, and environment syscalls. Those calls are forwarded over a websocket to a mirrord-agent pod that mirrord schedules onto the same node as the target pod, entering its network and PID namespaces. From there the agent can mirror incoming traffic to the local process (leaving the remote pod still serving real users), steal traffic outright, read the remote pod''s file system, and expose its environment variables and DNS resolver. Outgoing connections from the local process are tunnelled back out through the agent so they resolve cluster-internal service names correctly."}]},{"type":"paragraph","content":[{"type":"text","text":"mirrord competes with Telepresence and Skaffold''s port-forward + sync workflow; its distinguishing feature is syscall-level hooking that requires no changes to the application or cluster, and the ability to mirror rather than hijack traffic during debugging."}]}]}' WHERE `id` = 'mirrord';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ModelPack is a specification and toolset for packaging machine-learning models as OCI artifacts so the existing container registry ecosystem — Harbor, GHCR, ECR, GCP Artifact Registry — can store, sign, and distribute models the same way it already handles images. It is a CNCF sandbox project."}]},{"type":"paragraph","content":[{"type":"text","text":"The specification defines a media-type layout for a model package: a manifest that references layers containing model weights, tokenizer files, configuration, and optional datasets and code, each addressed by content digest. Because the result is a valid OCI artifact, standard tooling for signing (cosign), SBOMs, provenance attestations (in-toto), and mirroring works on models without modification. The reference CLI, modctl, builds packages from a ModelFile descriptor and pushes or pulls them from any OCI registry; KitOps is a compatible implementation that adds a Python SDK and integrations with common MLOps platforms."}]},{"type":"paragraph","content":[{"type":"text","text":"ModelPack competes conceptually with Hugging Face Hub''s proprietary repo format and with ad-hoc tarballs in S3. Its pitch is using OCI as the lingua franca for model distribution so the supply-chain controls teams already apply to container images — registry auth, scanning, admission policies — extend cleanly to ML artifacts."}]}]}' WHERE `id` = 'modelpack';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"n8n is a source-available workflow automation tool that connects APIs, databases, and SaaS products through a node-based visual editor. It sits in the same category as Zapier and Make, but runs as a self-hostable Node.js application backed by PostgreSQL, SQLite, or MySQL for workflow state and execution history."}]},{"type":"paragraph","content":[{"type":"text","text":"Workflows are directed graphs of nodes, where each node is a typed integration (HTTP Request, Postgres, Slack, OpenAI, etc.) or a control primitive (IF, Switch, Merge, Loop). Execution can be triggered by webhooks, cron, polling, or manual invocation, and the Code node lets you drop into JavaScript or Python when the built-in nodes are not enough. More recent releases add a LangChain-based AI agent node set for chaining LLM calls, tools, and vector stores inside the same graph."}]},{"type":"paragraph","content":[{"type":"text","text":"n8n is distributed under the Sustainable Use License, a source-available \"fair-code\" license that permits internal and personal use but restricts hosting it as a competing commercial service. The Enterprise edition adds SSO, RBAC, external secrets, and log streaming on top of the community build. For teams that want to avoid Zapier''s per-task pricing or keep sensitive data on their own infrastructure, n8n is the usual self-hosted alternative, alongside Node-RED (more IoT-oriented), Windmill, and Temporal for code-first durable workflows."}]}]}' WHERE `id` = 'n8n';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Namespace is a commercial cloud platform that provides fast, ephemeral Linux and macOS instances aimed at CI builds and developer preview environments. The product centres on per-job VMs that boot in seconds, run containerized or native workloads, and are billed by actual usage rather than reserved capacity."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood, Namespace runs its own orchestrator on top of KVM-based micro-VMs and exposes them through GitHub Actions runners, a Buildkite agent, a Docker-compatible remote builder, and a CLI ("},{"type":"text","text":"nsc","marks":[{"type":"code"}]},{"type":"text","text":"). Builds benefit from persistent cache volumes and remote caching hooks for Bazel, Nix, Turborepo, and Docker BuildKit, which removes the cold-start penalty typical of hosted CI runners. It also offers native Apple Silicon runners for iOS/macOS pipelines and nested virtualization for Android emulators."}]},{"type":"paragraph","content":[{"type":"text","text":"Namespace competes with GitHub''s hosted runners, BuildJet, Depot, Blacksmith, and Ubicloud in the \"faster CI\" niche, and with Gitpod or Coder for ephemeral dev environments. It is closed-source and usage-billed. Note: the Rawkode Academy matrix lists this entry as "},{"type":"text","text":"graveyard","marks":[{"type":"code"}]},{"type":"text","text":", reflecting that the project is no longer tracked for active coverage."}]}]}' WHERE `id` = 'namespace';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"NATS is a high-performance messaging system that provides publish/subscribe, request/reply, and queue group semantics over a single, lightweight protocol. The core server is written in Go, runs as a single static binary, and is designed to handle millions of messages per second per node with sub-millisecond latency."}]},{"type":"paragraph","content":[{"type":"text","text":"Subjects are hierarchical, dot-separated strings (e.g. "},{"type":"text","text":"orders.us.west.created","marks":[{"type":"code"}]},{"type":"text","text":") and support wildcards for fan-out routing. JetStream, the built-in persistence layer, adds at-least-once and exactly-once delivery, message replay, key-value and object stores, and Raft-replicated streams across clusters. Servers connect in a full mesh and can be federated across regions using leaf nodes and gateways, which makes NATS well-suited to edge and multi-cloud topologies where Kafka''s broker model is too heavy."}]},{"type":"paragraph","content":[{"type":"text","text":"NATS is commonly compared to Kafka, RabbitMQ, and Redis Streams. It is lighter than Kafka (no ZooKeeper or KRaft, no per-topic partitions to manage) but provides durable streams via JetStream when you need them. It ships clients for Go, Rust, Java, .NET, Python, JavaScript, and C, and integrates with Dapr, Benthos, CloudEvents, and Kubernetes via the NATS operator and Helm charts."}]}]}' WHERE `id` = 'nats';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"nerdctl is a Docker-compatible command-line interface for containerd, shipped directly under the containerd organisation. It mirrors the familiar "},{"type":"text","text":"docker run","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"docker build","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"docker compose","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"docker image","marks":[{"type":"code"}]},{"type":"text","text":" surface area so that anyone with muscle memory from the Docker CLI can drive a containerd daemon without learning a new tool. Because it sits on top of containerd, it is the natural CLI for environments that have already standardised on containerd as their runtime, including Kubernetes nodes, where it provides a much more ergonomic interaction model than the lower-level "},{"type":"text","text":"ctr","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"crictl","marks":[{"type":"code"}]},{"type":"text","text":" tools."}]},{"type":"paragraph","content":[{"type":"text","text":"Although nerdctl tracks the Docker CLI closely, it deliberately exposes capabilities that the Docker daemon does not surface. It supports rootless mode with near-native networking performance via bypass4netns, lazy-pulling of images through snapshotters like eStargz, Nydus, and OverlayBD so containers can start before their layers are fully downloaded, image encryption and decryption via ocicrypt, peer-to-peer image distribution through IPFS, and image signing and verification with cosign. Builds are powered by BuildKit, including multi-platform and cached builds, and there is a built-in "},{"type":"text","text":"nerdctl compose","marks":[{"type":"code"}]},{"type":"text","text":" implementation that parses standard "},{"type":"text","text":"docker-compose.yaml","marks":[{"type":"code"}]},{"type":"text","text":" files using compose-go."}]},{"type":"paragraph","content":[{"type":"text","text":"The typical use cases are running and debugging containers on Kubernetes nodes that use containerd, replacing the Docker CLI on workstations and CI runners that have moved off the Docker daemon, exercising containerd-specific features like lazy-pull and rootless networking, and acting as a thin developer-facing layer over containerd in tooling that does not want to depend on a separate Docker engine."}]}]}' WHERE `id` = 'nerdctl';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Network Service Mesh (NSM) is a CNCF sandbox project that provides L2/L3 connectivity between Kubernetes workloads independent of the CNI in use. Where traditional service meshes like Istio or Linkerd operate at L7 on top of the cluster''s existing pod network, NSM attaches additional network interfaces to pods on demand and wires them into arbitrary virtual networks."}]},{"type":"paragraph","content":[{"type":"text","text":"The architecture is modelled on telco Network Function Virtualization. A workload requests a \"network service\" via a label or annotation; an NSM control plane matches the request to a Network Service Endpoint (NSE), and a forwarder (using kernel, VPP, or SR-IOV dataplanes) sets up a point-to-point link, typically a VXLAN, Wireguard, or MEMIF tunnel. This enables use cases that plain CNI cannot express cleanly: multi-cluster L3 connectivity, service chaining through firewalls or DPI, multiple network interfaces per pod, and hybrid cloud/edge overlays that cross Kubernetes and non-Kubernetes endpoints."}]},{"type":"paragraph","content":[{"type":"text","text":"NSM is most commonly seen in 5G/telco workloads (vRAN, UPF) and in multi-cluster networking scenarios, alongside or as an alternative to Multus, Cilium Cluster Mesh, Submariner, and Skupper. It is Apache-2.0 licensed and has been in the CNCF sandbox since 2019."}]}]}' WHERE `id` = 'networkservicemesh';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ngrok is a hosted ingress service that exposes services running behind NAT or a firewall on a public HTTPS, TCP, or TLS endpoint without any inbound port forwarding. You run the ngrok agent next to your app; it opens an outbound TLS connection to ngrok''s edge and receives reversed traffic over that tunnel."}]},{"type":"paragraph","content":[{"type":"text","text":"The classic use case is giving a local development server a public URL for testing Stripe, GitHub, or Slack webhooks, but the product has grown into a general-purpose API gateway. The edge can terminate TLS on custom domains, enforce OAuth, OIDC, SAML, or JWT auth, apply rate limits and IP restrictions, rewrite headers, mirror traffic for inspection, and load-balance across multiple agents. Configuration is expressed either via CLI flags, a YAML config file, or declaratively through the Kubernetes Ingress controller and Gateway API implementation, so the same endpoint rules can be managed from cluster manifests."}]},{"type":"paragraph","content":[{"type":"text","text":"ngrok is commercial and closed-source, with a free tier that hands out random subdomains. In the same space you will find Cloudflare Tunnel (cloudflared), Tailscale Funnel, Telepresence, localtunnel, and frp for a fully self-hosted option. Its niche is the combination of zero-config tunnels with an API-gateway-grade edge, rather than just raw TCP forwarding."}]}]}' WHERE `id` = 'ngrok';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Notary Project is a set of specifications and tooling for signing and verifying OCI artifacts, most commonly container images. Its reference CLI, "},{"type":"text","text":"notation","marks":[{"type":"code"}]},{"type":"text","text":", produces detached signatures that are stored as OCI artifacts alongside the image in any OCI 1.1-compatible registry, so signature distribution rides on the same infrastructure as the image itself."}]},{"type":"paragraph","content":[{"type":"text","text":"Notation v2 is a clean break from the original TUF-based Notary v1 (which backed Docker Content Trust). It uses X.509 certificates and PKCS#11 or cloud KMS key stores rather than TUF key hierarchies, and signatures are expressed as COSE or JWS envelopes pointed at by an OCI "},{"type":"text","text":"referrers","marks":[{"type":"code"}]},{"type":"text","text":" relationship. Verification is driven by a trust policy document that pins trusted identities, certificate chains, and scopes per registry or repository. Plugins connect "},{"type":"text","text":"notation","marks":[{"type":"code"}]},{"type":"text","text":" to AWS Signer, Azure Key Vault, Google Cloud KMS, HashiCorp Vault, and hardware tokens."}]},{"type":"paragraph","content":[{"type":"text","text":"In the supply-chain security landscape, Notation competes and overlaps with Sigstore''s "},{"type":"text","text":"cosign","marks":[{"type":"code"}]},{"type":"text","text":". Cosign leans on keyless, OIDC-based signing against a transparency log (Rekor), while Notation targets teams that already operate traditional X.509 PKI and want CA-rooted trust. Both are commonly consumed at admission time via Kyverno, OPA Gatekeeper, or Ratify. Notary has been a CNCF incubating project since 2017."}]}]}' WHERE `id` = 'notary';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OAuth2 Proxy is a reverse proxy written in Go that puts an OAuth2 or OIDC login flow in front of any upstream HTTP service. It handles the authorization code exchange with an identity provider, stores the resulting session in a cookie (or Redis), and forwards authenticated requests to the backend along with identity headers such as "},{"type":"text","text":"X-Auth-Request-Email","marks":[{"type":"code"}]},{"type":"text","text":" or a pass-through "},{"type":"text","text":"Authorization: Bearer","marks":[{"type":"code"}]},{"type":"text","text":" token."}]},{"type":"paragraph","content":[{"type":"text","text":"It supports a long list of providers out of the box: Google, GitHub, GitLab, Keycloak, Okta, Azure AD, Auth0, and any generic OIDC issuer. Access can be filtered by email domain, GitHub org/team, GitLab group, or OIDC claim. The project is most commonly deployed alongside Kubernetes Ingress controllers — NGINX Ingress exposes an "},{"type":"text","text":"auth_request","marks":[{"type":"code"}]},{"type":"text","text":" hook, and Traefik has a "},{"type":"text","text":"forwardAuth","marks":[{"type":"code"}]},{"type":"text","text":" middleware — so a single oauth2-proxy instance can gate many cluster services without requiring each one to implement its own login flow. This is the canonical way to add SSO to dashboards like Prometheus, Alertmanager, Kibana, or Argo CD''s UI when you do not want a full service mesh."}]},{"type":"paragraph","content":[{"type":"text","text":"The project began as Bitly''s "},{"type":"text","text":"google_auth_proxy","marks":[{"type":"code"}]},{"type":"text","text":", was forked by Pusher, and now lives at "},{"type":"text","text":"oauth2-proxy/oauth2-proxy","marks":[{"type":"code"}]},{"type":"text","text":" under the MIT license. It entered the CNCF sandbox in 2025. Alternatives include Pomerium, Ory Oathkeeper, Authelia, and Keycloak Gatekeeper (now unmaintained)."}]}]}' WHERE `id` = 'oauth2-proxy';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Odin is a general-purpose programming language focused on performance, explicit control, and data-oriented programming."}]},{"type":"paragraph","content":[{"type":"text","text":"The language is positioned as a C alternative with distinct typing, custom allocators, built-in support for data-oriented layouts, and a large core and vendor library set for systems, graphics, and application development."}]}]}' WHERE `id` = 'odin';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Okteto is an inner-loop development tool for Kubernetes. The core workflow is "},{"type":"text","text":"okteto up","marks":[{"type":"code"}]},{"type":"text","text":": it swaps a running pod''s container image for a language-appropriate development image, starts a bidirectional file sync between your working directory and the container, and opens an interactive shell plus port-forwards. You edit code locally, the container sees the changes instantly, and your app runs against real cluster dependencies without a Docker build, push, or redeploy on every iteration."}]},{"type":"paragraph","content":[{"type":"text","text":"Development environments are described by an "},{"type":"text","text":"okteto.yml","marks":[{"type":"code"}]},{"type":"text","text":" manifest that can reference existing Helm charts, Kustomize bases, Docker Compose files, or raw manifests, and declare a "},{"type":"text","text":"dev","marks":[{"type":"code"}]},{"type":"text","text":" section per service that controls the sync, command, and forwarded ports. File synchronization is implemented on top of Syncthing, which gives it reasonable performance on large trees and across unreliable links. The "},{"type":"text","text":"okteto","marks":[{"type":"code"}]},{"type":"text","text":" CLI is open-source and Apache-2.0 licensed; the company also sells a managed SaaS and a self-hostable product that layer on top with preview environments per pull request, multi-tenant namespaces, and SSO."}]},{"type":"paragraph","content":[{"type":"text","text":"It occupies the same niche as Tilt, Skaffold, Telepresence, DevSpace, and Garden — all different takes on \"stop waiting for CI and redeploys while iterating on a service inside a cluster\". Okteto''s distinguishing trait is the container-swap-plus-sync model rather than rebuilding images on every change."}]}]}' WHERE `id` = 'okteto';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Open Policy Agent (OPA) is a general-purpose policy engine that evaluates structured JSON input against policies written in Rego and returns a structured decision. Applications, API gateways, CI pipelines, and Kubernetes admission controllers call OPA with \"can this user do X on resource Y?\" and OPA answers yes, no, or any arbitrary document a policy chooses to compute."}]},{"type":"paragraph","content":[{"type":"text","text":"Rego is a declarative, Datalog-inspired language built for querying nested JSON. Policies are compiled into an intermediate representation and can be evaluated in-process via the Go library, as a sidecar over HTTP/gRPC, as a WebAssembly module compiled from the same Rego source, or inside Envoy as an ext_authz service. The bundle protocol pulls signed policy and data bundles from a central server (OPAL, Styra DAS, or any HTTP endpoint), and decision logs are shipped back out for audit. In Kubernetes, OPA is most often consumed through Gatekeeper, which wraps it in a validating/mutating admission webhook with CRD-based ConstraintTemplates."}]},{"type":"paragraph","content":[{"type":"text","text":"OPA graduated from CNCF in 2021 and is Apache-2.0. Adjacent tools include Kyverno (Kubernetes-native, YAML-based, no Rego), Cedar (AWS), and Casbin. OPA''s reach is broader than any of them: the same engine enforces admission policies, Terraform plan checks (via "},{"type":"text","text":"conftest","marks":[{"type":"code"}]},{"type":"text","text":"), microservice authorization, and database row filtering, all from one policy language."}]}]}' WHERE `id` = 'opa';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Open Policy Containers (OPCR) is a set of tools and conventions for packaging Open Policy Agent policies as OCI artifacts and distributing them through standard container registries. Instead of pulling Rego bundles from ad-hoc HTTP servers, you "},{"type":"text","text":"policy build","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"policy push","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"policy pull","marks":[{"type":"code"}]},{"type":"text","text":" them from Docker Hub, GHCR, ECR, or any OCI-compliant registry, the same way you handle container images."}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"policy","marks":[{"type":"code"}]},{"type":"text","text":" CLI wraps the build-sign-push loop: it compiles Rego source into an OPA bundle, stores it as an OCI artifact with a well-defined media type, and can sign it with Cosign so consumers can verify provenance before loading the bundle into OPA. A companion discovery plugin lets an OPA instance pull policies directly from a registry at startup and on a refresh interval, which closes the gap between image supply-chain tooling (Cosign, Notation, Rekor) and policy supply chains."}]},{"type":"paragraph","content":[{"type":"text","text":"OPCR sits in the supply chain security niche alongside ORAS (generic OCI artifact packaging), Cosign (signing), and Styra DAS or OPAL (centralized policy distribution). It is sponsored primarily by Aserto and released under Apache-2.0. For teams that already treat registries as the single source of truth for deployable artifacts, OPCR lets Rego policies live in that same pipeline."}]}]}' WHERE `id` = 'opcr';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Open Cluster Management (OCM) is a multi-cluster control plane for Kubernetes that turns a fleet of clusters into an inventory you can query, schedule work onto, and apply policies across from a single hub. It is the upstream that powers Red Hat Advanced Cluster Management (RHACM) and is a CNCF sandbox project."}]},{"type":"paragraph","content":[{"type":"text","text":"The architecture is pull-based. A hub cluster runs the OCM control plane; each managed cluster runs a "},{"type":"text","text":"klusterlet","marks":[{"type":"code"}]},{"type":"text","text":" agent that registers itself with the hub (via a CSR-based join handshake) and then watches for "},{"type":"text","text":"ManifestWork","marks":[{"type":"code"}]},{"type":"text","text":" CRs targeted at it. Workload placement is expressed through "},{"type":"text","text":"Placement","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"PlacementDecision","marks":[{"type":"code"}]},{"type":"text","text":" resources, which let the scheduler pick clusters by labels, taints, or custom scoring plugins — effectively kube-scheduler semantics, but for clusters instead of pods. Add-ons built on top of OCM include the Policy framework (which layers on Kyverno, Gatekeeper, or config-policy-controller), Application lifecycle management, cluster-proxy for reaching private clusters, and the submariner add-on for pod-to-pod networking across clusters."}]},{"type":"paragraph","content":[{"type":"text","text":"OCM competes with Karmada, KubeFed (deprecated), Argo CD ApplicationSets for GitOps-driven fan-out, Rancher Fleet, and Cluster API-based fleet tools. It is Apache-2.0 licensed and contributed to primarily by Red Hat and Alibaba."}]}]}' WHERE `id` = 'open-cluster-management';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenCost is a cost monitoring tool for Kubernetes that attributes cloud infrastructure spend down to individual namespaces, deployments, pods, and labels. It is the open-source core extracted from Kubecost, donated to the CNCF, and maintained as the reference implementation of the FinOps Foundation''s Kubernetes cost allocation spec."}]},{"type":"paragraph","content":[{"type":"text","text":"OpenCost joins Prometheus metrics ("},{"type":"text","text":"kube_pod_container_resource_requests","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"container_memory_working_set_bytes","marks":[{"type":"code"}]},{"type":"text","text":", etc.) with cloud provider billing data to compute hourly costs for CPU, memory, GPU, storage, and network for every workload. It ships with built-in pricing for AWS, GCP, Azure, Oracle, Alibaba, and Scaleway, and can consume the AWS Cost and Usage Report or GCP/Azure billing exports for reconciled \"actual\" costs rather than list-price estimates. Allocation output is available via a REST API, exported as Prometheus metrics, and increasingly via the FOCUS billing schema for ingestion into downstream FinOps tools."}]},{"type":"paragraph","content":[{"type":"text","text":"The project is Apache-2.0 and a CNCF incubating project. In the same space you will find Kubecost (the commercial superset), Cloudability, CAST AI, Vantage, Finout, and cloud-native tools like AWS Cost Explorer — but OpenCost is the only vendor-neutral option that runs entirely inside the cluster and speaks Prometheus natively."}]}]}' WHERE `id` = 'opencost';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenEBS is a Container Attached Storage (CAS) project for Kubernetes that turns the block devices on cluster nodes into persistent volumes managed entirely through the Kubernetes API. The defining architectural idea is that each volume gets its own dedicated storage controller pod, rather than sharing a monolithic cluster-wide storage service, so storage scales and fails in the same units as the workloads that consume it."}]},{"type":"paragraph","content":[{"type":"text","text":"OpenEBS is really a family of CSI drivers sharing a control plane. Local PV Hostpath and Local PV LVM/ZFS expose node-local disks with no replication for high-throughput workloads that handle their own redundancy (Cassandra, Kafka, etcd). cStor provides synchronous replicated block volumes using the ZFS-on-Linux userspace port, suited to general-purpose stateful apps. Mayastor is the NVMe-first engine written in Rust and built on SPDK and NVMe-oF, targeting latency-sensitive databases on modern NVMe hardware. Jiva, the original iSCSI-based engine, is kept for legacy deployments."}]},{"type":"paragraph","content":[{"type":"text","text":"It is Apache-2.0 and joined the CNCF sandbox in 2024 after many years as an independent project led by MayaData/DataCore. In the Kubernetes storage landscape it overlaps with Longhorn (Rancher), Rook-Ceph, Portworx, Piraeus/LINSTOR, and the various cloud provider CSI drivers. OpenEBS''s distinguishing trait is the multi-engine approach: pick the data plane per workload instead of committing the whole cluster to one backend."}]}]}' WHERE `id` = 'openebs';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenFaaS is a Functions-as-a-Service framework that runs on Kubernetes (via "},{"type":"text","text":"faas-netes","marks":[{"type":"code"}]},{"type":"text","text":") or directly on containerd (via "},{"type":"text","text":"faasd","marks":[{"type":"code"}]},{"type":"text","text":" for single-node installs). A function is a container image that implements a simple HTTP watchdog contract: the "},{"type":"text","text":"of-watchdog","marks":[{"type":"code"}]},{"type":"text","text":" sidecar binary receives requests, invokes your handler over stdin/stdout or HTTP, and returns the response, so any language or binary can become a function."}]},{"type":"paragraph","content":[{"type":"text","text":"The control plane is an API gateway that fronts the function pods and exposes a REST API plus a CLI ("},{"type":"text","text":"faas-cli","marks":[{"type":"code"}]},{"type":"text","text":"). Functions are defined in a "},{"type":"text","text":"stack.yaml","marks":[{"type":"code"}]},{"type":"text","text":" that points at a language template, built with BuildKit, pushed to a registry, and deployed as Kubernetes Deployments. Autoscaling is driven by Prometheus metrics and handled either by OpenFaaS''s built-in scaler or by KEDA for event-driven scale-to-zero. Event connectors exist for Kafka, NATS, SQS, Postgres, cron, and MQTT, which turn OpenFaaS into a general-purpose event router rather than just an HTTP function runner."}]},{"type":"paragraph","content":[{"type":"text","text":"Licensing is mixed: "},{"type":"text","text":"faas-netes","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"faasd","marks":[{"type":"code"}]},{"type":"text","text":", and the community templates are MIT, while OpenFaaS Pro and OpenFaaS Edge (features like HA, retries, long-running async jobs, SSO) are commercial under a EULA. In the cloud-native serverless space it competes with Knative Serving, Fission, Nuclio, OpenFunction, and Kubeless (archived). OpenFaaS''s niche is the classic container-per-function FaaS model with minimal moving parts."}]}]}' WHERE `id` = 'openfaas';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenFeature is a vendor-neutral specification and set of SDKs for feature flagging. It decouples the feature-flag API your application calls from the backend that actually evaluates the flags, so switching between LaunchDarkly, Flagsmith, Split, ConfigCat, Unleash, GO Feature Flag, or a self-hosted implementation becomes a provider swap rather than a code rewrite."}]},{"type":"paragraph","content":[{"type":"text","text":"The spec defines a small, typed evaluation API — "},{"type":"text","text":"getBooleanValue","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"getStringValue","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"getObjectValue","marks":[{"type":"code"}]},{"type":"text","text":", etc. — along with an "},{"type":"text","text":"EvaluationContext","marks":[{"type":"code"}]},{"type":"text","text":" for passing user and request attributes, and a hooks system for cross-cutting concerns like logging, telemetry, and validation. Providers implement a narrow interface; the SDK plugs them in at runtime. There are official SDKs for Java, .NET, Go, JavaScript/Node, Python, Ruby, PHP, and Rust, plus a daemon called "},{"type":"text","text":"flagd","marks":[{"type":"code"}]},{"type":"text","text":" that speaks a gRPC evaluation protocol so languages without a native SDK can still participate. OpenFeature also publishes OpenTelemetry semantic conventions for feature-flag evaluation, so flag decisions can land on existing traces and metrics without custom instrumentation."}]},{"type":"paragraph","content":[{"type":"text","text":"OpenFeature was accepted into the CNCF in 2022, reached incubating status in 2023, and is Apache-2.0. Its position in the ecosystem is similar to what OpenTelemetry is to observability or SQL to databases: a common surface over a competitive market of backends."}]}]}' WHERE `id` = 'openfeature';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenFGA is an authorization system inspired by Google''s Zanzibar paper. Instead of static roles or attribute expressions, OpenFGA models permissions as a graph of relationships between objects: \"user:anne is a reader of document:readme\", \"document:readme is in folder:design\", \"folder:design parent-of document:readme\". Applications call "},{"type":"text","text":"Check(user, relation, object)","marks":[{"type":"code"}]},{"type":"text","text":" and OpenFGA answers by traversing those relationship tuples against an authorization model."}]},{"type":"paragraph","content":[{"type":"text","text":"The authorization model is written in a small DSL that compiles to a JSON schema describing types ("},{"type":"text","text":"user","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"document","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"folder","marks":[{"type":"code"}]},{"type":"text","text":", ...) and the relations between them, including computed relations like "},{"type":"text","text":"viewer = reader or owner or viewer from parent","marks":[{"type":"code"}]},{"type":"text","text":". Tuples are stored in a pluggable datastore — Postgres, MySQL, or SQLite today — and the server exposes gRPC and HTTP APIs plus official SDKs for Go, JavaScript, .NET, Java, Python, and more. On top of "},{"type":"text","text":"Check","marks":[{"type":"code"}]},{"type":"text","text":", it offers "},{"type":"text","text":"ListObjects","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ListUsers","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"Expand","marks":[{"type":"code"}]},{"type":"text","text":" for building UIs that ask \"which documents can Anne see?\" without N check calls. It was created and open-sourced by Auth0/Okta."}]},{"type":"paragraph","content":[{"type":"text","text":"OpenFGA joined the CNCF as a sandbox project in 2022 and was promoted to incubating in 2025. Competing or adjacent projects include SpiceDB from AuthZed (also Zanzibar-inspired), Cerbos (policy-based, closer to ABAC), Permit.io, Oso, and OPA when wired up for ReBAC. Pick OpenFGA when your authorization problem is naturally graph-shaped — shared drives, multi-tenant SaaS, org hierarchies — and fine-grained listing matters."}]}]}' WHERE `id` = 'openfga';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenFunction is a Kubernetes-native Functions-as-a-Service platform that stitches together best-of-breed components from the cloud-native ecosystem rather than reinventing the build or runtime layers. A single "},{"type":"text","text":"Function","marks":[{"type":"code"}]},{"type":"text","text":" CRD describes a source repository, build strategy, and runtime configuration; OpenFunction''s operator expands it into the underlying objects."}]},{"type":"paragraph","content":[{"type":"text","text":"The build phase uses Shipwright and Cloud Native Buildpacks (or Kaniko/BuildKit) to turn source code into an OCI image without a Dockerfile. For synchronous HTTP functions, the runtime phase deploys the image onto Knative Serving, giving scale-to-zero and request-based autoscaling. For asynchronous, event-driven functions, it uses Dapr for pub/sub bindings and KEDA for scaling based on queue depth (Kafka, NATS, RabbitMQ, Pulsar, Redis, etc.). An optional ingress controller, based on Contour, routes external HTTP traffic to the synchronous functions. The overall story: one CRD, many specialised projects doing the actual work."}]},{"type":"paragraph","content":[{"type":"text","text":"OpenFunction is a CNCF sandbox project sponsored mainly by KubeSphere/QingCloud and Apache-2.0 licensed. It competes with Knative as a standalone, OpenFaaS, Fission, and Nuclio. Its differentiator is explicit first-class support for both sync (Knative) and async (Dapr + KEDA) runtimes through a unified CRD."}]}]}' WHERE `id` = 'openfunction';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"openGemini is a distributed time-series database written in Go and originally developed by Huawei Cloud for telemetry, monitoring, and IoT workloads. It speaks the InfluxDB line protocol and InfluxQL, so existing Telegraf and Influx client pipelines can point at it with minimal changes."}]},{"type":"paragraph","content":[{"type":"text","text":"The engine is column-oriented and designed around high-cardinality tag sets, which has historically been a pain point for InfluxDB 1.x/2.x. openGemini uses time-partitioned shards, Z-order indexing for multi-dimensional filters, and vectorised query execution to keep scans efficient as the number of series grows. The cluster architecture separates metadata nodes, SQL nodes, and storage nodes, allowing independent horizontal scaling, and supports replication across storage nodes for high availability. A Kubernetes operator and Helm chart handle cluster lifecycle."}]},{"type":"paragraph","content":[{"type":"text","text":"openGemini was accepted into the CNCF sandbox in 2024 and is Apache-2.0 licensed. In the time-series landscape it sits alongside InfluxDB, VictoriaMetrics, TimescaleDB, QuestDB, and M3DB — the pitch being InfluxQL compatibility combined with better high-cardinality behaviour and horizontal scaling than single-node Influx deployments provide."}]}]}' WHERE `id` = 'opengemini';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenGitOps is a CNCF sandbox working group that publishes a vendor-neutral specification for what \"GitOps\" actually means, rather than a runnable piece of software. It exists so that Argo CD, Flux, Jenkins X, Weave GitOps, and other tools can claim GitOps conformance against a shared definition instead of everyone redefining the term."}]},{"type":"paragraph","content":[{"type":"text","text":"The project''s main artefact is a short set of principles: the desired state of a system is declarative, versioned and immutable, pulled automatically, and continuously reconciled. Around those principles, the GitOps Working Group maintains a glossary, conformance criteria, and reference documentation that tool authors and platform teams can cite. There is no controller or CLI here; the deliverables are markdown specs in the "},{"type":"text","text":"open-gitops/documents","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"open-gitops/project","marks":[{"type":"code"}]},{"type":"text","text":" repositories."}]},{"type":"paragraph","content":[{"type":"text","text":"OpenGitOps was founded by Weaveworks, Codefresh, GitHub, Microsoft, Red Hat, and others, accepted into the CNCF sandbox in 2021, and released under Apache-2.0. Treat it as the terminological and conformance layer underneath the actual implementations — Argo CD and Flux being the two dominant reconcilers most teams will end up running."}]}]}' WHERE `id` = 'opengitops';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenKruise is a set of Kubernetes controllers that extend the built-in workload APIs with features Alibaba and other large operators found missing in Deployment, StatefulSet, and DaemonSet. It is packaged as a single "},{"type":"text","text":"kruise-manager","marks":[{"type":"code"}]},{"type":"text","text":" operator that installs a family of CRDs."}]},{"type":"paragraph","content":[{"type":"text","text":"The headline workloads are "},{"type":"text","text":"CloneSet","marks":[{"type":"code"}]},{"type":"text","text":" (a Deployment replacement with in-place pod updates, partition-based canaries, and explicit pod deletion selection), "},{"type":"text","text":"Advanced StatefulSet","marks":[{"type":"code"}]},{"type":"text","text":" (a superset of StatefulSet with in-place updates, MaxUnavailable, and parallel pod management), "},{"type":"text","text":"Advanced DaemonSet","marks":[{"type":"code"}]},{"type":"text","text":" (partition rollouts and surging), "},{"type":"text","text":"SidecarSet","marks":[{"type":"code"}]},{"type":"text","text":" (inject and hot-upgrade sidecar containers across many pods without restarting the main container), and "},{"type":"text","text":"BroadcastJob","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"AdvancedCronJob","marks":[{"type":"code"}]},{"type":"text","text":" for running jobs on every matching node. Separate CRDs like "},{"type":"text","text":"PodUnavailableBudget","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"WorkloadSpread","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ContainerRecreateRequest","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ImagePullJob","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"NodeImage","marks":[{"type":"code"}]},{"type":"text","text":" cover pre-pulling images, controlled restarts, and topology-aware scheduling. The in-place update feature is the biggest draw: it mutates an existing pod''s container image without deleting and recreating the pod, which matters for workloads where pod identity or warmed state is expensive to lose."}]},{"type":"paragraph","content":[{"type":"text","text":"OpenKruise is a CNCF incubating project (sandbox 2020, incubating 2023), Apache-2.0, and comes from Alibaba. It is most often compared with Argo Rollouts and Flagger for progressive delivery, though Kruise operates at the workload controller layer rather than as a higher-level rollout manager."}]}]}' WHERE `id` = 'openkruise';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenTelemetry (OTel) is a vendor-neutral framework for generating, collecting, and exporting telemetry from applications — traces, metrics, and logs — under a single specification and wire protocol (OTLP). It is the result of merging OpenTracing and OpenCensus, and today is the second-most-active CNCF project after Kubernetes."}]},{"type":"paragraph","content":[{"type":"text","text":"The project is structured in three layers. The specification defines the data model, semantic conventions (e.g. how HTTP and database spans are named and attributed), and the OTLP protocol. SDKs in more than ten languages implement that spec, providing a tracer and meter API plus auto-instrumentation for common libraries (HTTP servers, gRPC, SQL drivers, messaging clients). The OpenTelemetry Collector is a standalone Go binary that ingests OTLP and legacy formats via receivers, runs processors (batching, sampling, attribute rewriting, tail-based sampling), and forwards to exporters for every major backend: Jaeger, Tempo, Prometheus, Loki, Elastic, Datadog, Honeycomb, Splunk, and others. Running the Collector as a sidecar, daemonset, and gateway tier is the standard production topology."}]},{"type":"paragraph","content":[{"type":"text","text":"OTel is Apache-2.0 licensed. Adopting OpenTelemetry is how teams avoid vendor lock-in on the instrumentation layer: instrument once against the OTel SDK, then point the Collector at whichever backend they happen to be paying for this year."}]}]}' WHERE `id` = 'opentelemetry';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenTofu is a community-driven fork of Terraform created after HashiCorp relicensed Terraform from MPL-2.0 to the Business Source License in August 2023. It is hosted by the Linux Foundation, remains MPL-2.0, and is a drop-in replacement for "},{"type":"text","text":"terraform","marks":[{"type":"code"}]},{"type":"text","text":": the HCL language, provider protocol, state file format, and CLI surface all match."}]},{"type":"paragraph","content":[{"type":"text","text":"OpenTofu stayed compatible with Terraform 1.5 and has since added features that the MPL community had been asking for. State encryption lets you encrypt state files at rest with AES-GCM using keys from KMS, PBKDF2, or static sources, without relying on bucket-level encryption alone. Provider-defined functions, early evaluation of "},{"type":"text","text":"for_each","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"count","marks":[{"type":"code"}]},{"type":"text","text":", and a fully open registry at "},{"type":"text","text":"registry.opentofu.org","marks":[{"type":"code"}]},{"type":"text","text":" are post-fork additions. It uses the same "},{"type":"text","text":"terraform-provider-*","marks":[{"type":"code"}]},{"type":"text","text":" plugins, which gives it immediate access to every provider written against the Terraform Plugin Protocol."}]},{"type":"paragraph","content":[{"type":"text","text":"OpenTofu is supported by Spacelift, env0, Scalr, Gruntwork, Harness, Digger, and others, and has its own CI integrations and IDE tooling alongside (or in place of) the official Terraform ones. For teams that want to stay on an open-source license or avoid BSL exposure in internal tooling, OpenTofu is the canonical path; for everyone else it is a near-identical alternative that tracks Terraform''s capabilities closely while drifting in opinionated directions like state encryption."}]}]}' WHERE `id` = 'opentofu';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenUnison is an identity and access management platform from Tremolo Security, best known for providing authentication, authorization, and self-service access to Kubernetes clusters. It acts as a reverse proxy and identity provider in front of the Kubernetes API server, the dashboard, and auxiliary tools like Argo CD, Grafana, and Vault, so a single SSO flow covers every cluster-adjacent UI."}]},{"type":"paragraph","content":[{"type":"text","text":"It supports SAML, OIDC, and LDAP as upstream identity sources and brokers those logins into Kubernetes-compatible tokens or impersonation headers. Beyond SSO, OpenUnison includes a lightweight workflow engine for access requests — a developer can request namespace access, an owner approves it, and OpenUnison reconciles the resulting RBAC bindings — which turns it into a cluster-scoped portal rather than a pure gateway. Features like automatic "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":" token refresh, audit logging, and multi-cluster support via a single portal are the main reasons teams deploy it instead of rolling their own oauth2-proxy plus dex plus dashboard setup."}]},{"type":"paragraph","content":[{"type":"text","text":"OpenUnison is open-source under the Apache-2.0 license, with a commercial \"Namespace as a Service\" distribution from Tremolo on top. In the same space sit Dex (pure OIDC bridge), Keycloak, Pinniped, and Teleport, with OpenUnison occupying the niche of \"integrated Kubernetes access portal with request workflows\" rather than a general-purpose IdP."}]}]}' WHERE `id` = 'openunison';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenYurt is a Kubernetes extension that turns a standard cluster into an edge cluster, allowing nodes spread across unreliable networks and remote sites to be managed from a single, unmodified control plane. It was started by Alibaba and is now a CNCF incubating project."}]},{"type":"paragraph","content":[{"type":"text","text":"The main architectural trick is the YurtHub agent, which runs on every edge node and sits between the kubelet and the API server. YurtHub caches watch results and object state on the node''s local disk, so if the link to the cloud control plane drops, the kubelet keeps reading from its local cache and pods continue running with their current configuration — a property OpenYurt calls \"edge autonomy\". The YurtTunnel and Yurt-manager components handle inbound reachability (log fetches, exec, port-forward) across NAT and asymmetric network paths from cloud to edge. On top of this, the NodePool and YurtAppSet CRDs let you describe groups of geographically co-located nodes and schedule workloads per-pool without inventing custom affinity rules."}]},{"type":"paragraph","content":[{"type":"text","text":"OpenYurt is Apache-2.0 and competes with KubeEdge (a more invasive fork-style approach where the edge runs a reduced control plane), SuperEdge, and k3s plus custom tooling. OpenYurt''s defining trade-off is staying as close to upstream Kubernetes as possible: any standard cluster can be converted to OpenYurt with "},{"type":"text","text":"yurtadm","marks":[{"type":"code"}]},{"type":"text","text":" and converted back, and workloads need no changes."}]}]}' WHERE `id` = 'openyurt';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Operator Framework is a toolkit for building, packaging, and distributing Kubernetes Operators — controllers that encode application lifecycle knowledge behind a Custom Resource Definition. It was started by CoreOS (now Red Hat) and is a CNCF incubating project."}]},{"type":"paragraph","content":[{"type":"text","text":"It has three main components. The Operator SDK scaffolds new operator projects and supports three flavours: Go operators built on "},{"type":"text","text":"controller-runtime","marks":[{"type":"code"}]},{"type":"text","text":" (the same reconciler library used by kubebuilder), Ansible operators that map CR events to playbook runs, and Helm operators that wrap an existing chart so each CR instance becomes a Helm release. The Operator Lifecycle Manager (OLM) is a controller you install into the cluster; it handles installing operators from catalogs, resolving their dependencies, managing subscription channels, and performing upgrades through "},{"type":"text","text":"ClusterServiceVersion","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Subscription","marks":[{"type":"code"}]},{"type":"text","text":" CRs. OperatorHub.io is the community catalog that OLM consumes by default. Operator authors publish bundle images — OCI artifacts containing CSVs, CRDs, and metadata — and OLM knows how to pull and install them."}]},{"type":"paragraph","content":[{"type":"text","text":"Operator Framework shares the controller-runtime foundation with kubebuilder; the two are closely related and the SDK exposes kubebuilder''s scaffolding plus the additional Ansible, Helm, OLM bundle, and scorecard testing tooling. It is Apache-2.0, used heavily inside OpenShift (where OLM is the default app-installation mechanism), and remains the canonical path for distributing a Kubernetes operator through a catalog rather than a raw Helm chart."}]}]}' WHERE `id` = 'operatorframework';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ORAS — OCI Registry As Storage — is a CLI and Go library for pushing, pulling, and referencing arbitrary artifacts in any OCI-compliant container registry. Instead of treating a registry as a place only for Docker images, ORAS lets you store Helm charts, WASM modules, SBOMs, Cosign signatures, Tekton pipelines, OPA bundles, ML models, or any other file with a custom media type, reusing the authentication, distribution, replication, and RBAC you already get from your registry."}]},{"type":"paragraph","content":[{"type":"text","text":"Technically, ORAS pushes artifacts as OCI image manifests (or, with OCI 1.1, artifact manifests) whose layers are the files you want to store and whose "},{"type":"text","text":"config","marks":[{"type":"code"}]},{"type":"text","text":" media type identifies the artifact kind. The "},{"type":"text","text":"referrers","marks":[{"type":"code"}]},{"type":"text","text":" API introduced in the OCI Distribution Spec 1.1 lets one artifact point at another — this is how Cosign signatures and SBOMs can be attached to an image and discovered later, and ORAS is the reference implementation of that flow. The "},{"type":"text","text":"oras","marks":[{"type":"code"}]},{"type":"text","text":" CLI handles push, pull, discover, copy, and attach operations, and the Go library is embedded inside Notation, Helm 3 OCI support, Flux, Cosign, and many other tools."}]},{"type":"paragraph","content":[{"type":"text","text":"ORAS is a CNCF sandbox project, Apache-2.0, and increasingly the de facto way the cloud-native ecosystem stores non-image artifacts. If a tool says \"we can store this in an OCI registry\", odds are very good that ORAS is doing the pushing and pulling underneath."}]}]}' WHERE `id` = 'oras';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OSCAL Compass is a collection of tools that make NIST''s Open Security Controls Assessment Language (OSCAL) usable in real DevSecOps pipelines. OSCAL is a set of JSON/YAML/XML schemas published by NIST for expressing control catalogs (NIST 800-53, ISO 27001, FedRAMP), profiles that tailor catalogs, component definitions, system security plans, and assessment results. OSCAL Compass provides the glue that turns those documents into something you can automate."}]},{"type":"paragraph","content":[{"type":"text","text":"The headline project is "},{"type":"text","text":"compliance-trestle","marks":[{"type":"code"}]},{"type":"text","text":", a Python CLI and library for editing, validating, splitting, merging, and version-controlling OSCAL documents. It lets compliance teams keep catalogs and SSPs in Git alongside the code they describe, generate Markdown for human review, and synchronize between OSCAL models and operational tooling. Around "},{"type":"text","text":"trestle","marks":[{"type":"code"}]},{"type":"text","text":", the project includes "},{"type":"text","text":"compliance-to-policy","marks":[{"type":"code"}]},{"type":"text","text":" (which translates OSCAL component definitions into Kyverno, OPA, or Auditree policies so declared controls actually get enforced) and "},{"type":"text","text":"agile-authoring","marks":[{"type":"code"}]},{"type":"text","text":" patterns for iterating on FedRAMP-style System Security Plans with pull requests instead of Word documents."}]},{"type":"paragraph","content":[{"type":"text","text":"OSCAL Compass was originally incubated by IBM, accepted into the CNCF sandbox in 2024, and is Apache-2.0. It is most relevant to teams operating under FedRAMP, FISMA, or any framework where NIST 800-53 is the source of truth — the goal is \"compliance as code\" in the literal sense of making assessment artifacts machine-readable from end to end."}]}]}' WHERE `id` = 'oscal-compass';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Otterize is an intent-based access control tool for Kubernetes that lets application teams declare which services their workload needs to reach, then automatically compiles those declarations into NetworkPolicies, Istio authorization policies, Linkerd server authorizations, database grants, AWS IAM roles, and Kafka ACLs."}]},{"type":"paragraph","content":[{"type":"text","text":"The core abstraction is a "},{"type":"text","text":"ClientIntents","marks":[{"type":"code"}]},{"type":"text","text":" custom resource. A developer lists the targets their service talks to — another Kubernetes service, a Postgres database, an S3 bucket, a Kafka topic — and Otterize''s operator translates that into the right low-level policy for each target. A companion Network Mapper watches live traffic in the cluster (via eBPF or Kubernetes service telemetry) and can produce "},{"type":"text","text":"ClientIntents","marks":[{"type":"code"}]},{"type":"text","text":" automatically from observed communication, which means you can roll out zero-trust network policies by generating them from reality instead of hand-writing YAML and hoping you covered everything. Otterize can also provision short-lived mTLS credentials via SPIRE for workloads that need identity-based auth rather than network-based."}]},{"type":"paragraph","content":[{"type":"text","text":"Otterize is Apache-2.0 open-source, with a commercial cloud management plane on top. In the zero-trust Kubernetes space it overlaps with Cilium Network Policies, Calico, Tetragon, Istio AuthorizationPolicy, and Kyverno — Otterize''s niche is the intent-based authoring model and the automatic cross-plane translation, so the same declaration produces network, mesh, database, and IAM policies in one pass."}]}]}' WHERE `id` = 'otterize';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OVN-Kubernetes is a Kubernetes CNI plugin built on top of Open Virtual Network (OVN), the logical networking layer that Open vSwitch (OVS) exposes for software-defined networks. It is the default CNI in OpenShift and the upstream project became a CNCF sandbox project in 2024."}]},{"type":"paragraph","content":[{"type":"text","text":"Instead of programming iptables or generating individual flow rules per node, OVN-Kubernetes translates Kubernetes objects — Services, NetworkPolicies, EndpointSlices, Nodes — into logical switches, routers, and ACLs in OVN''s northbound database. OVN''s northd then compiles those logical flows into OpenFlow rules that ovs-vswitchd installs on each node. The result is that policy, routing, and load balancing are modelled in a single declarative graph that OVS enforces at the datapath, and changes propagate through OVN''s southbound database to all nodes without per-node controllers reinventing state. It supports VXLAN and Geneve overlays, hardware offload via smart NICs, IPv4/IPv6 dual-stack, egress IPs, multicast, network segmentation per namespace, and multiple networks per pod through the upcoming "},{"type":"text","text":"NetworkAttachmentDefinition","marks":[{"type":"code"}]},{"type":"text","text":" integration."}]},{"type":"paragraph","content":[{"type":"text","text":"OVN-Kubernetes is Apache-2.0 and targets the same problem space as Cilium, Calico, Antrea, Kube-OVN, and Flannel. Its defining feature is reusing the mature OVN/OVS codebase from the OpenStack world rather than building a new datapath, which is attractive in telco and enterprise environments that already run OVS and want consistent networking across virtual machines and Kubernetes pods."}]}]}' WHERE `id` = 'ovn-kubernetes';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Paralus is a tool for managing secure, audited access to multiple Kubernetes clusters from a single portal. It gives platform teams a way to hand out "},{"type":"text","text":"kubeconfig","marks":[{"type":"code"}]},{"type":"text","text":" files tied to SSO identity, enforce RBAC across clusters centrally, and record every "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":" action for audit — without running a separate bastion host or VPN per cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"The architecture is a hub-and-spoke model. A central Paralus control plane (Postgres-backed) holds users, projects, roles, and cluster registrations; each managed cluster runs a lightweight agent that dials out to the control plane over a persistent connection. When a user runs "},{"type":"text","text":"kubectl","marks":[{"type":"code"}]},{"type":"text","text":", requests are proxied through the control plane to the cluster agent, which means inbound cluster connectivity is not required and audit logs naturally land at one point. Identities come from an upstream IdP via OIDC or SAML; the portal maps IdP groups to Paralus roles, which translate to Kubernetes RBAC bindings on the target clusters. A zero-trust kubectl CLI plugin ("},{"type":"text","text":"pctl","marks":[{"type":"code"}]},{"type":"text","text":") wraps credential handoff so users never see raw service account tokens."}]},{"type":"paragraph","content":[{"type":"text","text":"Paralus was donated to the CNCF sandbox by Rafay Systems in 2022 and is Apache-2.0. In the same space you will find Teleport, Pinniped, OpenUnison, Loft vCluster with the loft.sh platform, and cloud-vendor IAM-backed cluster access. Paralus''s niche is the combination of centralized audit and zero inbound connectivity for air-gapped and multi-cloud fleets."}]}]}' WHERE `id` = 'paralus';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Parca is an open-source continuous profiling system built around an eBPF-based whole-system profiler and a columnar storage engine designed specifically for stack-trace data. It is developed by Polar Signals and released under Apache-2.0."}]},{"type":"paragraph","content":[{"type":"text","text":"The Parca Agent runs as a DaemonSet on every node and uses eBPF perf events to sample on-CPU stacks across all processes at ~19 Hz, regardless of language or runtime. Because the sampler lives in the kernel, there is no per-service instrumentation or runtime agent to attach; native code, Go, Rust, C++, and Java (with appropriate unwinding support) all get profiled through the same pipeline. Symbols are resolved out-of-band, either from debug info on the node or from an uploaded symbol store, so stripped production binaries still produce useful flame graphs. Profiles are shipped in the standard pprof format to the Parca server, which stores them in FrostDB, an embedded columnar database also from Polar Signals, tuned for time-series of stacks."}]},{"type":"paragraph","content":[{"type":"text","text":"The query UI produces flame graphs, icicle graphs, and diff views across arbitrary label selectors and time ranges, so you can ask \"what changed in CPU usage for this deployment between yesterday and today?\" In the continuous profiling space Parca competes with Pyroscope (now Grafana Pyroscope), Pixie''s perf profiler, and vendor offerings from Datadog, Elastic, and Google Cloud Profiler. It integrates cleanly with Prometheus service discovery and is the natural fit when the rest of your observability stack is already eBPF- and label-based."}]}]}' WHERE `id` = 'parca';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Parsec, the Platform Abstraction for Security, is a hardware-agnostic security service that exposes a single API for cryptographic operations regardless of the underlying secure element. Applications ask Parsec to generate a key, sign a payload, or wrap a secret; Parsec routes the call to whichever hardware root of trust is available on the platform — a TPM 2.0, an HSM over PKCS#11, an Arm TrustZone-backed trusted application, or a cloud KMS."}]},{"type":"paragraph","content":[{"type":"text","text":"The service is written in Rust and runs as a local daemon that clients talk to over a Unix domain socket using a compact wire protocol. Client libraries exist for Rust, C, Go, and Python, and there is a PKCS#11 adapter for software that only knows how to talk to HSMs that way. Internally, Parsec organises providers — one per backend technology — behind a core that handles authentication, key naming, and RPC dispatch, so multiple applications on the same host can share access to the same HSM or TPM without trampling each other''s key slots. The project originated with Arm and is now under the Cloud Native Computing Foundation as a sandbox project."}]},{"type":"paragraph","content":[{"type":"text","text":"Parsec is useful anywhere you need workload-level access to hardware-backed keys without writing separate code for every device: confidential computing workloads, IoT gateways, vehicle ECUs, and Kubernetes nodes where several pods want to use the host TPM. It is Apache-2.0 licensed and lives at "},{"type":"text","text":"parallaxsecond/parsec","marks":[{"type":"code"}]},{"type":"text","text":" on GitHub."}]}]}' WHERE `id` = 'parsec';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Perses is a dashboarding tool for observability data that treats dashboards as versioned, schema-validated artifacts rather than JSON blobs edited in a UI. It is Apache-2.0, a CNCF sandbox project as of 2024, and driven primarily by contributors from Red Hat, Amadeus, and the Prometheus community."}]},{"type":"paragraph","content":[{"type":"text","text":"Dashboards in Perses are Kubernetes-style resources with an OpenAPI schema, a CUE-based data model for validation, and a stable Go/TypeScript SDK for programmatic authoring. You can define a dashboard in YAML, JSON, or by composing it from TypeScript/CUE at build time, then store it in Git, lint it in CI, and deploy it like any other manifest. The backend is a stateless Go server that can run embedded storage or a database and exposes a REST API; the frontend is a React app built on the Perses component library, which is also published so other projects (including Grafana plugins and observability vendors) can reuse the panels and query editors. Data source support focuses on Prometheus and Tempo today, with a plugin model for adding more."}]},{"type":"paragraph","content":[{"type":"text","text":"The explicit pitch is being the \"dashboards as code\" alternative to Grafana — Grafana supports JSON dashboards but was not designed schema-first, and its JSON model drifts across versions. Perses is aimed at teams running large numbers of dashboards across fleets of clusters that want generation, review, and validation to live in the same tooling as their application code. Alongside it sit Grafana (the incumbent), Chronosphere, Honeycomb Boards, and the observability UIs shipped with Prometheus and Thanos."}]}]}' WHERE `id` = 'perses';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PHP is a dynamically typed, interpreted scripting language created by Rasmus Lerdorf in 1994 and originally aimed at building server-rendered web pages. It is executed by the Zend Engine, a bytecode interpreter that compiles source files to opcodes on each request unless OPcache is enabled to keep compiled opcodes resident in shared memory."}]},{"type":"paragraph","content":[{"type":"text","text":"Most production PHP runs behind a web server via PHP-FPM, a FastCGI process manager that pools long-lived worker processes and hands requests to them from Nginx or Apache. Each request gets a fresh execution context, which keeps the shared-nothing model simple but historically made warm caches and connection pools awkward. PHP 8 introduced a JIT compiler on top of OPcache, along with attributes, enums, union types, and readonly properties, closing much of the gap with other modern runtimes."}]},{"type":"paragraph","content":[{"type":"text","text":"The ecosystem is dominated by Composer for dependency management and PSR standards from PHP-FIG for autoloading, HTTP messages, and logging. Laravel and Symfony are the two large application frameworks, with Symfony components forming the backbone of projects like Drupal. WordPress still powers a large fraction of the public web on PHP, and Magento, MediaWiki, Nextcloud, and phpBB remain widely deployed. PHP also backs Facebook''s original codebase, which evolved into HHVM and the Hack language as a separate runtime."}]}]}' WHERE `id` = 'php';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PipeCD is a GitOps-style continuous delivery system originally built at CyberAgent and donated to the CNCF in 2023. It targets a wide range of deployment targets from a single control plane: Kubernetes manifests and Kustomize/Helm, Terraform, AWS ECS, AWS Lambda, and Google Cloud Run."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally, PipeCD splits into a central control plane (piped-control-plane) that stores pipeline state and a lightweight agent called "},{"type":"text","text":"piped","marks":[{"type":"code"}]},{"type":"text","text":" that runs inside each target environment. The agent pulls desired state from Git, plans a diff against the live target, and executes user-defined stages such as canary, baseline/canary analysis, traffic shifting, manual approval, and rollback. Because the agent runs inside the cluster or account it deploys to, no inbound access to workloads is required from the control plane."}]},{"type":"paragraph","content":[{"type":"text","text":"Compared to Argo CD and Flux, PipeCD''s differentiator is the unified pipeline model across non-Kubernetes targets like Lambda and ECS, plus built-in progressive delivery primitives without a separate controller like Argo Rollouts or Flagger. It integrates with Prometheus, Datadog, Stackdriver, and CloudWatch for metrics-based analysis during progressive rollouts."}]}]}' WHERE `id` = 'pipecd';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pipedream is a hosted integration platform for building event-driven workflows that connect SaaS APIs, databases, and AI services. Workflows are triggered by sources such as HTTP webhooks, schedules, email, RSS, or SaaS events (GitHub, Stripe, Slack, Google Sheets) and execute a sequence of steps that can be either pre-built actions or inline code."}]},{"type":"paragraph","content":[{"type":"text","text":"Each workflow step runs in a managed Node.js, Python, Go, or Bash sandbox on Pipedream''s serverless runtime, and steps can pass structured data to each other through a shared "},{"type":"text","text":"steps","marks":[{"type":"code"}]},{"type":"text","text":" object. The platform handles OAuth token management and credential storage for thousands of connected accounts, so workflow code never has to implement auth flows. Workflows have a managed state store, a "},{"type":"text","text":"$.flow.suspend","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"$.flow.rerun","marks":[{"type":"code"}]},{"type":"text","text":" API for long-running or human-in-the-loop steps, and event history for replay and debugging."}]},{"type":"paragraph","content":[{"type":"text","text":"The integration catalog is open-sourced at github.com/PipedreamHQ/pipedream under MIT, while the execution platform is commercial with a free tier. It competes with Zapier, Make, n8n, and Workato, differentiating on the amount of custom code you can drop into a workflow without leaving the UI, which makes it popular for glue code between internal services and third-party APIs."}]}]}' WHERE `id` = 'pipedream';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Piraeus Datastore is a Kubernetes-native block storage system that packages LINBIT''s LINSTOR and DRBD as an operator. It provides persistent volumes for stateful workloads by replicating block devices across cluster nodes at the kernel level rather than over a userspace data path."}]},{"type":"paragraph","content":[{"type":"text","text":"Underneath, DRBD (Distributed Replicated Block Device) is a Linux kernel module that synchronously mirrors block writes between nodes over TCP or RDMA, giving Piraeus its consistency guarantees without an intermediate object layer. LINSTOR is the control plane that places volumes, manages LVM or ZFS storage pools on each node, and reconciles replica counts. The Piraeus Operator installs LINSTOR controllers, satellites, and the CSI driver onto a cluster and exposes StorageClasses so that standard PVC workflows create replicated DRBD volumes transparently."}]},{"type":"paragraph","content":[{"type":"text","text":"Because DRBD operates below the filesystem, Piraeus is typically chosen for workloads that need low-latency, strongly-consistent block storage with local reads, such as databases, message queues, and virtual machines under KubeVirt. It sits in the same space as Rook-Ceph (RBD), Longhorn, and OpenEBS, trading Ceph''s feature surface for a simpler, kernel-accelerated data path. Piraeus was accepted into the CNCF sandbox in 2021."}]}]}' WHERE `id` = 'piraeus';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pixie is a Kubernetes observability tool that uses eBPF to capture application telemetry without code instrumentation or sidecars. It was created by Pixie Labs, acquired by New Relic in 2020, and donated to the CNCF sandbox in 2021."}]},{"type":"paragraph","content":[{"type":"text","text":"A Pixie deployment runs the Vizier agent as a DaemonSet on each node. Vizier attaches eBPF probes to kernel tracepoints, uprobes, and kprobes to capture HTTP, gRPC, MySQL, PostgreSQL, DNS, Kafka, Redis, and TLS traffic directly off the socket layer, as well as CPU profiles via perf_events. All captured data is stored in an in-memory columnar store on each node rather than shipped to a central backend, which keeps egress costs low and lets queries run against the last few minutes of full-fidelity traffic. A separate cloud control plane coordinates clusters and hosts the UI."}]},{"type":"paragraph","content":[{"type":"text","text":"Queries are written in PxL, a Pythonic DataFrame-style language that compiles to a distributed execution plan across Vizier agents. Pixie ships with scripts for service maps, HTTP latency breakdowns, database query profiling, and flame graphs out of the box. It can export data to OpenTelemetry collectors and is often paired with Grafana or New Relic for long-term storage, with Pixie handling the live, high-cardinality layer that traditional APM agents would otherwise need instrumentation for."}]}]}' WHERE `id` = 'pixie';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"pkgx is a cross-platform package runner and package manager from the creator of Homebrew, Max Howell. Instead of installing tools globally, "},{"type":"text","text":"pkgx node@20","marks":[{"type":"code"}]},{"type":"text","text":" fetches an isolated build of Node 20 into "},{"type":"text","text":"~/.pkgx","marks":[{"type":"code"}]},{"type":"text","text":" and runs it, resolving its transitive dependencies on the fly from a distributed registry of pre-built binaries."}]},{"type":"paragraph","content":[{"type":"text","text":"Packages are defined declaratively in the pantry repository (github.com/pkgxdev/pantry) as YAML specs that describe how to build each project from source for macOS (arm64/x86_64) and Linux (arm64/x86_64). The builds are content-addressed and relocatable, which means multiple versions coexist without conflict and activation is just a matter of prepending the right directories to "},{"type":"text","text":"PATH","marks":[{"type":"code"}]},{"type":"text","text":". A "},{"type":"text","text":"dev","marks":[{"type":"code"}]},{"type":"text","text":" shim hooks into your shell so that entering a project directory with a "},{"type":"text","text":"package.json","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"pyproject.toml","marks":[{"type":"code"}]},{"type":"text","text":", or similar manifest automatically makes the correct versions of node, python, or go available in that shell, similar to direnv combined with asdf or mise."}]},{"type":"paragraph","content":[{"type":"text","text":"pkgx is MIT-licensed and competes with Homebrew, asdf, mise, Nix, and devbox. Its niche is being daemonless, not requiring sudo, and being usable as a one-off runner in CI ("},{"type":"text","text":"pkgx +node@20 npm test","marks":[{"type":"code"}]},{"type":"text","text":") without committing to a package manager installation on the runner."}]}]}' WHERE `id` = 'pkgx';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Podman is a daemonless container engine for running OCI containers and pods on Linux, developed primarily by Red Hat. Unlike Docker, there is no long-running root daemon mediating container operations: the "},{"type":"text","text":"podman","marks":[{"type":"code"}]},{"type":"text","text":" CLI forks "},{"type":"text","text":"conmon","marks":[{"type":"code"}]},{"type":"text","text":" per container, which then execs "},{"type":"text","text":"crun","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"runc","marks":[{"type":"code"}]},{"type":"text","text":" to launch the workload, and exits when the container exits."}]},{"type":"paragraph","content":[{"type":"text","text":"This fork-exec model is what enables Podman''s rootless support: a normal user can create containers in their own user namespace, with UID/GID mappings backed by "},{"type":"text","text":"/etc/subuid","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"/etc/subgid","marks":[{"type":"code"}]},{"type":"text","text":" and networking handled by "},{"type":"text","text":"slirp4netns","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"pasta","marks":[{"type":"code"}]},{"type":"text","text":" instead of privileged bridge setup. Podman natively understands Kubernetes-style pods as a group of containers sharing a network namespace, and "},{"type":"text","text":"podman generate kube","marks":[{"type":"code"}]},{"type":"text","text":" produces Kubernetes YAML from a running pod while "},{"type":"text","text":"podman play kube","marks":[{"type":"code"}]},{"type":"text","text":" does the reverse, making it useful for local development of workloads destined for a cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"The CLI is intentionally a drop-in for Docker — aliasing "},{"type":"text","text":"docker=podman","marks":[{"type":"code"}]},{"type":"text","text":" works for most workflows — and on macOS and Windows "},{"type":"text","text":"podman machine","marks":[{"type":"code"}]},{"type":"text","text":" provisions a Fedora CoreOS VM to run the Linux engine. Related projects in the same family include Buildah for image builds, Skopeo for image inspection and copy, and CRI-O for the Kubernetes runtime interface, all of which share Podman''s "},{"type":"text","text":"containers/storage","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"containers/image","marks":[{"type":"code"}]},{"type":"text","text":" libraries."}]}]}' WHERE `id` = 'podman';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Podman Desktop is a cross-platform graphical application for managing containers and Kubernetes from a developer workstation. It is built on Electron and maintained by Red Hat, with the project accepted into the CNCF sandbox in 2025. It acts as a Docker Desktop replacement while remaining fully open-source under Apache-2.0."}]},{"type":"paragraph","content":[{"type":"text","text":"On macOS and Windows, Podman Desktop provisions and manages a "},{"type":"text","text":"podman machine","marks":[{"type":"code"}]},{"type":"text","text":" VM (a Fedora CoreOS guest running on QEMU, Hyper-V, or Apple''s Virtualization framework via vfkit) so that the Linux Podman engine is available to the host CLI and GUI. The UI exposes image builds and pulls, container lifecycle, volumes, and pod management, plus a compose view for multi-container applications. A Docker compatibility socket ships out of the box, so tools wired to "},{"type":"text","text":"/var/run/docker.sock","marks":[{"type":"code"}]},{"type":"text","text":" (testcontainers, IDE plugins, Buildx clients) continue to work without change."}]},{"type":"paragraph","content":[{"type":"text","text":"Beyond Podman itself, the app is extensible and ships integrations for Kind, Minikube, Lima, OpenShift Local (crc), and even Docker as an alternative backend. It can deploy workloads directly into a local Kubernetes cluster, inspect pods, and port-forward services, which positions it as the GUI layer for developers standardizing on Podman and local Kubernetes for inner-loop work."}]}]}' WHERE `id` = 'podman-desktop';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Policy Reporter watches the Kubernetes "},{"type":"text","text":"PolicyReport","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"ClusterPolicyReport","marks":[{"type":"code"}]},{"type":"text","text":" CRDs defined by the Kubernetes Policy Working Group and turns them into metrics, dashboards, and notifications. It does not itself evaluate policies; it consumes the reports produced by engines like Kyverno, Falco, Trivy Operator, jsPolicy, and kube-bench."}]},{"type":"paragraph","content":[{"type":"text","text":"The core component is a Go controller that subscribes to PolicyReport changes and fans them out to multiple targets: Prometheus metrics on results per policy/category/severity, a REST API, and push targets such as Slack, Microsoft Teams, Discord, Elasticsearch, Loki, S3, Google Chat, Webhooks, and Jira. Each target supports filtering by namespace, policy, severity, and result status, which lets different teams subscribe to the subset of violations they care about without duplicating policy logic. A separate UI component provides a Vue-based dashboard that reads from the API and visualizes the current compliance state of a cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"Policy Reporter is effectively the reporting and alerting layer on top of the Kyverno stack and is what most teams use to surface policy failures from admission controllers into the same channels they already use for runtime alerts. It is MIT-licensed and part of the Kyverno GitHub organization."}]}]}' WHERE `id` = 'policy-reporter';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Portainer is a web UI and management server for container environments that targets Docker, Docker Swarm, Kubernetes, and Nomad from a single console. It is written in Go with an Angular frontend and is distributed as a container image that runs alongside the environments it manages."}]},{"type":"paragraph","content":[{"type":"text","text":"A Portainer deployment consists of a central server and one or more agents. The agent is deployed into each managed environment and exposes a hardened API back to the server over TLS so that a single Portainer instance can control clusters across different networks and cloud accounts without needing direct Docker socket or kubeconfig access. The server handles authentication (local, LDAP, OAuth, OIDC), role-based access control down to individual resources, and stores its state in BoltDB. For Kubernetes it provides a form-based application editor, live manifest view, Helm chart deployment via the Helm SDK, and GitOps workflows that reconcile stacks from a Git repository."}]},{"type":"paragraph","content":[{"type":"text","text":"Portainer is often deployed on home labs, edge fleets, and small to midsize Docker and K3s environments where kubectl or raw Docker Compose is too friction-heavy for the operators. The Community Edition is Zlib-licensed; the Business Edition is a commercial product that adds features like OpenID RBAC, audit logs, Edge Compute, and support contracts."}]}]}' WHERE `id` = 'portainer';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Porter is a tool for packaging applications together with all the scripts, tools, and credentials they need to deploy, as a single distributable artifact called a bundle. It is the reference implementation of the CNAB (Cloud Native Application Bundle) specification and has been a CNCF sandbox project since 2020."}]},{"type":"paragraph","content":[{"type":"text","text":"A Porter bundle is built from a "},{"type":"text","text":"porter.yaml","marks":[{"type":"code"}]},{"type":"text","text":" that declares parameters, credentials, outputs, and a sequence of install/upgrade/uninstall actions implemented by mixins. Mixins wrap common tools — Helm, Terraform, kubectl, the AWS/Azure/GCP CLIs, Docker, Exec — so that a single bundle can, for example, provision an AWS RDS instance with Terraform, install a Helm chart against it, and then run a database migration with a shell script, all in one atomic operation. The bundle itself is an OCI image that can be pushed to any OCI registry alongside the invocation image that contains the mixins and logic."}]},{"type":"paragraph","content":[{"type":"text","text":"Porter tracks installation state (parameters supplied, outputs produced, last action taken) so that "},{"type":"text","text":"porter upgrade","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"porter uninstall","marks":[{"type":"code"}]},{"type":"text","text":" know exactly what to act on, which gives CNAB-style lifecycle management to stacks that would otherwise be a pile of README steps. It is primarily used by platform teams who need to ship opinionated, cross-tool deployment bundles to internal consumers without forcing them to install and configure the underlying tools themselves."}]}]}' WHERE `id` = 'porter';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PostgreSQL is an open-source object-relational database descended from the POSTGRES project started by Michael Stonebraker at UC Berkeley in 1986. It implements a large subset of the SQL standard, enforces ACID guarantees, and uses multi-version concurrency control (MVCC) so that readers never block writers and writers never block readers."}]},{"type":"paragraph","content":[{"type":"text","text":"Its architecture is a process-per-connection model: a "},{"type":"text","text":"postmaster","marks":[{"type":"code"}]},{"type":"text","text":" supervisor forks a backend for each client, backends coordinate through shared buffers and WAL (write-ahead log), and background workers handle autovacuum, checkpointing, and logical/streaming replication. The WAL is also the foundation for physical replication, point-in-time recovery, and logical decoding that feeds tools like Debezium. The query planner is a cost-based optimizer with support for parallel sequential scans, parallel hash joins, JIT compilation via LLVM, and partitioned tables."}]},{"type":"paragraph","content":[{"type":"text","text":"What sets Postgres apart from most databases is its extensibility: user-defined types, operators, index access methods (B-tree, Hash, GiST, SP-GiST, GIN, BRIN), procedural languages (PL/pgSQL, PL/Python, PL/Perl), and loadable C extensions. That surface enables PostGIS for geospatial, TimescaleDB for time-series, pgvector for embeddings, Citus for sharding, and hundreds more. PostgreSQL backs a large portion of the hosted database market (AWS RDS, Aurora, Google AlloyDB, Azure Database for PostgreSQL, Supabase, Neon, Crunchy Data) and is the default SQL choice for most new application workloads."}]}]}' WHERE `id` = 'postgresql';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Postman is an API development platform that started life as a simple Chrome extension for firing HTTP requests against REST APIs and has since grown into a comprehensive tool covering the full API lifecycle: design, develop, test, mock, document, and monitor. Requests are organized into collections, which can be grouped, versioned, and shared, while environments provide scoped variables for switching between local, staging, and production targets without rewriting URLs, headers, or credentials. The desktop and web apps offer a visual request builder, a scripting sandbox for pre-request and test code, and auto-generated documentation derived from the collections themselves."}]},{"type":"paragraph","content":[{"type":"text","text":"Beyond REST, Postman supports GraphQL with schema introspection and a visual query builder, gRPC with reflection-based service discovery and streaming, WebSocket connections for bidirectional message streams, as well as SOAP and MQTT. Newman, the open-source command-line collection runner, executes the same collections used interactively in CI pipelines such as GitHub Actions, Jenkins, or GitLab CI, which makes it straightforward to turn an exploratory request flow into an automated contract or integration test. Mock servers, monitors, and OpenAPI/AsyncAPI definitions tie the design and runtime sides of an API together inside a single workspace."}]},{"type":"paragraph","content":[{"type":"text","text":"Postman Cloud underpins the collaboration story: workspaces are the unit of sharing, with personal, team, partner, and public scopes. The Public API Network exposes tens of thousands of published collections and APIs from vendors and community authors, making Postman a common distribution channel for vendor-supplied API examples. Pricing is commercial with a free tier covering individual use and small teams; paid plans add team workspaces, governance, single sign-on, and enterprise controls."}]}]}' WHERE `id` = 'postman';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prometheus is a pull-based metrics monitoring system and time-series database originally built at SoundCloud in 2012, inspired by Google''s Borgmon. It was the second project to join the CNCF after Kubernetes and graduated in 2018. It is the de facto standard for metrics collection in Kubernetes environments."}]},{"type":"paragraph","content":[{"type":"text","text":"A Prometheus server scrapes HTTP endpoints at a configurable interval, parses the text-based exposition format (or OpenMetrics), and stores samples in a local TSDB organized into two-hour blocks on disk with a write-ahead log for durability. Each series is uniquely identified by a metric name and a set of key-value labels, which gives the data model its high dimensionality. Targets are discovered dynamically through service discovery for Kubernetes, Consul, EC2, GCE, Azure, DNS, and file-based configs. Instrumented applications expose metrics through client libraries (Go, Java, Python, Rust, etc.), and unmodified systems are covered by exporters like node_exporter, blackbox_exporter, and kube-state-metrics."}]},{"type":"paragraph","content":[{"type":"text","text":"Queries are written in PromQL, a functional language with range vectors, instant vectors, and operators for aggregation, rate calculation, histograms, and joins across label sets. Alerting rules evaluate PromQL expressions and send fired alerts to Alertmanager, which handles grouping, inhibition, silencing, and routing to PagerDuty, OpsGenie, Slack, email, and webhooks. For long-term storage and horizontal scaling, Prometheus exposes a remote_write API consumed by Thanos, Cortex, Mimir, VictoriaMetrics, and M3DB."}]}]}' WHERE `id` = 'prometheus';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PromLens is a PromQL query builder and visual debugger for Prometheus. It was originally built by Julius Volz at PromLabs, then donated by PromLabs and Chronosphere to the Prometheus project and open-sourced under Apache-2.0 in 2022."}]},{"type":"paragraph","content":[{"type":"text","text":"Its distinguishing feature is a tree view of the PromQL AST: as you type a query, PromLens decomposes it into its sub-expressions and evaluates each node independently against a connected Prometheus server, so you can see the intermediate result of every selector, aggregation, and binary operation in one place. Each node can be inspected as a table or graph, making it straightforward to understand why a rate() produces an unexpected value or where a join is dropping series. It also provides metric and label autocompletion backed by the Prometheus metadata API, a \"link to this query\" share feature, and direct integration with Grafana panels via a copy-to-Grafana action."}]},{"type":"paragraph","content":[{"type":"text","text":"PromLens is typically run as a standalone Docker container or static bundle served next to a Prometheus deployment and is a common tool for SREs learning PromQL or reverse-engineering complex alerting rules. Much of its query-construction UX has since been absorbed back into the Prometheus project''s own web UI."}]}]}' WHERE `id` = 'promlens';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Promscale was an observability backend built by Timescale that used PostgreSQL with the TimescaleDB extension as the underlying store for Prometheus metrics and OpenTelemetry traces. It implemented the Prometheus remote_write and remote_read APIs so that a standard Prometheus server could stream samples into a Postgres hypertable, and it provided a PromQL query engine that translated PromQL into SQL against that schema."}]},{"type":"paragraph","content":[{"type":"text","text":"The value proposition was full SQL access to Prometheus data: histograms, exemplars, and labels were all queryable with joins against business tables living in the same Postgres instance, and long-term retention and downsampling were handled by TimescaleDB''s continuous aggregates and compression policies. Promscale also accepted OTLP traces and stored them alongside metrics so that trace-to-metric correlation could be expressed as a SQL join instead of a cross-system link."}]},{"type":"paragraph","content":[{"type":"text","text":"Timescale announced Promscale''s discontinuation in February 2023 and the repository is archived. Teams that evaluated Promscale have generally moved to Mimir, Thanos, VictoriaMetrics, or Cortex for metrics and to Tempo or Jaeger for traces. The project remains useful as a reference for how a SQL database can back a PromQL engine, but it should not be used for new deployments."}]}]}' WHERE `id` = 'promscale';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Promtail is the logging agent purpose-built by Grafana Labs to ship logs from local files into Loki. It tails files on disk, applies a pipeline of parsing and relabelling stages, and pushes batched log streams to a Loki distributor over HTTP, attaching the same kind of label set Loki uses for indexing. Each log line ends up with a small, well-chosen set of labels (job, namespace, pod, container) that match how operators already think about their workloads in Prometheus and Grafana."}]},{"type":"paragraph","content":[{"type":"text","text":"Configuration is service-discovery-driven and deliberately modelled on Prometheus. The same "},{"type":"text","text":"kubernetes_sd_config","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"consul_sd_config","marks":[{"type":"code"}]},{"type":"text","text":", and file-based discovery mechanisms, combined with "},{"type":"text","text":"relabel_configs","marks":[{"type":"code"}]},{"type":"text","text":", are used to decide which files to scrape and what labels to attach, so metrics and logs end up with matching metadata for joins and correlation in Grafana. The most common deployment pattern is a Kubernetes DaemonSet that mounts the node''s "},{"type":"text","text":"/var/log/pods","marks":[{"type":"code"}]},{"type":"text","text":" directory, discovers pods via the Kubernetes API, and forwards every container''s stdout and stderr into Loki, all governed by a single scrape config that mirrors how Prometheus targets the same pods."}]},{"type":"paragraph","content":[{"type":"text","text":"As of February 2025 Grafana has deprecated Promtail and moved it into long-term support, with end of life scheduled for March 2026. Its functionality has been absorbed into Grafana Alloy, the unified OpenTelemetry-based collector that now handles logs, metrics, traces, and profiles in a single agent, and Grafana ships a "},{"type":"text","text":"convert","marks":[{"type":"code"}]},{"type":"text","text":" command that translates Promtail YAML directly into Alloy configuration. Existing Promtail deployments will keep working for now, but new logging pipelines targeting Loki should start with Alloy rather than Promtail."}]}]}' WHERE `id` = 'promtail';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pulumi is an Infrastructure as Code tool that lets you define cloud resources in real programming languages — TypeScript, JavaScript, Python, Go, C#, F#, Java, and YAML — instead of a DSL like HCL. It was founded in 2017 by Joe Duffy and colleagues from Microsoft."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood, a Pulumi program constructs a resource graph by instantiating provider-backed classes. That graph is diffed against a state file during "},{"type":"text","text":"pulumi up","marks":[{"type":"code"}]},{"type":"text","text":", which then calls into provider plugins to create, update, or delete actual cloud resources. Many of Pulumi''s providers are bridged from Terraform providers, so day-one coverage of AWS, Azure, GCP, Kubernetes, and thousands of other services matches Terraform''s, while native providers for AWS, Azure, Google Cloud, and Kubernetes are generated directly from the upstream API specifications for same-day support of new resources. State is stored in a backend — Pulumi Cloud by default, or S3/GCS/Azure Blob/local filesystem."}]},{"type":"paragraph","content":[{"type":"text","text":"Because programs are normal code, Pulumi supports real abstractions (functions, classes, packages on npm/PyPI), unit testing with standard frameworks, and imperative logic like loops and conditionals without templating. Higher-level features include Component Resources for reusable abstractions, Stacks for environment isolation, Pulumi ESC for secrets and configuration, CrossGuard for policy-as-code written in TS/Python, and the Automation API for embedding Pulumi into other programs. It is Apache-2.0 licensed with a commercial SaaS for team state, RBAC, and CI/CD orchestration."}]}]}' WHERE `id` = 'pulumi';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python is a high-level, dynamically typed programming language used for automation, data engineering, machine learning, web services, infrastructure tooling, and command-line applications. It was created by Guido van Rossum in the early 1990s and is now governed through the Python Software Foundation and the Python Enhancement Proposal process."}]},{"type":"paragraph","content":[{"type":"text","text":"The reference implementation, CPython, compiles source code to bytecode and executes it in a virtual machine. The standard library covers networking, file formats, concurrency primitives, packaging metadata, testing, and system integration, while the broader package ecosystem is distributed through PyPI. Common production stacks pair Python with frameworks such as FastAPI, Django, Flask, Celery, SQLAlchemy, and Pydantic."}]},{"type":"paragraph","content":[{"type":"text","text":"In cloud-native systems, Python often appears in control-plane automation, operators, CI/CD glue, analytics jobs, model-serving workflows, and internal platform tools. Its strengths are readable syntax, a large ecosystem, fast iteration, and strong bindings into C, Rust, and native libraries. Its tradeoffs are runtime performance, packaging complexity, and the need to choose the right concurrency model for I/O-heavy or CPU-heavy workloads."}]}]}' WHERE `id` = 'python';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Qovery is an internal developer platform that sits on top of a customer''s own AWS, GCP, Azure, or Scaleway account and provides a Heroku-style experience for deploying applications to Kubernetes. Unlike fully-hosted PaaS offerings, Qovery runs the workloads in the customer''s own VPC on EKS, GKE, AKS, or a self-managed cluster, with Qovery only acting as the control plane."}]},{"type":"paragraph","content":[{"type":"text","text":"The platform is organized around Organizations, Projects, Environments, and Services. Services can be containers, Git-backed applications (built with Buildpacks or Dockerfiles), managed databases (RDS, Cloud SQL, or in-cluster), Helm charts, Terraform modules, lifecycle jobs, or cron jobs. Each Environment is a self-contained namespace with its own ingress, databases, and configuration, which makes ephemeral preview environments per pull request straightforward. Qovery''s engine, written in Rust and open-sourced on GitHub, handles the reconciliation loop: reading desired state from the Qovery API and applying the necessary Terraform, Helm, and Kubernetes operations."}]},{"type":"paragraph","content":[{"type":"text","text":"Qovery integrates with GitHub, GitLab, and Bitbucket for Git-driven deploys, with Datadog/New Relic for observability, and exposes a CLI, Terraform provider, and REST API for automation. Its target audience is engineering teams that have outgrown Heroku/Render but don''t want to build a platform team from scratch on top of raw Kubernetes."}]}]}' WHERE `id` = 'qovery';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Quarkus is a Kubernetes-native Java framework tailored for GraalVM and OpenJDK HotSpot, marketed as \"supersonic, subatomic Java.\" It reimagines the traditional Java application lifecycle by shifting as much work as possible to build time: dependency injection wiring, configuration parsing, ORM metadata, and bytecode generation all happen during compilation rather than at startup. The result is a runtime that boots in tens of milliseconds and runs in a fraction of the memory of a conventional Jakarta EE or Spring stack, making Java a credible target for serverless functions, scale-to-zero workloads, and densely packed Kubernetes deployments."}]},{"type":"paragraph","content":[{"type":"text","text":"The developer experience is built around a long-running dev mode ("},{"type":"text","text":"quarkus:dev","marks":[{"type":"code"}]},{"type":"text","text":") that watches sources, recompiles in the background, and live-reloads the running application on the next HTTP request, with continuous testing and a Dev UI for inspecting beans, configuration, and extensions. The same codebase compiles two ways: a fast JVM-mode JAR for traditional deployments, and a GraalVM native image that produces a standalone executable with near-instant startup and a memory footprint typically in the 20–50 MB range. That AOT path is what makes Quarkus particularly well suited to cold-start-sensitive environments like AWS Lambda, Knative, and KEDA-driven autoscaling."}]},{"type":"paragraph","content":[{"type":"text","text":"Functionality is delivered through a curated extension ecosystem covering CDI (via the ArC container), Hibernate ORM and Panache, RESTEasy Reactive, the MicroProfile specs (Config, Health, OpenAPI, Fault Tolerance), Vert.x, Kafka, gRPC, and integrations for most major datastores and identity providers. Quarkus is led by Red Hat and ships as the foundation of Red Hat build of Quarkus, but the project itself is vendor-neutral Apache-licensed open source with a broad contributor base and governance that welcomes upstream participation independent of any single distributor."}]}]}' WHERE `id` = 'quarkus';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"QuestDB is an open-source column-oriented time-series database written in Java and C++ with a SQL query interface. Data is stored in columnar files partitioned by time, which enables sequential I/O, vectorized execution, and SIMD-accelerated aggregations over large ranges of contiguous samples."}]},{"type":"paragraph","content":[{"type":"text","text":"Tables in QuestDB have a designated timestamp column and are laid out on disk as one file per column per partition (by day, hour, or month). Writes are append-friendly and support out-of-order ingestion through a commit-time merge step, which matters for real-world telemetry where samples arrive late. The ingestion path accepts the InfluxDB Line Protocol over TCP/UDP/HTTP for high-throughput inserts, the PostgreSQL wire protocol for standard clients, and a REST API. Reads use a Postgres-compatible dialect with time-series extensions: "},{"type":"text","text":"SAMPLE BY","marks":[{"type":"code"}]},{"type":"text","text":" for time bucketing, "},{"type":"text","text":"LATEST ON","marks":[{"type":"code"}]},{"type":"text","text":" for last-value-per-series, and "},{"type":"text","text":"ASOF JOIN","marks":[{"type":"code"}]},{"type":"text","text":" for aligning two series by nearest timestamp without exact-match joins."}]},{"type":"paragraph","content":[{"type":"text","text":"QuestDB is commonly deployed for financial tick data, IoT telemetry, infrastructure metrics, and application observability, often as an alternative to InfluxDB, TimescaleDB, or ClickHouse when the workload is dominated by high-cardinality time-ordered writes and point-in-time analytical queries. It is Apache-2.0 licensed, with a Cloud offering for managed deployments and a community edition built as a single Java binary."}]}]}' WHERE `id` = 'questdb';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Quickwit is a distributed search engine for logs, traces, and general event data, written in Rust and built around Tantivy, the inverted-index library that also powers Meilisearch. Its core design decision is decoupling storage from compute: indexes are stored as immutable splits on object storage (S3, GCS, Azure Blob, or local filesystem) and queried by stateless search nodes that can be scaled independently of ingestion."}]},{"type":"paragraph","content":[{"type":"text","text":"Each split is a self-contained Tantivy index with a hotcache that lets Quickwit answer queries by fetching only the relevant byte ranges from object storage, which is what makes running log search directly on S3 affordable. Ingestion happens through a push API, Kafka, Kinesis, Pulsar, or OTLP; a metastore (PostgreSQL or a file-backed store) tracks splits and their metadata. Quickwit implements the Elasticsearch _search API for compatibility with existing clients, the Jaeger gRPC API as a tracing backend, and an OTLP ingest endpoint for OpenTelemetry logs and traces. There is no Lucene or JVM in the path."}]},{"type":"paragraph","content":[{"type":"text","text":"In practice it competes with Elasticsearch, OpenSearch, Loki, and Grafana Tempo. The pitch is sub-second log search at Grafana Loki-style storage cost, without Loki''s label-only query model, and it is commonly paired with Grafana or Jaeger as the query frontend. Quickwit was acquired by Datadog in 2025 but remains Apache-2.0 licensed on GitHub."}]}]}' WHERE `id` = 'quickwit';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Radius is an application platform that lets developers describe a whole distributed application — containers, databases, queues, caches, and the relationships between them — as a single model, and then deploys it across Kubernetes and cloud resources. It was created by Microsoft, open-sourced in 2023, and accepted into the CNCF sandbox in 2024."}]},{"type":"paragraph","content":[{"type":"text","text":"The core abstraction is the Radius Application, written in Bicep (and increasingly Terraform) and composed of Containers, Resources (e.g., "},{"type":"text","text":"Applications.Datastores/mongoDatabases","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Applications.Messaging/rabbitMQQueues","marks":[{"type":"code"}]},{"type":"text","text":"), and typed Connections between them. At deploy time, the Radius control plane resolves each Resource to either an in-cluster implementation via its Recipes system (which runs a Bicep or Terraform module) or to a managed cloud service like Azure Cosmos DB or AWS SQS, and wires credentials and endpoints into the connected containers automatically. This separates the developer''s view of the app from the platform engineer''s view of how each dependency is fulfilled in a given environment."}]},{"type":"paragraph","content":[{"type":"text","text":"Radius runs as a set of controllers on top of Kubernetes and manages state via its own resource provider model borrowed from ARM/Azure. Supported targets include Kubernetes, Azure, and AWS, with extensibility through Recipes so platform teams can define standard implementations of things like \"a Postgres database\" or \"a Redis cache\" once and reuse them across environments. It sits in the same problem space as Crossplane, Score, and KubeVela."}]}]}' WHERE `id` = 'radius';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rancher is a multi-cluster Kubernetes management platform originally built by Rancher Labs and now maintained by SUSE. It provides a single control plane for provisioning, upgrading, and operating Kubernetes clusters across clouds, on-prem, and edge, regardless of whether those clusters are RKE, RKE2, K3s, EKS, AKS, GKE, or any other CNCF-certified distribution."}]},{"type":"paragraph","content":[{"type":"text","text":"A Rancher deployment runs as a set of controllers on a management Kubernetes cluster. Downstream clusters are registered through a lightweight agent that establishes an outbound tunnel to the Rancher server, allowing the management plane to authenticate users via SAML/OIDC/LDAP, impersonate them against the downstream API server, and enforce Rancher-level RBAC that projects onto native Kubernetes RBAC. Rancher ships integrated components for in-cluster monitoring (Prometheus/Grafana), logging (Fluent Bit/Fluentd), GitOps (Fleet), service mesh (Istio), security scanning (CIS benchmarks, Kubewarden), and application catalogs backed by Helm."}]},{"type":"paragraph","content":[{"type":"text","text":"Rancher is frequently paired with SUSE''s own distributions — K3s for edge and single-node deployments, RKE2 for government-grade hardened Kubernetes, and Harvester for HCI and VM workloads via KubeVirt. It is Apache-2.0 licensed and typically chosen by organizations that run fleets of Kubernetes clusters in heterogeneous environments and want a vendor-neutral UI and RBAC layer on top of them."}]}]}' WHERE `id` = 'rancher';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ratify is a verification engine for OCI artifacts and container images. It plugs into Kubernetes admission control and other enforcement points to answer the question \"is this image allowed to run, given the signatures, SBOMs, and vulnerability scans attached to it?\" The project was started by Microsoft and accepted into the CNCF sandbox in 2024."}]},{"type":"paragraph","content":[{"type":"text","text":"Ratify''s architecture is pluggable. Stores know how to fetch artifacts and their referrers from an OCI registry (via the OCI 1.1 Referrers API or fallback ORAS tag schemes). Verifiers validate specific types of referrer: Notary v2 (notation) and Cosign signatures, SPDX/CycloneDX SBOMs, Trivy and Grype vulnerability reports, and arbitrary schema-validation verifiers. A policy provider — either a config-based one or Rego via OPA — combines verifier results into an accept/reject decision. On Kubernetes, Ratify runs as an external data provider for Gatekeeper (or as a Kyverno verifier), so constraints like \"all images in the "},{"type":"text","text":"prod","marks":[{"type":"code"}]},{"type":"text","text":" namespace must be signed by our Notary key and have a Trivy report with no critical CVEs\" are enforced at admission time."}]},{"type":"paragraph","content":[{"type":"text","text":"The project is the reference implementation for supply-chain verification against OCI 1.1-compliant registries and is commonly paired with Cosign, Notation, and Tekton Chains in a secure software supply chain pipeline."}]}]}' WHERE `id` = 'ratify';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Restate is a durable execution engine for building resilient distributed applications. Founded by alumni of the Apache Flink and AWS teams, it provides the same \"write code like it''s local, but every step is persisted and replayable\" model as Temporal, AWS Step Functions, and Cloudflare Durable Objects, but as a single self-contained binary written in Rust."}]},{"type":"paragraph","content":[{"type":"text","text":"The runtime sits in front of stateless service handlers that you write in TypeScript, Java, Kotlin, Go, Python, or Rust. Handlers are invoked via HTTP or Lambda, and each call goes through the Restate server, which records every side effect, RPC, sleep, and state access in a journaled log backed by RocksDB. If a handler crashes mid-execution, Restate replays the journal so that already-completed steps are returned from the log and the function resumes from where it left off with exactly-once semantics. Keyed services provide per-key state and serialized access — effectively virtual actors — for workflows that need to coordinate on a single entity without an external database."}]},{"type":"paragraph","content":[{"type":"text","text":"Restate clusters run as a set of peer nodes that replicate the log using a Raft-like consensus protocol, so there is no separate database or queue to operate: invocations, state, and timers are all stored by Restate itself. Typical use cases include order processing, payment workflows, agentic AI orchestration, saga patterns, and anywhere you would otherwise reach for Temporal. It is released under BUSL-1.1, with each release converting to Apache-2.0 after its change date."}]}]}' WHERE `id` = 'restate';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Robusta is an open-source Kubernetes alerting and troubleshooting toolkit that wraps Prometheus alerts with context, automated diagnostics, and rich notifications. It ships with its own kube-prometheus-stack distribution so that a single Helm install brings up Prometheus, Alertmanager, Grafana, and the Robusta relay in a pre-integrated configuration."}]},{"type":"paragraph","content":[{"type":"text","text":"The core component is a Python-based engine that consumes Alertmanager webhooks and Kubernetes events, then runs playbooks in response. A playbook is a small piece of code that can, for example, fetch pod logs, describe the offending resource, run "},{"type":"text","text":"kubectl top","marks":[{"type":"code"}]},{"type":"text","text":", pull a Java thread dump, generate a flame graph, or compare the current deployment to its previous revision, then attach the result directly to the Slack, Microsoft Teams, PagerDuty, or ServiceNow message. The built-in playbook library covers common Kubernetes failure modes — CrashLoopBackOff, OOMKilled, ImagePullBackOff, failing liveness probes, noisy neighbors — so operators see the root-cause information inline with the alert instead of context-switching to kubectl."}]},{"type":"paragraph","content":[{"type":"text","text":"Robusta also exposes a SaaS UI called Robusta Platform that aggregates data across clusters, provides timelines and change tracking, and in its HolmesGPT component uses an LLM agent to reason over cluster state during incident investigation. The engine itself is MIT licensed on GitHub."}]}]}' WHERE `id` = 'robusta';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rook is a Kubernetes operator that runs Ceph as a cloud-native storage system inside a cluster. It was the first storage project to graduate in the CNCF (2020) and since version 1.3 has focused exclusively on Ceph after earlier support for Cassandra, CockroachDB, and NFS was dropped."}]},{"type":"paragraph","content":[{"type":"text","text":"The operator deploys and manages every Ceph component — monitors (MON), managers (MGR), object storage daemons (OSDs), metadata servers (MDS), and RGW — as Kubernetes pods, with CRDs like "},{"type":"text","text":"CephCluster","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"CephBlockPool","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"CephFilesystem","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"CephObjectStore","marks":[{"type":"code"}]},{"type":"text","text":" describing desired state. OSDs consume raw block devices directly from worker nodes, and Rook takes care of running the CSI drivers ("},{"type":"text","text":"rook-ceph-csi-rbd","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"cephfs","marks":[{"type":"code"}]},{"type":"text","text":") that expose Ceph RBD images and CephFS volumes to standard PersistentVolumeClaims. Day-two operations such as expanding capacity, rolling upgrades, failure domain placement, encryption at rest with LUKS, and orchestrating monitor failover are handled by the operator''s reconcile loop."}]},{"type":"paragraph","content":[{"type":"text","text":"With Rook-Ceph, a single storage backend provides block (RWO), shared file (RWX), and S3-compatible object storage from the same cluster, which is why it remains the go-to choice for self-hosted Kubernetes that needs production-grade persistent storage without depending on a cloud provider. It is Apache-2.0 licensed and typically paired with kernel-level Ceph clients and the native Ceph tooling for debugging."}]}]}' WHERE `id` = 'rook';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"runme turns Markdown files into executable, interactive runbooks. Shell fenced code blocks inside a "},{"type":"text","text":"README.md","marks":[{"type":"code"}]},{"type":"text","text":" or any other Markdown file become runnable cells that you can execute from a CLI, a VS Code extension, or a standalone desktop app, with outputs captured back into the session."}]},{"type":"paragraph","content":[{"type":"text","text":"The project is built around the idea that the documentation developers already write — install steps, local dev loops, deployment commands, on-call runbooks — is executable in principle but broken in practice because copy-pasting into a terminal loses context, order, and environment. runme addresses this by parsing Markdown into a cell-based notebook model and attaching metadata per block through standard code fence attributes: working directory, whether to require confirmation, environment variable propagation, shell to use, whether to stream output, and so on. A single runbook can mix bash, PowerShell, JavaScript, Python, and other interpreters, and variables exported in one cell are available to later cells."}]},{"type":"paragraph","content":[{"type":"text","text":"runme integrates with VS Code as a notebook renderer, ships a CLI ("},{"type":"text","text":"runme run <task>","marks":[{"type":"code"}]},{"type":"text","text":") for CI, and has a cloud component for team runbook sharing and audit. Typical use cases include onboarding guides, incident playbooks, and opinionated \"how to ship this service\" documents that platform teams want to stay in sync with reality. It is Apache-2.0 licensed and written in Go."}]}]}' WHERE `id` = 'runme';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rust is a statically typed, compiled systems programming language that provides memory and thread safety without a garbage collector. It was started at Mozilla by Graydon Hoare in 2006, reached 1.0 in 2015, and is now governed by the Rust Foundation with an open RFC and edition process."}]},{"type":"paragraph","content":[{"type":"text","text":"The defining feature is the ownership and borrow-checker model: every value has a single owner, references are checked at compile time to prevent dangling pointers and data races, and lifetimes encode how long a borrow is valid. The result is C/C++-level runtime performance with the memory-safety guarantees usually associated with managed languages. Rust compiles to native code via LLVM, supports no_std bare-metal targets, and has first-class WebAssembly support through "},{"type":"text","text":"wasm32-unknown-unknown","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"wasm32-wasip1","marks":[{"type":"code"}]},{"type":"text","text":" targets, making it the default choice for writing WASI components and browser-side Wasm modules. The toolchain — "},{"type":"text","text":"rustup","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"cargo","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"rustc","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"clippy","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"rustfmt","marks":[{"type":"code"}]},{"type":"text","text":" — is shipped as a unified stack, and dependencies are managed through crates.io."}]},{"type":"paragraph","content":[{"type":"text","text":"Cloud-native projects written in Rust include the Linkerd2-proxy data plane, Firecracker microVMs, Deno and Bun runtimes, the TiKV distributed KV store, the Databend and Polars analytics engines, InfluxDB 3.0, the Wasmtime and WasmEdge runtimes, and significant parts of the Linux kernel. Rust is dual-licensed under MIT or Apache-2.0."}]}]}' WHERE `id` = 'rust';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Salt (formerly SaltStack) is a Python-based configuration management and remote execution system created by Thomas S. Hatch in 2011. It targets the same space as Ansible, Puppet, and Chef but differs in being designed around a persistent pub/sub bus for low-latency command execution across tens of thousands of nodes."}]},{"type":"paragraph","content":[{"type":"text","text":"A typical Salt deployment has a central "},{"type":"text","text":"salt-master","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"salt-minion","marks":[{"type":"code"}]},{"type":"text","text":" agents on each managed host connected over ZeroMQ (or the newer RAET/TCP transports). Commands issued on the master are published on a bus and executed in parallel by every matching minion, with results streamed back, which makes ad-hoc operations like \"run this command on every web server tagged production\" near-instantaneous. Desired state is expressed in States, written as YAML files rendered through the Jinja templating engine and organized into SLS (SaLt State) formulas. A parallel data layer called Pillar provides per-minion secrets and variables, while Grains expose static facts gathered from each host."}]},{"type":"paragraph","content":[{"type":"text","text":"Beyond agent-based operation, Salt also supports agentless SSH via "},{"type":"text","text":"salt-ssh","marks":[{"type":"code"}]},{"type":"text","text":", cloud provisioning via "},{"type":"text","text":"salt-cloud","marks":[{"type":"code"}]},{"type":"text","text":", and a Reactor system that turns events on the bus into automated responses, which is the basis for its event-driven infrastructure story. Salt is Apache-2.0 licensed and maintained by VMware (now Broadcom) after the 2020 SaltStack acquisition."}]}]}' WHERE `id` = 'salt';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SchemaHero is a Kubernetes operator that manages database schemas declaratively. Instead of shipping a series of ordered up/down migration files, developers describe the desired shape of each table as a Kubernetes custom resource and SchemaHero computes the DDL needed to get the live database there."}]},{"type":"paragraph","content":[{"type":"text","text":"The operator installs two CRDs: "},{"type":"text","text":"Database","marks":[{"type":"code"}]},{"type":"text","text":", which holds connection details to a target PostgreSQL, MySQL, CockroachDB, Cassandra, SQLite, RQLite, or TimescaleDB instance, and "},{"type":"text","text":"Table","marks":[{"type":"code"}]},{"type":"text","text":", which declares the desired columns, types, indexes, and constraints. When a Table is applied, the operator introspects the current schema in the target database, diffs it against the desired state, and generates a "},{"type":"text","text":"Migration","marks":[{"type":"code"}]},{"type":"text","text":" resource containing the planned ALTER/CREATE statements. Migrations are not applied automatically — they sit in a pending state so that a human or GitOps workflow can review the SQL before approving it, which is the primary safety mechanism against destructive changes in production. Once approved, the operator executes the statements and records the result."}]},{"type":"paragraph","content":[{"type":"text","text":"SchemaHero was created at Replicated and accepted into the CNCF sandbox in 2020. It fits naturally into a GitOps pipeline alongside Argo CD or Flux, replacing migration runners like Flyway and Liquibase for teams that want their database schema to live next to their Kubernetes manifests as a first-class declarative resource. It is Apache-2.0 licensed."}]}]}' WHERE `id` = 'schemahero';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Score is an open, platform-agnostic workload specification created by Humanitec and donated to the CNCF (sandbox, 2024). It defines a small YAML schema that describes a workload — its containers, resource requests, and declared dependencies on things like databases, DNS, queues, and volumes — without specifying how any of those dependencies are actually provisioned."}]},{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"score.yaml","marks":[{"type":"code"}]},{"type":"text","text":" file is intentionally the lowest common denominator between local development and production. A developer hands the file to a Score implementation, and that implementation translates it into the target runtime''s native manifests. "},{"type":"text","text":"score-compose","marks":[{"type":"code"}]},{"type":"text","text":" generates a Docker Compose file for local use; "},{"type":"text","text":"score-k8s","marks":[{"type":"code"}]},{"type":"text","text":" generates Kubernetes manifests; "},{"type":"text","text":"score-helm","marks":[{"type":"code"}]},{"type":"text","text":" produces Helm values. Resources referenced in the spec ("},{"type":"text","text":"type: postgres","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"type: s3","marks":[{"type":"code"}]},{"type":"text","text":") are resolved to local stand-ins in dev and to real cloud services in production by the platform team''s chosen implementation, so the same workload definition flows unchanged from laptop to CI to cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"The point of Score is to be the contract between application developers and platform engineers in a platform-engineering setup: developers describe what their service needs, platform teams decide how each resource type is fulfilled per environment. It sits alongside tooling like Humanitec Orchestrator, Crossplane, Radius, and KubeVela, and is explicitly designed to be thin enough to generate into any of them. Score is Apache-2.0 licensed."}]}]}' WHERE `id` = 'score';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SeaweedFS is a distributed file and object store written in Go, inspired by Facebook''s Haystack paper. It is designed to store and serve large numbers of small files efficiently by packing them into append-only volume files and locating them through compact in-memory indexes instead of a traditional inode tree."}]},{"type":"paragraph","content":[{"type":"text","text":"The cluster has three roles. Master servers track volume-to-server mapping and keep the topology. Volume servers store the actual data in fixed-size volumes (typically 30 GB) replicated according to a configurable replication policy across racks or data centers. Filer servers provide a POSIX-like metadata layer backed by a pluggable database (LevelDB, BoltDB, SQLite, MySQL, Postgres, Redis, Cassandra, TiKV, or etcd) so that directories and permissions sit on top of the volume store. On top of that, SeaweedFS exposes an HTTP API for raw blob access, an S3-compatible gateway, WebDAV, FUSE mounts, a HDFS adapter, and a Kubernetes CSI driver."}]},{"type":"paragraph","content":[{"type":"text","text":"Because data is append-only and reads go straight from an in-memory needle map to a byte offset within a volume file, SeaweedFS handles billions of small files with tight latency budgets, which is its differentiator against Ceph, MinIO, and Longhorn. It also supports erasure coding for cold data, tiered storage to S3, and cross-cluster replication. The project is Apache-2.0 licensed."}]}]}' WHERE `id` = 'seaweedfs';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Second State is the company behind WasmEdge, a lightweight, high-performance WebAssembly runtime that is a CNCF sandbox project. WasmEdge is written in C++ and is optimized for server-side and edge use cases rather than the browser, with extensions for networking, database access, KV storage, and AI inference that go beyond the standard WASI specification."}]},{"type":"paragraph","content":[{"type":"text","text":"WasmEdge can run Wasm modules ahead-of-time compiled via LLVM for near-native performance, embed directly into host applications via C, Go, Rust, Java, Python, and JavaScript SDKs, and plug into container runtimes: it integrates with containerd and CRI-O through the "},{"type":"text","text":"crun","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"youki","marks":[{"type":"code"}]},{"type":"text","text":" OCI runtime as a Wasm runtime class, so Kubernetes can schedule Wasm workloads alongside Linux containers through RuntimeClass. Its proprietary extensions include a TLS-capable non-blocking socket API, a rustls/wasmedge_wasi_nn interface for running ONNX, PyTorch, TensorFlow Lite, and llama.cpp models from inside a Wasm module, and bindings for Redis, Postgres, and MySQL."}]},{"type":"paragraph","content":[{"type":"text","text":"Typical workloads include serverless functions, service-mesh data-plane extensions (used in Istio''s proxy-wasm ecosystem), edge inference for LLMs, and SaaS plugin sandboxes. WasmEdge is Apache-2.0 licensed. Second State itself also builds developer tooling and a hosted LLM inference service on top of WasmEdge."}]}]}' WHERE `id` = 'second-state';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Security Profiles Operator (SPO) is a Kubernetes SIG project that manages the lifecycle of seccomp, SELinux, and AppArmor profiles across a cluster. It turns low-level Linux security profiles into Kubernetes-native custom resources that can be distributed to every node and bound to workloads declaratively."}]},{"type":"paragraph","content":[{"type":"text","text":"SPO installs a DaemonSet that syncs profiles onto each node''s local filesystem at the path that kubelet expects, so a "},{"type":"text","text":"SeccompProfile","marks":[{"type":"code"}]},{"type":"text","text":" CR named "},{"type":"text","text":"nginx-restricted","marks":[{"type":"code"}]},{"type":"text","text":" becomes a file under "},{"type":"text","text":"/var/lib/kubelet/seccomp/operator/...","marks":[{"type":"code"}]},{"type":"text","text":" ready to be referenced by pod security context. Similar controllers handle "},{"type":"text","text":"SelinuxProfile","marks":[{"type":"code"}]},{"type":"text","text":" (translating high-level rules into CIL and loading them via selinuxd) and "},{"type":"text","text":"AppArmorProfile","marks":[{"type":"code"}]},{"type":"text","text":". Beyond static distribution, SPO can record profiles at runtime: a "},{"type":"text","text":"ProfileRecording","marks":[{"type":"code"}]},{"type":"text","text":" resource attaches eBPF or oci-hook-based recorders to selected pods, captures every syscall they make, and produces a minimal seccomp profile that represents exactly the workload''s real behavior — effectively automating what was previously a tedious manual audit."}]},{"type":"paragraph","content":[{"type":"text","text":"SPO also exposes a webhook that can bind profiles to workloads via labels and a profile-binding mechanism for enforcing \"every pod in this namespace must use this seccomp profile.\" It is the standard way to deploy fine-grained kernel-level confinement on Kubernetes without maintaining node-level provisioning scripts, and is the project CIS and NSA Kubernetes hardening guides point to for runtime syscall restriction. It is Apache-2.0 licensed under kubernetes-sigs."}]}]}' WHERE `id` = 'security-profiles-operator';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sermant is a proxyless service mesh for Java applications, originally developed by Huawei and donated to the CNCF Sandbox. It uses the JVM''s bytecode instrumentation (Java Agent) API to inject service governance logic directly into running applications, rather than intercepting traffic through a sidecar proxy like Envoy."}]},{"type":"paragraph","content":[{"type":"text","text":"Because the governance code runs inside the same JVM as the application, Sermant avoids the extra network hop and serialization cost that sidecar meshes incur. It ships plugins for common concerns such as traffic routing, tag-based routing, graceful online/offline handling, flow control, and database read/write separation. Plugins are loaded and isolated via a dedicated class loader so application classpaths are unaffected."}]},{"type":"paragraph","content":[{"type":"text","text":"Sermant integrates with existing Java microservice stacks including Spring Cloud and Apache Dubbo, and uses registries like Nacos, ServiceComb, or ZooKeeper for service discovery. It targets brownfield environments where teams want mesh-like governance capabilities without rewriting services or deploying sidecars on every pod."}]}]}' WHERE `id` = 'sermant';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Serverless Devs is an open-source developer tool for building, deploying, and managing serverless applications across multiple cloud providers. Originated by Alibaba and donated to the CNCF Sandbox, it offers a single CLI and YAML-based application model ("},{"type":"text","text":"s.yaml","marks":[{"type":"code"}]},{"type":"text","text":") that abstracts provider-specific details behind reusable components."}]},{"type":"paragraph","content":[{"type":"text","text":"The tool is built around a component model: each component is a versioned package, published to a public registry, that implements operations like "},{"type":"text","text":"deploy","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"remove","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"invoke","marks":[{"type":"code"}]},{"type":"text","text":", or "},{"type":"text","text":"logs","marks":[{"type":"code"}]},{"type":"text","text":" for a given target such as Alibaba Cloud Function Compute, AWS Lambda, Tencent SCF, or Huawei FunctionGraph. An application''s "},{"type":"text","text":"s.yaml","marks":[{"type":"code"}]},{"type":"text","text":" references components with inputs, so the same project description can be deployed through provider-specific implementations."}]},{"type":"paragraph","content":[{"type":"text","text":"Serverless Devs includes a component marketplace, environment/stage support, and plugin hooks for CI pipelines, making it a pragmatic choice for teams operating functions across Chinese and global cloud providers from a unified workflow."}]}]}' WHERE `id` = 'serverless-devs';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Serverless Workflow is a CNCF specification for defining declarative workflows that orchestrate functions, services, and events. Rather than being a single engine, it is a vendor-neutral DSL, expressed in YAML or JSON, that describes states, transitions, event triggers, retries, timeouts, and compensation logic in a portable format."}]},{"type":"paragraph","content":[{"type":"text","text":"The spec models workflows as a finite state machine with state types such as "},{"type":"text","text":"operation","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"event","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"switch","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"parallel","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"foreach","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"callback","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"inject","marks":[{"type":"code"}]},{"type":"text","text":". Data flows between states using JSONPath or jq expressions, and functions can be invoked via REST, gRPC, GraphQL, OpenAPI, AsyncAPI, or CloudEvents. This lets authors express long-running, event-driven business processes without coupling them to a specific runtime."}]},{"type":"paragraph","content":[{"type":"text","text":"Multiple runtimes implement the specification, including SonataFlow (formerly Kogito Serverless Workflow), Synapse, and Automatiko. The goal is the same portability story that OCI brought to container images: a workflow written against the spec can move between compatible engines on Kubernetes, Knative, or hosted FaaS platforms."}]}]}' WHERE `id` = 'serverlessworkflow';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Shipwright is a Kubernetes framework for building container images from source code using pluggable build strategies. It defines a set of CRDs, primarily "},{"type":"text","text":"Build","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"BuildRun","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"BuildStrategy","marks":[{"type":"code"}]},{"type":"text","text":", that let platform teams describe how to turn a Git repository into an OCI image without committing to any single build tool."}]},{"type":"paragraph","content":[{"type":"text","text":"Under the hood, Shipwright compiles a "},{"type":"text","text":"BuildRun","marks":[{"type":"code"}]},{"type":"text","text":" into a Tekton "},{"type":"text","text":"TaskRun","marks":[{"type":"code"}]},{"type":"text","text":" that executes the selected strategy. Out of the box it supports Buildpacks, Kaniko, BuildKit, Buildah, ko, and Source-to-Image, each wrapped as a "},{"type":"text","text":"ClusterBuildStrategy","marks":[{"type":"code"}]},{"type":"text","text":". Because strategies are CRDs themselves, platform engineers can fork, extend, or write new ones, and application developers reference them by name without knowing the underlying tool."}]},{"type":"paragraph","content":[{"type":"text","text":"Shipwright slots into CI/CD systems alongside Tekton Pipelines, Argo CD, and OpenShift Pipelines, and is the upstream project behind OpenShift Builds v2. It is useful for teams that want a consistent, declarative image-building API on Kubernetes while keeping flexibility about which builder runs underneath."}]}]}' WHERE `id` = 'shipwright';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sigstore is a set of services and tools for signing, verifying, and proving the provenance of software artifacts without requiring developers to manage long-lived signing keys. It was started at Red Hat and the Linux Foundation to close the gap that GPG and manual key management left in the software supply chain."}]},{"type":"paragraph","content":[{"type":"text","text":"The system has three core components. Cosign is the CLI that produces and verifies signatures over OCI container images, blobs, and in-toto attestations. Fulcio is a certificate authority that issues short-lived X.509 code-signing certificates bound to an OIDC identity (GitHub Actions, Google, GitLab, etc.), so the signer is a verifiable identity rather than an opaque key. Rekor is an append-only, Merkle-tree transparency log that records every signature so tampering and backdating become detectable."}]},{"type":"paragraph","content":[{"type":"text","text":"Together these enable keyless signing: a CI job authenticates to Fulcio via its workload OIDC token, receives a certificate valid for a few minutes, signs the artifact, and logs the signature to Rekor. Verifiers later check the signature against the certificate chain and the Rekor inclusion proof. Sigstore is used by Kubernetes, the Python Package Index, npm, Homebrew, and Chainguard images, and it underpins SLSA provenance attestations across the CNCF ecosystem."}]}]}' WHERE `id` = 'sigstore';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Skaffold is a command-line tool from Google that automates the build, push, and deploy inner loop for Kubernetes applications. Running "},{"type":"text","text":"skaffold dev","marks":[{"type":"code"}]},{"type":"text","text":" watches a source tree, rebuilds container images on change, pushes them to a registry, and applies the resulting manifests to a target cluster, giving developers a continuous feedback loop without bespoke scripts."}]},{"type":"paragraph","content":[{"type":"text","text":"Its pipeline is defined in "},{"type":"text","text":"skaffold.yaml","marks":[{"type":"code"}]},{"type":"text","text":" and is pluggable at every stage. Builders include Docker, Buildpacks, Bazel, Jib, ko, and Kaniko. Deployers include kubectl, Helm, Kustomize, and kpt. A file sync mode can copy changed files straight into running containers to skip image rebuilds for interpreted languages. Profiles override config per environment, and port-forwarding plus log aggregation stream output from every pod in the session."}]},{"type":"paragraph","content":[{"type":"text","text":"Skaffold is commonly used as the engine behind Cloud Code for VS Code and IntelliJ, and sits alongside Tilt and Garden as one of the standard ways to get a fast local-to-cluster dev loop without locking into a particular build or deploy tool."}]}]}' WHERE `id` = 'skaffold';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Slim Toolkit (formerly DockerSlim) analyzes container images and produces minimized versions that contain only the files a workload actually uses at runtime. Typical results are 10x to 30x smaller images with a drastically reduced attack surface, without requiring the application to be rewritten for a distroless or scratch base."}]},{"type":"paragraph","content":[{"type":"text","text":"The core "},{"type":"text","text":"slim build","marks":[{"type":"code"}]},{"type":"text","text":" command runs the source image, probes the application using HTTP/TCP probes, unit tests, or a user-supplied script, and traces system calls and file access to learn which binaries, libraries, and config files are actually touched. It then generates a new image containing only those artifacts, optionally re-applying seccomp and AppArmor profiles derived from the observed syscalls. Other commands include "},{"type":"text","text":"xray","marks":[{"type":"code"}]},{"type":"text","text":" for static analysis of image layers and "},{"type":"text","text":"lint","marks":[{"type":"code"}]},{"type":"text","text":" for Dockerfile inspection."}]},{"type":"paragraph","content":[{"type":"text","text":"Slim Toolkit is used as a post-build hardening step in CI pipelines where teams want to ship smaller, more secure images from familiar base images like "},{"type":"text","text":"node","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"python","marks":[{"type":"code"}]},{"type":"text","text":", or "},{"type":"text","text":"openjdk","marks":[{"type":"code"}]},{"type":"text","text":" without maintaining custom minimal base images themselves."}]}]}' WHERE `id` = 'slim-toolkit';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SlimFaaS is a lightweight function-as-a-service runtime for Kubernetes, written in .NET and designed to turn any existing container into a scale-to-zero HTTP endpoint with minimal infrastructure. Unlike Knative or OpenFaaS, it does not require a service mesh, an ingress controller, or a CRD-heavy operator install."}]},{"type":"paragraph","content":[{"type":"text","text":"A single SlimFaaS deployment acts as a proxy and scaler in front of user pods. It reads a simple configuration (env vars or ConfigMap) that lists functions, their target deployments, and scale-to-zero timeouts, then uses the Kubernetes API to scale replicas up on incoming requests and back down when idle. It supports synchronous HTTP invocation, a built-in queue for async calls, public/private visibility, and a small web UI for inspecting functions."}]},{"type":"paragraph","content":[{"type":"text","text":"SlimFaaS is aimed at teams that already run Kubernetes and want per-function scale-to-zero for cost-sensitive workloads, internal tooling, or event handlers without pulling in a full serverless platform."}]}]}' WHERE `id` = 'slimfaas';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Snyk is a commercial developer-first security platform that scans source code, open-source dependencies, container images, and infrastructure-as-code for vulnerabilities and license issues. It is built around a proprietary vulnerability database curated by Snyk''s security research team that augments public CVE data with earlier disclosures, exploit maturity, and fix metadata."}]},{"type":"paragraph","content":[{"type":"text","text":"The platform is split into four main products. Snyk Open Source performs software composition analysis across package managers like npm, Maven, pip, Go modules, and NuGet, and can generate automatic fix pull requests that bump to the minimum non-vulnerable version. Snyk Code is a static application security testing engine that uses a semantic, AST-based analysis rather than regex rules. Snyk Container inspects OCI images and recommends base-image upgrades. Snyk IaC scans Terraform, CloudFormation, Kubernetes manifests, and Helm charts against policy."}]},{"type":"paragraph","content":[{"type":"text","text":"Snyk integrates through CLI, IDE plugins (VS Code, JetBrains), Git providers (GitHub, GitLab, Bitbucket), CI systems, and container registries, which is why it is commonly used as the \"shift-left\" security gate in developer workflows alongside Dependabot and Trivy."}]}]}' WHERE `id` = 'snyk';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sonobuoy is a diagnostic tool for Kubernetes clusters that runs conformance and custom test suites inside the cluster and reports back on the results. It is the reference tool used by the CNCF Kubernetes Conformance Program: if a vendor wants to earn the \"Certified Kubernetes\" mark, they must pass the upstream end-to-end tests via Sonobuoy and submit the tarball."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally, "},{"type":"text","text":"sonobuoy run","marks":[{"type":"code"}]},{"type":"text","text":" deploys an aggregator pod and a set of plugin pods into the target cluster. The default plugins execute the upstream Kubernetes e2e conformance tests and the systemd-logs gatherer, but any container that writes results to a known path can be a plugin, so teams can run custom compliance, security, or smoke-test suites the same way. Results are streamed back to the aggregator, bundled into a tarball, and inspectable via "},{"type":"text","text":"sonobuoy results","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Sonobuoy was created at Heptio (now VMware/Broadcom) and is the canonical way to validate that a new or upgraded cluster actually behaves like Kubernetes before handing it to application teams."}]}]}' WHERE `id` = 'sonobuoy';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SOPS (Secrets OPerationS) is a file-level encryption tool for YAML, JSON, ENV, INI, and binary files that lets teams store secrets in Git alongside the rest of their configuration. Originally built at Mozilla and now a CNCF Sandbox project maintained by the getsops community, it solves the awkward problem that generic tools like GPG encrypt the whole file, making diffs useless and merges painful."}]},{"type":"paragraph","content":[{"type":"text","text":"SOPS encrypts only the values in a structured file while leaving keys in plaintext, so diffs still show which field changed without revealing the secret. Each file gets a data key that encrypts the values with AES-256-GCM; that data key is itself wrapped with one or more key management backends, so you can mix and match AWS KMS, GCP KMS, Azure Key Vault, HashiCorp Vault, age, and PGP in the same file. A "},{"type":"text","text":".sops.yaml","marks":[{"type":"code"}]},{"type":"text","text":" creation rule maps file paths to recipients, so committing a new file automatically picks the right keys."}]},{"type":"paragraph","content":[{"type":"text","text":"SOPS is the default secrets story in GitOps workflows built on Flux (which has a dedicated SOPS controller) and is commonly paired with Terraform, Helm, and Kustomize through plugins to decrypt secrets at apply time."}]}]}' WHERE `id` = 'sops';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Spectro Cloud is a commercial vendor focused on Kubernetes lifecycle management at scale. Its flagship product, Palette, is an enterprise platform for provisioning, upgrading, and operating fleets of Kubernetes clusters across public cloud, private cloud, edge, and bare metal, with multi-cluster orchestration built on top of the upstream Cluster API project."}]},{"type":"paragraph","content":[{"type":"text","text":"The platform is organized around a declarative model called Cluster Profiles. A profile defines the full stack of a cluster, including the operating system, Kubernetes distribution, CNI, CSI, and any add-on application services, and is applied uniformly to every cluster derived from it. Palette continuously reconciles running clusters against their profile to prevent configuration drift, and changes such as patches or upgrades to a profile are rolled out to all clusters using it. The same model spans day 0 provisioning through day 2 operations across heterogeneous infrastructure, including managed services like EKS, AKS, and GKE alongside on-prem and edge deployments."}]},{"type":"paragraph","content":[{"type":"text","text":"Spectro Cloud is also the lead sponsor of Kairos, a CNCF Sandbox project that provides an immutable, image-based Linux meta-distribution aimed at edge Kubernetes. Kairos lets operators build bootable OS plus Kubernetes images and roll out atomic A/B upgrades by pushing new container images, and it underpins much of Palette''s edge story while remaining an independent open-source project under CNCF governance."}]}]}' WHERE `id` = 'spectro-cloud';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SpiceDB is an open-source, Google Zanzibar-inspired database for storing and computing permissions data at global scale. Created by AuthZed, it enables developers to build fine-grained authorization systems that can handle millions of permission checks per second while maintaining consistency guarantees."}]},{"type":"paragraph","content":[{"type":"text","text":"SpiceDB provides a foundation for implementing relationship-based access control (ReBAC), attribute-based access control (ABAC), or hybrid authorization models through its expressive schema language and powerful APIs."}]},{"type":"heading","attrs":{"level":2,"id":"architecture-zanzibar-inspired-design"},"content":[{"type":"text","text":"Architecture: Zanzibar-Inspired Design"}]},{"type":"paragraph","content":[{"type":"text","text":"SpiceDB implements the core concepts from Google''s Zanzibar paper, which powers authorization for Google services like Drive, Calendar, and Cloud. The system stores authorization data as relationships (tuples) between objects and subjects, then computes permissions by traversing these relationship graphs."}]},{"type":"paragraph","content":[{"type":"text","text":"The architecture provides:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Relationship Storage:","marks":[{"type":"bold"}]},{"type":"text","text":" Persists tuples like \"user:alice is a member of group:engineering\""}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Permission Computation:","marks":[{"type":"bold"}]},{"type":"text","text":" Evaluates whether a subject can perform an action on a resource"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Consistency Guarantees:","marks":[{"type":"bold"}]},{"type":"text","text":" Protects against the \"New Enemy Problem\" using ZedTokens"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"key-features"},"content":[{"type":"text","text":"Key Features"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Expressive APIs:","marks":[{"type":"bold"}]},{"type":"text","text":" gRPC and HTTP/JSON interfaces for CheckPermission, LookupResources, LookupSubjects, and WriteRelationships operations"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Schema Language:","marks":[{"type":"bold"}]},{"type":"text","text":" An intuitive DSL for defining object types, relations, and permission rules with full CI/CD integration support"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Multi-Paradigm Authorization:","marks":[{"type":"bold"}]},{"type":"text","text":" Combines ReBAC with ABAC through caveated relationships for context-aware permissions"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pluggable Storage:","marks":[{"type":"bold"}]},{"type":"text","text":" Supports PostgreSQL, MySQL, CockroachDB, Google Cloud Spanner, and in-memory backends"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deep Observability:","marks":[{"type":"bold"}]},{"type":"text","text":" Built-in Prometheus metrics, structured logging, OpenTelemetry tracing, and pprof profiling"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Global Consistency:","marks":[{"type":"bold"}]},{"type":"text","text":" Configurable per-request consistency balancing correctness and latency"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"performance-at-scale"},"content":[{"type":"text","text":"Performance at Scale"}]},{"type":"paragraph","content":[{"type":"text","text":"SpiceDB is designed for production workloads at scale:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"5ms p95 latency","marks":[{"type":"bold"}]},{"type":"text","text":" for permission checks"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Millions of queries per second","marks":[{"type":"bold"}]},{"type":"text","text":" throughput"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Billions of relationships","marks":[{"type":"bold"}]},{"type":"text","text":" storage capacity"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Used in production by organizations including GitHub, Adobe, Google, Fastly, Plaid, Red Hat, and Reddit"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"getting-started"},"content":[{"type":"text","text":"Getting Started"}]},{"type":"paragraph","content":[{"type":"text","text":"Define your authorization schema:"}]},{"type":"codeBlock","attrs":{"language":"zed","title":null,"meta":null},"content":[{"type":"text","text":"definition user {}\n\ndefinition document {\n    relation owner: user\n    relation editor: user\n    relation viewer: user\n\n    permission edit = owner + editor\n    permission view = edit + viewer\n}"}]},{"type":"paragraph","content":[{"type":"text","text":"Write relationships and check permissions using the API:"}]},{"type":"codeBlock","attrs":{"language":"bash","title":null,"meta":null},"content":[{"type":"text","text":"# Write a relationship\nzed relationship create document:readme owner user:alice\n\n# Check permission\nzed permission check document:readme edit user:alice"}]},{"type":"heading","attrs":{"level":2,"id":"common-use-cases"},"content":[{"type":"text","text":"Common Use Cases"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Multi-tenant SaaS applications:","marks":[{"type":"bold"}]},{"type":"text","text":" Implement organization-based access control with teams, roles, and resource hierarchies"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Document collaboration:","marks":[{"type":"bold"}]},{"type":"text","text":" Model complex sharing rules like \"editors can share with viewers\""}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Microservices authorization:","marks":[{"type":"bold"}]},{"type":"text","text":" Centralize permission decisions across distributed services"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enterprise compliance:","marks":[{"type":"bold"}]},{"type":"text","text":" Audit permission changes and answer \"who has access to what\" queries"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"IoT and device management:","marks":[{"type":"bold"}]},{"type":"text","text":" Control access to devices, fleets, and telemetry data"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"best-practices-for-production"},"content":[{"type":"text","text":"Best Practices for Production"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use ZedTokens:","marks":[{"type":"bold"}]},{"type":"text","text":" Always pass ZedTokens from write operations to subsequent reads to ensure consistency"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Design schemas carefully:","marks":[{"type":"bold"}]},{"type":"text","text":" Model your domain''s natural relationships rather than forcing RBAC patterns"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Leverage caveats:","marks":[{"type":"bold"}]},{"type":"text","text":" Use caveated relationships for time-based, attribute-based, or context-aware permissions"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Monitor performance:","marks":[{"type":"bold"}]},{"type":"text","text":" Set up dashboards for latency percentiles, cache hit rates, and dispatch counts"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Test with zed CLI:","marks":[{"type":"bold"}]},{"type":"text","text":" Use the playground and test assertions to validate schema changes before deployment"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"ecosystem-and-tools"},"content":[{"type":"text","text":"Ecosystem and Tools"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"zed CLI:","marks":[{"type":"bold"}]},{"type":"text","text":" Command-line tool for schema management, relationship operations, and testing"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Playground:","marks":[{"type":"bold"}]},{"type":"text","text":" Web-based environment for experimenting with schemas and permissions"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Client Libraries:","marks":[{"type":"bold"}]},{"type":"text","text":" Official SDKs for Go, Python, Java, Ruby, Node.js, and more"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"AuthZed Cloud:","marks":[{"type":"bold"}]},{"type":"text","text":" Managed SpiceDB service with additional enterprise features"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SpiceDB Operator:","marks":[{"type":"bold"}]},{"type":"text","text":" Kubernetes operator for deploying and managing SpiceDB clusters"}]}]}]}]}' WHERE `id` = 'spicedb';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Spiderpool is an IP Address Management (IPAM) plugin for Kubernetes focused on underlay and RDMA networking scenarios, particularly where pods need to attach directly to a physical network via Macvlan, SR-IOV, or IPvlan. It is a CNCF Sandbox project originated at DaoCloud."}]},{"type":"paragraph","content":[{"type":"text","text":"Most CNIs (Calico, Cilium, Flannel) manage IPs as part of an overlay model, but underlay networks that share a LAN with the host require coordinated, non-conflicting address allocation, gateway detection, stale-lease cleanup, and sometimes affinity to specific nodes or namespaces. Spiderpool provides these via CRDs such as "},{"type":"text","text":"SpiderIPPool","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"SpiderSubnet","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"SpiderReservedIP","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"SpiderMultusConfig","marks":[{"type":"code"}]},{"type":"text","text":", with garbage collection that reconciles leases against actual pod state to avoid IP leakage during crashes."}]},{"type":"paragraph","content":[{"type":"text","text":"Spiderpool is typically deployed alongside Multus CNI so pods can attach to multiple networks, and it integrates with Macvlan, SR-IOV, Cilium, Calico, and Weave. Its main audience is operators running Kubernetes on bare metal or for telco/AI workloads where high-performance underlay and RDMA networks are required."}]}]}' WHERE `id` = 'spiderpool';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SPIFFE (Secure Production Identity Framework For Everyone) is a CNCF-graduated specification that defines how workloads can be given a cryptographic identity independent of network location, shared secrets, or bearer tokens. The goal is to replace IP allowlists, API keys, and long-lived certificates with short-lived, automatically rotated identities that work the same across VMs, containers, Kubernetes pods, and serverless functions."}]},{"type":"paragraph","content":[{"type":"text","text":"The spec has three main concepts. A SPIFFE ID is a URI of the form "},{"type":"text","text":"spiffe://trust-domain/workload/path","marks":[{"type":"code"}]},{"type":"text","text":" that names a workload. An SVID (SPIFFE Verifiable Identity Document) is the cryptographic credential that proves that identity, issued as either an X.509 certificate with the SPIFFE ID in the SAN or a signed JWT. The Workload API is a local, unauthenticated gRPC endpoint that workloads call to fetch their current SVID and trust bundle; the implementation attests the caller (by process, K8s pod, AWS instance metadata, etc.) before issuing credentials, so no secret ever needs to be provisioned into the workload."}]},{"type":"paragraph","content":[{"type":"text","text":"SPIFFE is the identity foundation under Istio, Consul, Kuma, Cilium, and many zero-trust networking stacks, and SPIRE is its reference implementation."}]}]}' WHERE `id` = 'spiffe';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Spin is an open-source framework from Fermyon for building and running event-driven microservices as WebAssembly components. Applications are compiled to the WebAssembly Component Model and run on top of Wasmtime, giving sub-millisecond cold starts and sandbox-level isolation without the overhead of a container runtime."}]},{"type":"paragraph","content":[{"type":"text","text":"A Spin application is described by a "},{"type":"text","text":"spin.toml","marks":[{"type":"code"}]},{"type":"text","text":" manifest that declares one or more components and the triggers they respond to: HTTP requests, Redis pub/sub messages, cron schedules, or custom plugin triggers. Each component is a "},{"type":"text","text":".wasm","marks":[{"type":"code"}]},{"type":"text","text":" module compiled from Rust, Go (via TinyGo), JavaScript/TypeScript, Python, .NET, or any other language with Wasm support. Spin exposes capability APIs through WASI and WIT interfaces for key-value storage, SQLite, outbound HTTP, LLM inference, and relational databases, so components stay portable while still reaching real services."}]},{"type":"paragraph","content":[{"type":"text","text":"Spin applications are packaged as OCI artifacts and can be run locally with "},{"type":"text","text":"spin up","marks":[{"type":"code"}]},{"type":"text","text":", deployed to Fermyon Cloud, or scheduled on Kubernetes via SpinKube. The project is now a CNCF Sandbox project and is one of the primary reference runtimes for the WebAssembly Component Model in production."}]}]}' WHERE `id` = 'spin';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SpinKube is an open-source project for running Spin (WebAssembly) applications natively on Kubernetes. Instead of wrapping each Wasm module in a container, it registers Wasm as a first-class workload type so the kubelet runs components directly on a Wasm runtime, cutting resource use and startup latency dramatically compared to container-based serverless stacks."}]},{"type":"paragraph","content":[{"type":"text","text":"The stack has four main pieces. "},{"type":"text","text":"containerd-shim-spin","marks":[{"type":"code"}]},{"type":"text","text":" is a containerd shim that executes Spin apps on Wasmtime when a pod''s runtime class targets it. The Spin Operator provides a "},{"type":"text","text":"SpinApp","marks":[{"type":"code"}]},{"type":"text","text":" CRD so users can declare a Spin application as a Kubernetes resource. Runtime Class Manager (formerly KWasm) installs and configures the shim on each node. The Spin Plugin for kube streamlines building and deploying apps from a Spin project. Spin apps are distributed as OCI artifacts, so existing registries and image-signing workflows apply unchanged."}]},{"type":"paragraph","content":[{"type":"text","text":"SpinKube was contributed by Fermyon, Microsoft, SUSE, and LiquidReply, and is a CNCF Sandbox project. It is useful for teams that want the density and cold-start profile of Wasm without abandoning Kubernetes as their control plane."}]}]}' WHERE `id` = 'spinkube';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SPIRE (the SPIFFE Runtime Environment) is the reference implementation of the SPIFFE specification. It issues short-lived X.509 or JWT SVIDs to workloads after cryptographically attesting their identity, and automatically rotates them before expiry so applications never deal with long-lived credentials."}]},{"type":"paragraph","content":[{"type":"text","text":"SPIRE splits responsibilities between a central Server and per-node Agents. The Server runs its own certificate authority (or federates with an external one via upstream signing), stores registration entries that map attestation selectors to SPIFFE IDs, and signs SVIDs. Each node runs an Agent that attests itself to the Server (using a plugin for EC2, GCP, Azure, Kubernetes PSAT, TPM, etc.) and then exposes a local Unix-domain Workload API. When a process connects, the Agent attests it through workload attestors (Unix, Docker, Kubernetes), looks up matching registration entries, and hands back the correct SVID without ever placing a secret on disk."}]},{"type":"paragraph","content":[{"type":"text","text":"SPIRE supports federation between trust domains, nested topologies for multi-cluster deployments, and pluggable datastores (SQL, etcd). It is the identity plane under production Istio, Consul, and Kuma deployments, and is used directly by organizations like Bloomberg, Uber, Pinterest, and ByteDance to eliminate shared secrets between services."}]}]}' WHERE `id` = 'spire';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Spring is the dominant application framework for the Java ecosystem, built around the original Spring Framework that introduced dependency injection (DI) and aspect-oriented programming (AOP) to enterprise Java as a lighter alternative to the J2EE container model. The framework provides a comprehensive programming and configuration model for modern Java applications, focusing on the plumbing of enterprise systems, including transactions, data access, messaging, and web request handling, so application teams can concentrate on business logic. Spring Boot layers an opinionated convention-over-configuration experience on top, with auto-configuration, embedded servers, production-ready actuators, and a catalog of starter dependencies that turn a single Maven or Gradle coordinate into a runnable, batteries-included service."}]},{"type":"paragraph","content":[{"type":"text","text":"The Spring portfolio extends well beyond the core: Spring Data abstracts relational and non-relational stores, Spring Security handles authentication and authorization, Spring Batch covers large-scale job processing, and Spring Cloud provides the building blocks for distributed systems including service discovery, configuration servers, circuit breakers, and gateway routing. For cloud-native deployments, Spring Boot 3 absorbed the work pioneered by the Spring Native project and now ships first-class ahead-of-time (AOT) compilation support that produces GraalVM native images with sub-second startup and dramatically lower memory footprints, making Spring services competitive with Go and Node.js on Kubernetes for cold-start-sensitive and FaaS workloads."}]},{"type":"paragraph","content":[{"type":"text","text":"Spring originated as an open-source project from Rod Johnson''s 2002 book before commercial stewardship passed through SpringSource, VMware''s Pivotal subsidiary, and the rebranded VMware Tanzu, finally landing inside Broadcom after the 2023 VMware acquisition. Despite that corporate journey, the code remains Apache-2.0 licensed at github.com/spring-projects with a large independent contributor base, and Spring Boot is the default Java runtime for an enormous fraction of containerised microservices, which is why it shows up so often in Kubernetes deployment discussions and platform tooling demos."}]}]}' WHERE `id` = 'spring';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Stacker is a tool for building OCI container images from a declarative YAML file, without requiring a Docker daemon or root privileges. It was originally developed at Cisco for building minimal, reproducible images for network operating systems and is now a CNCF Sandbox project."}]},{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"stacker.yaml","marks":[{"type":"code"}]},{"type":"text","text":" describes a set of layers, each with a base image, build commands, imports (files or tarballs pulled into the build), and runtime config. Stacker executes the build inside an unprivileged user namespace using LXC, so builds work on shared CI runners where Docker-in-Docker is not an option. Layers are content-addressed and cached, and the tool can directly emit OCI images into an OCI layout, push them to a registry, or produce SquashFS-backed images suitable for immutable appliances."}]},{"type":"paragraph","content":[{"type":"text","text":"Stacker is differentiated by its focus on reproducibility, offline/air-gapped workflows, and integration with the OCI image spec and zot registry rather than Docker tooling. It is typically chosen by teams shipping embedded systems, network OS images, or strict supply-chain environments where daemonless and rootless builds matter."}]}]}' WHERE `id` = 'stacker';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Strimzi is a Kubernetes operator for running Apache Kafka. It turns every moving part of a Kafka deployment, brokers, controllers, topics, users, connectors, and mirror pipelines, into Kubernetes custom resources, so operators can "},{"type":"text","text":"kubectl apply","marks":[{"type":"code"}]},{"type":"text","text":" a cluster rather than shepherd JVMs and ZooKeeper ensembles by hand."}]},{"type":"paragraph","content":[{"type":"text","text":"The project ships several CRDs and controllers. "},{"type":"text","text":"Kafka","marks":[{"type":"code"}]},{"type":"text","text":" describes a cluster and its listeners, storage, authentication, and authorization; the Cluster Operator then creates StatefulSets, Services, and ConfigMaps to match. "},{"type":"text","text":"KafkaTopic","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"KafkaUser","marks":[{"type":"code"}]},{"type":"text","text":" are reconciled by dedicated Entity Operators that drive changes into Kafka via its admin API. "},{"type":"text","text":"KafkaConnect","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"KafkaConnector","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"KafkaMirrorMaker2","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"KafkaBridge","marks":[{"type":"code"}]},{"type":"text","text":" cover connect pipelines, cross-cluster replication, and HTTP access. Strimzi supports both classic ZooKeeper mode and KRaft mode and handles rolling upgrades, rebalancing via Cruise Control, TLS cert rotation, and OAuth integration."}]},{"type":"paragraph","content":[{"type":"text","text":"Strimzi is a CNCF Incubating project originated by Red Hat and is the upstream for Red Hat''s AMQ Streams and OpenShift Streams for Apache Kafka. It is the dominant way to run self-managed Kafka on Kubernetes."}]}]}' WHERE `id` = 'strimzi';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Submariner provides flat Layer 3 connectivity and cross-cluster service discovery between Kubernetes clusters, including clusters that live in different clouds, VPCs, or on-premises networks with overlapping or non-overlapping CIDRs. It lets a pod in cluster A reach a service in cluster B by its DNS name, as if they were in the same cluster."}]},{"type":"paragraph","content":[{"type":"text","text":"Architecturally, Submariner elects a Gateway node in each participating cluster that terminates an encrypted tunnel (IPsec via Libreswan or WireGuard) to the other clusters'' gateways. A Route Agent on every node programs the data path so pod and service traffic destined for remote CIDRs is routed through the local gateway. The Broker is a lightweight coordination point (itself a Kubernetes cluster) that shares endpoint and service information across members. Lighthouse extends CoreDNS with the "},{"type":"text","text":"clusterset.local","marks":[{"type":"code"}]},{"type":"text","text":" domain defined by the Kubernetes multi-cluster services API so services can be exported and consumed by name. Globalnet handles the overlapping-CIDR case by NATing traffic through a virtual global CIDR."}]},{"type":"paragraph","content":[{"type":"text","text":"Submariner is a CNCF Sandbox project originated at Rancher/SUSE and is commonly used for hybrid-cloud failover, regulated multi-region deployments, and federating clusters managed by Red Hat Advanced Cluster Management."}]}]}' WHERE `id` = 'submariner';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Suborbital was a WebAssembly-based platform for embedding third-party extensions and plugins inside SaaS applications, best known for its E2Core runtime and the Atmo/Reactr/Sat framework for building Wasm-backed microservices. It let product teams expose extension points where customers could upload their own Wasm modules, written in Rust, Go, or JavaScript, and have them run safely inside the host application."}]},{"type":"paragraph","content":[{"type":"text","text":"The core building block was Reactr, a Go library that embedded Wasmer/Wasmtime and provided a scheduler and capability API so Wasm modules could do controlled HTTP calls, logging, and cache access without breaking the sandbox. E2Core extended that into a full server that ran functions behind HTTP routes, and Subo was the developer CLI for scaffolding and building modules. The design targeted \"plugin systems for SaaS\" rather than general-purpose FaaS."}]},{"type":"paragraph","content":[{"type":"text","text":"Reactr is now explicitly deprecated, but the Suborbital repositories remain available on GitHub, so the codebase is still a useful reference implementation for embedding WebAssembly as an extensibility surface in Go applications."}]}]}' WHERE `id` = 'suborbital';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sveltos is a Kubernetes add-on controller for deploying and managing resources, Helm charts, and Kustomize overlays across a fleet of workload clusters from a single management cluster. It sits one level above tools like Argo CD and Flux by treating \"where to deploy\" as a first-class selector problem rather than a per-cluster configuration step."}]},{"type":"paragraph","content":[{"type":"text","text":"A user creates a "},{"type":"text","text":"ClusterProfile","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Profile","marks":[{"type":"code"}]},{"type":"text","text":" that lists the Helm charts, raw manifests, Kustomize references, or Carvel packages to install, plus a label selector that matches target clusters. Sveltos then reconciles the selected add-ons onto any cluster whose labels match, continuously, so new clusters that join the fleet inherit the right add-ons automatically and clusters that drift get repaired. It supports templating based on the target cluster''s metadata, cross-cluster event-driven deployment (deploy to cluster B when something happens in cluster A), drift detection, and techniques like rolling upgrades across clusters."}]},{"type":"paragraph","content":[{"type":"text","text":"Sveltos integrates with Cluster API for provisioning, uses Sveltos Agent on each workload cluster as the enforcement point, and is commonly paired with Rancher, EKS Anywhere, or Cluster API-based fleet management where per-cluster GitOps repositories become unmanageable."}]}]}' WHERE `id` = 'sveltos';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Swamp is a framework for building with AI from repeatable behaviours rather than token-heavy agent loops. It works alongside an existing coding agent such as Claude Code or Codex, teaching it how to reach into your systems through typed TypeScript extensions that it can call as tools."}]},{"type":"paragraph","content":[{"type":"text","text":"Extensions from the Swamp Club registry connect to cloud providers, databases, observability tools and SaaS APIs, and Swamp writes new ones when nothing fits. Behaviours compose into workflows that run on a schedule or from webhooks via "},{"type":"text","text":"swamp serve","marks":[{"type":"code"}]},{"type":"text","text":", results are captured as versioned, queryable data, and vaults such as 1Password inject credentials just in time without exposing them to the model."}]}]}' WHERE `id` = 'swamp';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Syft is an open-source CLI and Go library from Anchore that generates Software Bill of Materials (SBOMs) for container images and filesystems. Given an image reference, a Docker archive, an OCI layout, or a directory, it catalogs every installed package it can recognize and emits an SBOM in SPDX, CycloneDX, or Syft''s own JSON format."}]},{"type":"paragraph","content":[{"type":"text","text":"Detection is catalog-driven: Syft ships cataloguers for OS packages (dpkg, rpm, apk, Alpine, Wolfi), and language ecosystems including Go modules and binaries, Java JARs and WARs, Python wheels and egg-info, Node.js "},{"type":"text","text":"package.json","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"package-lock.json","marks":[{"type":"code"}]},{"type":"text","text":", Ruby gems, Rust Cargo lockfiles, PHP Composer, Dart pub, Dotnet, Elixir, and more. Each cataloguer walks the target''s filesystem with a pluggable source abstraction, so Syft can run against a running container, a remote image, or an SBOM-generating build step without needing a daemon."}]},{"type":"paragraph","content":[{"type":"text","text":"Syft is the canonical upstream for SBOM generation in the Sigstore/SLSA supply-chain toolchain and is commonly paired with Grype (for CVE scanning of the resulting SBOM) and Cosign (to attach and sign the SBOM as an in-toto attestation on the image)."}]}]}' WHERE `id` = 'syft';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sympozium is a Kubernetes-native coordination layer for multi-agent AI systems. It models agents as pods and uses Kubernetes primitives such as CRDs and jobs to coordinate structured handoffs, shared context, and agent workflow execution."}]},{"type":"paragraph","content":[{"type":"text","text":"The project is aimed at teams building agent systems that need shared situational awareness rather than isolated prompt execution."}]}]}' WHERE `id` = 'sympozium';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Initiative was an infrastructure automation platform built by Adam Jacob (co-founder of Chef) that replaced declarative IaC files and plan/apply cycles with a live, collaborative graph of infrastructure components. Instead of writing HCL or YAML and running a planner, engineers worked in a visual canvas where each asset was a \"component\" backed by a programmable model."}]},{"type":"paragraph","content":[{"type":"text","text":"Each component had attributes, qualification functions (checks that ran as the model changed), code-generation functions that produced provider payloads, and action functions that called out to real APIs. The system continuously re-evaluated the graph as users dragged, connected, or edited components, so validation and generated cloud payloads updated in real time. Changes were staged in change sets that multiple users could collaborate on simultaneously, with conflict resolution built into the model, before being applied to the real world. Asset definitions (for AWS, Docker, Kubernetes, and so on) were themselves components that could be forked and customized inside the tool."}]},{"type":"paragraph","content":[{"type":"text","text":"System Initiative open-sourced its platform in 2024 under the Apache-2.0 license, but archived the public repository in February 2026 and is no longer maintaining it. It remains a historical reference for teams exploring alternatives to text-file IaC, long plan cycles, and brittle module abstractions."}]}]}' WHERE `id` = 'system-initiative';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tekton is a Kubernetes-native CI/CD framework that models pipelines entirely as Kubernetes custom resources. Every unit of work is a pod, every pipeline is a CRD, and there is no long-running build server to operate: the Kubernetes control plane is the scheduler and state store."}]},{"type":"paragraph","content":[{"type":"text","text":"The core primitives are "},{"type":"text","text":"Step","marks":[{"type":"code"}]},{"type":"text","text":" (a container), "},{"type":"text","text":"Task","marks":[{"type":"code"}]},{"type":"text","text":" (an ordered list of Steps that run in a single pod sharing a workspace), "},{"type":"text","text":"Pipeline","marks":[{"type":"code"}]},{"type":"text","text":" (a DAG of Tasks with parameter passing and results), and the "},{"type":"text","text":"TaskRun","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"PipelineRun","marks":[{"type":"code"}]},{"type":"text","text":" resources that represent a single execution. Workspaces abstract over persistent volumes, ConfigMaps, or secrets so Tasks can share files without baking volume assumptions into their definitions. Tekton Triggers turns webhook payloads into PipelineRuns, Tekton Chains signs artifacts and produces in-toto/SLSA provenance using Sigstore, Tekton Results archives completed runs, and Tekton Hub and the Tekton Catalog distribute reusable Tasks."}]},{"type":"paragraph","content":[{"type":"text","text":"Tekton began at Google as a fork of the Knative build project and is now a CDF (Continuous Delivery Foundation) project. It is the engine underneath Jenkins X, OpenShift Pipelines, and Google Cloud Build''s second-generation offering."}]}]}' WHERE `id` = 'tektoncd';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Telegraf is an open-source, plugin-driven agent from InfluxData for collecting, processing, and forwarding metrics, events, and logs. It ships as a single Go binary with no runtime dependencies and is commonly used as the scraping and shipping layer in front of a time-series database."}]},{"type":"paragraph","content":[{"type":"text","text":"Its architecture is organized around four kinds of plugins declared in a TOML config. Input plugins gather data: system stats, SNMP, Kafka, Kubernetes, MySQL, PostgreSQL, Prometheus endpoints, cloud provider APIs, and hundreds more. Processor plugins enrich, filter, rename, or tag points in flight. Aggregator plugins compute rolling statistics like min/max/percentiles. Output plugins write the results to destinations such as InfluxDB, Prometheus remote write, Kafka, Elasticsearch, CloudWatch, Datadog, or files. Telegraf speaks InfluxDB Line Protocol natively but supports JSON, CSV, Prometheus, OpenTelemetry, and many other formats."}]},{"type":"paragraph","content":[{"type":"text","text":"Because a single agent can ingest from many sources and fan out to many sinks, Telegraf is frequently used as a vendor-neutral metrics collector in hybrid environments, a protocol translator in front of Prometheus or OTLP pipelines, and the default on-host agent for InfluxDB and Grafana Cloud deployments."}]}]}' WHERE `id` = 'telegraf';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Teleport is an identity-aware access proxy that provides unified, short-lived certificate-based access to infrastructure: SSH servers, Kubernetes clusters, databases, internal web applications, Windows desktops, and cloud provider APIs. It replaces the sprawl of static SSH keys, bastion hosts, VPNs, and per-tool credentials with a single control plane that knows who you are and what you''re allowed to touch."}]},{"type":"paragraph","content":[{"type":"text","text":"A Teleport cluster consists of an Auth Service (a certificate authority and policy engine), a Proxy Service (the user-facing entry point that terminates TLS and brokers connections), and Agents that run next to the resources being protected and register themselves with the cluster. Users authenticate via SSO (SAML, OIDC, GitHub) and optional hardware MFA, and the Auth Service issues short-lived X.509 and SSH certificates scoped by role. Every session is recorded and audit-logged; interactive SSH and kubectl sessions can be replayed afterward. Features like Access Requests, Session Moderation, and Device Trust layer zero-trust controls on top of that baseline."}]},{"type":"paragraph","content":[{"type":"text","text":"Teleport is used as a common access layer across clouds and on-prem, and integrates with Kubernetes RBAC, AWS IAM, and existing IdPs so permissions remain grounded in the upstream identity provider rather than in Teleport-specific users."}]}]}' WHERE `id` = 'teleport';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Telepresence lets developers run a single service locally while it behaves as if it were running inside a remote Kubernetes cluster, so they can iterate on code with their normal IDE and debugger instead of building a container, pushing to a registry, and waiting for a rollout on every change."}]},{"type":"paragraph","content":[{"type":"text","text":"When you "},{"type":"text","text":"telepresence connect","marks":[{"type":"code"}]},{"type":"text","text":", the CLI installs a Traffic Manager in the cluster and establishes an encrypted tunnel from the workstation. DNS lookups for cluster services resolve locally, outbound requests from the local process are routed through the cluster so it can reach databases, queues, and other services by their in-cluster names, and environment variables and mounted volumes from the target pod are proxied to the local process. "},{"type":"text","text":"telepresence intercept","marks":[{"type":"code"}]},{"type":"text","text":" then tells the Traffic Manager to redirect some or all of a target service''s traffic (optionally filtered by HTTP headers for per-developer intercepts) to the local instance, so the developer''s code becomes a live participant in the real cluster without disrupting other users."}]},{"type":"paragraph","content":[{"type":"text","text":"Telepresence is a CNCF project originally built at Ambassador Labs. It is commonly used by teams whose microservice topology is too large or resource-hungry to run locally, as an alternative to Skaffold/Tilt-style rebuild loops for services with slow startup or heavy integration dependencies."}]}]}' WHERE `id` = 'telepresence';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Terraform is HashiCorp''s infrastructure-as-code tool for declaratively provisioning and managing resources across cloud providers, SaaS, and on-prem systems. Users write configuration in HCL (HashiCorp Configuration Language), Terraform computes the difference between that configuration and a recorded state file, and then calls provider APIs to reconcile the real world with the declared intent."}]},{"type":"paragraph","content":[{"type":"text","text":"Its extensibility comes from providers: separate binaries that expose typed resources and data sources for AWS, Azure, Google Cloud, Kubernetes, GitHub, Cloudflare, Datadog, and thousands of other systems published on the Terraform Registry. The core engine builds a dependency graph from resource references, runs "},{"type":"text","text":"plan","marks":[{"type":"code"}]},{"type":"text","text":" to produce a reviewable diff, then "},{"type":"text","text":"apply","marks":[{"type":"code"}]},{"type":"text","text":" to execute it in the right order. State can live locally or in a remote backend (S3, GCS, Terraform Cloud, HTTP) with locking to prevent concurrent writes; modules package reusable configuration, and workspaces model multiple environments against the same code."}]},{"type":"paragraph","content":[{"type":"text","text":"HashiCorp relicensed Terraform from MPL-2.0 to the Business Source License (BUSL-1.1) in 2023, which triggered the OpenTofu fork now governed by the Linux Foundation. Both share the provider ecosystem and HCL language, and Terraform remains the de facto standard for cloud provisioning alongside Pulumi, Crossplane, and AWS CDK."}]}]}' WHERE `id` = 'terraform';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tetragon is an eBPF-based security observability and runtime enforcement tool, part of the Cilium project at Isovalent and the CNCF. It instruments the Linux kernel directly to observe process execution, file access, network activity, and capability changes, and can synchronously kill or block offending processes from within the kernel before the syscall returns."}]},{"type":"paragraph","content":[{"type":"text","text":"The key difference from auditd or user-space agents is that Tetragon attaches eBPF programs to kernel hooks (kprobes, tracepoints, LSM hooks, uprobes) and evaluates policies in kernel space. A "},{"type":"text","text":"TracingPolicy","marks":[{"type":"code"}]},{"type":"text","text":" CRD describes which events to match, which selectors to apply (by binary path, namespace, pod label, argument value, capability), and what action to take: log, produce a Tetragon event, or "},{"type":"text","text":"SIGKILL","marks":[{"type":"code"}]},{"type":"text","text":" the process. Because enforcement happens in the kernel, there is no TOCTOU gap between detection and action, which is a chronic weakness of user-space eBPF observers."}]},{"type":"paragraph","content":[{"type":"text","text":"Tetragon automatically correlates kernel events with Kubernetes metadata (pod, namespace, container image, labels) and exports JSON events for consumption by SIEMs, Grafana, or Falco-compatible pipelines. It is commonly deployed alongside Cilium as the runtime-security layer in cloud-native environments."}]}]}' WHERE `id` = 'tetragon';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Thanos extends Prometheus with unlimited retention, high availability, and a single global query view across many Prometheus servers. It is a set of stateless components that cooperate with existing Prometheus instances rather than a rewrite, so teams can adopt it incrementally."}]},{"type":"paragraph","content":[{"type":"text","text":"The Sidecar runs next to each Prometheus and uploads completed TSDB blocks to an object store (S3, GCS, Azure Blob, Ceph, MinIO, etc.). Store Gateway exposes those historical blocks as a query API backed by object storage. Querier is a stateless PromQL engine that fans out over Sidecars, Store Gateways, and other Queriers via the Thanos gRPC Store API, deduplicates samples from HA Prometheus pairs, and returns a global result. Compactor downsamples old blocks to 5m and 1h resolutions and runs vertical compaction to make long-range queries tractable. Receive accepts Prometheus remote-write for push-based or multi-tenant setups, and Ruler evaluates recording and alerting rules against the global view."}]},{"type":"paragraph","content":[{"type":"text","text":"Thanos is a CNCF Incubating project originated at Improbable and is one of the two dominant approaches (the other being Cortex/Mimir) for turning Prometheus into a long-term, global monitoring system."}]}]}' WHERE `id` = 'thanos';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"TiKV is a distributed, transactional key-value store written in Rust that provides horizontal scalability, strong consistency, and ACID transactions across a cluster. It is the storage layer underneath TiDB and a CNCF Graduated project inspired in part by Google''s Spanner."}]},{"type":"paragraph","content":[{"type":"text","text":"Data is range-partitioned into \"Regions\" of roughly 96 MiB, each replicated via the Raft consensus algorithm to tolerate node failures. The Placement Driver (PD) is a separate cluster that tracks region metadata and orchestrates splits, merges, and rebalancing based on live load and size metrics. The per-node storage engine is RocksDB (with the Titan extension for large values) and, more recently, the Raft Engine for the Raft log. Transactions are built on a Percolator-style two-phase commit protocol using timestamps from PD, providing snapshot isolation and serializable transactions across regions. Clients can use either the raw KV API or the transactional API, and gRPC is the wire protocol."}]},{"type":"paragraph","content":[{"type":"text","text":"TiKV powers TiDB''s HTAP platform and is also used directly as a standalone store by projects that need a scalable, consistent KV layer, including JuiceFS, TiFS, and various geospatial and indexing systems."}]}]}' WHERE `id` = 'tikv';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tilt is a development environment automation tool for multi-service Kubernetes applications. It watches your source tree, rebuilds the affected containers, updates them in a local or remote cluster, and streams logs and health into a single live dashboard so developers don''t have to stitch together "},{"type":"text","text":"docker build","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"kubectl apply","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"kubectl logs","marks":[{"type":"code"}]},{"type":"text","text":" by hand."}]},{"type":"paragraph","content":[{"type":"text","text":"The build is driven by a "},{"type":"text","text":"Tiltfile","marks":[{"type":"code"}]},{"type":"text","text":", a Starlark (Python-dialect) script that declares how services are built and deployed: Docker images, Helm charts, Kustomize overlays, raw YAML, or custom build commands. Tilt''s killer feature is "},{"type":"text","text":"live_update","marks":[{"type":"code"}]},{"type":"text","text":", which syncs changed files straight into running containers and optionally runs in-container steps (like "},{"type":"text","text":"npm install","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"go build","marks":[{"type":"code"}]},{"type":"text","text":") instead of doing a full image rebuild and pod restart, collapsing the feedback loop to seconds. The UI shows per-resource status, readiness, logs, and errors, and supports triggers and dependencies so services that depend on a database come up in the right order."}]},{"type":"paragraph","content":[{"type":"text","text":"Tilt was created by Windmill Engineering (acquired by Docker in 2023). It occupies the same niche as Skaffold and Garden, with a stronger emphasis on a rich interactive UI for developers working on large microservice stacks."}]}]}' WHERE `id` = 'tilt';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"TimescaleDB is a PostgreSQL extension that turns Postgres into a time-series database. It adds hypertables, which transparently partition a regular table into chunks by time (and optionally by space), so inserts and range queries stay fast as the table grows into billions of rows."}]},{"type":"paragraph","content":[{"type":"text","text":"Because it is an extension, TimescaleDB inherits the full SQL surface, indexes, joins, foreign keys, and tooling of Postgres. On top of that it adds time-series specific features: continuous aggregates that incrementally materialize rollups, compression that converts row-oriented chunks into columnar segments, data retention policies, and hyperfunctions for things like time_bucket, gap-filling, and last-observation-carried-forward."}]},{"type":"paragraph","content":[{"type":"text","text":"TimescaleDB is a common backend for metrics, IoT telemetry, financial tick data, and application observability, where teams want the operational familiarity of Postgres without running a separate specialized TSDB like InfluxDB or Prometheus for long-term storage. The company behind it rebranded from Timescale to Tiger Data in 2025, but the open-source extension and repository still use the TimescaleDB name."}]}]}' WHERE `id` = 'timescale';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Timoni is a package manager for Kubernetes that uses CUE instead of Go templates. A Timoni module is a CUE project that generates and validates Kubernetes manifests, and modules are distributed as OCI artifacts signed with Cosign, rather than as tarballs on an HTTP chart repository."}]},{"type":"paragraph","content":[{"type":"text","text":"Using CUE gives Timoni schema-aware validation: values are type-checked against the same CUE definitions that produce the manifests, so invalid configuration is caught before anything reaches the API server. Timoni also supports bundles, which compose multiple modules into a single deployable unit, and handles CRD lifecycle, drift detection, and server-side apply as part of its reconciliation loop."}]},{"type":"paragraph","content":[{"type":"text","text":"It was created by Stefan Prodan, who also maintains Flux. Timoni is aimed at teams who have outgrown the string-templating model of Helm and want the configuration itself to be a programmable, typed artifact."}]}]}' WHERE `id` = 'timoni';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tinkerbell is a bare-metal provisioning engine that treats physical machines like cloud instances. It was created at Equinix Metal (then Packet) to automate the process of netbooting, installing, and configuring servers at scale, and is now a CNCF project."}]},{"type":"paragraph","content":[{"type":"text","text":"A Tinkerbell stack combines several components: Smee handles DHCP, PXE, and iPXE; Hegel exposes instance metadata; Tink runs workflows made of containerized actions against a target machine; and Rufio drives power and boot control through BMCs using IPMI or Redfish. Hardware inventory and workflows are expressed as Kubernetes custom resources, so the same GitOps patterns used for applications can drive OS installs, firmware updates, and disk wipes on real servers."}]},{"type":"paragraph","content":[{"type":"text","text":"Tinkerbell is used to bring up bare metal for Kubernetes clusters, edge sites, and private cloud fleets without relying on vendor-specific provisioning tools."}]}]}' WHERE `id` = 'tinkerbell';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tokenetes is a CNCF sandbox project that implements the IETF Transaction Tokens (TraT) draft. Transaction Tokens are short-lived, signed tokens that carry the authenticated identity of the original caller and the immutable context of a specific transaction as a request fans out through a chain of microservices."}]},{"type":"paragraph","content":[{"type":"text","text":"The problem Tokenetes addresses is that OAuth access tokens were designed to authorize a client to call a resource server, not to preserve \"who started this, and what did they ask for\" across many internal hops. Without transaction tokens, downstream services either over-trust their peers or re-authorize against the original bearer token in ways that are hard to scope. A Tokenetes service sits inside the trust domain, issues TraTs to workloads on demand, and lets receivers verify that the request they are handling is part of a sanctioned transaction."}]},{"type":"paragraph","content":[{"type":"text","text":"The project originated from work by SGNL and is aimed at zero-trust architectures where cross-service identity propagation needs to be explicit and auditable."}]}]}' WHERE `id` = 'tokenetes';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tremor is an event processing engine written in Rust, originally built at Wayfair to sit between their applications and their observability and messaging backends. It was donated to the CNCF and is designed for the kind of high-volume routing, filtering, rate-limiting, and transformation work that otherwise ends up scattered across Logstash, Vector, and custom Kafka consumers."}]},{"type":"paragraph","content":[{"type":"text","text":"Pipelines in Tremor are expressed as directed graphs with connectors (onramps and offramps) for things like Kafka, NATS, HTTP, Elasticsearch, and the file system. The logic inside a pipeline is written in Tremor''s own query and scripting languages, which include structural pattern matching over JSON-like records and a SQL-style windowed query language for aggregations."}]},{"type":"paragraph","content":[{"type":"text","text":"Tremor''s CNCF matrix status is now archived and the project is effectively dormant, but its ideas around typed event pipelines in Rust live on in tools like Vector and Benthos."}]}]}' WHERE `id` = 'tremor';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Trickster is an HTTP reverse proxy cache built primarily to accelerate time-series dashboards. It sits in front of backends like Prometheus, InfluxDB, ClickHouse, and Grafana''s SimpleJSON, and caches query results so that repeated dashboard loads do not re-run the same range queries against the TSDB."}]},{"type":"paragraph","content":[{"type":"text","text":"Its main trick is Delta Proxy Caching. When a dashboard refreshes a range query, Trickster recognizes that most of the requested window overlaps data it already has, and only fetches the delta from the upstream, merging it with the cached series before returning the response. It also normalizes time ranges and step intervals so that small differences in the request do not defeat the cache."}]},{"type":"paragraph","content":[{"type":"text","text":"Trickster started at Comcast and is now a CNCF sandbox project. It supports multiple cache backends (in-memory, bbolt, Redis, filesystem) and can also act as a general HTTP reverse proxy with a rules-based routing engine."}]}]}' WHERE `id` = 'trickster';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Trivy is a security scanner from Aqua Security that finds vulnerabilities, misconfigurations, exposed secrets, and license issues across a wide range of targets. A single binary can scan container images, filesystems, Git repositories, running Kubernetes clusters, Terraform and CloudFormation, Helm charts, Dockerfiles, and SBOMs."}]},{"type":"paragraph","content":[{"type":"text","text":"For vulnerability scanning it inspects OS packages (Alpine, Debian, Ubuntu, RHEL, and others) and language-specific lockfiles (npm, pip, Go modules, Cargo, Maven, and more), matching them against a database assembled from upstream advisories. The database is distributed as an OCI artifact so air-gapped environments can mirror it. For IaC and Kubernetes it uses built-in policies (formerly shipped as tfsec and Defsec) to flag misconfigurations like public S3 buckets or privileged pods."}]},{"type":"paragraph","content":[{"type":"text","text":"Trivy integrates cleanly into CI with non-zero exit codes on findings, and ships as a Kubernetes operator and an Aqua Trivy Helm chart for continuous in-cluster scanning. It has become the default scanner embedded in GitLab, Harbor, Artifact Hub, and many CNCF projects."}]}]}' WHERE `id` = 'trivy';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Update Framework (TUF) is a specification for securing software update systems against a realistic attacker model, including a compromised repository or a stolen signing key. It was originally designed at NYU for the Tor project and is now a CNCF graduated project."}]},{"type":"paragraph","content":[{"type":"text","text":"TUF''s core idea is role-based metadata signed with separate keys, where each role has a narrow responsibility. The root role establishes trust and is rotated infrequently from offline keys. The targets role signs the actual file hashes. The snapshot role signs a consistent view of all targets metadata to prevent mix-and-match attacks, and the timestamp role signs a short-lived attestation that the client is seeing current metadata, which defends against freeze and rollback attacks. Responsibility for subtrees of targets can be delegated to additional keys without expanding the root''s trust."}]},{"type":"paragraph","content":[{"type":"text","text":"TUF is the basis for Docker Notary, Sigstore''s root of trust, Python''s PEP 458 for PyPI, Automotive Grade Linux''s Uptane, and the update mechanisms in Fuchsia and RubyGems."}]}]}' WHERE `id` = 'tuf';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tyk is an open-source API gateway written in Go that fronts REST, GraphQL, gRPC, and async (Kafka, SSE, WebSocket) APIs. The gateway handles the usual concerns: authentication, rate limiting and quotas, request and response transformation, versioning, circuit breaking, and analytics."}]},{"type":"paragraph","content":[{"type":"text","text":"It supports most common auth schemes out of the box, including API keys, JWTs, OAuth2, OpenID Connect, HMAC, and mTLS, and policies are attached to keys so rate limits and access rights travel with the consumer. Custom logic can be added with middleware written in JavaScript, Python, Lua, gRPC plugins, or Go plugins compiled into the gateway. For GraphQL, Tyk can act as a universal data graph, stitching REST and gRPC upstreams into a single schema."}]},{"type":"paragraph","content":[{"type":"text","text":"The gateway itself is open source under MPL-2.0, while the dashboard, developer portal, and multi-data-center management (\"Tyk Cloud\" / self-managed) are commercial. It is commonly deployed in front of internal APIs or as an alternative to Kong and Apigee."}]}]}' WHERE `id` = 'tyk';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Universal Blue is a family of custom Fedora Atomic desktop images built with cloud-native tooling. Instead of installing Fedora Silverblue or Kinoite and then tweaking it by hand, you rebase to an OCI image maintained on GitHub, and ostree pulls the next version atomically on reboot."}]},{"type":"paragraph","content":[{"type":"text","text":"The images are assembled in GitHub Actions by layering RPMs, Flatpaks, drivers, and configuration on top of the Fedora base, then pushed to a container registry as signed OCI artifacts. Because the whole OS is an immutable container image, rollbacks are trivial (pin to the previous tag) and drift between machines effectively disappears. The project maintains several curated variants: Bluefin (GNOME, developer workstation), Aurora (KDE Plasma), Bazzite (gaming, Steam Deck-style with HDR and controller support), and uCore (a server variant based on Fedora CoreOS)."}]},{"type":"paragraph","content":[{"type":"text","text":"Universal Blue is a practical demonstration that the container build-and-ship model works for desktop Linux, not just for server workloads."}]}]}' WHERE `id` = 'universal-blue';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"urunc is an OCI-compliant container runtime for unikernels. Where runc spawns a Linux process in namespaces and cgroups, urunc takes the same OCI bundle and instead boots the contained unikernel image on top of a virtual machine monitor or sandbox (QEMU, Firecracker, solo5, and others)."}]},{"type":"paragraph","content":[{"type":"text","text":"The point is to let unikernels participate in the existing container ecosystem. A unikernel image is packaged into a standard OCI artifact, stored in any registry, and scheduled by containerd, CRI-O, or Kubernetes just like a normal container. urunc reads the OCI spec, picks the appropriate VMM based on annotations, and launches the unikernel with the right devices and network plumbing. This gives workloads hardware-level isolation and very small attack surfaces without forcing operators to adopt an entirely separate orchestration stack."}]},{"type":"paragraph","content":[{"type":"text","text":"urunc is a CNCF sandbox project, developed by Nubificus, and is primarily useful for edge, multi-tenant, and security-sensitive scenarios where unikernel boot times and footprint matter."}]}]}' WHERE `id` = 'urunc';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"vCluster creates fully functional Kubernetes clusters that run as Pods inside another Kubernetes cluster. Each virtual cluster has its own API server, controller manager, and data store, so tenants see their own dedicated cluster, can install CRDs, and can create cluster-scoped resources like namespaces, without needing cluster-admin on the host."}]},{"type":"paragraph","content":[{"type":"text","text":"By default vCluster runs k3s as the virtual control plane (k8s and k0s are also supported) and stores state in SQLite, Postgres, or an embedded etcd. It does not run its own kubelets. Instead, a syncer translates workloads from the virtual cluster into real Pods on the host cluster, rewriting namespaces and ownership so multiple vClusters can coexist safely. Services, endpoints, and persistent volume claims are mapped through in the same way."}]},{"type":"paragraph","content":[{"type":"text","text":"Compared to namespace-based multi-tenancy, vCluster gives tenants meaningful API-level isolation; compared to running separate real clusters, it is dramatically cheaper. It is maintained by Loft Labs and widely used for preview environments, per-team dev clusters, and CI."}]}]}' WHERE `id` = 'vcluster';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Velero is a backup and disaster recovery tool for Kubernetes, originally built at Heptio as Ark and now maintained by the community. It backs up two things together: the Kubernetes API objects in a namespace or cluster, and the persistent volumes attached to the workloads running in it."}]},{"type":"paragraph","content":[{"type":"text","text":"API resources are serialized and written to an object store (S3, GCS, Azure Blob, MinIO, or anything S3-compatible). Volumes are handled either through the underlying storage provider''s snapshot API (EBS, GCE PD, Azure Disk, CSI snapshots) or via filesystem-level backup using Kopia or Restic, which copies the contents of any PV regardless of storage backend. Restores can be scoped by namespace, label selector, or resource type, and include label transformations so a backup can be rehydrated into a different cluster or namespace."}]},{"type":"paragraph","content":[{"type":"text","text":"Velero is the standard answer to Kubernetes backup for cluster migration, cross-region DR, and pre-upgrade safety nets, and is the foundation for several vendor backup products including VMware''s Tanzu Mission Control and OpenShift OADP."}]}]}' WHERE `id` = 'velero';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Vineyard (v6d) is an in-memory immutable data manager for distributed analytics and ML pipelines. Its job is to let two stages of a pipeline pass large objects like dataframes, tensors, and graphs to each other without serializing to disk or over a socket."}]},{"type":"paragraph","content":[{"type":"text","text":"Each node runs a vineyardd daemon that owns a shared memory segment. Objects are stored once and consumers in other processes on the same node map them in with zero copies. A separate metadata service, typically etcd, tracks where each object lives in the cluster, so a distributed dataframe partitioned across nodes can be addressed as a single logical object. Vineyard separates metadata from payload so new data structures can be plugged in by registering builders, resolvers, and I/O drivers."}]},{"type":"paragraph","content":[{"type":"text","text":"It was created at Alibaba and is a CNCF sandbox project. Typical use cases are handing intermediate data between Spark, Dask, Ray, and PyTorch stages in Kubernetes-scheduled ML workflows, where the alternative is writing Parquet to object storage between every step."}]}]}' WHERE `id` = 'vineyard';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Virtual Kubelet is a library and open project that implements the kubelet API without actually running containers on a node. It registers itself with the Kubernetes API server as a Node object, and when the scheduler places a Pod on that \"node\" the provider implementation translates the Pod spec into something else entirely."}]},{"type":"paragraph","content":[{"type":"text","text":"That \"something else\" is the whole point. Providers have been written for AWS Fargate, Azure Container Instances, Alibaba ECI, HashiCorp Nomad, and AdmiraltyLab''s cross-cluster scheduling, among others. From the cluster''s perspective, Pods come up, report status, and stream logs like any other workload, but underneath they are running on a serverless container service, a separate cluster, or a bespoke runtime. This is the mechanism behind AKS Virtual Nodes and EKS-on-Fargate style integrations."}]},{"type":"paragraph","content":[{"type":"text","text":"Virtual Kubelet is a CNCF sandbox project and is primarily a building block: most users encounter it indirectly through a specific cloud provider''s burst-to-serverless feature rather than deploying it by hand."}]}]}' WHERE `id` = 'virtualkubelet';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Vitess is a database clustering system that turns MySQL into a horizontally-scalable, sharded database while keeping it look like a single logical MySQL server to applications. It was built at YouTube to survive the scaling problems of a write-heavy MySQL deployment and is now a CNCF graduated project."}]},{"type":"paragraph","content":[{"type":"text","text":"Clients talk to VTGate, a stateless proxy that speaks the MySQL wire protocol. VTGate parses queries, consults a VSchema to figure out how tables are sharded, and routes or scatter-gathers the query to the right VTTablet processes, which each sit in front of a real MySQL instance. Resharding is online: Vitess can split shards by streaming rows between tablets, switching writes over atomically, and cleaning up the old shards, all without downtime. It also handles topology metadata, backups, automatic failover, and connection pooling, so MySQL''s usual operational pain points are absorbed by the control plane."}]},{"type":"paragraph","content":[{"type":"text","text":"Vitess powers databases at Slack, YouTube, Square, GitHub, HubSpot, and PlanetScale, which was built directly on top of it."}]}]}' WHERE `id` = 'vitess';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Volcano is a batch scheduling system for Kubernetes aimed at HPC, AI, and big data workloads that the default kube-scheduler handles poorly. These workloads want group semantics: a training job needs all of its workers to start together or none of them, and a distributed job should not deadlock against another job that has grabbed half the GPUs each."}]},{"type":"paragraph","content":[{"type":"text","text":"Volcano addresses this with gang scheduling, fair-share and capacity queues, preemption, job dependencies, and topology-aware placement that takes GPU and NUMA locality into account. It introduces a PodGroup CRD and a Job CRD so that a set of Pods can be scheduled atomically, and ships framework integrations for TensorFlow, PyTorch, MPI, Spark, Flink, Ray, and Argo workflows, so jobs from those frameworks can be submitted natively and queued by Volcano."}]},{"type":"paragraph","content":[{"type":"text","text":"It originated at Huawei and is a CNCF incubating project, commonly used as the scheduler for Kubernetes-based AI training platforms and HPC clusters."}]}]}' WHERE `id` = 'volcano';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"WasmEdge is a lightweight, high-performance WebAssembly runtime written in C++, optimized for server-side and edge workloads. It implements the core Wasm spec plus WASI, and layers on extensions for things the base spec does not cover: sockets for networking, a TensorFlow / PyTorch / llama.cpp inference plugin, a KV store interface, and async HTTP."}]},{"type":"paragraph","content":[{"type":"text","text":"The runtime can execute Wasm in interpreted mode or ahead-of-time compiled to native via LLVM, which closes most of the performance gap with native binaries. It ships as an OCI-compatible runtime that plugs into containerd and CRI-O via crun or runwasi, so a Pod with a Wasm workload can be scheduled by Kubernetes exactly like a container. It also embeds into Rust, Go, Node.js, and Python processes as a library, which is how it is often used as a sandbox for user-defined functions."}]},{"type":"paragraph","content":[{"type":"text","text":"WasmEdge is a CNCF sandbox project maintained by Second State, and is commonly used for serverless functions, edge compute, and running LLM inference at the edge."}]}]}' WHERE `id` = 'wasm-edge-runtime';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"wasmCloud is a distributed application runtime built around the WebAssembly Component Model. Applications are composed of stateless WebAssembly components that declare the capabilities they need (HTTP server, key-value store, messaging, blob storage) using WIT interfaces, and the runtime injects providers that implement those capabilities at deploy time."}]},{"type":"paragraph","content":[{"type":"text","text":"A wasmCloud lattice is a set of hosts connected by NATS. Components and capability providers can be scheduled onto any host in the lattice, and invocations between them are routed through NATS, so a component in one region can transparently call a KV provider running elsewhere. Applications are described declaratively with wadm manifests, which the control plane reconciles across the lattice. Because components are pure Wasm with no ambient capabilities, they start in milliseconds and can be safely multi-tenanted."}]},{"type":"paragraph","content":[{"type":"text","text":"The project was started at Cosmonic and is a CNCF incubating project. It is one of the more concrete production uses of the Wasm component model, alongside Fermyon Spin and Fastly''s Compute@Edge."}]}]}' WHERE `id` = 'wasmcloud';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Waypoint was HashiCorp''s attempt at a unified build, deploy, and release tool. A single "},{"type":"text","text":"waypoint.hcl","marks":[{"type":"code"}]},{"type":"text","text":" described an application and its three phases: build (using Cloud Native Buildpacks, a Dockerfile, or a language-specific builder), deploy (to Kubernetes, Nomad, ECS, Lambda, Cloud Run, or a static host), and release (flipping traffic over via an ingress, load balancer, or service mesh). Plugins supplied the concrete implementations for each target."}]},{"type":"paragraph","content":[{"type":"text","text":"The idea was to give developers a "},{"type":"text","text":"waypoint up","marks":[{"type":"code"}]},{"type":"text","text":" command that produced a URL, regardless of the underlying platform, while operators retained control over the plugins and policies. A Waypoint server held project state, history, and auth, and the CLI and a web UI talked to it."}]},{"type":"paragraph","content":[{"type":"text","text":"HashiCorp sunset Waypoint Community Edition in 2024, and the GitHub repository was archived on January 8, 2024. HashiCorp now steers users toward HCP Waypoint, so the open-source codebase is mainly useful as a reference for existing installations."}]}]}' WHERE `id` = 'waypoint';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"WebAssembly (Wasm) is a portable binary instruction format for a stack-based virtual machine. It was originally designed so browsers could run languages other than JavaScript at near-native speed, and is a W3C standard shipped in every major browser. Code written in C, C++, Rust, Go, Zig, AssemblyScript, and increasingly other languages can be compiled to a .wasm module and executed inside a sandboxed VM with explicit, capability-based access to the outside world."}]},{"type":"paragraph","content":[{"type":"text","text":"That sandboxing model is what makes Wasm interesting outside the browser. A module has no ambient access to the filesystem, network, or clock; the host must explicitly grant each capability. WASI, the WebAssembly System Interface, standardizes those host APIs so the same module can run on Wasmtime, Wasmer, WasmEdge, or a browser polyfill. The Component Model builds on top of WASI with typed interfaces (WIT), so components written in different source languages can link together without sharing ABIs."}]},{"type":"paragraph","content":[{"type":"text","text":"Wasm is now used well beyond the browser: as a plugin format for Envoy and Istio, as a serverless runtime (Fastly Compute, Fermyon Spin, wasmCloud), as an embedded scripting engine inside databases and proxies, and as a secure sandbox for user-provided code."}]}]}' WHERE `id` = 'webassembly';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"werf is an open-source CLI that combines image building, registry management, and Kubernetes deployment into one Git-driven workflow. It wraps Buildah and Helm under a single tool so that a commit hash deterministically produces the same images, the same tags, and the same release."}]},{"type":"paragraph","content":[{"type":"text","text":"The distinguishing idea is \"Giterminism\": the configuration werf reads must come from Git, and builds are keyed by content hashes of the files that actually influenced them, which enables strong layer caching across CI runners and across branches. Images are tagged by content rather than by branch or commit, so identical content skips a rebuild and redeploy. On the deploy side, werf uses Helm 3 under the hood but adds real-time resource tracking, so "},{"type":"text","text":"werf converge","marks":[{"type":"code"}]},{"type":"text","text":" blocks until Pods are actually Ready and streams logs and events from the workloads it just applied. Cleanup is based on which images are still referenced by Git history and by the cluster, so unused images get garbage collected from the registry automatically."}]},{"type":"paragraph","content":[{"type":"text","text":"werf is developed by Flant and is a CNCF sandbox project, commonly used as a replacement for hand-rolled \"build image + helm upgrade\" CI pipelines."}]}]}' WHERE `id` = 'werf';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"WunderGraph is an open-source GraphQL federation platform centered on Cosmo, a high-performance router written in Go. Cosmo implements the Apollo Federation v1 and v2 specs and acts as the supergraph gateway: teams publish subgraph schemas to a schema registry, Cosmo composes them, and clients query a single federated endpoint."}]},{"type":"paragraph","content":[{"type":"text","text":"The router executes query plans natively in Go rather than by proxying to an external query planner, which is how it claims significantly better tail latency than Apollo Router for the same workloads. On top of federation it supports event-driven GraphQL subscriptions over NATS, Kafka, and Redis (Cosmo Streams), adapts REST and gRPC upstreams into subgraphs, and provides an analytics backend backed by ClickHouse for tracing and schema usage. A separate Hub product adds governance: schema proposals, breaking-change checks, and CI-enforced change policies."}]},{"type":"paragraph","content":[{"type":"text","text":"WunderGraph originally shipped a different product focused on BFF-style generated clients, but the current focus is Cosmo as an open-source alternative to Apollo GraphOS for teams running federated GraphQL at scale."}]}]}' WHERE `id` = 'wundergraph';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Xdebug is a PHP extension that provides the debugging, profiling, and tracing facilities that the language itself does not. It is loaded as a Zend extension, hooks into the PHP engine, and then speaks the DBGp protocol over a TCP socket to an IDE like PhpStorm, VS Code, or Vim, providing step debugging, breakpoints, watches, and stack inspection for running scripts and web requests."}]},{"type":"paragraph","content":[{"type":"text","text":"Beyond the debugger, Xdebug has several distinct modes that can be enabled independently. "},{"type":"text","text":"develop","marks":[{"type":"code"}]},{"type":"text","text":" replaces PHP''s plain "},{"type":"text","text":"var_dump","marks":[{"type":"code"}]},{"type":"text","text":" output with a prettified, color-aware version and improves error messages with full stack traces. "},{"type":"text","text":"profile","marks":[{"type":"code"}]},{"type":"text","text":" writes Cachegrind-format files that KCachegrind or QCachegrind can visualize to find hot paths. "},{"type":"text","text":"trace","marks":[{"type":"code"}]},{"type":"text","text":" writes a line-by-line execution log of every function call, arguments, and return values. "},{"type":"text","text":"coverage","marks":[{"type":"code"}]},{"type":"text","text":" is the engine PHPUnit and other test runners use to produce code coverage reports."}]},{"type":"paragraph","content":[{"type":"text","text":"It has been maintained by Derick Rethans since 2002 and is the de facto debugger for PHP, typically enabled only in development and CI environments because of its runtime cost."}]}]}' WHERE `id` = 'xdebug';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"xRegistry is a specification for a generic, extensible metadata registry and the HTTP API to query it. It defines a common resource model (\"groups\" containing \"resources\" with versioned \"versions\") and a standard set of conventions for discovery, pagination, filtering, and references, so that different kinds of metadata registries all look the same from a client''s perspective."}]},{"type":"paragraph","content":[{"type":"text","text":"On top of that core model, xRegistry defines domain-specific specs that instantiate it: the Schema Registry spec for managing JSON Schema, Avro, and Protobuf; the Message Definitions spec for CloudEvents and async message payloads; and the Endpoints spec for describing where producers and consumers can reach those messages. In practice that means a single API can serve schemas, event type definitions, and endpoint metadata in an interoperable way, rather than each tool inventing its own registry shape."}]},{"type":"paragraph","content":[{"type":"text","text":"xRegistry is a CNCF sandbox project and is being driven by contributors from Microsoft, Google, and the CloudEvents community. The reference server is available at github.com/xregistry/server, and the specs cover both the wire format (JSON over HTTP) and filesystem representations so registries can be checked into Git."}]}]}' WHERE `id` = 'xregistry';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yoke is a Kubernetes package deployer that replaces templated YAML packages with code packages. Its packages are called Flights: programs that generate Kubernetes resources as JSON or YAML, commonly packaged as WebAssembly executables."}]},{"type":"paragraph","content":[{"type":"text","text":"The project includes the "},{"type":"text","text":"yoke","marks":[{"type":"code"}]},{"type":"text","text":" CLI for client-side package deployment, YokeCD for Argo CD GitOps workflows, and Air Traffic Controller for CRD-native package management. The goal is to bring normal software engineering affordances such as type checking, testing, control flow, and language-native package distribution to Kubernetes resource management."}]}]}' WHERE `id` = 'yoke';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"youki is an OCI-compliant low-level container runtime written in Rust, a drop-in alternative to runc. It implements the OCI runtime specification, so higher-level tooling like containerd, CRI-O, Podman, and Docker can delegate container creation to youki without changes on their side."}]},{"type":"paragraph","content":[{"type":"text","text":"Because it is written in Rust, youki avoids a class of memory-safety issues that affect C runtimes, and benchmarks have shown faster container startup than both runc (Go) and crun (C) in several workloads. The implementation covers the usual Linux isolation primitives: namespaces (PID, mount, network, user, UTS, IPC, cgroup), cgroups v1 and v2, seccomp, capabilities, AppArmor, SELinux labeling, and rootless mode. It also supports the WasmEdge and Wasmtime handlers so that Wasm workloads can be launched through the OCI runtime interface."}]},{"type":"paragraph","content":[{"type":"text","text":"youki is a CNCF sandbox project and is one of the better-known examples of \"rewrite it in Rust\" applied to foundational container tooling."}]}]}' WHERE `id` = 'youki';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ZITADEL is an open-source identity and access management platform written in Go. It provides a full OpenID Connect and OAuth 2.0 provider, SAML 2.0, user management, multi-tenant organizations, RBAC, and a self-service account console, positioning itself as an alternative to Keycloak, Auth0, and Okta."}]},{"type":"paragraph","content":[{"type":"text","text":"Internally, ZITADEL is built on event sourcing: every change to a user, project, application, or grant is an immutable event in an event store, and the query side is projected into Postgres (previously CockroachDB) tables. That gives it a full audit log for free and makes horizontal scaling of the read path straightforward. It supports the features you would expect from a modern IdP, including passkeys and WebAuthn, OTP, push notifications, passwordless login, SCIM-like user provisioning, custom actions (JavaScript hooks that run during flows), and branding per organization."}]},{"type":"paragraph","content":[{"type":"text","text":"ZITADEL is available as a managed cloud, self-hosted binary, or Helm chart. It is a common pick for teams that want a self-hostable Auth0 replacement without running the older Keycloak stack."}]}]}' WHERE `id` = 'zitadel';
UPDATE `technologies` SET `body` = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"zot is an OCI-native container and artifact registry that stores everything on a plain filesystem or object store, with no database. The on-disk layout is the OCI Image Layout specification verbatim, so the contents of a zot storage directory can be read by any OCI-compliant tool without going through zot at all."}]},{"type":"paragraph","content":[{"type":"text","text":"Because it is OCI-only (no Docker v1 legacy), the codebase is much smaller than Distribution/Harbor and focuses on the features modern supply-chain work actually needs: storing and serving OCI artifacts of any media type, ORAS references, Cosign signatures, SBOMs, and Notary v2 signatures as first-class objects. It ships with built-in Trivy-based vulnerability scanning, a search extension that exposes a GraphQL API for finding images and their referrers, and sync/mirroring from upstream registries. Authentication supports htpasswd, LDAP, OIDC, and mTLS, and authorization can be expressed per-repository."}]},{"type":"paragraph","content":[{"type":"text","text":"zot is a CNCF sandbox project maintained primarily by Cisco. It is commonly deployed as an embedded registry in edge and air-gapped environments, and as a lightweight registry for CI where the operational overhead of Harbor is too much."}]}]}' WHERE `id` = 'zot';
